def lookup_actor(addr: str | None) -> dict | None:
    return KNOWN_ACTORS.get(addr.lower()) if addr else None


def lookup_selector(sel: str | None) -> dict | None:
    return KNOWN_SELECTORS.get(sel.lower()) if sel else None


# ============================================================================
# Heuristic actor attribution — for kit contracts NOT yet in KNOWN_ACTORS
# ============================================================================
# A wide sweep of the LenAI ecosystem turned up 27 distinct contracts; only 6
# were in KNOWN_ACTORS. The other 21 all used selector 0xb68d1809 (getDomain)
# and resolved to a .beer / .sbs / .click / .cfd host — a deterministic BW v2
# panel-router pattern. Hand-curating KNOWN_ACTORS for every new sibling is
# unsustainable; we infer when an unattributed contract MUST be one.
#
# Returns the same shape as KNOWN_ACTORS values, with attribution_method set
# to "heuristic_*" so analysts can downgrade trust if needed.

_BW_V2_HOST_RE = re.compile(r"^[\w.-]+\.(beer|sbs|click|cfd|cyou|shop|lat)$",
                              re.IGNORECASE)


def synthesize_actor_attribution(contract_addr: str | None,
                                  selector: str | None,
                                  resolved_url: str | None) -> dict | None:
    """Synthesize an actor attribution from observable signals when the
    contract isn't in KNOWN_ACTORS. Currently recognises BW v2 panel-routers
    (getDomain + burner-TLD result). Conservative — only fires when ALL
    signals align. Returns None when no heuristic match is confident.
    """
    if not contract_addr or not selector:
        return None
    sel = selector.lower()
    addr = contract_addr.lower()
    # BW v2 panel-router pattern: getDomain selector + burner-TLD result.
    if sel == "0xb68d1809" and resolved_url:
        # Strip protocol + path to get host
        host = resolved_url
        if "://" in host:
            host = host.split("://", 1)[1]
        host = host.split("/", 1)[0].split("?", 1)[0].lower()
        # Replace common defang shapes back
        host = host.replace("[.]", ".").rstrip(".")
        if _BW_V2_HOST_RE.match(host):
            return {
                "name":      f"ErrTraffic v3 (BW v2) panel-router for {host}",
                "advertised_as":   "ErrTraffic v3 BW v2",
                "chain":     "polygon",
                "first_seen": None,
                "infra":     {"hoster_pattern": "LenAI ecosystem panel-router"},
                "downstream": ["likely Vidar (S25-F1) — depends on panel"],
                "sources":   ["clickchain.py heuristic_bw_v2_pattern"],
                "attribution_method": "heuristic_bw_v2_pattern",
                "confidence": "high",   # selector + burner TLD is deterministic
                "notes":     ("Auto-attributed by ClickChain heuristic: contract "
                              "uses 0xb68d1809=getDomain() and resolves to a "
                              "BW-v2-family burner TLD. Not hand-curated in "
                              "KNOWN_ACTORS but follows the documented LenAI "
                              "sibling-contract pattern."),
            }
    return None


# ============================================================================
# Panel ↔ lure memory — the kit cross-validates src=<lure_host> on /api/init.
# A panel served by lure X returns os_not_allowed when probed with src=Y, even
# though Y is a valid lure for a different panel. We auto-learn which lures
# each panel actually served by watching lure-role targets resolve on-chain;
# panel-role targets then pull a known-good src from the memory instead of
# falling back to a single static --probe-src flag.
# ============================================================================
import threading as _threading_for_lure_mem
_PANEL_LURE_MEMORY: dict[str, list[str]] = {}
_PANEL_LURE_LOCK = _threading_for_lure_mem.Lock()

# DESIGN: We only need a handful of known-good lures per panel. ClickChain's
# probe path uses ONLY entry [0] as src — keeping 32 was historical and
# wasteful. The kit accepts any of them, so the second-to-last lure adds no
# value over the most recent one. Cap chosen empirically:
#   - 8 lures retained (gives room to rotate if a top entry goes dead)
#   - Total memory footprint at 1000 panels × 8 lures × ~32 bytes = ~250KB
#   - File serialization stays under 100KB for 1000 panels
_LURES_PER_PANEL_CAP = 8

# Seed universal-fallback lure hosts (proven across multiple BW v2 panels in
# prior runs). Used as a last-resort src when neither the panel-specific
# memory NOR a CLI override is set. The dynamic-derivation function below
# augments this with "promiscuous" lures observed in the loaded memory —
# lures that appear in multiple panels' memory are statistically the safest
# universal-fallback candidates.
_BW_V2_UNIVERSAL_LURE_SEED: tuple[str, ...] = (
    "kidspepe.com",         # served nsservclod.beer (S25)
    "compraway.com",        # served lenders.digital (S18-20)
    "groutcleaningperth.com.au",  # served lenders.digital (S20)
)


def register_panel_lure(panel_host: str | None, lure_host: str | None) -> None:
    """Record that `lure_host` is a known-good src for `panel_host`.

    Smart dedup: if the lure is already on the list, just BUMP it to the
    front (most-recent-first ordering). New lures push the list down with a
    hard cap of _LURES_PER_PANEL_CAP. We deliberately discard older lures
    because we only USE entry [0] as src — extras beyond 8 are dead weight.
    """
    if not panel_host or not lure_host:
        return
    panel = panel_host.lower().lstrip(".")
    lure = lure_host.lower().lstrip(".")
    if panel == lure:
        return
    with _PANEL_LURE_LOCK:
        lst = _PANEL_LURE_MEMORY.setdefault(panel, [])
        if lure in lst:
            # Bump to the front (most-recent-first ordering); preserves size
            lst.remove(lure)
        lst.insert(0, lure)
        if len(lst) > _LURES_PER_PANEL_CAP:
            del lst[_LURES_PER_PANEL_CAP:]


def lookup_panel_lures(panel_host: str | None) -> list[str]:
    """Return the list of known-good lure hosts for `panel_host`, most-recent
    first. Empty list when nothing is known."""
    if not panel_host:
        return []
    with _PANEL_LURE_LOCK:
        return list(_PANEL_LURE_MEMORY.get(panel_host.lower().lstrip("."), []))


def derive_universal_fallback_lures(max_lures: int = 8) -> list[str]:
    """Return the best-guess universal-fallback lures, ranked by how many
    panels each lure has worked for (most "promiscuous" first).

    A lure that appears in 8 different panels' memories is statistically a
    strong universal fallback. The seed list is always merged in afterwards
    so we never fall below the curated-known set.
    """
    counts: dict[str, int] = {}
    with _PANEL_LURE_LOCK:
        for panel, lures in _PANEL_LURE_MEMORY.items():
            for l in lures:
                counts[l] = counts.get(l, 0) + 1
    # Rank by panel-count desc, then alphabetically for determinism
    ranked = sorted(counts.items(), key=lambda x: (-x[1], x[0]))
    out: list[str] = []
    seen: set[str] = set()
    # Anything with ≥2 panel matches is a strong universal candidate
    for lure, n in ranked:
        if n < 2:
            break
        if lure not in seen:
            seen.add(lure); out.append(lure)
        if len(out) >= max_lures:
            break
    # Pad with the curated seed list
    for s in _BW_V2_UNIVERSAL_LURE_SEED:
        if s not in seen and len(out) < max_lures:
            seen.add(s); out.append(s)
    return out


def panel_lure_memory_export() -> dict:
    """Return a JSON-serialisable snapshot of _PANEL_LURE_MEMORY."""
    with _PANEL_LURE_LOCK:
        return {p: list(lures) for p, lures in _PANEL_LURE_MEMORY.items()}


def panel_lure_memory_load(snapshot: dict) -> int:
    """Pre-seed _PANEL_LURE_MEMORY from a JSON snapshot. Returns the number
    of panel entries loaded. Trims oversized entries to the per-panel cap so
    a legacy file with 32-lure entries gets normalised on load."""
    if not isinstance(snapshot, dict):
        return 0
    n = 0
    with _PANEL_LURE_LOCK:
        for panel, lures in snapshot.items():
            if isinstance(panel, str) and isinstance(lures, list):
                # Dedup while preserving order — older clones drop out
                clean: list[str] = []
                seen: set[str] = set()
                for l in lures:
                    if not l: continue
                    lc = str(l).lower()
                    if lc in seen: continue
                    seen.add(lc); clean.append(lc)
                    if len(clean) >= _LURES_PER_PANEL_CAP:
                        break
                if clean:
                    _PANEL_LURE_MEMORY[panel.lower()] = clean
                    n += 1
    return n


# ============================================================================
# Sandboxed arithmetic evaluator  (no eval / no exec / no JS)
# ============================================================================
_ALLOWED_BINOPS = (ast.Add, ast.Sub, ast.Mult, ast.Mod, ast.BitAnd, ast.BitOr,
                   ast.BitXor, ast.LShift, ast.RShift, ast.FloorDiv)
_ALLOWED_UNARY  = (ast.USub, ast.UAdd, ast.Invert)


class SafeEval:
    def __init__(self, names: dict): self.names = names
    def eval(self, expr: str): return self._ev(ast.parse(expr, mode="eval").body)
    def _ev(self, n):
        if isinstance(n, ast.BinOp) and isinstance(n.op, _ALLOWED_BINOPS):
            return self._apply(n.op, self._ev(n.left), self._ev(n.right))
        if isinstance(n, ast.UnaryOp) and isinstance(n.op, _ALLOWED_UNARY):
            v = self._ev(n.operand)
            return -v if isinstance(n.op, ast.USub) else (~v if isinstance(n.op, ast.Invert) else +v)
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, str)):
            return n.value
        if isinstance(n, ast.Name):
            if n.id not in self.names: raise ValueError(f"unknown name {n.id!r}")
            return self.names[n.id]
        if isinstance(n, ast.Subscript):
            arr = self._ev(n.value); sl = n.slice
            if hasattr(ast, "Index") and isinstance(sl, ast.Index): sl = sl.value
            idx = self._ev(sl)
            if isinstance(arr, (list, tuple)):
                return arr[idx] if 0 <= idx < len(arr) else 0
            if isinstance(arr, str):
                return ord(arr[idx]) if 0 <= idx < len(arr) else 0
            raise ValueError("subscript on non-array/string")
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute) \
                and n.func.attr == "charCodeAt" and len(n.args) == 1:
            target = self._ev(n.func.value); idx = self._ev(n.args[0])
            if isinstance(target, str):
                return ord(target[idx]) if 0 <= idx < len(target) else 0
            raise ValueError("charCodeAt on non-string")
        raise ValueError(f"disallowed node {type(n).__name__}")
    @staticmethod
    def _apply(op, a, b):
        if isinstance(op, ast.Add): return a + b
        if isinstance(op, ast.Sub): return a - b
        if isinstance(op, ast.Mult): return a * b
        if isinstance(op, ast.Mod): return a % b if b else 0
        if isinstance(op, ast.FloorDiv): return a // b if b else 0
        if isinstance(op, ast.BitAnd): return a & b
        if isinstance(op, ast.BitOr): return a | b
        if isinstance(op, ast.BitXor): return a ^ b
        if isinstance(op, ast.LShift): return a << b
        if isinstance(op, ast.RShift): return a >> b
        raise ValueError("bad op")


# ============================================================================
# Source-text scraping
# ============================================================================
_RE_INT_VAR   = re.compile(r'\b(?:var|let|const)?\s*(\w+)\s*=\s*(-?\d+)\s*[,;)\]}\n]')
_RE_ARR_VAR   = re.compile(r'\b(?:var|let|const)?\s*(\w+)\s*=\s*\[((?:\s*-?\d+\s*,)*\s*-?\d+\s*)\]')
_RE_STR_VAR   = re.compile(r'''\b(?:var|let|const)?\s*(\w+)\s*=\s*(['"`])([^'"`\n]{4,})\2''')
_RE_ATOB      = re.compile(r'\batob\(\s*(?:(["\'`])([A-Za-z0-9+/=\s]{16,})\1|(\w+))\s*\)')
_RE_ATOB_VAR  = re.compile(r'\b(\w+)\s*=\s*atob\(\s*(?:(["\'`])([A-Za-z0-9+/=\s]{16,})\2|(\w+))\s*\)')
_RE_CHARCODE  = re.compile(r'(\w+)\.charCodeAt\(\s*(\w+)\s*\)')
_RE_SCRIPT    = re.compile(r'<script\b(?![^>]*\bsrc=)[^>]*>(.*?)</script>', re.I | re.S)
_RE_SCRIPT_POS = re.compile(r'<script\b(?![^>]*\bsrc=)[^>]*>', re.I)    # for byte-offset lookup
_RE_SCRIPTSRC = re.compile(r'<script\b[^>]*\bsrc=["\']([^"\']+)["\']', re.I)
_RE_HEX_ESC   = re.compile(r'(?:\\x[0-9a-fA-F]{2}){8,}')
_RE_CC_ARRAY  = re.compile(r'String\.fromCharCode\.apply\(\s*null\s*,\s*\[((?:\s*\d+\s*,){4,}\s*\d+\s*)\]\s*\)')


def _b64(s: str) -> bytes:
    s = "".join(s.split()); s += "=" * (-len(s) % 4)
    return base64.b64decode(s, validate=False)


def _balanced(text: str, start_token: str, pos: int = 0):
    i = text.find(start_token, pos)
    if i < 0: return None, -1
    i += len(start_token); start, depth, n = i, 1, len(text)
    while i < n and depth:
        c = text[i]
        if c == "(": depth += 1
        elif c == ")":
            depth -= 1
            if depth == 0: return text[start:i], i + 1
        i += 1
    return None, -1


def scrape_namespace(code: str, base: dict | None = None) -> dict:
    ns: dict = {}
    for m in _RE_ARR_VAR.finditer(code):
        try: ns[m.group(1)] = [int(x) for x in m.group(2).split(",")]
        except ValueError: pass
    for m in _RE_INT_VAR.finditer(code):
        if m.group(1) not in ns:
            try: ns[m.group(1)] = int(m.group(2))
            except ValueError: pass
    for m in _RE_STR_VAR.finditer(code):
        if m.group(1) not in ns: ns[m.group(1)] = m.group(3)
    if base:
        for k, v in base.items(): ns.setdefault(k, v)
    return ns


def _js_to_py_expr(expr: str, src_var: str) -> str:
    def repl(m): return "b" if m.group(1) == src_var else m.group(0)
    expr = _RE_CHARCODE.sub(repl, expr)
    return expr.replace("String.fromCharCode", "").strip()


# ============================================================================
# Obfuscation schemes
# ============================================================================
def _atob_blobs(code: str, ns: dict) -> list[tuple[str | None, bytes]]:
    out = []
    for m in _RE_ATOB_VAR.finditer(code):
        var, _q, lit, ref = m.group(1), m.group(2), m.group(3), m.group(4)
        s = lit if lit else (ns.get(ref) if isinstance(ns.get(ref), str) else None)
        if not s: continue
        try: raw = _b64(s)
        except Exception: continue
        if any(raw == r for _, r in out): continue
        out.append((var, raw))
    for m in _RE_ATOB.finditer(code):
        _q, lit, ref = m.group(1), m.group(2), m.group(3)
        s = lit if lit else (ns.get(ref) if isinstance(ns.get(ref), str) else None)
        if not s: continue
        try: raw = _b64(s)
        except Exception: continue
        if any(raw == r for _, r in out): continue
        out.append((None, raw))
    out.sort(key=lambda kv: len(kv[1]), reverse=True)
    return out


def scheme_atob_byte_transform(code: str, ns: dict):
    blobs = _atob_blobs(code, ns)
    if not blobs: return None, None
    expr = None
    inner, _end = _balanced(code, "String.fromCharCode(")
    if inner and "charCodeAt" in inner: expr = inner
    if expr is None:
        m = re.search(r'\[\s*\w+\s*\]\s*=\s*([^;\n}]*charCodeAt[^;\n}]*)', code)
        if m: expr = m.group(1).strip()
    if expr is None:
        m = re.search(r'(\w+\.charCodeAt\([^)]*\))\s*([\^&|+\-*%][^;)\]\n]+)', code)
        if m: expr = m.group(1) + m.group(2)
    if expr is None: return None, None
    src_var, payload = None, None
    for var, raw in blobs:
        if var and var in expr: src_var, payload = var, raw; break
    if payload is None: src_var, payload = blobs[0]
    if src_var is None:
        src_var = "__blob"
        expr = re.sub(r'\w+\.charCodeAt', f'{src_var}.charCodeAt', expr, count=1)
    py_expr = _js_to_py_expr(expr, src_var)
    ev = SafeEval({**ns, "b": 0, "i": 0})
    try: ev.eval(py_expr)
    except Exception as e: return None, f"transform parse failed: {e}"
    is_u8 = "Uint8Array" in code or "TextDecoder" in code
    out_b, out_c = bytearray(), []
    try:
        for i, byte in enumerate(payload):
            ev.names["b"] = byte; ev.names["i"] = i
            v = ev.eval(py_expr)
            if is_u8: out_b.append(v & 0xFF)
            else: out_c.append(chr(v & 0xFFFF))
    except Exception as e: return None, f"transform eval failed at i={i}: {e}"
    text = out_b.decode("utf-8", "replace") if is_u8 else "".join(out_c)
    return text, f"atob({len(payload)}B) -> [{py_expr}] -> {'utf8' if is_u8 else 'fromCharCode'}"


def scheme_atob_utf8_roundtrip(code: str, ns: dict):
    if not (re.search(r'\bdecodeURIComponent\s*\(\s*escape\s*\(\s*atob\b', code)
            or re.search(r'\bunescape\s*\(\s*escape\s*\(\s*atob\b', code)
            or re.search(r'\bdecodeURI\s*\(\s*atob\b', code)):
        return None, None
    blobs = _atob_blobs(code, ns)
    if not blobs: return None, None
    _, raw = blobs[0]
    try: text = raw.decode("utf-8")
    except Exception: text = raw.decode("latin-1")
    return text, f"atob({len(raw)}B) -> utf8-roundtrip"


def scheme_atob_reversed(code: str, ns: dict):
    if not re.search(r'atob\([^)]+\)\s*\.\s*split\s*\([^)]*\)\s*\.\s*reverse\s*\(\)\s*\.\s*join', code):
        return None, None
    blobs = _atob_blobs(code, ns)
    if not blobs: return None, None
    _, raw = blobs[0]
    return raw.decode("latin-1")[::-1], f"atob({len(raw)}B) -> reversed"


def scheme_charcode_array(code: str, ns: dict):
    m = _RE_CC_ARRAY.search(code)
    if not m: return None, None
    try: nums = [int(x) for x in m.group(1).split(",")]
    except ValueError: return None, None
    return "".join(chr(n & 0xFFFF) for n in nums), f"charCodeArray({len(nums)} ints)"


def scheme_hex_escape_blob(code: str, ns: dict):
    m = _RE_HEX_ESC.search(code)
    if not m: return None, None
    blob = m.group(0)
    bytes_ = bytes(int(blob[i+2:i+4], 16) for i in range(0, len(blob), 4))
    return bytes_.decode("utf-8", "replace"), f"hexEscape({len(bytes_)}B)"


# Pattern for the BW v2 / ErrTraffic v3 (May 2026 generation) loader layout:
#
#   (function(){
#     var KEY = <int>;
#     var BLOB = '<base64>';
#     function DECODER(s, k) {
#       s = atob(s);
#       /* arr[i] = s.charCodeAt(i) ^ k; */
#       /* utf-8 round-trip via TextDecoder or escape() fallback */
#     }
#     var X = DECODER(BLOB, KEY);
#     (new Function(X))();
#   })();
#
# The decoder function is one layer of indirection deeper than the generic
# atob_byte_transform scheme handles (which looks for charCodeAt at the top
# scope). This scheme matches the IIFE explicitly: identify the decoder
# function by its body (atob + charCodeAt + XOR), then find the call site
# DECODER(BLOB, KEY) to bind the arguments, then apply.
# The regex captures any 2-arg function whose body contains the canonical
# atob+XOR pattern, regardless of which parameter is the data and which is the
# key. We disambiguate at the call site by argument TYPE (str → blob, int → key).
_RE_BW_V2_DECODER_FN = re.compile(
    r'function\s+(\w+)\s*\(\s*(\w+)\s*,\s*(\w+)\s*\)\s*\{[^}]*?'
    r'\batob\s*\([^)]+\)[^}]*?'
    r'\.charCodeAt\s*\([^)]+\)\s*\^\s*(?:\2|\3)'
    r'[^}]*?\}',
    re.S
)


def scheme_bw_v2_iife_xor(code: str, ns: dict):
    """Match the ErrTraffic v3 (BW v2 generation) IIFE-wrapped XOR loader.
    The decoder is defined as a nested function and called with (BLOB, KEY)
    explicit args. Mirrors the kit's exact JS: atob → byte XOR → utf-8 with
    `decodeURIComponent(escape(...))` fallback.

    Returns (decoded_text, info_str) on success, or (None, reason_str)."""
    m = _RE_BW_V2_DECODER_FN.search(code)
    if not m: return None, None
    fn_name, src_param, key_param = m.group(1), m.group(2), m.group(3)
    # Find a USABLE call site: FN_NAME(BLOB, KEY) OR FN_NAME(KEY, BLOB). Match
    # ALL occurrences and skip the function signature itself (whose args are
    # the parameter names s,k which aren't in the page namespace). Pick the
    # first call whose two args resolve to a (str, int) pair in either order.
    call_re = re.compile(rf'\b{re.escape(fn_name)}\s*\(\s*(\w+)\s*,\s*(\w+)\s*\)')
    blob = key = None
    chosen_args = (None, None)
    for cm in call_re.finditer(code):
        a1, a2 = cm.group(1), cm.group(2)
        # Skip the function-definition signature line (args are parameter names)
        if {a1, a2} == {src_param, key_param}: continue
        v1, v2 = ns.get(a1), ns.get(a2)
        if isinstance(v1, str) and isinstance(v2, int):
            blob, key, chosen_args = v1, v2, (a1, a2); break
        if isinstance(v2, str) and isinstance(v1, int):
            blob, key, chosen_args = v2, v1, (a1, a2); break
    if blob is None or key is None:
        return None, (f"BW-v2 decoder fn `{fn_name}` defined but no usable "
                      f"(blob,key) call site found in code")
    a1, a2 = chosen_args
    # Sanity-check XOR key is a single byte
    if not (0 <= key <= 0xFF):
        return None, f"BW-v2 XOR key out of byte range: {key}"
    # Decode: atob(blob) -> bytes ^ key -> utf-8 (with the kit's escape fallback)
    try:
        raw = _b64(blob)
    except Exception as e:
        return None, f"BW-v2 base64 decode failed: {e}"
    out = bytes(b ^ key for b in raw)
    try:
        text = out.decode("utf-8")
    except UnicodeDecodeError:
        # Mirror the kit's `decodeURIComponent(escape(tmp))` fallback by reading
        # the bytes as latin-1 first then UTF-8 — for our purposes treating the
        # bytes as latin-1 captures whatever the loader meant.
        text = out.decode("latin-1")
    return text, (f"BW-v2 IIFE XOR: fn={fn_name}, blob={a1 if blob is v1 else a2} "
                  f"({len(raw)}B), key=0x{key:02x} ({key})")


SCHEMES = [
    # Order matters — most specific first. The BW v2 IIFE matcher catches
    # explicit `decoder(BLOB, KEY)` calls which the generic top-scope
    # atob_byte_transform misses (it can't reach through the function
    # indirection).
    ("bw_v2_iife_xor",       scheme_bw_v2_iife_xor),
    ("atob_byte_transform",  scheme_atob_byte_transform),
    ("atob_utf8_roundtrip",  scheme_atob_utf8_roundtrip),
    ("atob_reversed",        scheme_atob_reversed),
    ("charcode_array",       scheme_charcode_array),
    ("hex_escape_blob",      scheme_hex_escape_blob),
]


def is_obfuscated(code: str) -> bool:
    if "atob(" in code and ("charCodeAt" in code or "fromCharCode" in code): return True
    if "atob(" in code and ("decodeURIComponent" in code or "unescape(" in code): return True
    if _RE_CC_ARRAY.search(code): return True
    if _RE_HEX_ESC.search(code): return True
    return False


def decode_layer(code: str, ns: dict):
    last_reason = "no recognized scheme"
    for name, fn in SCHEMES:
        try: text, info = fn(code, ns)
        except Exception as e: last_reason = f"{name} raised: {e}"; continue
        if text is not None: return text, name, info
        if info: last_reason = f"{name}: {info}"
    return None, None, last_reason


def decode_chain(code: str, page_ns: dict, max_depth: int = 8):
    methods, cur, depth = [], code, 0
    while depth < max_depth and is_obfuscated(cur):
        local_ns = scrape_namespace(cur, page_ns)
        text, name, info = decode_layer(cur, local_ns)
        if text is None:
            methods.append({"scheme": "[stop]", "info": info}); break
        methods.append({"scheme": name, "info": info})
        cur = text; depth += 1
    return cur, methods


# ============================================================================
# Classifiers
# ============================================================================
_ETH_RPC_HOST_RE  = re.compile(
    r'https?://(?:[a-z0-9-]+\.)*'
    r'(?:publicnode\.com|drpc\.org|lava\.build|nodies\.app|pokt\.network|alchemy\.com|'
    r'infura\.io|quicknode\.com|chainstack\.com|getblock\.io|subquery\.network|'
    r'ankr\.com|blastapi\.io|llamarpc\.com|blockpi\.network|polygonscan\.com|'
    r'bnbchain\.org|binance\.org|onfinality\.io)/?[^\s\'"<>)\]}]*', re.I)
_ETH_ADDR_RE       = re.compile(r"['\"](0x[a-fA-F0-9]{40})['\"]")
_ETH_SELECTOR_RE   = re.compile(r"data\s*:\s*['\"]0x([a-fA-F0-9]{8,16})['\"]"
                                r"|data\s*:\s*['\"]0x['\"]\s*\+\s*(\w+)"
                                # BW v2 generation: 'FUNCTION_SELECTOR:"b68d1809"' inside
                                # a CONTRACT_CONFIG object — the kit author's modern layout.
                                r"|(?:FUNCTION_SELECTOR|methodSelector|FN_SELECTOR|selectorHex)"
                                r"\s*[:=]\s*['\"]0?x?([a-fA-F0-9]{8})['\"]")
_ETH_SEL_VAR_RE    = re.compile(r"""\b(\w+)\s*=\s*['"]([a-fA-F0-9]{6,16})['"]""")
_ETH_CALL_RE       = re.compile(r"method\s*:\s*['\"]eth_call['\"]", re.I)
_CHAIN_HINTS = [
    ("polygon",  r'polygon|matic|pokt'),
    ("bsc",      r'\bbsc\b|binance|bnb-chain|bnbchain|bsc-?mainnet'),
    ("bsc-testnet", r'bsc-?testnet|data-seed-prebsc'),
    ("ethereum", r'\beth(?:ereum)?(?!_)|mainnet\.infura|eth-mainnet'),
    ("base",     r'base-rpc|basemainnet|base\.org'),
    ("arbitrum", r'arbitrum'),
    ("optimism", r'optimism\.io|op-mainnet'),
]
# Shell-command name match. Every alternative is anchored with leading + trailing
# \b so substring matches inside JS identifiers don't fire — `confirm(`,
# `mshtag.example.com`, `curlservice`, `bitsadminUI`, `loadFirmware`, etc. all
# used to false-positive against `irm\b[^\n]{0,200}` / `mshta[^\n"'`]{0,300}` /
# `curl[^\n"'`]{0,300}` / `bitsadmin[^\n"'`]{0,300}`. The fix is two-stage:
# (1) `_CMD_NAME_RE` finds candidate command-token positions with strict
# word-boundaries on both sides; (2) for ambiguous short tokens (iwr/irm/iex/
# curl), `_find_cmd_runs` verifies a PS/cmdline discriminator (URL, flag,
# $variable, ScriptBlock, FromBase64, pipe→iex, .ps1/.bat/.exe etc.) is present
# in the surrounding window. `_CMD_RE` is kept as a back-compat alias for any
# legacy callsites that may grow elsewhere — it behaves the same as the
# old monolithic regex would have, but is now a strict-boundary union that
# `findall` returns the same shape from.
_CMD_NAME_RE = re.compile(
    r'\b('
    r'powershell(?:\.exe)?|pwsh(?:\.exe)?|mshta(?:\.exe)?|msiexec(?:\.exe)?|'
    r'cmd(?:\.exe)?\s+/c|certutil(?:\.exe)?|bitsadmin(?:\.exe)?|'
    r'wscript(?:\.exe)?|cscript(?:\.exe)?|regsvr32(?:\.exe)?|rundll32(?:\.exe)?|'
    r'Invoke-Expression|Invoke-WebRequest|Start-Process|'
    r'iwr|irm|iex|curl'
    r')\b',
    re.I)

_AMBIGUOUS_CMDS = {'iwr', 'irm', 'iex', 'curl'}

_CMD_DISCRIMINATOR_RE = re.compile(
    r'(?:https?://|\s-[A-Za-z]|\|\s*i?e[xrm]\b|/c\s|/qn\b|/s\s|/i\s|'
    r'\$[A-Za-z_]\w*|FromBase64String|ScriptBlock|::Create|'
    r'-enc(?:odedCommand)?\b|-w\s+(?:hidden|h)\b|-nop\b|-noprofile\b|'
    r'\.ps1\b|\.vbs\b|\.bat\b|\.exe\b|\.msi\b|\.ocx\b|\.scr\b)',
    re.I)


# Per-command tail-termination policy. Mirrors the old _CMD_RE's behavior:
# - Process launchers (powershell, pwsh, mshta, msiexec, cmd /c, certutil, ...)
#   terminate at newline / quote / backtick. The launcher line is usually a
#   single token like `powershell.exe -enc <b64>` and quotes in the JS source
#   are reliable termination markers.
# - Invoke-Expression / Invoke-WebRequest / Start-Process / iex / irm / iwr
#   capture through escaped quotes (only `\n` terminates) because they often
#   appear inside JSON-stringified PS where the tail contains `\"`.
_CMD_TERMINATOR_STRICT = '\n"\'`'   # newline, quote, backtick
_CMD_TERMINATOR_LOOSE  = '\n'        # newline only

_CMD_LOOSE_TAIL_NAMES = {
    "invoke-expression", "invoke-webrequest", "start-process",
    "iex", "irm", "iwr",
}


def _find_cmd_runs(text: str) -> list[str]:
    """Locate shell-command runs in `text`. Returns each run captured up to
    the appropriate terminator (newline only for Invoke-X / Start-Process /
    short PS aliases — to allow capture through JSON-escaped quotes; newline
    + quote + backtick for the heavyweight launchers).

    For ambiguous short tokens (irm / iex / iwr / curl), a PowerShell/cmdline
    discriminator (URL, flag, `$var`, ScriptBlock, FromBase64,
    `.ps1/.vbs/.exe/.msi/.ocx`, pipe-to-iex, etc.) must appear within an
    80-char window starting at the token — otherwise the candidate is JS
    identifier noise (e.g. `confirm(` → `irm(...)`, `curlservice`,
    `loadFirmware`, `iexports`) and is dropped."""
    runs: list[str] = []
    for m in _CMD_NAME_RE.finditer(text):
        raw = (m.group(1) or "")
        name = raw.lower().split('.')[0].split()[0]
        start = m.start()
        cap   = 400 if name in {"powershell", "pwsh"} else 300
        term  = _CMD_TERMINATOR_LOOSE if raw.lower() in _CMD_LOOSE_TAIL_NAMES else _CMD_TERMINATOR_STRICT
        end = start
        for i in range(start, min(start + cap, len(text))):
            ch = text[i]
            if ch in term:
                break
            end = i + 1
        run = text[start:end]
        if name in _AMBIGUOUS_CMDS:
            window = text[start:start + 80]
            if not _CMD_DISCRIMINATOR_RE.search(window):
                continue
        runs.append(run)
    return runs


# Back-compat shim: a callable with `.findall(text)` semantics matching the
# old monolithic regex (returns each command run as a string). Any newly-
# written code should call `_find_cmd_runs` directly.
class _CmdReShim:
    @staticmethod
    def findall(text: str) -> list[str]:
        return _find_cmd_runs(text)

_CMD_RE = _CmdReShim()
_FB64_RE   = re.compile(r'FromBase64String\(\s*[\'"]([A-Za-z0-9+/=]{12,})[\'"]', re.I)
_AES_RE    = re.compile(r'RijndaelManaged|AesManaged|CreateDecryptor|TransformFinalBlock|Security\.Crypto', re.I)
_CFID_RE   = re.compile(r'(?:Cloudflare\s*ID|Verification\s*code|Code\s*Verification|Ray\s*ID)\s*[:=]\s*([0-9a-fA-F]{6,})', re.I)
_CLIP_RE   = re.compile(r'navigator\.clipboard\.writeText|document\.execCommand\(\s*[\'"]copy|'
                        r'\.value\s*=\s*[\'"`][^\'"`]{20,}', re.I)
_TDS_RE    = re.compile(r'(?:webanalytics-cdn|fp-collector|fingerprintjs|adsbeacon|tracksdk)\.[a-z]{2,15}', re.I)
_OS_GATE_RE = re.compile(r'/Windows/\.test|/Mac\s*OS/\.test|/iPhone\|iPad/\.test|navigator\.userAgent', re.I)
_DBG_GATE_RE = re.compile(r'\bdebugger\s*;|performance\.now\(\)\s*[-+]\s*\w+\s*>\s*\d+', re.I)
_COOKIE_GATE_RE = re.compile(r"document\.cookie\.indexOf\(\s*['\"]([\w_-]+)=", re.I)
_URL_RE  = re.compile(r'https?://[^\s\'"<>)\]}`]+', re.I)
_IP_RE   = re.compile(r'\b(?:\d{1,3}\.){3}\d{1,3}(?::\d{1,5})?\b')


def _defang(u: Any) -> Any:
    if not isinstance(u, str): return u
    if "://" in u:
        sch, rest = u.split("://", 1)
        return f"{sch.replace('http','hxxp')}://{rest.replace('.', '[.]', 1)}"
    return u.replace(".", "[.]")


def _refang(s: str) -> str:
    """Reverse: '[.]'/'(.)'/'hxxp' -> '.'/'http'."""
    s = s.replace("[.]", ".").replace("(.)", ".").replace("[dot]", ".").replace("{.}", ".")
    s = re.sub(r'\bhxxp(s?)://', r'http\1://', s, flags=re.I)
    return s


_URL_DEFANG_RE = re.compile(r'\bhttps?://[A-Za-z0-9._~%/:?#\[\]@!$&\'()*+,;=-]+', re.I)

def _defang_urls_in_text(s: str) -> str:
    """Defang every http(s) URL substring inside `s` (for terminals that
    auto-link URLs). Replaces scheme `http`→`hxxp` and the FIRST `.` in the
    host with `[.]`. Used when we render multi-line text bodies (clipboard
    PS plaintext, dropper PS, recovered loader JS) so a hot terminal doesn't
    accidentally hyperlink a live C2."""
    if not s: return s
    def _one(m):
        u = m.group(0)
        sch, rest = u.split("://", 1)
        return f"{sch.replace('http','hxxp')}://{rest.replace('.', '[.]', 1)}"
    return _URL_DEFANG_RE.sub(_one, s)


def classify_etherhiding(text: str) -> dict | None:
    rpcs = sorted({m.group(0).rstrip('/?,') for m in _ETH_RPC_HOST_RE.finditer(text)})
    addrs = sorted({m.group(1) for m in _ETH_ADDR_RE.finditer(text)})
    has_eth_call = bool(_ETH_CALL_RE.search(text))
    score = (1 if has_eth_call else 0) + (1 if addrs else 0) + (1 if len(rpcs) >= 2 else 0)
    if score < 2: return None
    sel = None
    m = _ETH_SELECTOR_RE.search(text)
    if m:
        # groups: (1) literal 0x... in data, (2) var-name in data:0x+var,
        # (3) FUNCTION_SELECTOR/methodSelector literal — BW v2 layout
        raw = m.group(1) or m.group(3) or m.group(2)
        if raw and len(raw) in (8, 16) and all(c in "0123456789abcdefABCDEF" for c in raw):
            sel = raw.lower()
        elif raw:
            for vm in _ETH_SEL_VAR_RE.finditer(text):
                if vm.group(1) == raw and len(vm.group(2)) in (8, 16):
                    sel = vm.group(2).lower(); break
    chain = "unknown"
    for label, pat in _CHAIN_HINTS:
        if re.search(pat, " ".join(rpcs).lower()): chain = label; break
    selector_full = f"0x{sel}" if sel else None
    attribution = None
    for a in addrs:
        att = lookup_actor(a)
        if att: attribution = {"contract_matched": a, **att}; break
    return {
        "scheme":              "etherhiding",
        "chain":               chain,
        "contract_addresses":  addrs,
        "method_selector":     selector_full,
        "selector_info":       lookup_selector(selector_full),
        "rpc_pool":            rpcs,
        "rpc_pool_defanged":   [_defang(u) for u in rpcs],
        "wall_reason":         ("next-stage URL/JS is stored in contract storage and returned by "
                                "eth_call; cannot be recovered statically without an RPC fetch"),
        "actor_attribution":   attribution,
    }


def classify_clipboard_payload(text: str) -> dict | None:
    if not _CLIP_RE.search(text): return None
    arg = None
    m = re.search(r'navigator\.clipboard\.writeText\(\s*(["\'`])(.+?)\1', text, re.S)
    if m: arg = m.group(2)
    if arg is None:
        m = re.search(r'navigator\.clipboard\.writeText\(\s*(\w+)\s*\)', text)
        if m:
            mm = re.search(rf'\b{re.escape(m.group(1))}\s*=\s*(["\'`])(.+?)\1', text, re.S)
            if mm: arg = mm.group(2)
    # NOTE: the clipboard argument is the canonical IOC for ClickFix research —
    # it IS the malicious PowerShell command victims paste. Truncation would
    # destroy CTI fidelity, so the full string is stored verbatim. The
    # `clipboard_arg_excerpt` field is preserved as a back-compat alias for
    # any existing JSONL consumers; both fields contain the SAME full string.
    return {
        "scheme":                 "clipboard_payload",
        "sink":                   ("navigator.clipboard.writeText" if "writeText" in text
                                   else "execCommand('copy')"),
        "clipboard_arg":          arg,
        "clipboard_arg_excerpt":  arg,
        "clipboard_arg_length":   len(arg) if arg else None,
    }


def classify_aes_kit(text: str) -> dict | None:
    if not _AES_RE.search(text): return None
    blobs = _FB64_RE.findall(text)
    cfids = [m.group(1) for m in _CFID_RE.finditer(text)]
    return {
        "scheme":           "aes_kit",
        "fromBase64_blobs": [{"len": len(b), "head": b[:48]} for b in blobs[:6]],
        "labeled_ids":      cfids[:6],
        "note":             ("RijndaelManaged/AES kit (key+IV+ciphertext as base64, "
                             "scriptblock-invoked plaintext) — N1 AES-wave family"),
    }


def classify_powershell_command(text: str) -> dict | None:
    # Full commands kept verbatim — these are the kit's canonical IOCs.
    # No 400-char per-command truncation and no 8-command cap (a single page
    # can legitimately carry 10+ distinct PS variants for different OSes or
    # campaign IDs, and the cmdline tail often holds the panel URL + token).
    cmds = sorted({c.strip() for c in _CMD_RE.findall(text)})
    if not cmds: return None
    return {"scheme": "powershell_command", "commands": cmds}


# Outer rolling-XOR-hex clipboard wrapper used by the BW v2 generation. The
# captured clipboard string is NOT the dropper directly — it's:
#     $K='<alpha key>'; $D='<long hex>'; $R='';
#     <loop over $D 2 hex chars at a time>{ $R += [char]( ToInt32($D[i:i+2],16)
#                                            -bxor [int][char]$K[(i/2) % $K.Length] ) }
#     &([ScriptBlock]::Create($R))   |  iex $R  |  .($env:ComSpec[4,26,25]-join'') $R
# The XOR key index is the BYTE index (position/2), confirmed across every
# observed sample ($p/2%$k.Length, $_%$key.Length with $_=0..len/2-1, $z/2%).
_RE_OUTER_XOR_KEYREF = re.compile(r'\[int\]\[char\]\$(\w+)\[')
_RE_OUTER_XOR_HEXVAR = re.compile(r"\$(\w+)\s*=\s*'([0-9a-fA-F]{40,})'")

def _xor_rolling(raw: bytes, key: str) -> str:
    """Rolling single-key XOR (key repeats over the byte buffer). Returns the
    decoded string (UTF-8 preferred, latin-1 fallback). Pure arithmetic."""
    kb = key.encode("latin-1", "replace")
    out = bytes(b ^ kb[i % len(kb)] for i, b in enumerate(raw))
    try:
        return out.decode("utf-8")
    except UnicodeDecodeError:
        return out.decode("latin-1")


# A decoded inner PS is "plausible" if it reads as ASCII-ish PowerShell/URL
# text rather than XOR garbage. Used to validate fallback key guesses so a
# wrong (key, data) pairing is rejected instead of emitting noise.
def _looks_like_decoded_ps(s: str) -> bool:
    if not s:
        return False
    printable = sum(1 for c in s if 32 <= ord(c) < 127 or c in "\r\n\t")
    if printable / max(1, len(s)) < 0.85:
        return False
    low = s.lower()
    return bool(re.search(r"https?://", s) or "iwr" in low or "invoke-" in low
                or "[byte[]]" in low or "frombase64string" in low
                or "/api/index.php" in low or "downloadstring" in low
                or "new-object" in low or "iex" in low)


def decode_outer_xor_clipboard(text: str) -> dict | None:
    """Statically decode the BW v2 outer rolling-XOR-hex clipboard wrapper.
    Returns {ok, key, hex_len, decoded, invocation, key_source} or None if the
    shape isn't present. Pure arithmetic — never executes anything.

    Two key-extraction strategies (the second makes us robust to the kit
    renaming/re-shaping its invocation gadget, observed on newer panels whose
    /api/init `token` carries this wrapper):
      A. GADGET: the documented `[int][char]$KEYVAR[...]` index gadget names the
         key variable explicitly — most reliable, used by the bulk of samples.
      B. INFERENCE: when the gadget isn't present but a `-bxor` is, treat the
         largest hex-blob assignment as the data and try every short
         single-quoted *non-hex* string literal as the candidate key, accepting
         the first whose decode reads as plausible PowerShell/URL text.
    """
    # Collect every long-hex assignment ($var='<40+ hex>') as data candidates.
    hexes = sorted({m.group(2) for m in _RE_OUTER_XOR_HEXVAR.finditer(text)},
                   key=len, reverse=True)

    # ── Strategy A: explicit key gadget ───────────────────────────────────────
    kref = _RE_OUTER_XOR_KEYREF.search(text)
    if kref and hexes:
        key_var = kref.group(1)
        km = re.search(rf"\${re.escape(key_var)}\s*=\s*'([^']{{1,64}})'", text)
        if km:
            key = km.group(1)
            hexstr = hexes[0]
            if key and len(hexstr) % 2 == 0:
                try:
                    raw = bytes.fromhex(hexstr)
                    decoded = _xor_rolling(raw, key)
                    return {"ok": True, "key": key, "hex_len": len(hexstr),
                            "decoded": decoded, "key_source": "gadget",
                            "invocation": _xor_invocation(text)}
                except ValueError:
                    pass

    # ── Strategy B: inference (no gadget, but -bxor + hex blob present) ─────────
    if not hexes or "-bxor" not in text.lower():
        return None
    # Candidate keys: short single-quoted literals that are NOT themselves the
    # hex data buffer. Real XOR keys are short (6–16 chars), so we restrict to
    # 1–32 chars and CAP the candidate count — this both improves precision and
    # bounds work so a panel can't DoS the scanner with thousands of decoy
    # string literals (each guess is an O(n) XOR + plausibility scan).
    cand_keys: list[str] = []
    seen_k: set[str] = set()
    for m in re.finditer(r"'([^']{1,32})'", text):
        v = m.group(1)
        if v in seen_k or v in hexes:
            continue
        if re.fullmatch(r"[0-9a-fA-F]+", v) and len(v) >= 40:
            continue
        seen_k.add(v)
        cand_keys.append(v)
    # Real keys are short alpha-ish strings; try those first, cap the total.
    cand_keys.sort(key=len, reverse=True)
    cand_keys = cand_keys[:48]
    for hexstr in hexes[:3]:
        if len(hexstr) % 2:
            continue
        try:
            raw = bytes.fromhex(hexstr)
        except ValueError:
            continue
        for key in cand_keys:
            if not key:
                continue
            decoded = _xor_rolling(raw, key)
            if _looks_like_decoded_ps(decoded):
                return {"ok": True, "key": key, "hex_len": len(hexstr),
                        "decoded": decoded, "key_source": "inferred",
                        "invocation": _xor_invocation(text)}
    return None


def _xor_invocation(text: str) -> str | None:
    """Identify which gadget runs the decoded string (informational only)."""
    if re.search(r'\[ScriptBlock\]::Create', text, re.I):        return "ScriptBlock::Create"
    if re.search(r'\biex\b|\bInvoke-Expression\b', text, re.I):   return "iex"
    if re.search(r'\$env:ComSpec\[', text):                      return "ComSpec-index (iex)"
    return None


# ErrTraffic BW v2 dropper internals (operate on the DECODED inner PowerShell).
_RE_DL_URL    = re.compile(r"(https?://[^\s'\"`]+/api/index\.php\?[^\s'\"`]*?\ba=dl\b[^\s'\"`]*)")
_RE_7Z_URL    = re.compile(r"(https?://[^\s'\"`]+/api/7z\.exe)")
_RE_HEX64_KV  = re.compile(r"[?&]([A-Za-z0-9_]{1,16})=([0-9a-fA-F]{32,128})\b")
# Any URL-param-value capture — used to grab the LITERAL `rlm=` value from
# the dropper PS (whatever the kit set it to: lure host literal,
# base64url-of-some-bytes, theme keyword, etc.). NOT 64-hex — captures any
# 1+ non-delimiter chars so we get whatever the operator put there.
_RE_RLM_KV    = re.compile(r"[?&]rlm=([^&\s'\"`]+)")

def parse_bw_v2_dropper(text: str) -> dict | None:
    """Extract the full BW v2 chain from the decoded dropper PowerShell:
    real download URL, the panel host, the download token + its (randomized)
    param NAME found BY SHAPE (the param whose value is a 32-128 hex string,
    not by a hardcoded `uj`/`token` name — the kit randomizes it per panel),
    the 7z helper URL, the per-campaign 7z extraction password, and the
    invocation gadget. Returns None if no a=dl URL is present."""
    # Normalize PowerShell doubled single-quotes ('') → (') so embedded string
    # literals parse the same whether we got the raw or the un-nested form.
    norm = text.replace("''", "'")
    dm = _RE_DL_URL.search(norm)
    if not dm:
        return None
    dl_url = dm.group(1)
    # token by SHAPE: the dl URL param whose value is a long hex string.
    token = token_param = None
    for pm in _RE_HEX64_KV.finditer(dl_url):
        # skip the action param itself
        if pm.group(1).lower() in ("a", "action"):
            continue
        token_param, token = pm.group(1), pm.group(2)
        break
    from urllib.parse import urlparse
    panel_host = urlparse(dl_url).hostname
    sevenz_m = _RE_7Z_URL.search(norm)
    # 7z password: the literal assigned immediately after the '7z' marker
    #   ...$x='7z';$p='2026';...   /   ...$g7='7z';$h8='cJLFQDb8Tj';...
    pw_m = re.search(r"'7z'\s*;\s*\$\w+\s*=\s*'([^']*)'", norm)
    sevenz_pw = pw_m.group(1) if pw_m else None
    # all other dl params (decoys) for fingerprinting the panel's schema
    other_params = sorted({pm.group(1) for pm in re.finditer(r"[?&]([A-Za-z0-9_]{1,16})=", dl_url)}
                          - {"a", "action", token_param or ""})
    gadget = None
    if re.search(r'\[ScriptBlock\]::Create', norm, re.I):        gadget = "ScriptBlock::Create"
    elif re.search(r'\bStart-Process\b.*powershell', norm, re.I): gadget = "Start-Process powershell"
    elif re.search(r'\biex\b|\bInvoke-Expression\b', norm, re.I): gadget = "iex"
    # The LITERAL rlm= value — what the kit dropper actually wrote into the dl
    # URL. In some kits it's the lure host (`worldopportunitiesfund.com`); in
    # others it's a base64url-encoded blob of small bytes (`AXV5gj`/`AWNsbw`);
    # in others it's a theme keyword (`recaptcha`). Whatever it is, the panel
    # will only accept THAT value — guessing the lure host won't work when the
    # kit serves a base64url-encoded one. We extract the literal here and feed
    # it as the first `rlm` candidate downstream so we never have to guess.
    rlm_match = _RE_RLM_KV.search(dl_url)
    rlm_value = rlm_match.group(1) if rlm_match else None
    return {
        "dl_url":          dl_url,
        "dl_url_defanged": _defang(dl_url),
        "panel_host":      panel_host,
        "token":           token,
        "token_param":     token_param,
        "rlm_value":       rlm_value,
        "rlm_shape":       _classify_rlm_shape(rlm_value),
        "decoy_params":    other_params,
        "sevenz_helper_url": sevenz_m.group(1) if sevenz_m else None,
        "sevenz_password": sevenz_pw,
        "invocation":      gadget,
    }


def _classify_rlm_shape(v: str | None) -> str | None:
    """Categorize the literal rlm= value to help analysts reason about it.
    Useful when a fresh panel ships an rlm= shape we haven't seen before."""
    if not v: return None
    if "." in v and not any(c in v for c in "=+/"):       return "host_literal"
    if re.fullmatch(r'[A-Za-z0-9_-]{4,32}', v):
        # Could be base64url or theme keyword. The known BW v2 themes are
        # small and case-distinguished; b64url tends to mix case + digits.
        if v in ("browser","font","recaptcha","bsod","silent","cloudflare",
                 "cf_update","mac_recaptcha","mac_cloudflare","recaptcha_win_r"):
            return "theme_keyword"
        return "b64url_or_id"
    return "other"


# ── Byte-array numeric-XOR clipboard scheme ────────────────────────────────
# A distinct ErrTraffic clipboard generation (observed served as `loader_NN.ps1`
# directly off the panel's a=dl, e.g. slndcdnclaud.beer). The decoded URL is
# built from a byte array XOR'd against a single small integer key:
#     $k2949=51; $b=[byte[]](0x5b,0x47,...); -join ($b | %{ [char]($_ -bxor $k2949) })
# This recovers a SHELLCODE download URL; the PS then VirtualAlloc/CreateThread-
# injects the downloaded bytes. NOT the BW v2 string-XOR-hex shape — handled
# separately so both kit branches are covered.
_RE_BA_KEYDEF  = re.compile(r'\$(\w+)\s*=\s*(\d{1,3})\b')
_RE_BA_BYTES   = re.compile(r'\[byte\[\]\]\(\s*((?:0x[0-9a-fA-F]{1,2}\s*,?\s*){4,})\)')
_RE_BA_XORKEY  = re.compile(r'-bxor\s*\$(\w+)\b')

def decode_bytearray_xor_clipboard(text: str) -> dict | None:
    """Decode the byte-array numeric-XOR clipboard scheme. Returns
    {ok, key, n_bytes, decoded, urls} or None when the shape isn't present.
    Pure arithmetic — never executes anything.

    Robust to multiple byte arrays + key defs: for each `[byte[]](0x..)` literal
    it tries the key named by the nearest `-bxor $key`, then every small-int
    `$var=<n>` assignment, accepting whichever decode yields printable text
    (preferring one that contains a URL)."""
    arrays = _RE_BA_BYTES.findall(text)
    if not arrays:
        return None
    # All candidate integer keys defined in the snippet (0–255). Dedupe + cap so
    # a decoy-heavy snippet can't blow up the array×key decode loop.
    int_keys = list(dict.fromkeys(
        int(m.group(2)) for m in _RE_BA_KEYDEF.finditer(text)
        if 0 <= int(m.group(2)) <= 255))[:64]
    # The key explicitly used in a `-bxor $var` — resolve its int value.
    used = _RE_BA_XORKEY.search(text)
    if used:
        kv = used.group(1)
        km = re.search(rf'\${re.escape(kv)}\s*=\s*(\d{{1,3}})\b', text)
        if km:
            int_keys.insert(0, int(km.group(1)))
    if not int_keys:
        return None
    best = None
    for arr in arrays:
        try:
            bs = [int(x, 16) for x in re.findall(r'0x[0-9a-fA-F]{1,2}', arr)]
        except ValueError:
            continue
        if len(bs) < 4:
            continue
        for k in dict.fromkeys(int_keys):   # dedupe, preserve order
            dec = "".join(chr(b ^ k) for b in bs)
            printable = sum(1 for c in dec if 32 <= ord(c) < 127) / max(1, len(dec))
            if printable < 0.85:
                continue
            urls = re.findall(r'https?://[^\s\'"`<>]+', dec)
            cand = {"ok": True, "key": k, "n_bytes": len(bs),
                    "decoded": dec, "urls": urls}
            # Prefer a decode that yields a URL; otherwise keep first printable.
            if urls:
                return cand
            if best is None:
                best = cand
    return best


# Markers that tell us a fetched/served artifact is itself a clipboard /
# dropper *command* (an intermediate stage) rather than the final binary.
_RE_CLIP_DL_ENDPOINT = re.compile(r'/api/index\.php\?[^\s\'"`]*\ba=dl\b', re.I)
_RE_ANY_HTTP_URL     = re.compile(r'https?://[^\s\'"`<>]+')

_RE_PS_ENC = re.compile(
    r'(?:-e(?:nc(?:odedcommand)?)?)\s+([A-Za-z0-9+/=]{16,})', re.I)

def _decode_ps_encodedcommand(text: str) -> str | None:
    """Decode a PowerShell `-EncodedCommand <base64>` argument. PS expects
    base64-of-UTF-16LE; we also fall back to UTF-8 for the rare kit that uses
    plain `-e <b64utf8>`. Returns the inner command, or None when no encoded
    arg is present / it doesn't decode to plausible text. Never executes."""
    m = _RE_PS_ENC.search(text)
    if not m:
        return None
    blob = m.group(1)[:400_000]   # cap decode size (defense vs adversarial input)
    # base64 length must be a multiple of 4; pad if the capture clipped it.
    pad = (-len(blob)) % 4
    try:
        raw = _b64_std_decode(blob + "=" * pad)
    except Exception:
        return None
    if not raw:
        return None
    for enc in ("utf-16-le", "utf-8"):
        try:
            dec = raw.decode(enc)
        except UnicodeDecodeError:
            continue
        printable = sum(1 for c in dec if 32 <= ord(c) < 127 or c in "\r\n\t") / max(1, len(dec))
        if printable >= 0.85 and len(dec) >= 4:
            return dec
    return None


def _b64_std_decode(s: str) -> bytes:
    import base64
    return base64.b64decode(s, validate=False)


def decode_clipboard_command(text: str) -> dict:
    """Unified clipboard/dropper decoder — the single entry point used by every
    recovery path (init-token handler, served-script handler, lure-side loader).

    Tries each known wrapper scheme in most-specific → least-specific order and,
    on success, parses the DECODED inner text for the next stage (a kit a=dl
    endpoint, or a direct binary/shellcode URL). Designed to fail safely on
    unseen input: an unrecognized blob returns {ok: False} with a reason rather
    than raising, so the caller can still save the raw artifact.

    Returns:
      {ok, scheme, raw, decoded, invocation,
       next_stage: {url, kind, token, token_param, rlm, sevenz_password}}
      scheme ∈ aes_cbc | bw_v2_str_xor_hex | bytearray_num_xor | plaintext_ps | None
      next_stage.kind ∈ dl_endpoint | direct_binary | None
    """
    res = {"ok": False, "scheme": None, "raw": text, "decoded": None,
           "invocation": None, "reason": None,
           "next_stage": {"url": None, "kind": None, "token": None,
                          "token_param": None, "rlm": None,
                          "sevenz_password": None}}
    if not text or not isinstance(text, str):
        res["reason"] = "empty/non-string input"
        return res

    decoded = None
    # 1) AES-CBC triple-blob (v3-original clipboard)
    try:
        aes = try_recover_clipboard_aes(text)
    except Exception:
        aes = None
    if aes and aes.get("ok") and (aes.get("plaintext_excerpt") or aes.get("plaintext")):
        decoded = aes.get("plaintext_excerpt") or aes.get("plaintext")
        res.update(scheme="aes_cbc", decoded=decoded)
    # 2) BW v2 string-key rolling-XOR-hex
    if decoded is None:
        try:
            xr = decode_outer_xor_clipboard(text)
        except Exception:
            xr = None
        if xr and xr.get("decoded"):
            decoded = xr["decoded"]
            res.update(scheme="bw_v2_str_xor_hex", decoded=decoded,
                       invocation=xr.get("invocation"))
    # 3) byte-array numeric-XOR (shellcode-injector clipboard)
    if decoded is None:
        try:
            ba = decode_bytearray_xor_clipboard(text)
        except Exception:
            ba = None
        if ba and ba.get("decoded"):
            decoded = ba["decoded"]
            res.update(scheme="bytearray_num_xor", decoded=decoded)
    # 4) PowerShell -EncodedCommand <base64>: the inner command (often carrying
    #    the real download URL) is base64-of-UTF-16LE. Decode it so the URL
    #    surfaces. Generic ClickFix, not ErrTraffic-specific.
    if decoded is None:
        enc = _decode_ps_encodedcommand(text)
        if enc:
            decoded = enc
            res.update(scheme="ps_encodedcommand", decoded=decoded)
    # 5) FromBase64String blob whose decoded bytes hide a URL (e.g. the URL is
    #    itself base64'd inside an otherwise plain PS one-liner). Decode each
    #    blob and re-scan; accept only if a URL surfaces.
    if decoded is None and "frombase64string" in text.lower():
        _b64_tries = 0
        for bm in re.finditer(r"FromBase64String\(\s*['\"]([A-Za-z0-9+/=]{20,})['\"]", text, re.I):
            _b64_tries += 1
            if _b64_tries > 64:          # bound work on decoy-heavy input
                break
            blob = bm.group(1)[:400_000]  # cap per-blob decode size
            try:
                raw = _b64_std_decode(blob + "=" * ((-len(blob)) % 4))
            except Exception:
                continue
            for enc in ("utf-16-le", "utf-8", "latin-1"):
                try:
                    inner = raw.decode(enc)
                except UnicodeDecodeError:
                    continue
                if _RE_ANY_HTTP_URL.search(inner):
                    decoded = inner
                    res.update(scheme="base64_embedded_url", decoded=decoded)
                    break
            if decoded is not None:
                break
    # 6) already-plaintext command (PS / cmd / WSH) that carries a URL (generic
    #    ClickFix / unwrapped dropper, incl. the port-5506 MSXML/WinHTTP .vbs
    #    downloader cluster). Only accept when BOTH a fetchable URL AND a clear
    #    download/execution verb are present — so a bare lure URL or a benign
    #    `open "youtube"` decoy is NOT mislabeled a payload command.
    if decoded is None:
        if _RE_ANY_HTTP_URL.search(text) and re.search(
                r'\b(iwr|irm|iex|invoke-\w+|downloadstring|downloaddata|downloadfile|'
                r'new-object|webclient|net\.webclient|system\.net|webrequest|'
                r'start-process|start-bitstransfer|wget|curl|certutil|bitsadmin|'
                r'mshta|msiexec|regsvr32|rundll32|createobject|xmlhttp|winhttp|'
                r'msxml2|wscript|cscript)\b', text, re.I):
            decoded = text
            res.update(scheme="plaintext_ps", decoded=decoded)

    if decoded is None:
        res["reason"] = ("no known clipboard wrapper matched (not AES, not "
                         "string-XOR-hex, not byte-array-XOR, no plaintext URL "
                         "command). Raw artifact still saved for manual review.")
        return res

    res["ok"] = True
    # ── Next-stage extraction from the DECODED inner text ──────────────────────
    # Preferred: a BW v2 a=dl endpoint (token + randomized param + rlm + 7z pw).
    ns = res["next_stage"]
    if _RE_CLIP_DL_ENDPOINT.search(decoded):
        try:
            drop = parse_bw_v2_dropper(decoded)
        except Exception:
            drop = None
        if drop and drop.get("dl_url"):
            ns.update(url=drop["dl_url"], kind="dl_endpoint",
                      token=drop.get("token"), token_param=drop.get("token_param"),
                      rlm=drop.get("rlm_value"),
                      sevenz_password=drop.get("sevenz_password"))
            if not res.get("invocation"):
                res["invocation"] = drop.get("invocation")
            return res
    # Fallback: first plain http(s) URL = a direct binary/shellcode download.
    m = _RE_ANY_HTTP_URL.search(decoded)
    if m:
        ns.update(url=m.group(0).rstrip('\'");,'), kind="direct_binary")
    return res


# ── Loader-side intelligence extraction (per-panel BW v2 secrets) ──────────
# The BW v2 loader JS (typically a compromised WP plugin file like
# wp-content/plugins/file-updater-<hex>/assets/css.js) embeds the OPERATOR's
# panel-router contract + the AES-256-GCM API base key + the function selector
# used to read the panel URL off-chain. Recovering these three values from a
# single decoded loader lifts the kit's per-panel envelope decrypt from
# "decrypt FAILS with default key" to "decrypt SUCCEEDS with the panel's
# real key" — closing the top remaining capability gap.
_RE_LOADER_KEY      = re.compile(
    r"(?:const|let|var)\s+API_Q2_KEY_HEX\s*=\s*['\"]([0-9a-fA-F]{64})['\"]"
)
_RE_LOADER_CONTRACT = re.compile(
    r"CONTRACT_ADDRESS\s*:\s*['\"](0x[0-9a-fA-F]{40})['\"]"
)
_RE_LOADER_SELECTOR = re.compile(
    r"FUNCTION_SELECTOR\s*:\s*['\"]([0-9a-fA-F]{4,12})['\"]"
)


def extract_loader_intel(text: str) -> dict | None:
    """Recover the BW v2 loader's per-panel secrets from a decoded JS body.

    Returns a dict with `api_q2_key_hex` (the AES-256-GCM base key, REQUIRED
    for envelope decryption), `contract_address` (the on-chain panel-router,
    used by the loader's `getDomain()` call), `function_selector` (the read
    selector, almost always `b68d1809` on BW v2 = Aeternum-style getDomain
    pattern), or None when no key literal is present (the input isn't a BW v2
    loader — it's a plain WP-page script, a different kit's loader, etc.).

    The presence of `API_Q2_KEY_HEX` is the BW-v2 loader's strongest single
    fingerprint, so we anchor on it; the contract + selector are recovered
    on a best-effort basis and may be missing on stripped builds."""
    if not text: return None
    km = _RE_LOADER_KEY.search(text)
    if not km: return None
    cm = _RE_LOADER_CONTRACT.search(text)
    sm = _RE_LOADER_SELECTOR.search(text)
    # Confirm BW-namespace presence too. The API_Q2_KEY_HEX literal alone is
    # almost-unique but the BW namespace tokens are the operator's internal
    # name (the visible __BW_* identifiers + the "BrowserWarning:" prefix in
    # error strings, where "BW" stands for "BrowserWarning"). When present
    # we surface them so the report carries the kit-author-internal name.
    bw_markers = []
    for tok in ("__BW_SCRIPT_INITIALIZED_V2__", "__BW_SCRIPT_INITIALIZED__",
                 "__BW_MODE_RUN__", "__bwDecryptApiEnvelope",
                 "BrowserWarning:"):
        if tok in text: bw_markers.append(tok)
    return {
        "api_q2_key_hex":    km.group(1).lower(),
        "contract_address":  cm.group(1) if cm else None,
        "function_selector": (sm.group(1).lower() if sm else None),
        "kit_name_internal": "BrowserWarning (BW) — kit-author's name baked into the loader",
        "bw_markers_found":  bw_markers,
    }


# Process-lifetime registries — survive across analyze_html + fetch_panel_payload
# calls so a key recovered from lure A's loader carries over to lure B's payload
# fetch when both point at the same panel/contract. Thread-safe.
_BW_V2_KEYS_LOCK = threading.Lock()
_BW_V2_KEYS_OBSERVED: dict[str, dict] = {}   # panel_host (lc) -> {key, contract, source, observed_at}

# Per-run envelope-probe cache. The /api/cfg + /api/settings endpoints return
# the operator's live config (same for every lure pointing at the panel), so
# at sweep scale we MUST cache by panel_host or 12K lures → 24 panels would
# trigger 12K probes instead of 24. Thread-safe; populated by the lure-mode
# comprehensive flow and panel-mode comprehensive flow share the same cache.
_ENVELOPE_PROBE_CACHE_LOCK = threading.Lock()
_ENVELOPE_PROBE_CACHE: dict[str, dict] = {}   # panel_host (lc) -> envelope_recovery dict

# Same rationale for the admin/install-panel probe: at sweep scale thousands of
# lures resolve to a handful of panels; we must probe each panel's /admin surface
# ONCE, not once per lure. Keyed by panel origin (scheme+host, lc). Thread-safe.
_ADMIN_PROBE_CACHE_LOCK = threading.Lock()
_ADMIN_PROBE_CACHE: dict[str, dict] = {}

# Same caching rationale for the full known-endpoint enumeration.
_ENDPOINT_PROBE_CACHE_LOCK = threading.Lock()
_ENDPOINT_PROBE_CACHE: dict[str, dict] = {}


def get_or_probe_envelope(panel_url: str, *, host: str | None = None,
                          timeout: int = 15, verify_tls: bool = True,
                          progress_fh=None) -> dict:
    """Cached wrapper around probe_panel_envelopes() — guarantees one probe per
    panel_host across the whole run. Returns the same dict shape; sets a
    `cache_hit: True` field on cached returns so the renderer can show it
    was a re-use rather than a fresh fetch. Thread-safe."""
    from urllib.parse import urlparse
    cache_key = (host or urlparse(panel_url).hostname or "").lower()
    if not cache_key:
        return probe_panel_envelopes(panel_url, host=host, timeout=timeout,
                                     verify_tls=verify_tls, progress_fh=progress_fh)
    with _ENVELOPE_PROBE_CACHE_LOCK:
        cached = _ENVELOPE_PROBE_CACHE.get(cache_key)
    if cached is not None:
        # Shallow copy + mark cache hit so the consuming report's local state
        # mutations don't pollute the cached canonical object.
        out = dict(cached); out["cache_hit"] = True
        return out
    fresh = probe_panel_envelopes(panel_url, host=host, timeout=timeout,
                                  verify_tls=verify_tls, progress_fh=progress_fh)
    with _ENVELOPE_PROBE_CACHE_LOCK:
        _ENVELOPE_PROBE_CACHE.setdefault(cache_key, fresh)
    return fresh


def register_bw_v2_key(*, panel_host: str | None,
                        contract_address: str | None,
                        api_q2_key_hex: str,
                        source: str = "loader_extract") -> None:
    """Record an observed (panel_host, contract, key) triple in the kit-keys
    registry. Mutates ERRTRAFFIC_KIT['bw_v2_keys']['by_host'] and
    ['by_contract'] in-place so every subsequent envelope-decrypt picks up
    the per-panel key without rewiring."""
    if not api_q2_key_hex or not re.fullmatch(r'[0-9a-fA-F]{64}', api_q2_key_hex):
        return
    api_q2_key_hex = api_q2_key_hex.lower()
    ts = datetime.datetime.now(datetime.timezone.utc).isoformat(
        timespec="seconds").replace("+00:00", "Z")
    with _BW_V2_KEYS_LOCK:
        keys_cfg    = ERRTRAFFIC_KIT.setdefault("bw_v2_keys", {})
        by_host     = keys_cfg.setdefault("by_host", {})
        by_contract = keys_cfg.setdefault("by_contract", {})
        if panel_host:
            ph = panel_host.lower()
            by_host[ph] = api_q2_key_hex
            _BW_V2_KEYS_OBSERVED[ph] = {
                "key":         api_q2_key_hex,
                "contract":    (contract_address or "").lower() or None,
                "source":      source,
                "observed_at": ts,
            }
        if contract_address:
            by_contract[contract_address.lower()] = api_q2_key_hex


def resolve_bw_v2_key(*, panel_host: str | None,
                       contract_address: str | None) -> tuple[str | None, str]:
    """Look up the AES-256-GCM base key for a panel or contract. Returns
    (key_hex_or_None, source_label) so reports can show provenance. Lookup
    order: host-specific → contract-specific → kit-author default."""
    keys_cfg    = ERRTRAFFIC_KIT.get("bw_v2_keys", {}) or {}
    by_host     = keys_cfg.get("by_host", {}) or {}
    by_contract = keys_cfg.get("by_contract", {}) or {}
    if panel_host:
        k = by_host.get(panel_host.lower())
        if k: return k, "host_specific"
    if contract_address:
        k = by_contract.get(contract_address.lower())
        if k: return k, "contract_specific"
    default = keys_cfg.get("API_Q2_KEY_HEX")
    return (default, "default") if default else (None, "none")


# Panel → randomized download-token param name. The kit author picks a
# different param name per panel deployment so signature-based detection on
# `?uj=`/`?token=` fails. We seed this map from live FlareVM observations
# (clickchainDumps/, 2026-05-27); register_panel_token_param() extends it at
# runtime as classify_bw_v2_launcher recovers new ones.
_PANEL_TOKEN_PARAM_LOCK = threading.Lock()
_PANEL_TOKEN_PARAM_MAP: dict[str, str] = {
    "slndcdnclaud.beer":  "uj",
    "web-security.beer":  "token",
    "smtnscerver.beer":   "uc",
    "lsikjsns.beer":      "tj",
    "ntsnsdns.beer":      "vl",
    "nsservclod.beer":    "ujxm",
}


def register_panel_token_param(panel_host: str | None, token_param: str | None) -> None:
    """Record an observed panel → token_param mapping discovered by
    parse_bw_v2_dropper. Used by fetch_panel_payload to build dl URLs that
    use the panel's real randomized name instead of the global `uj=` guess."""
    if not panel_host or not token_param: return
    with _PANEL_TOKEN_PARAM_LOCK:
        _PANEL_TOKEN_PARAM_MAP[panel_host.lower()] = token_param


def resolve_panel_token_param(panel_host: str | None) -> tuple[str, str]:
    """Look up the per-panel token-param name. Returns (param_name, source).
    Falls back to `uj` (the most common BW v2 name) when no observation
    exists — Strategy 4's fallback chain handles the misses."""
    if panel_host:
        with _PANEL_TOKEN_PARAM_LOCK:
            p = _PANEL_TOKEN_PARAM_MAP.get(panel_host.lower())
        if p: return p, "observed"
    return "uj", "default"


def classify_bw_v2_launcher(text: str) -> dict | None:
    """Recognize the ErrTraffic v3 (BW v2 generation) clipboard PS launcher and
    statically recover its full chain. Handles BOTH layers:
      1. the OUTER rolling-XOR-hex wrapper (the raw clipboard string), decoded
         in-process to the inner dropper; and
      2. the INNER dropper PS itself (a plaintext launcher) if already decoded.

    Distinct from classify_aes_kit (the AES-CBC-wrapped v3 ORIGINAL). The token
    download-param name is RANDOMIZED per panel (observed: token / uc / tj / vl
    / ujxm / uj), so we find the token BY SHAPE (64-hex value), never by a fixed
    name. Also surfaces the per-campaign 7z extraction password — the key to
    opening the password-protected .7z dropper the kit serves."""
    outer = decode_outer_xor_clipboard(text)
    inner_text = outer["decoded"] if outer else text
    drop = parse_bw_v2_dropper(inner_text)
    if not drop:
        return None
    # Side-effect: record the observed (panel_host → token_param) mapping so
    # fetch_panel_payload's Strategy 4 can use the panel's REAL randomized
    # name instead of the global `uj=` fallback. The map persists for the
    # rest of the process (and across batched lures via _PANEL_TOKEN_PARAM_MAP).
    register_panel_token_param(drop.get("panel_host"), drop.get("token_param"))
    has_iwr        = bool(re.search(r'\bInvoke-WebRequest\b|\biwr\b', inner_text, re.I))
    has_start_proc = bool(re.search(r'\bStart-Process\b', inner_text, re.I))
    has_7z         = bool(drop.get("sevenz_helper_url") or drop.get("sevenz_password"))
    confidence = 0.97 if (has_iwr and (has_7z or has_start_proc)) else 0.85
    out = {
        "scheme":                "bw_v2_launcher",
        "kit":                   "ErrTraffic v3 (BW v2 generation)",
        # The kit author calls it "BrowserWarning" internally — visible in every
        # loader JS as the __BW_* namespace + the literal "BrowserWarning:"
        # error-string prefix. "BW v2" is the v2 generation of that codebase
        # (May 2026+). Public CTI (LevelBlue/Trinity/Censys) uses the umbrella
        # name "ErrTraffic v3" and doesn't distinguish BW v1 vs BW v2.
        "kit_name_origin":       "BW = BrowserWarning — kit-author internal name",
        "kit_signature_markers": ["__BW_SCRIPT_INITIALIZED_V2__", "__BW_MODE_RUN__",
                                   "__bwDecryptApiEnvelope", "BrowserWarning:"],
        "outer_layer":           ("rolling_xor_hex" if outer else "plaintext"),
        "outer_xor_key":         outer["key"] if outer else None,
        "outer_invocation":      outer["invocation"] if outer else None,
        "dl_url":                drop["dl_url"],
        "dl_url_defanged":       drop["dl_url_defanged"],
        "panel_host":            drop["panel_host"],
        "token":                 drop["token"],
        "token_param":           drop["token_param"],   # the per-panel randomized name
        "rlm_value":             drop["rlm_value"],     # LITERAL rlm= the kit set
        "rlm_shape":             drop["rlm_shape"],     # host_literal / theme_keyword / b64url_or_id / other
        "decoy_params":          drop["decoy_params"],
        "sevenz_helper_url":     drop["sevenz_helper_url"],
        "sevenz_password":       drop["sevenz_password"],
        "invocation":            drop["invocation"],
        "has_invoke_webrequest": has_iwr,
        "has_start_process":     has_start_proc,
        "confidence":            confidence,
        "note":                  ("BW v2 clipboard launcher fully recovered statically. The download "
                                  "token's URL param name is randomized per panel — found here by shape "
                                  "(64-hex value). The payload is a password-protected .7z opened with "
                                  "the recovered 7z password, then the inner .exe/.msi is run. Feed the "
                                  "token + token_param + src(=lure host, from ref=) to --payload-token to "
                                  "replay the panel download with the real victim-issued token."),
    }
    return out


def classify_tds_beacon(text: str) -> dict | None:
    hits = sorted({h for h in _TDS_RE.findall(text)})
    if not hits: return None
    return {"scheme": "tds_beacon", "hosts": hits, "hosts_defanged": [_defang(h) for h in hits]}


def classify_antianalysis_gate(text: str) -> dict | None:
    flags = {"scheme": "antianalysis_gate",
             "debugger_timing_gate": False, "os_device_gate": False,
             "os_device_excl": [], "cookie_dedup_names": []}
    hit = False
    if _DBG_GATE_RE.search(text): flags["debugger_timing_gate"] = True; hit = True
    if _OS_GATE_RE.search(text):
        excl = re.findall(
            r'\[\s*("(?:iOS|Android|mobile|tablet)")\s*(?:,\s*("(?:iOS|Android|mobile|tablet)")\s*)*\]',
            text)
        flags["os_device_gate"] = True
        flags["os_device_excl"] = sorted({s.strip('"') for tup in excl for s in tup if s})
        hit = True
    cookies = sorted(set(_COOKIE_GATE_RE.findall(text)))
    if cookies: flags["cookie_dedup_names"] = cookies; hit = True
    return flags if hit else None


CLASSIFIERS = [classify_etherhiding, classify_clipboard_payload, classify_aes_kit,
               classify_bw_v2_launcher,
               classify_powershell_command, classify_tds_beacon, classify_antianalysis_gate]


def classify(text: str) -> list[dict]:
    return [c for c in (fn(text) for fn in CLASSIFIERS) if c]


def extract_loose_iocs(text: str) -> dict:
    return {
        "urls":               sorted({_defang(u) for u in _URL_RE.findall(text)})[:30],
        "ips":                sorted({_defang(ip) for ip in _IP_RE.findall(text)})[:30],
        "labeled_ids":        sorted({m.group(1) for m in _CFID_RE.finditer(text)})[:8],
        "contract_addresses": sorted({m.group(1) for m in _ETH_ADDR_RE.finditer(text)}),
    }


# ============================================================================
# Passive HTTP fetch (--url, target list)
# ============================================================================
_BROWSER_UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
               "(KHTML, like Gecko) Chrome/130.0.0.0 Safari/537.36")


def fetch_url_passively(url: str, timeout: int = DEFAULT_FETCH_TIMEOUT,
                        max_bytes: int = DEFAULT_MAX_BYTES, verify_tls: bool = True,
                        extra_headers: dict | None = None
                        ) -> tuple[str, dict]:
    """Passive HTTP GET. Returns (body_text, meta_dict). meta now ALSO includes
    a `headers` dict (all response headers, case-insensitive) so downstream
    detectors (Cloudflare, WordPress) can read CF-RAY, Server, Link, etc."""
    if not url.startswith(("http://", "https://")):
        raise ValueError(f"URL must start with http(s)://  — got {url!r}")
    base_headers = {
        "User-Agent": _BROWSER_UA,
        "Accept":     "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
        "Accept-Language": "en-US,en;q=0.9",
        "Connection": "close",
    }
    if extra_headers: base_headers.update(extra_headers)
    req = urllib.request.Request(url, headers=base_headers)
    ctx = ssl.create_default_context() if verify_tls else ssl._create_unverified_context()
    started = datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z")
    with urllib.request.urlopen(req, timeout=timeout, context=ctx) as r:
        body = r.read(max_bytes)
        # Normalize headers into a plain dict (lower-keyed) — urllib returns a
        # case-insensitive HTTPMessage; we keep it readable for JSON serialization
        hdr = {k: v for k, v in r.headers.items()}
        meta = {
            "fetched_at":     started,
            "status":         r.status,
            "final_url":      r.url,
            "content_type":   r.headers.get("Content-Type"),
            "bytes_received": len(body),
            "truncated":      len(body) == max_bytes,
            "headers":        hdr,
        }
    enc = "utf-8"
    ct = meta["content_type"] or ""
    m = re.search(r'charset\s*=\s*([\w-]+)', ct, re.I)
    if m: enc = m.group(1)
    try: return body.decode(enc, errors="replace"), meta
    except LookupError: return body.decode("utf-8", errors="replace"), meta


# ============================================================================
# Passive on-chain resolver  (--resolve)
# ============================================================================
def rpc_call(rpc_url: str, method: str, params: list, timeout: int = DEFAULT_RPC_TIMEOUT) -> Any:
    req = urllib.request.Request(
        rpc_url, data=json.dumps({"jsonrpc": "2.0", "id": 1, "method": method,
                                   "params": params}).encode(),
        headers={"Content-Type": "application/json", "User-Agent": _BROWSER_UA},
        method="POST")
    with urllib.request.urlopen(req, timeout=timeout) as r:
        resp = json.loads(r.read())
    if "error" in resp:
        raise RuntimeError(f"RPC error: {resp['error']}")
    return resp.get("result")


def eth_call(rpc_url: str, contract: str, selector_hex: str,
             timeout: int = DEFAULT_RPC_TIMEOUT) -> str:
    if not selector_hex.startswith("0x"): selector_hex = "0x" + selector_hex
    if not contract.startswith("0x"):     contract = "0x" + contract
    return rpc_call(rpc_url, "eth_call",
                    [{"to": contract, "data": selector_hex}, "latest"], timeout=timeout) or ""


def decode_abi_string(hex_data: str, lax_drop_nulls: bool = True) -> str | None:
    """Decode an ABI-encoded `string` return. With lax_drop_nulls=True, behaves
    like ErrTraffic's _f395efb0() — reads length at chars 64-128, takes bytes
    from 128+, drops zeros, trims."""
    if not hex_data: return None
    if hex_data.startswith("0x"): hex_data = hex_data[2:]
    if len(hex_data) < 128: return None
    try: length = int(hex_data[64:128], 16)
    except ValueError: return None
    if length == 0 or length > 8192: return None
    data_hex = hex_data[128:128 + length * 2]
    if len(data_hex) < length * 2: return None
    raw = bytes.fromhex(data_hex)
    if lax_drop_nulls:
        return "".join(chr(b) for b in raw if b > 0).strip() or None
    try: return raw.decode("utf-8").rstrip("\x00").strip() or None
    except Exception: return None


# ── Generic contract-storage decoder cascade ───────────────────────────────
# When the on-chain return is NOT a plain ABI string (e.g. operator's 2nd
# contract returns a high-entropy blob, jobloom.info returns a hyphen-reverse-
# charSub-encoded string, Aeternum stores AES-GCM-encrypted bytes), we
# cascade through a series of decoder strategies and surface BOTH the best
# guess AND every attempt — so an analyst can pivot on the failure mode
# instead of seeing "got bytes, no decoder" and moving on.
def _looks_url_ish(s: str | None) -> bool:
    """Heuristic — does this look like a hostname/URL? Used to score decoder
    outputs. We accept domain-shaped (`foo.bar`), URL-shaped (`http(s)://`),
    and IP-shaped strings; reject if any control chars survived."""
    if not s or len(s) < 4 or len(s) > 512: return False
    if not all(0x20 <= ord(c) <= 0x7e for c in s): return False
    if s.startswith(("http://", "https://", "//")):              return True
    if re.fullmatch(r'[A-Za-z0-9.\-_/:?#&=+@~]{4,512}', s):
        if "." in s and any(c.isalpha() for c in s.rsplit(".", 1)[-1]): return True
        if re.fullmatch(r'(?:\d{1,3}\.){3}\d{1,3}(?::\d{1,5})?', s):     return True
    return False


def _printable_ratio(s: str) -> float:
    if not s: return 0.0
    return sum(1 for c in s if 0x20 <= ord(c) <= 0x7e) / len(s)


def _is_plausible_panel_host(s: str) -> bool:
    """Stricter than `_looks_url_ish` — for inputs that are about to be
    treated as a real C2 panel hostname/URL. Rejects long undotted alphanumeric
    runs (e.g. failed decoder output that's still printable but is just raw
    base-36/base-N storage bytes). A real panel URL must have:
      * a dot,
      * at least one label-with-alpha-chars (so `1.2.3.4` IPv4 also passes),
      * a TLD label of 2..24 chars made of letters only (or IPv4 numeric),
      * label segments of plausible DNS length (≤63).

    Note: this is intentionally conservative — if a kit author starts using
    base-N-encoded IPs we'd want to round-trip through `_is_plausible_panel_host`
    only AFTER decoding, never on raw bytes."""
    if not s or len(s) > 2048: return False
    if not all(0x20 <= ord(c) <= 0x7e for c in s): return False
    # Strip scheme if present
    from urllib.parse import urlparse as _urlparse  # module imports it inside fn scopes elsewhere
    if s.startswith(("http://","https://")):
        try:
            host = _urlparse(s).hostname or ""
        except Exception:
            return False
    elif s.startswith("//"):
        try:
            host = _urlparse("http:" + s).hostname or ""
        except Exception:
            return False
    else:
        host = s.split("/",1)[0].split(":",1)[0]
    if not host: return False
    if len(host) > 253: return False
    # IPv4 fast path
    if re.fullmatch(r'(?:\d{1,3}\.){3}\d{1,3}', host):
        return all(0 <= int(o) <= 255 for o in host.split("."))
    # DNS host check
    if "." not in host: return False
    labels = host.split(".")
    if any(not l or len(l) > 63 for l in labels): return False
    if any(not re.fullmatch(r'[A-Za-z0-9-]+', l) for l in labels): return False
    if any(l.startswith("-") or l.endswith("-") for l in labels): return False
    tld = labels[-1]
    if not re.fullmatch(r'[A-Za-z]{2,24}', tld): return False
    return True


def _decode_jobloom_hyphen_reverse(text: str) -> str | None:
    """The jobloom.info-cluster decoder: split on '-', reverse the parts,
    then for each part i interpret it as hex(num) and emit chr(num - i - 5)."""
    if not text or "-" not in text: return None
    parts = text.split("-")[::-1]
    out_chars = []
    for i, p in enumerate(parts):
        try:
            n = int(p, 16)
            c = n - i - 5
            if not (0 <= c < 0x10000): return None
            out_chars.append(chr(c))
        except ValueError:
            return None
    s = "".join(out_chars)
    return s if _printable_ratio(s) > 0.85 else None


_JOBLOOM_BASE36_ALPHABET = "0123456789abcdefghijklmnopqrstuvwxyz"

def _decode_jobloom_base36_position_shifted(text: str) -> str | None:
    """Jobloom-cluster generation-2 decoder (S29 finding — verbatim recovered
    from blockchaindev.in lure inline JS). The encoded string is a sequence of
    base-36 PAIRS (no separators); for each pair at chunk index i (i=0,1,2,…),
    we compute num = chars.indexOf(s[0])*36 + chars.indexOf(s[1]), then emit
    chr(num - i - 5). The JS source uses character index `i` stepping by 2, so
    the chunk index is `i//2` — which makes the offset (i//2) here.

    Validated on `0xf5966808a9ECbdb8794F568922809C52b0Fd2446` getServer():
        31 3e 3f 3c → 'h' 't' 't' 'p'
        full output: https://exactupdate.com;https://mothechurh.com;https://invokeupdate.com
    """
    if not text: return None
    # The encoded form MUST be even-length, all lowercase base-36 (0-9 a-z).
    # Empirically the encoded strings are 100+ chars; require ≥ 8 to avoid FPs.
    if len(text) < 8 or len(text) % 2: return None
    if not re.fullmatch(r'[0-9a-z]+', text): return None
    out_chars = []
    alpha = _JOBLOOM_BASE36_ALPHABET
    for chunk_idx, i in enumerate(range(0, len(text), 2)):
        pair = text[i:i+2]
        # both digits must be valid base-36
        try:
            num = alpha.index(pair[0]) * 36 + alpha.index(pair[1])
        except ValueError:
            return None
        c = num - chunk_idx - 5
        if not (0 <= c < 0x10000): return None
        out_chars.append(chr(c))
    s = "".join(out_chars)
    return s if _printable_ratio(s) > 0.85 else None


def _decode_single_byte_xor(data: bytes) -> dict | None:
    """Brute over all 256 single-byte XOR keys, pick the highest-printable
    output. Returns {"key": int, "plaintext": str, "score": float} or None."""
    if not data: return None
    best = None
    for k in range(256):
        xed = bytes(b ^ k for b in data)
        try:    s = xed.decode("utf-8")
        except UnicodeDecodeError: continue
        score = _printable_ratio(s)
        if score < 0.85: continue
        if best is None or score > best["score"]:
            best = {"key": k, "plaintext": s, "score": score}
    return best


def decode_contract_storage(hex_data: str | None) -> dict:
    """Cascade decoder for arbitrary contract storage. Tries:
      A. Plain ABI string  (lenders.digital / BW v2 panel-routers)
      B. Plain UTF-8 (the raw bytes as a string, no ABI wrap — Aeternum-like)
      C. Hyphen-reverse + charCode-subtract  (jobloom.info cluster v1)
      D. Single-byte XOR brute  (catches operator's 2nd contract's blob style)
      E. base64 of UTF-8  (some cluster encodings nest a b64 layer)
      F. base-36 PAIR position-shifted (jobloom-cluster v2 — S29 finding;
         decoder verbatim from blockchaindev.in lure JS;
         validated on 0xf5966808…2446 getServer())

    Returns:
      {"ok": bool, "best": str|None, "best_strategy": str|None,
       "attempts": [{"strategy": str, "ok": bool, "decoded": str|None,
                      "note": str|None}, ...]}

    Even when no strategy succeeds, returns the full attempt log so the
    analyst can see WHICH decoders ruled it out — useful for spotting a
    novel encoding shape that needs a new strategy added."""
    out = {"ok": False, "best": None, "best_strategy": None, "attempts": []}
    if not hex_data: return out
    h = hex_data[2:] if hex_data.startswith("0x") else hex_data

    # Strategy A — plain ABI string
    decA = decode_abi_string(hex_data, lax_drop_nulls=True)
    if decA and _looks_url_ish(decA):
        out["best"], out["best_strategy"] = decA, "abi_string_lax"
    out["attempts"].append({"strategy": "abi_string_lax", "ok": bool(decA),
                             "decoded": decA, "note": None if decA else "no length prefix or not printable"})
    if out["best"]: return {**out, "ok": True}

    # Strategy B — raw UTF-8 of full bytes (no ABI wrap)
    try:
        b = bytes.fromhex(h)
        decB = b.rstrip(b"\x00").decode("utf-8")
        if _looks_url_ish(decB):
            out["best"], out["best_strategy"] = decB, "raw_utf8"
        out["attempts"].append({"strategy": "raw_utf8", "ok": _looks_url_ish(decB),
                                 "decoded": decB[:200], "note": None})
    except (ValueError, UnicodeDecodeError) as e:
        out["attempts"].append({"strategy": "raw_utf8", "ok": False,
                                 "decoded": None, "note": str(e)[:80]})
    if out["best"]: return {**out, "ok": True}

    # Strategy C — jobloom hyphen-reverse-charSub (applied to raw UTF-8 first
    # because the encoded form is itself ASCII text inside the storage word)
    try:
        b = bytes.fromhex(h)
        raw_str = b.rstrip(b"\x00").decode("utf-8", errors="ignore")
        # Strip any ABI length prefix bytes if present
        # (try both raw-utf8 and ABI-data-portion as input)
        cand_inputs = [raw_str]
        if len(h) >= 128:
            try:
                length = int(h[64:128], 16)
                if 0 < length <= 1024:
                    cand_inputs.append(bytes.fromhex(h[128:128+length*2]).rstrip(b"\x00").decode("utf-8","ignore"))
            except ValueError:
                pass
        for cand in cand_inputs:
            decC = _decode_jobloom_hyphen_reverse(cand)
            if decC and _looks_url_ish(decC):
                out["best"], out["best_strategy"] = decC, "jobloom_hyphen_reverse_charsub"
                out["attempts"].append({"strategy": "jobloom_hyphen_reverse_charsub",
                                         "ok": True, "decoded": decC, "note": None})
                return {**out, "ok": True}
        out["attempts"].append({"strategy": "jobloom_hyphen_reverse_charsub",
                                 "ok": False, "decoded": None,
                                 "note": "no hyphenated input or output not URL-ish"})
    except Exception as e:
        out["attempts"].append({"strategy": "jobloom_hyphen_reverse_charsub",
                                 "ok": False, "decoded": None, "note": str(e)[:80]})

    # Strategy D — single-byte XOR brute (catches operator's-2nd-contract style)
    try:
        b = bytes.fromhex(h)
        x = _decode_single_byte_xor(b)
        if x and _looks_url_ish(x["plaintext"]):
            out["best"], out["best_strategy"] = x["plaintext"], f"single_byte_xor[k={x['key']}]"
            out["attempts"].append({"strategy": "single_byte_xor", "ok": True,
                                     "decoded": x["plaintext"][:200],
                                     "note": f"key={x['key']} score={x['score']:.2f}"})
            return {**out, "ok": True}
        out["attempts"].append({"strategy": "single_byte_xor", "ok": False,
                                 "decoded": None,
                                 "note": "no key produced URL-ish printable output"})
    except Exception as e:
        out["attempts"].append({"strategy": "single_byte_xor", "ok": False,
                                 "decoded": None, "note": str(e)[:80]})

    # Strategy E — base64 of UTF-8 (catches Aeternum-encoded-as-b64-in-storage)
    try:
        b = bytes.fromhex(h)
        s_raw = b.rstrip(b"\x00").decode("utf-8", errors="ignore")
        # Only attempt b64 decode on clean base64-shape input
        if re.fullmatch(r'[A-Za-z0-9+/=_-]{8,1024}', s_raw):
            try:
                b64decoded = base64.b64decode(s_raw + "=" * (-len(s_raw) % 4), validate=False)
                decE = b64decoded.rstrip(b"\x00").decode("utf-8", errors="replace")
                if _looks_url_ish(decE):
                    out["best"], out["best_strategy"] = decE, "base64_of_utf8"
                    out["attempts"].append({"strategy": "base64_of_utf8", "ok": True,
                                             "decoded": decE, "note": None})
                    return {**out, "ok": True}
                out["attempts"].append({"strategy": "base64_of_utf8", "ok": False,
                                         "decoded": decE[:200],
                                         "note": "decoded to non-URL; might be encrypted bytes (Aeternum-style)"})
            except Exception as eb:
                out["attempts"].append({"strategy": "base64_of_utf8", "ok": False,
                                         "decoded": None, "note": str(eb)[:80]})
        else:
            out["attempts"].append({"strategy": "base64_of_utf8", "ok": False,
                                     "decoded": None, "note": "input is not base64-shaped"})
    except Exception as e:
        out["attempts"].append({"strategy": "base64_of_utf8", "ok": False,
                                 "decoded": None, "note": str(e)[:80]})

    # Strategy F — jobloom-cluster v2: base-36 pair position-shifted decoder.
    # The encoded form is itself ASCII text in the storage word; pull it out of
    # the ABI string (or raw UTF-8) and feed to the decoder. Validated against
    # 0xf5966808a9ECbdb8794F568922809C52b0Fd2446 (S29).
    try:
        cand_inputs: list[str] = []
        if decA: cand_inputs.append(decA)
        b = bytes.fromhex(h)
        try: cand_inputs.append(b.rstrip(b"\x00").decode("utf-8", errors="ignore"))
        except Exception: pass
        # Also try the ABI data-portion only (post 64-char-length prefix)
        if len(h) >= 128:
            try:
                length = int(h[64:128], 16)
                if 0 < length <= 2048:
                    cand_inputs.append(bytes.fromhex(h[128:128+length*2]).rstrip(b"\x00").decode("utf-8","ignore"))
            except ValueError:
                pass
        # de-dup; lowercase + strip only the candidates we'll try (decoder
        # itself requires 0-9 a-z)
        seen_cand = set()
        tried_any = False
        for cand in cand_inputs:
            if not cand: continue
            s = cand.strip().lower()
            if s in seen_cand: continue
            seen_cand.add(s)
            decF = _decode_jobloom_base36_position_shifted(s)
            tried_any = True
            if decF and _looks_url_ish(decF):
                out["best"], out["best_strategy"] = decF, "jobloom_base36_position_shifted"
                out["attempts"].append({"strategy": "jobloom_base36_position_shifted",
                                         "ok": True, "decoded": decF[:300], "note": None})
                return {**out, "ok": True}
        out["attempts"].append({"strategy": "jobloom_base36_position_shifted", "ok": False,
                                 "decoded": None,
                                 "note": ("no base-36-shape candidate" if not tried_any
                                          else "candidate did not decode to URL-shape")})
    except Exception as e:
        out["attempts"].append({"strategy": "jobloom_base36_position_shifted", "ok": False,
                                 "decoded": None, "note": str(e)[:80]})

    return out


def _decode_abi_address(hex_data: str | None) -> str | None:
    """Decode an ABI-encoded `address` return (a left-padded 32-byte word →
    the low 20 bytes). Returns a checksum-lowercased 0x… address, or None for
    the zero address / malformed data. Used to read admin()/owner() getters."""
    if not hex_data: return None
    h = hex_data[2:] if hex_data.startswith("0x") else hex_data
    if len(h) < 40: return None
    word = h[:64] if len(h) >= 64 else h
    a = word[-40:]
    if not re.fullmatch(r'[0-9a-fA-F]{40}', a) or int(a, 16) == 0: return None
    return "0x" + a.lower()


# Fallback admin-resolution path: jobloom-pattern contracts (S29 finding) store
# the admin/deployer in storage slot 0x1 directly via constructor (msg.sender),
# without exposing `admin()` as a function selector. eth_call admin() returns
# nothing → we miss the operator. eth_getStorageAt(addr, 0x1) reads the raw
# slot and recovers the 20-byte EOA from the low bytes of that 32-byte word.
# Slot 0x0 is also probed because some patterns put admin there; slot 0x1 is
# what the jobloom 0xf5966808 contract uses (verified S29 vs Etherscan creator).
_ADMIN_STORAGE_SLOTS = ("0x0", "0x1", "0x2", "0x3")

def fetch_storage_admin(addr: str, rpc: str, *, timeout: int = 8,
                         slots: tuple[str, ...] = _ADMIN_STORAGE_SLOTS) -> dict:
    """Try eth_getStorageAt on a handful of low slots; return the first one
    that decodes to a non-zero, valid-looking EOA. Returns:
        {"wallet": "0x…" | None, "slot": "0x1" | None, "raw_by_slot": {...},
         "errors": [...]}
    Each slot is one cheap JSON-RPC call. Total cost: 0 gas, ~50 ms per slot
    on a healthy public RPC. Used as a fallback by triage_contract when neither
    admin()/owner() selector responds (i.e., the contract dispatch table is
    minimal and the operator stored admin directly in state)."""
    out = {"wallet": None, "slot": None, "raw_by_slot": {}, "errors": []}
    if not isinstance(addr, str) or not re.fullmatch(r'0x[0-9a-fA-F]{40}', addr):
        out["errors"].append("invalid address"); return out
    if not rpc:
        out["errors"].append("no rpc"); return out
    for slot in slots:
        try:
            req = {"jsonrpc": "2.0", "id": 1, "method": "eth_getStorageAt",
                   "params": [addr, slot, "latest"]}
            data = json.dumps(req).encode()
            r = urllib.request.Request(rpc, data=data, method="POST",
                                        headers={"Content-Type": "application/json",
                                                 "Accept": "application/json",
                                                 "User-Agent": _BROWSER_UA})
            with urllib.request.urlopen(r, timeout=timeout,
                                         context=ssl._create_unverified_context()) as resp:
                body = resp.read()
        except Exception as e:
            out["errors"].append(f"slot {slot}: {str(e)[:80]}")
            continue
        try:
            j = json.loads(body)
        except Exception:
            continue
        raw = j.get("result")
        out["raw_by_slot"][slot] = raw
        if not isinstance(raw, str) or not raw.startswith("0x") or len(raw) < 42:
            continue
        # Decode the 32-byte word's low 20 bytes as an address
        a = _decode_abi_address(raw)
        if not a:
            continue
        # Stricter heuristic — addresses from EOA derivation have ~160 bits of
        # entropy, so they almost never look like small integers. Slot 0x0 on
        # many contracts holds a small counter / length / mode-flag — reject
        # anything where the address interpretation is < 2^96 (12 zero leading
        # bytes). This filters small ints stored as `address`-typed without
        # rejecting any plausible real wallet.
        try:
            iv = int(a, 16)
        except ValueError:
            continue
        if iv < (1 << 96):
            continue
        out["wallet"] = a
        out["slot"]   = slot
        return out
    return out


# Process-lifetime cache for --resolve in batch mode: avoid hitting the same
# (contract, selector) tuple repeatedly when 1000s of compromised pages all
# point at the same on-chain C2 holder.
_RESOLVE_CACHE: dict[tuple, dict] = {}
_RESOLVE_CACHE_LOCK = threading.Lock()


def resolve_etherhiding(eh: dict, override_rpc: str | None = None,
                        timeout: int = DEFAULT_RPC_TIMEOUT) -> dict:
    contracts = eh.get("contract_addresses") or []
    selector  = eh.get("method_selector") or "0x38bcdc1c"
    if not contracts: return {"ok": False, "error": "no contract address in classification"}
    cache_key = (tuple(c.lower() for c in contracts), selector.lower(), override_rpc)
    with _RESOLVE_CACHE_LOCK:
        cached = _RESOLVE_CACHE.get(cache_key)
    if cached:
        # mark cache hit so report shows we didn't hammer the RPC repeatedly
        return {**cached, "from_cache": True}
    rpcs = [override_rpc] if override_rpc else list(eh.get("rpc_pool") or [])
    if not rpcs: rpcs = DEFAULT_RPC_POOL.get(eh.get("chain"), [])
    if not rpcs: return {"ok": False, "error": "no RPC pool and no chain fallback known"}
    tried, last_err = [], None
    for rpc in rpcs:
        for contract in contracts:
            t0 = datetime.datetime.now(datetime.timezone.utc)
            try: raw = eth_call(rpc, contract, selector, timeout=timeout)
            except (urllib.error.URLError, ConnectionError, TimeoutError,
                    RuntimeError, ValueError) as e:
                tried.append({"rpc": rpc, "contract": contract, "error": str(e)[:200]})
                last_err = str(e); continue
            decoded = decode_abi_string(raw, lax_drop_nulls=True)
            # If plain ABI decode failed OR produced non-URL-ish text, run
            # the multi-strategy decoder cascade. Surfaces both the best guess
            # AND every attempt (so a never-before-seen encoding fails LOUDLY
            # with a per-strategy explanation, not silently).
            cascade = None
            if not decoded or not _looks_url_ish(decoded):
                cascade = decode_contract_storage(raw)
                if cascade["ok"]:
                    decoded = cascade["best"]
                else:
                    # Defect fix (S31): the raw ABI value was already rejected
                    # by _looks_url_ish above. Letting it remain in `decoded`
                    # propagates garbage to downstream `panel_url` construction
                    # (caused the blockchaindev.in jobloom v2 record in the
                    # 05-28 sweep to set panel_origin =
                    # `https://313e3f3c3g1w1m1n...` — pure base-36 with no
                    # decoder available pre-v5.5). Clearing it forces the
                    # caller to handle the unresolved case correctly.
                    decoded = None
            result = {
                "ok": True, "rpc_used": rpc, "contract": contract, "selector": selector,
                "raw_response": raw[:512] + ("…" if len(raw) > 512 else ""),
                "raw_response_len": len(raw),
                "decoded_url": decoded,
                "decoded_url_defanged": _defang(decoded) if decoded else None,
                "decoded_at": t0.isoformat(timespec="seconds").replace("+00:00", "Z"),
                "decoder_strategy":  (cascade.get("best_strategy") if cascade
                                       else ("abi_string_lax" if decoded else None)),
                "decoder_attempts":  (cascade.get("attempts") if cascade else None),
                "attempts": tried + [{"rpc": rpc, "contract": contract, "ok": True}],
                "from_cache": False,
            }
            with _RESOLVE_CACHE_LOCK:
                _RESOLVE_CACHE[cache_key] = result
            return result
    return {"ok": False, "error": f"all {len(rpcs)} RPCs failed; last: {last_err}",
            "attempts": tried}


# ============================================================================
# NEW: Contract investigation mode
# ============================================================================
# A contract's dispatch table looks like:
#   PUSH4 <4-byte selector>  EQ  PUSH2 <jumpdest>  JUMPI
# Opcodes:  63=PUSH4   14=EQ   61=PUSH2   57=JUMPI
# So the pattern is:  63 <8 hex> 14 (optional small ops, often 61 then JUMPI later)
_BYTECODE_SELECTOR_RE = re.compile(r'63([0-9a-fA-F]{8})14', re.I)


def extract_selectors_from_bytecode(bytecode_hex: str) -> list[str]:
    """Find all 4-byte function selectors hardcoded in the contract's dispatch
    table. Reliable for Solidity-compiled contracts using the standard
    PUSH4-EQ pattern."""
    if not bytecode_hex: return []
    if bytecode_hex.startswith("0x"): bytecode_hex = bytecode_hex[2:]
    seen = []
    for m in _BYTECODE_SELECTOR_RE.finditer(bytecode_hex):
        sel = "0x" + m.group(1).lower()
        if sel not in seen: seen.append(sel)
    return seen


def race_rpc(rpcs: list[str], method: str, params: list,
             timeout: int = DEFAULT_RPC_TIMEOUT) -> tuple[Any, str | None]:
    """Try each RPC in order until one succeeds. Returns (result, rpc_used) or (None, None)."""
    for r in rpcs:
        try: return rpc_call(r, method, params, timeout=timeout), r
        except Exception: continue
    return None, None


def _decode_param_string_from_input(inp: str) -> str | None:
    """Decode a transaction input's ABI string parameter (after 4-byte selector)."""
    if not inp or len(inp) <= 10 + 128: return None
    try:
        length = int(inp[10+64:10+128], 16)
        if 0 < length <= 8192 and len(inp) >= 10 + 128 + length*2:
            return bytes.fromhex(inp[10+128:10+128+length*2]) \
                .decode("utf-8", errors="replace").rstrip("\x00").strip()
    except Exception: pass
    return None


def _fetch_tx_history_etherscan(addr: str, chain: str, max_history: int,
                                progress_fh=None) -> list[dict] | None:
    """Fast path: Etherscan V1/V2 multichain endpoint. With a key set in
    POLYGONSCAN_API_KEY / BSCSCAN_API_KEY / ETHERSCAN_API_KEY env vars, returns
    the complete history. Without a key, falls back to keyless attempts (which
    mostly fail in 2026). Returns None if no endpoint worked."""
    chain_id = {"polygon": 137, "bsc": 56, "bsc-testnet": 97, "ethereum": 1}.get(chain)
    if not chain_id: return None
    key = (os.environ.get("POLYGONSCAN_API_KEY") if chain == "polygon"
           else os.environ.get("BSCSCAN_API_KEY") if chain in ("bsc","bsc-testnet")
           else os.environ.get("ETHERSCAN_API_KEY"))
    etherscan_key = os.environ.get("ETHERSCAN_API_KEY") or key
    # V2 multichain (the canonical endpoint as of 2026)
    urls = []
    if etherscan_key:
        urls.append(f"https://api.etherscan.io/v2/api?chainid={chain_id}"
                    f"&module=account&action=txlist&address={addr}"
                    f"&page=1&offset={max_history}&sort=desc&apikey={etherscan_key}")
    # legacy V1 (still works sometimes, with or without key)
    if chain == "polygon":
        urls.append(f"https://api.polygonscan.com/api?module=account&action=txlist"
                    f"&address={addr}&page=1&offset={max_history}&sort=desc"
                    + (f"&apikey={key}" if key else ""))
    if chain in ("bsc","bsc-testnet"):
        urls.append(f"https://api.bscscan.com/api?module=account&action=txlist"
                    f"&address={addr}&page=1&offset={max_history}&sort=desc"
                    + (f"&apikey={key}" if key else ""))
    # V2 multichain (no key) — usually 'Missing API Key', but try
    urls.append(f"https://api.etherscan.io/v2/api?chainid={chain_id}"
                f"&module=account&action=txlist&address={addr}"
                f"&page=1&offset={max_history}&sort=desc")
    for url in urls:
        if not url: continue
        try:
            req = urllib.request.Request(url, headers={"User-Agent": _BROWSER_UA})
            with urllib.request.urlopen(req, timeout=15) as r:
                d = json.loads(r.read())
        except Exception as e:
            if progress_fh: print(f"  [etherscan] {url[:60]}... -> {e}", file=progress_fh)
            continue
        if d.get("status") != "1":
            if progress_fh: print(f"  [etherscan] {url[:60]}... -> {d.get('message','?')}: "
                                  f"{str(d.get('result',''))[:80]}", file=progress_fh)
            continue
        # parse v1 result format
        history = []
        for t in d.get("result", []):
            sel = (t.get("input") or "0x")[:10].lower()
            meta = lookup_selector(sel) or {}
            decoded_param = (_decode_param_string_from_input(t.get("input", ""))
                             if meta.get("param") == "string" else None)
            history.append({
                "block_number": int(t["blockNumber"]),
                "block_time":   datetime.datetime.fromtimestamp(int(t["timeStamp"]),
                                                                 datetime.timezone.utc)
                                 .isoformat(timespec="seconds").replace("+00:00", "Z"),
                "tx_hash":      t["hash"],
                "from":         t["from"],
                "from_attribution": (lookup_actor(t["from"]) or {}).get("name"),
                "selector":     sel,
                "function":     meta.get("signature", "?"),
                "decoded_param": decoded_param,
                "decoded_param_defanged": _defang(decoded_param) if decoded_param else None,
            })
        if progress_fh:
            print(f"  [etherscan] {url[:60]}... -> {len(history)} txs", file=progress_fh)
        return history
    return None


# ============================================================================
# S28 : DEPLOYER ENUMERATION + FUNDING-PATH TRACE
# ============================================================================
# These two modes power "walk down a deployer's full inventory" + "walk back
# customer wallet funding to find common nodes." Both use the Etherscan v2
# multichain API with the same key as --triage-contracts. Costs $0 (read-only),
# OPSEC-clean (no contact with attacker infra), and graceful without a key
# (returns empty + a clear message).
# ============================================================================

def enumerate_deployer_contracts(wallet: str, chain: str = "polygon",
                                  max_pages: int = 20,
                                  page_size: int = 10_000,
                                  progress_fh=None) -> list[dict]:
    """List every contract `wallet` ever deployed on `chain`.

    Walks Etherscan v2 txlist paginated with sort=asc; a contract creation
    transaction has `to == ""` AND `contractAddress` populated. Returns
    chronological list of {address, creation_tx, block_number, block_time,
    gas_used, input_first10, tx_status}.

    Requires POLYGONSCAN_API_KEY / ETHERSCAN_API_KEY (one of). Without a key,
    returns [] and logs a clear message (public free RPCs can't answer the
    equivalent query at scale).
    """
    chain_id = {"polygon": 137, "bsc": 56, "bsc-testnet": 97, "ethereum": 1}.get(chain)
    if not chain_id: return []
    key = (os.environ.get("POLYGONSCAN_API_KEY") if chain == "polygon"
           else os.environ.get("BSCSCAN_API_KEY") if chain in ("bsc","bsc-testnet")
           else os.environ.get("ETHERSCAN_API_KEY"))
    etherscan_key = os.environ.get("ETHERSCAN_API_KEY") or key
    if not etherscan_key:
        if progress_fh:
            print("  [enumerate] POLYGONSCAN_API_KEY (or ETHERSCAN_API_KEY) "
                  "env var required — public free RPCs can't paginate full "
                  "tx history.", file=progress_fh)
        return []

    wallet_lc = wallet.lower()
    contracts: list[dict] = []
    seen_addrs: set[str] = set()
    for page in range(1, max_pages + 1):
        url = (f"https://api.etherscan.io/v2/api?chainid={chain_id}"
               f"&module=account&action=txlist&address={wallet_lc}"
               f"&page={page}&offset={page_size}&sort=asc"
               f"&apikey={etherscan_key}")
        try:
            req = urllib.request.Request(url, headers={"User-Agent": _BROWSER_UA})
            with urllib.request.urlopen(req, timeout=25) as r:
                d = json.loads(r.read())
        except Exception as e:
            if progress_fh:
                print(f"  [enumerate] page {page}: {e}", file=progress_fh)
            break
        if d.get("status") != "1":
            msg = str(d.get("message", "?"))
            # End-of-list is normal — status=0 + "No transactions found"
            if "No transactions found" in msg:
                if progress_fh:
                    print(f"  [enumerate] page {page}: end of list "
                          f"({len(contracts)} total)", file=progress_fh)
                break
            if progress_fh:
                print(f"  [enumerate] page {page}: {msg}: "
                      f"{str(d.get('result',''))[:100]}", file=progress_fh)
            break
        rows = d.get("result") or []
        if not isinstance(rows, list) or not rows:
            break
        page_creations = 0
        for tx in rows:
            to_addr      = (tx.get("to") or "").lower()
            new_contract = (tx.get("contractAddress") or "").lower()
            if to_addr or not new_contract or new_contract in seen_addrs:
                continue
            seen_addrs.add(new_contract)
            ts = int(tx.get("timeStamp", "0") or 0)
            contracts.append({
                "address":      new_contract,
                "chain":        chain,
                "creation_tx":  tx.get("hash"),
                "block_number": int(tx.get("blockNumber", "0") or 0),
                "block_time":   (datetime.datetime.fromtimestamp(
                    ts, datetime.timezone.utc
                ).isoformat(timespec="seconds").replace("+00:00", "Z") if ts else None),
                "gas_used":     int(tx.get("gasUsed", "0") or 0),
                "input_first10": (tx.get("input") or "")[:10],
                "tx_status":    tx.get("txreceipt_status", "1"),
            })
            page_creations += 1
        if progress_fh:
            print(f"  [enumerate] page {page}: +{len(rows)} txs, "
                  f"+{page_creations} new contracts ({len(contracts)} total)",
                  file=progress_fh)
        if len(rows) < page_size:
            break
        # Etherscan v2 free tier = 5 req/sec; sleep to be safe
        time.sleep(0.25)
    return contracts


def trace_funding_path(wallet: str, chain: str = "polygon",
                        hops: int = 2,
                        progress_fh=None) -> dict:
    """Walk back N hops of incoming MATIC starting from `wallet`.

    At each hop: fetch txlist + txlistinternal sorted ASC, take the FIRST
    transaction where `to == wallet` AND value > 0 (incoming MATIC). The
    `from` of that tx is the funding source. Tag it against KNOWN_EXCHANGES
    + KNOWN_ACTORS. Stop if the source is a known exchange/actor OR depth
    reached OR no incoming MATIC found.

    Returns:
      {start_wallet, chain, hops: [...], terminus_type, terminus_wallet}
    where terminus_type ∈ {known_exchange, known_actor, depth_exhausted,
    no_funding, no_api_key, unsupported_chain}.
    """
    out = {
        "start_wallet": wallet.lower(),
        "chain": chain,
        "hops": [],
        "terminus_type": "depth_exhausted",
        "terminus_wallet": None,
    }
    chain_id = {"polygon": 137, "bsc": 56, "bsc-testnet": 97, "ethereum": 1}.get(chain)
    if not chain_id:
        out["terminus_type"] = "unsupported_chain"; return out
    key = (os.environ.get("POLYGONSCAN_API_KEY") if chain == "polygon"
           else os.environ.get("BSCSCAN_API_KEY") if chain in ("bsc","bsc-testnet")
           else os.environ.get("ETHERSCAN_API_KEY"))
    etherscan_key = os.environ.get("ETHERSCAN_API_KEY") or key
    if not etherscan_key:
        out["terminus_type"] = "no_api_key"; return out

    def _first_incoming(addr: str) -> dict | None:
        """Find the chronologically-first incoming MATIC transfer to addr.
        Tries normal txlist, then internal txs (bridges/contracts often
        send via internal calls)."""
        candidates: list[dict] = []
        for action in ("txlist", "txlistinternal"):
            url = (f"https://api.etherscan.io/v2/api?chainid={chain_id}"
                   f"&module=account&action={action}&address={addr}"
                   f"&page=1&offset=200&sort=asc"
                   f"&apikey={etherscan_key}")
            try:
                req = urllib.request.Request(url, headers={"User-Agent": _BROWSER_UA})
                with urllib.request.urlopen(req, timeout=20) as r:
                    d = json.loads(r.read())
            except Exception as e:
                if progress_fh:
                    print(f"  [trace] {addr[:10]}.. {action}: {e}", file=progress_fh)
                continue
            if d.get("status") != "1":
                continue
            for t in (d.get("result") or []):
                to_addr = (t.get("to") or "").lower()
                if to_addr != addr.lower(): continue
                # internal txs include isError field
                if action == "txlistinternal" and t.get("isError") == "1":
                    continue
                value = int(t.get("value", "0") or 0)
                if value <= 0: continue
                ts = int(t.get("timeStamp", "0") or 0)
                candidates.append({
                    "tx_hash":      t.get("hash"),
                    "from":         (t.get("from") or "").lower(),
                    "amount_matic": value / 1e18,
                    "block_number": int(t.get("blockNumber", "0") or 0),
                    "block_time":   (datetime.datetime.fromtimestamp(
                        ts, datetime.timezone.utc
                    ).isoformat(timespec="seconds").replace("+00:00", "Z") if ts else None),
                    "tx_type":      "normal" if action == "txlist" else "internal",
                })
            time.sleep(0.25)
        if not candidates: return None
        # earliest block across both lists wins
        candidates.sort(key=lambda c: c["block_number"])
        return candidates[0]

    current = wallet.lower()
    for depth in range(hops):
        funded = _first_incoming(current)
        if not funded:
            if depth == 0: out["terminus_type"] = "no_funding"
            out["terminus_wallet"] = current
            break
        src = funded["from"]
        ex = lookup_exchange(src)
        actor = lookup_actor(src)
        tag = ex or actor
        hop = {
            "depth":          depth,
            "for_wallet":     current,
            "from_wallet":    src,
            "funded_via_tx":  funded["tx_hash"],
            "block_time":     funded["block_time"],
            "block_number":   funded["block_number"],
            "amount_matic":   funded["amount_matic"],
            "tx_type":        funded["tx_type"],
            "tag_name":       (tag or {}).get("name"),
            "tag_kind":       (tag or {}).get("kind"),
        }
        out["hops"].append(hop)
        out["terminus_wallet"] = src
        if ex:
            out["terminus_type"] = "known_exchange"; break
        if actor:
            out["terminus_type"] = "known_actor"; break
        current = src
    return out


def _decode_two_string_data(hex_data: str) -> tuple[str | None, str | None]:
    """Decode an ABI-encoded (string, string) event data field. Returns (s1, s2)
    or (None, None) if it doesn't look right."""
    if not hex_data: return (None, None)
    if hex_data.startswith("0x"): hex_data = hex_data[2:]
    if len(hex_data) < 256: return (None, None)
    try:
        off1 = int(hex_data[0:64], 16)
        off2 = int(hex_data[64:128], 16)
    except ValueError: return (None, None)
    def _read_str(byte_off):
        pos = byte_off * 2
        if pos + 64 > len(hex_data): return None
        try: length = int(hex_data[pos:pos+64], 16)
        except ValueError: return None
        if length == 0 or length > 4096: return None
        h = hex_data[pos+64:pos+64+length*2]
        if len(h) < length * 2: return None
        try: return bytes.fromhex(h).decode("utf-8", "replace").rstrip("\x00").strip()
        except Exception: return None
    return (_read_str(off1), _read_str(off2))


def _fetch_tx_history_getlogs(addr: str, rpcs: list[str], max_history: int,
                              max_block_range: int, timeout: int,
                              chunk_size: int = 10_000,
                              progress_fh=None) -> tuple[list[dict] | None, int]:
    """Fast path #2: use eth_getLogs to pull every event the contract emitted in
    the recent <max_block_range> blocks. Each event = one rotation. Adaptively
    halves chunk_size on rate-limit / 400 errors. Returns (history, blocks_covered)
    or (None, 0) if the contract doesn't emit logs."""
    try:
        latest_hex, _ = race_rpc(rpcs, "eth_blockNumber", [], timeout=timeout)
        latest = int(latest_hex, 16)
    except Exception as e:
        if progress_fh: print(f"  [getlogs] eth_blockNumber failed: {e}", file=progress_fh)
        return None, 0
    addr_lc = addr.lower()
    history: list[dict] = []
    block_ts_cache: dict[int, int] = {}     # blockNumber -> unix ts
    to_blk = latest
    floor_blk = max(0, latest - max_block_range)
    covered = 0
    cur_chunk = chunk_size
    saw_any_response = False
    pruned_at = None  # track when public RPC archive horizon is hit
    consecutive_empty = 0
    MAX_CONSECUTIVE_EMPTY = 8     # stop after 8 empty windows (~80k blocks of nothing)
    while to_blk > floor_blk and len(history) < max_history:
        from_blk = max(floor_blk, to_blk - cur_chunk)
        # try each RPC until one accepts the range
        logs = None
        chosen_rpc = None
        pruned_this_round = False
        for rpc in rpcs:
            try:
                req = urllib.request.Request(rpc, data=json.dumps({
                    "jsonrpc":"2.0","id":1,"method":"eth_getLogs",
                    "params":[{"address": addr_lc, "fromBlock": hex(from_blk),
                                "toBlock": hex(to_blk)}],
                }).encode(), headers={"Content-Type":"application/json",
                                       "User-Agent": _BROWSER_UA}, method="POST")
                with urllib.request.urlopen(req, timeout=timeout) as r:
                    d = json.loads(r.read())
                if "error" in d:
                    err = d["error"].get("message","getLogs error")[:200]
                    if "pruned" in err.lower() or "history" in err.lower():
                        pruned_this_round = True
                    raise RuntimeError(err[:100])
                logs = d.get("result") or []
                chosen_rpc = rpc
                saw_any_response = True
                break
            except Exception as e:
                msg = str(e)[:120]
                if "pruned" in msg.lower() or "history has been pruned" in msg.lower():
                    pruned_this_round = True
                if progress_fh and "Bad Request" not in msg:
                    print(f"  [getlogs] {rpc[:40]}... ({from_blk}-{to_blk}): {msg}",
                          file=progress_fh)
                continue
        if pruned_this_round and logs is None:
            pruned_at = from_blk
            if progress_fh:
                print(f"  [getlogs] hit public-RPC archive horizon at block ~{from_blk} "
                      f"(history pruned). Stopping. For deeper history, set "
                      f"POLYGONSCAN_API_KEY or use an archive RPC via --rpc-url.",
                      file=progress_fh)
            break
        if logs is None:
            # halve chunk and retry the same window
            if cur_chunk >= 200:
                cur_chunk //= 2
                if progress_fh: print(f"  [getlogs] reducing chunk to {cur_chunk}",
                                      file=progress_fh)
                continue
            else:
                break  # give up on this range
        # process the logs we got
        # gather block numbers we need timestamps for
        need_ts_blocks = list({int(l["blockNumber"], 16) for l in logs
                                if int(l["blockNumber"], 16) not in block_ts_cache})
        if need_ts_blocks:
            # batch-fetch block timestamps (eth_getBlockByNumber w/ tx flag false)
            for batch_idx in range(0, len(need_ts_blocks), 50):
                batch_blocks = need_ts_blocks[batch_idx:batch_idx+50]
                batch_req = [{"jsonrpc":"2.0","id":i,"method":"eth_getBlockByNumber",
                              "params":[hex(b), False]} for i, b in enumerate(batch_blocks)]
                resp = _rpc_batch(chosen_rpc, batch_req, timeout) or []
                for b, blk in zip(batch_blocks, resp):
                    if blk and "timestamp" in blk:
                        block_ts_cache[b] = int(blk["timestamp"], 16)
        for log in logs:
            blk_num = int(log["blockNumber"], 16)
            ts = block_ts_cache.get(blk_num, 0)
            old_url, new_url = _decode_two_string_data(log.get("data", "0x"))
            # If we couldn't decode 2 strings, try as a single string (different event shape)
            if not (old_url or new_url):
                single = decode_abi_string(log.get("data", "0x"), lax_drop_nulls=True)
                if single: new_url = single
            history.append({
                "block_number": blk_num,
                "block_time":   datetime.datetime.fromtimestamp(ts, datetime.timezone.utc)
                                 .isoformat(timespec="seconds").replace("+00:00", "Z") if ts else None,
                "tx_hash":      log.get("transactionHash"),
                "from":         None,           # not in log; would need separate eth_getTransactionByHash
                "from_attribution": None,
                "selector":     None,
                "function":     "(event)",
                "event_topic0": (log.get("topics") or [None])[0],
                "decoded_param": new_url,
                "decoded_param_defanged": _defang(new_url) if new_url else None,
                "previous_value": old_url,
                "previous_value_defanged": _defang(old_url) if old_url else None,
            })
        covered += (to_blk - from_blk)
        if logs:
            consecutive_empty = 0
        else:
            consecutive_empty += 1
        if progress_fh:
            print(f"  [getlogs] blocks [{from_blk}..{to_blk}] ({to_blk-from_blk}) -> "
                  f"{len(logs)} logs (total: {len(history)})", file=progress_fh)
        if consecutive_empty >= MAX_CONSECUTIVE_EMPTY and history:
            if progress_fh:
                print(f"  [getlogs] {MAX_CONSECUTIVE_EMPTY} consecutive empty windows; "
                      f"likely past archive horizon or rotation gap. Stopping.",
                      file=progress_fh)
            break
        to_blk = from_blk
    if not saw_any_response:
        return None, 0
    if not history:
        return None, covered   # responded but contract emits no events — fallback to block scan
    history.sort(key=lambda h: -h["block_number"])
    return history[:max_history], covered


def _rpc_batch(rpc_url: str, requests: list[dict], timeout: int) -> list[dict] | None:
    """Send a JSON-RPC batch. Returns list of result dicts (None for failed individual calls)."""
    try:
        req = urllib.request.Request(rpc_url, data=json.dumps(requests).encode(),
            headers={"Content-Type":"application/json","User-Agent": _BROWSER_UA}, method="POST")
        with urllib.request.urlopen(req, timeout=timeout) as r:
            resp = json.loads(r.read())
    except Exception:
        return None
    if not isinstance(resp, list):
        return None
    by_id = {r.get("id"): r for r in resp}
    return [by_id.get(req["id"], {}).get("result") for req in requests]


def _fetch_block_batch(rpcs: list[str], block_nums: list[int], timeout: int
                       ) -> list[dict | None]:
    """Fetch N blocks in one JSON-RPC batch; race across RPC pool on failure."""
    batch = [{"jsonrpc":"2.0", "id": i, "method": "eth_getBlockByNumber",
              "params": [hex(b), True]} for i, b in enumerate(block_nums)]
    for rpc in rpcs:
        result = _rpc_batch(rpc, batch, timeout)
        if result is not None:
            return result
    return [None] * len(block_nums)


def _fetch_tx_history_rpc_parallel(addr: str, rpcs: list[str], max_history: int,
                                   max_blocks: int, timeout: int, workers: int,
                                   batch_size: int = 50,
                                   progress_fh=None) -> tuple[list[dict], int]:
    """Fallback: parallel BATCHED block-scan via JSON-RPC. Each batch fetches
    `batch_size` blocks in a single HTTP round-trip; `workers` batches run
    concurrently across the RPC pool. Default config: 8 workers x 50-block
    batches = 400 blocks per round-trip ≈ 1000+ blocks/sec on healthy RPCs."""
    try:
        latest_hex, _ = race_rpc(rpcs, "eth_blockNumber", [], timeout=timeout)
        latest = int(latest_hex, 16)
    except Exception as e:
        if progress_fh: print(f"  [rpc-scan] eth_blockNumber failed: {e}", file=progress_fh)
        return [], 0

    history: list[dict] = []
    scanned = 0
    cur = latest
    addr_lc = addr.lower()
    started = datetime.datetime.now(datetime.timezone.utc)

    def process_batch(block_nums: list[int]) -> list[dict]:
        blocks = _fetch_block_batch(rpcs, block_nums, timeout)
        local = []
        for b in blocks:
            if not b: continue
            ts = int(b.get("timestamp", "0x0"), 16)
            for tx in b.get("transactions", []):
                if (tx.get("to") or "").lower() != addr_lc: continue
                inp = tx.get("input") or "0x"
                sel = inp[:10].lower() if len(inp) >= 10 else ""
                meta = lookup_selector(sel) or {}
                decoded_param = (_decode_param_string_from_input(inp)
                                 if meta.get("param") == "string" else None)
                local.append({
                    "block_number": int(tx["blockNumber"], 16),
                    "block_time":   datetime.datetime.fromtimestamp(ts, datetime.timezone.utc)
                                     .isoformat(timespec="seconds").replace("+00:00", "Z"),
                    "tx_hash":      tx["hash"],
                    "from":         tx["from"],
                    "from_attribution": (lookup_actor(tx["from"]) or {}).get("name"),
                    "selector":     sel,
                    "function":     meta.get("signature", "?"),
                    "decoded_param": decoded_param,
                    "decoded_param_defanged": _defang(decoded_param) if decoded_param else None,
                })
        return local

    with ThreadPoolExecutor(max_workers=workers) as ex:
        in_flight = []
        per_round = batch_size * workers
        while cur > 0 and len(history) < max_history and scanned < max_blocks:
            for _ in range(workers):
                if cur <= 0 or scanned >= max_blocks: break
                end = max(0, cur - batch_size)
                block_nums = list(range(cur, end, -1))
                if not block_nums: break
                in_flight.append(ex.submit(process_batch, block_nums))
                cur = end
                scanned += len(block_nums)
            for fut in as_completed(in_flight):
                history.extend(fut.result())
                if len(history) >= max_history: break
            in_flight = []
            if progress_fh:
                dt = max(0.001, (datetime.datetime.now(datetime.timezone.utc)
                                  - started).total_seconds())
                rate = scanned / dt
                print(f"  [rpc-scan] scanned {scanned:,} blocks "
                      f"({rate:.0f}/s), found {len(history)} txs", file=progress_fh)

    history.sort(key=lambda h: -h["block_number"])
    return history[:max_history], scanned


def investigate_contract(addr: str, chain: str = "polygon",
                         max_history: int = 200,
                         max_blocks_to_scan: int = 250_000,
                         workers: int = 16,
                         rpc_override: str | None = None,
                         timeout: int = DEFAULT_RPC_TIMEOUT,
                         skip_etherscan: bool = False,
                         progress_fh=None) -> dict:
    """Comprehensive contract analysis: current state + bytecode-extracted
    selectors + tx history (Etherscan fast-path with RPC block-scan fallback)."""
    addr = addr.lower()
    if not re.fullmatch(r'0x[0-9a-f]{40}', addr):
        return {"error": f"invalid address {addr!r} (must be 0x + 40 hex)"}
    rpcs = [rpc_override] if rpc_override else DEFAULT_RPC_POOL.get(chain, [])
    if not rpcs:
        return {"error": f"no RPC pool known for chain={chain!r}; pass --rpc-url"}
    started = datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z")
    report: dict = {
        "schema_version": SCHEMA_VERSION, "tool": TOOL_VERSION, "mode": "investigate_contract",
        "address": addr, "chain": chain, "started_at": started,
        "actor_attribution": lookup_actor(addr),
        "bytecode": {}, "current_state": {}, "history": [],
        "history_source": None, "errors": [],
    }

    # 1. Bytecode
    if progress_fh: print(f"[investigate] eth_getCode {addr}", file=progress_fh)
    code, used = race_rpc(rpcs, "eth_getCode", [addr, "latest"], timeout=timeout)
    if code:
        report["bytecode"] = {
            "rpc_used":         used,
            "size_bytes":       (len(code) - 2) // 2,
            "selectors_found":  extract_selectors_from_bytecode(code),
        }
    else:
        report["errors"].append("eth_getCode returned nothing on all RPCs")

    # 2. Current state — call every known getter we find in the bytecode.
    #    Decodes both `string` returns (the C2 URL) AND `address` returns
    #    (admin()/owner() → the operator wallet).
    for sel in report["bytecode"].get("selectors_found", []):
        meta = lookup_selector(sel)
        if not meta or "returns" not in meta: continue
        try:
            raw = eth_call(rpcs[0], addr, sel, timeout=timeout)
            ret = meta["returns"]
            decoded = None
            if ret.startswith("string"):
                decoded = decode_abi_string(raw, lax_drop_nulls=ret == "string_lax")
            elif ret == "address":
                decoded = _decode_abi_address(raw)
            report["current_state"][sel] = {
                "signature": meta["signature"],
                "returns":   ret,
                "raw":       raw[:256] + ("…" if len(raw) > 256 else ""),
                "decoded":   decoded,
                # only URL-style strings get defanged; addresses stay as-is
                "decoded_defanged": (_defang(decoded) if (decoded and ret.startswith("string")) else decoded),
            }
        except Exception as e:
            report["current_state"][sel] = {"signature": meta["signature"], "error": str(e)[:200]}

    # 2b. Convenience top-level extraction of the two highest-value state fields:
    #     the current C2 URL (string getter) and the admin/operator wallet
    #     (address getter), the latter cross-referenced against KNOWN_ACTORS.
    cur = report["current_state"]
    cur_url = None
    for st in cur.values():
        if (st.get("returns") or "").startswith("string") and st.get("decoded"):
            cur_url = st["decoded"]; break
    report["current_url"]          = cur_url
    report["current_url_defanged"] = _defang(cur_url) if cur_url else None
    admin_wallet = None
    for st in cur.values():
        if st.get("returns") == "address" and st.get("decoded"):
            admin_wallet = st["decoded"]; break
    report["admin_wallet"]             = admin_wallet
    report["admin_wallet_attribution"] = lookup_actor(admin_wallet) if admin_wallet else None

    # 3. Transaction history — try in order:
    #    (a) Etherscan-family API  (fastest if key present; usually requires one now)
    #    (b) eth_getLogs            (fast & key-free IF the contract emits events)
    #    (c) Parallel batched block-scan via RPC  (works on any contract; slowest)
    history = None
    if not skip_etherscan:
        if progress_fh: print(f"[investigate] trying Etherscan-family fast path", file=progress_fh)
        history = _fetch_tx_history_etherscan(addr, chain, max_history, progress_fh)
        if history is not None: report["history_source"] = "etherscan-family-api"
    if history is None:
        if progress_fh:
            print(f"[investigate] trying eth_getLogs (event-based; needs contract to emit events)",
                  file=progress_fh)
        history, blocks_covered = _fetch_tx_history_getlogs(
            addr, rpcs, max_history, max_block_range=max_blocks_to_scan,
            timeout=timeout, progress_fh=progress_fh)
        if history is not None:
            report["history_source"] = "eth_getLogs"
            report["blocks_covered"] = blocks_covered
    if history is None:
        if progress_fh:
            print(f"[investigate] fallback: parallel BATCHED RPC block scan "
                  f"({workers} workers, batch=50 blocks, up to {max_blocks_to_scan} blocks)",
                  file=progress_fh)
        history, scanned = _fetch_tx_history_rpc_parallel(
            addr, rpcs, max_history, max_blocks_to_scan, timeout, workers,
            progress_fh=progress_fh)
        report["scanned_blocks"] = scanned
        report["history_source"] = "rpc-parallel-block-scan"
    report["history"] = history or []

    # 4. Cross-reference unique writer wallets against KNOWN_ACTORS
    # (event-sourced history has from=None; only tx-sourced history populates it)
    history = report["history"]
    writers = sorted({h["from"].lower() for h in history if h.get("from")})
    report["writer_wallets"] = []
    for w in writers:
        att = lookup_actor(w)
        report["writer_wallets"].append({
            "address": w, "attribution": att,
            "tx_count": sum(1 for h in history if (h.get("from") or "").lower() == w),
        })

    # 5. Aggregate the rotation timeline (unique decoded URLs in order)
    unique_urls = []
    seen = set()
    for h in history:
        u = h.get("decoded_param")
        if u and u not in seen:
            seen.add(u); unique_urls.append({"url": u, "url_defanged": _defang(u),
                                             "first_set_block": h["block_number"],
                                             "first_set_time":  h["block_time"]})
    report["unique_urls_seen"] = unique_urls

    # 6. One-line summary block — the row a bulk run flattens into CSV.
    report["summary"] = {
        "address":              addr,
        "chain":                chain,
        "actor":                (report.get("actor_attribution") or {}).get("name"),
        "current_url":          report.get("current_url"),
        "current_url_defanged": report.get("current_url_defanged"),
        "admin_wallet":         report.get("admin_wallet"),
        "admin_attribution":    (report.get("admin_wallet_attribution") or {}).get("name"),
        "n_selectors":          len((report.get("bytecode") or {}).get("selectors_found") or []),
        "n_history":            len(history),
        "n_distinct_urls":      len(unique_urls),
        "n_writer_wallets":     len(report.get("writer_wallets") or []),
        "history_source":       report.get("history_source"),
        "first_rotation_time":  (unique_urls[0]["first_set_time"] if unique_urls else None),
        "last_rotation_time":   (unique_urls[-1]["first_set_time"] if unique_urls else None),
    }
    return report


# ============================================================================
# ANSI colors  (auto-disabled when stdout is not a TTY)
# ============================================================================
class C:
    RED     = "\x1b[91m"
    GREEN   = "\x1b[92m"
    YELLOW  = "\x1b[93m"
    BLUE    = "\x1b[94m"
    MAGENTA = "\x1b[95m"
    CYAN    = "\x1b[96m"
    WHITE   = "\x1b[97m"
    GRAY    = "\x1b[90m"
    BOLD    = "\x1b[1m"
    DIM     = "\x1b[2m"
    UNDER   = "\x1b[4m"
    RESET   = "\x1b[0m"
    BG_RED  = "\x1b[41m"
    BG_GREEN = "\x1b[42m"

    @classmethod
    def disable(cls):
        for attr in dir(cls):
            if attr.isupper() and not attr.startswith("_"):
                setattr(cls, attr, "")

# Color auto-enable:
#  - Real TTY on any OS: ON
#  - Git Bash / MinTTY on Windows: ON (sys.stdout.isatty() returns False even
#    though it's a real terminal; detect via $TERM, $MSYSTEM, $WT_SESSION)
#  - JSON/JSONL stdout redirection: OFF (auto via tty check)
#  - Explicit --no-color always wins
def _looks_like_real_terminal() -> bool:
    if sys.stdout.isatty(): return True
    env = os.environ
    if env.get("WT_SESSION") or env.get("TERM_PROGRAM"): return True
    if env.get("MSYSTEM") and env.get("TERM"): return True       # Git Bash / MinTTY
    if env.get("ConEmuANSI") == "ON": return True
    return False

if not _looks_like_real_terminal():
    C.disable()
elif sys.platform == "win32":
    try:
        import ctypes
        kernel32 = ctypes.windll.kernel32
        kernel32.SetConsoleMode(kernel32.GetStdHandle(-11), 7)
    except Exception: pass


# ============================================================================
# WordPress detection — multi-signal scoring
# ============================================================================
_WP_SIGNALS = [
    # (regex, weight, signal_name)
    (re.compile(r'<meta\s+name=["\']generator["\']\s+content=["\']WordPress\s*([\d.]+)?', re.I), 0.9, "meta_generator"),
    (re.compile(r'/wp-content/(?:themes|plugins|uploads)/', re.I),                              0.5, "wp_content_path"),
    (re.compile(r'/wp-includes/(?:js|css|images)/', re.I),                                       0.4, "wp_includes_path"),
    (re.compile(r'/wp-json/(?:wp/v2/|oembed/)', re.I),                                           0.5, "wp_json_rest"),
    (re.compile(r'\bwp-embed(?:\.min)?\.js', re.I),                                              0.3, "wp_embed_js"),
    (re.compile(r'\bwp-emoji-release(?:\.min)?\.js', re.I),                                      0.3, "wp_emoji"),
    (re.compile(r'\bwpemojiSettings\s*=', re.I),                                                 0.3, "wp_emoji_settings"),
    (re.compile(r'<link[^>]+href=["\'][^"\']*/wp-content/themes/', re.I),                        0.3, "wp_theme_link"),
    (re.compile(r'\bwp_admin\b|wp_ajax_', re.I),                                                 0.2, "wp_admin_kw"),
    (re.compile(r'window\._wpemojiSettings|window\.wp\.', re.I),                                 0.2, "wp_window_obj"),
]


def detect_wordpress(html: str, headers: dict | None = None) -> dict:
    """Return {is_wp, confidence, signals[], version}. Confidence is 0..1 from
    weighted signal sum; is_wp = confidence >= 0.6."""
    if not html:
        return {"is_wp": False, "confidence": 0.0, "signals": [], "version": None}
    signals = []
    score = 0.0
    version = None
    version_implausible = False
    for pattern, weight, name in _WP_SIGNALS:
        m = pattern.search(html)
        if m:
            signals.append(name)
            score += weight
            if name == "meta_generator" and m.lastindex and m.group(1):
                version = m.group(1)
    # Sanity-check the extracted version. WordPress is at 6.x in 2026; any
    # version >= 7 is almost certainly a kit fingerprint-randomized meta tag
    # (we saw 1,924 reports falsely tagged "7.0" in the 05-28 sweep). Cap to
    # plausible range: major in {2..6}. Out-of-range versions get DROPPED
    # from the report and flagged as a signal — telling the analyst the page
    # is lying about its CMS version (a kit-injection signal in itself).
    if version:
        try:
            major = int(version.split(".")[0])
            if major < 2 or major > 6:
                version_implausible = True
                signals.append(f"meta_generator_implausible:{version}")
                version = None    # drop; don't propagate a fake claim
        except (ValueError, IndexError):
            # Non-numeric version → drop too (e.g. "WordPress.org" mis-parse)
            version = None
    if headers:
        link = headers.get("Link") or headers.get("link") or ""
        if "/wp-json/" in link:
            signals.append("link_header_wp_json"); score += 0.4
    score = min(1.0, score)
    return {
        "is_wp":      score >= 0.6,
        "confidence": round(score, 2),
        "signals":    signals,
        "version":    version,
        "version_implausible": version_implausible,
    }


# ============================================================================
# Cloudflare detection — multi-signal scoring  (headers + body + DNS)
# ============================================================================
_CF_RAY_RE          = re.compile(r'\bCF-RAY[:=]\s*([\w-]+)', re.I)
_CF_BODY_SIGNAL_RE  = re.compile(r'cloudflare\.com/cdn-cgi/|/cdn-cgi/challenge-platform/'
                                  r'|cf-browser-verification|__cf_bm', re.I)
_CF_CNAME_HINTS     = re.compile(r'\.cloudflare\.net\.?$|\.cdn\.cloudflare\.net\.?$', re.I)


def detect_cloudflare(html: str, headers: dict | None, ip_meta: dict | None = None) -> dict:
    """Multi-source CF detection. Looks at headers first (strongest), then body
    markers, then IP/CNAME hints. Returns {behind_cf, signals[], cf_ray, server}."""
    signals = []
    cf_ray = None
    server = None
    if headers:
        srv = (headers.get("Server") or headers.get("server") or "").strip()
        if srv: server = srv
        if "cloudflare" in srv.lower():
            signals.append(f"server_header:{srv}")
        if headers.get("CF-RAY") or headers.get("cf-ray"):
            cf_ray = headers.get("CF-RAY") or headers.get("cf-ray")
            signals.append(f"cf_ray_header:{cf_ray}")
        for hk in ("CF-Cache-Status","cf-cache-status","CF-Connecting-IP",
                   "Expect-CT","cf-mitigated","cf-apo-via"):
            if hk in headers or hk.lower() in headers:
                signals.append(f"cf_header:{hk}")
    if html and _CF_BODY_SIGNAL_RE.search(html):
        signals.append("cf_body_marker")
    if html and not cf_ray:
        m = _CF_RAY_RE.search(html)
        if m: cf_ray = m.group(1); signals.append(f"cf_ray_inline:{m.group(1)}")
    if ip_meta:
        # CF AS13335 IPs
        asn = (ip_meta.get("asn") or "").lower()
        if "13335" in asn or "cloudflare" in asn:
            signals.append(f"cf_asn:{ip_meta.get('asn')}")
        # CF CIDRs (subset; could be expanded with full official list)
        ip = ip_meta.get("ip") or ""
        if ip.startswith(("104.16.", "104.17.", "104.18.", "104.19.", "104.20.", "104.21.",
                           "172.64.", "172.65.", "172.66.", "172.67.", "172.68.", "172.69.",
                           "162.158.", "131.0.72.", "162.159.", "188.114.")):
            signals.append(f"cf_ip_cidr:{ip}")
        cname = ip_meta.get("cname") or ""
        if _CF_CNAME_HINTS.search(cname):
            signals.append(f"cf_cname:{cname}")
    return {
        "behind_cf": bool(signals),
        "signals":   signals,
        "cf_ray":    cf_ray,
        "server":    server,
    }


# ============================================================================
# ErrTraffic URL parser — pull token/mode/src/os/etc out of any panel URL
# ============================================================================
def parse_errtraffic_panel_url(url: str) -> dict | None:
    """Parse an ErrTraffic API URL into its constituent parts. Returns None if
    URL doesn't look like one. Handles v2, v3 (original), and v3 BW v2 generation
    URL shapes — token, src, and mode params each have multiple known aliases.
    """
    from urllib.parse import urlparse, parse_qs
    try:
        p = urlparse(url)
    except Exception:
        return None
    path = (p.path or "").lower()
    qs = parse_qs(p.query or "", keep_blank_values=True)
    version = detect_errtraffic_version(url)
    if version == "unknown":
        # not an ErrTraffic-shaped URL
        if not ("/api/" in path or "index.php" in path): return None
    qget = lambda k: (qs.get(k, [""])[0] or "").strip()
    action = qget("action") or qget("a")
    # Token aliases — v3 original used `token`; BW v2 renamed to `uj`; some
    # beacons use short-form `t`. Accept any; remember which alias we found.
    token_val, token_alias = None, None
    for alias in ERRTRAFFIC_KIT.get("bw_v2", {}).get("token_param_aliases", ["token","uj","t"]):
        v = qget(alias)
        if v: token_val, token_alias = v, alias; break
    # Source/realm aliases — v3 original `src=` (clickfix/...); BW v2 may
    # collapse to `rlm=` (4 bytes base64-url-safe of a per-deploy ID).
    src_val, src_alias = None, None
    for alias in ERRTRAFFIC_KIT.get("bw_v2", {}).get("src_param_aliases", ["src","rlm"]):
        v = qget(alias)
        if v: src_val, src_alias = v, alias; break
    info = {
        "version":  version,
        "host":     p.hostname,
        "host_defanged": _defang(p.hostname) if p.hostname else None,
        "path":     p.path,
        "action":   action,
        "token":    token_val,
        "token_alias": token_alias,    # which param name carried the token
        "os":       qget("os") or None,
        "src":      src_val,
        "src_alias": src_alias,
        "mode":     qget("mode") or None,
        "cb":       qget("cb") or None,
        "ref":      qget("ref") or None,
        # BW v2: `q` carries the encrypted envelope on signed-outgoing-request URLs
        "envelope_q": qget("q") or None,
    }
    # known role
    if action in ("dl","download"):                       info["role"] = "payload_download"
    elif action in ("cfg","settings"):                    info["role"] = "config_fetch"
    elif action == "evt":                                 info["role"] = "telemetry"
    elif action == "init":                                info["role"] = "session_init"
    elif action in ("generateDownloadToken","gen-token"): info["role"] = "token_generation"
    elif "css.js" in path:                                info["role"] = "obfuscated_loader"
    elif info["envelope_q"]:                              info["role"] = "encrypted_envelope_request"
    # ── v2 endpoints (where the action is in the path, not the query string)
    elif "generate-download-token.php" in path:           info["role"] = "token_generation"
    elif "download.php" in path:                          info["role"] = "payload_download"
    elif "log.php" in path:                               info["role"] = "telemetry"
    else:                                                 info["role"] = "unknown"
    return info


# ============================================================================
# Server / endpoint fingerprinting — DNS + ports + TLS cert  (cached)
# ============================================================================
_SERVER_FP_CACHE: dict[str, dict] = {}
_SERVER_FP_LOCK  = threading.Lock()

def probe_wordpress_backdoor(origin: str, *, timeout: int = 6,
                              verify_tls: bool = True) -> dict:
    """Passive probe for the ErrTraffic WordPress backdoor footprint, per
    LevelBlue 2026 + Sucuri 2025. The kit drops a base64-decoded session-manager.php
    into /wp-content/mu-plugins/ to capture admin credentials and ensure persistence
    (mu-plugins auto-load on every WP request, no manual activation needed).

    We probe a small set of common backdoor paths via HEAD/GET and report what
    is/isn't reachable. We DO NOT execute anything — pure observation. A 200 OR
    a strongly-suggestive non-200 (e.g. PHP error page, 403 from an existing
    file) is reported with the body excerpt so the analyst can decide.

    Returns: {"checked": int, "hits": [{path, status, content_type, body_head, signal}],
              "wp_admin_redirect_check": {...}, "notes": [str...]}.
    Caller decides confidence — we just report what we saw."""
    from urllib.parse import urljoin
    origin = origin.rstrip("/")
    # Paths to probe — only ErrTraffic-attributed mu-plugins names per LevelBlue
    # 2026, plus the parent dir for listing detection. We deliberately do NOT
    # probe wp-includes/js/dist/script-modules/.../view.min.js: that's a
    # legitimate WP 6.4+ Interactivity API file present on EVERY WP site of
    # that version, not a kit IOC by itself.
    paths = [
        # ErrTraffic-specific (LevelBlue 2026 — session-manager.php in mu-plugins)
        ("/wp-content/mu-plugins/session-manager.php", "errtraffic_backdoor_levelblue"),
        ("/wp-content/mu-plugins/",                     "mu_plugins_dir_listing"),
        # Common companion-backdoor names (Sucuri / Hudson Rock observations)
        ("/wp-content/mu-plugins/auto-loader.php",      "mu_plugins_loader_unusual"),
        ("/wp-content/mu-plugins/wp-load.php",          "mu_plugins_wpload_unusual"),
    ]
    headers = {"User-Agent": _BROWSER_UA,
               "Accept":     "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8"}
    hits = []
    cf_intercept_count = 0

    def _is_cf_interstitial(att: dict) -> bool:
        """Detect when the response was served by Cloudflare's error /
        challenge handler rather than the origin server itself."""
        hdrs = att.get("response_headers") or {}
        body = (att.get("body_text_head") or "").lower()
        return (
            (hdrs.get("server") or "").lower() == "cloudflare"
            and (
                "cloudflare" in body or "cf-ray" in body
                or "ie6 oldie" in body          # the CF classic 403/404 template
                or "<!doctype html>\r" in body  # CF interstitial CRLF signature
                or att.get("status") in (403, 503, 520, 521, 522, 523, 524, 525, 526)
                and "<!doctype html" in body
            )
        )

    for path, signal_name in paths:
        url = origin + path
        att = _http_get_safe(url, headers, timeout, max_bytes=8192)
        if att["status"] is None:
            continue  # network error — not informative
        if att["status"] == 404:
            continue  # path absent — not a hit (don't log noise)
        cf_blocked = _is_cf_interstitial(att)
        if cf_blocked:
            cf_intercept_count += 1
        body_head = (att["body_text_head"] or "")[:200]
        # Confidence tier for THIS hit:
        #   high   = 200 + non-empty body + content-type that suggests PHP execution
        #   medium = 200 + 0-byte body (could be backdoor returning empty for our
        #            probe, OR an empty file, OR a cache hit). Ambiguous.
        #   low    = 403/401 served by origin (path exists but ACL'd)
        #   intercepted = 403/5xx served by Cloudflare (we can't tell what's there)
        if cf_blocked:
            tier = "cf_intercepted"
        elif att["status"] == 200 and (att.get("bytes") or 0) > 0:
            tier = "high"
        elif att["status"] == 200:
            tier = "medium"  # 0 bytes — ambiguous
        elif att["status"] in (401, 403):
            tier = "low"
        else:
            tier = "low"
        hits.append({
            "path":            path,
            "url":             url,
            "status":          att["status"],
            "content_type":    att["content_type"],
            "bytes":           att["bytes"],
            "body_head":       body_head,
            "signal":          signal_name,
            "cf_intercepted":  cf_blocked,
            "confidence_tier": tier,
        })
    notes = []
    high_conf_hits = [h for h in hits if h["confidence_tier"] == "high"
                       and h["signal"] == "errtraffic_backdoor_levelblue"]
    medium_conf_hits = [h for h in hits if h["confidence_tier"] == "medium"
                         and h["signal"] == "errtraffic_backdoor_levelblue"]
    if high_conf_hits:
        notes.append("session-manager.php returned HTTP 200 with a non-empty body — "
                     "strong indicator of ErrTraffic PHP backdoor (LevelBlue 2026). "
                     "Manually inspect the body to confirm.")
    elif medium_conf_hits:
        notes.append("session-manager.php returned HTTP 200 but 0-byte body. "
                     "Ambiguous — could be the backdoor silently returning empty "
                     "for our request, an empty placeholder file, or a CDN cache "
                     "hit. NOT confirmation of the backdoor by itself.")
    if cf_intercept_count > 0:
        notes.append(f"{cf_intercept_count} of {len(paths)} responses were served "
                     "by Cloudflare's edge (not the origin server) — these "
                     "tell us nothing about what files actually exist on disk.")
    if not hits:
        notes.append("No probed paths returned a non-404 response. Absence is NOT "
                     "proof the backdoor isn't present (mu-plugins is usually not "
                     "listable and the kit may use other filenames).")
    return {"checked": len(paths), "hits": hits, "notes": notes,
            "cf_intercepted_count": cf_intercept_count}


def shodan_host_enrich(ip: str, *, api_key: str | None = None,
                       timeout: float = 10.0) -> dict | None:
    """OPTIONAL free enrichment via Shodan's /shodan/host/{ip} endpoint.
    Returns None if no Shodan key is configured OR Shodan returns 404 for
    the IP. On Membership tier this endpoint is FREE (no query credit
    deducted, verified 2026-05-28). Returns a slim dict — hostnames,
    domains, tags, ports, org, asn, country, n_services. We keep banners
    out of this dict to avoid bloating per-target reports; the full data
    is one API call away for an analyst who wants it.

    The Cloudflare WAF on `/shodan/host/search` rejects browser-style UAs;
    `/shodan/host/{ip}` is more lenient but we use the same non-browser
    UA for consistency."""
    if not api_key or not ip: return None
    try:
        req = urllib.request.Request(
            f"https://api.shodan.io/shodan/host/{ip}?key={api_key}&minify=false",
            headers={"User-Agent": "python-requests/2.31.0",
                     "Accept": "application/json"})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            j = json.loads(r.read())
    except urllib.error.HTTPError as e:
        if e.code == 404: return None     # IP simply not indexed
        return {"error": f"HTTP {e.code}", "ip": ip}
    except Exception as e:
        return {"error": f"{type(e).__name__}: {str(e)[:100]}", "ip": ip}
    services = j.get("data") or []
    return {
        "ip":          j.get("ip_str") or ip,
        "hostnames":   j.get("hostnames") or [],
        "domains":     j.get("domains")   or [],
        "tags":        j.get("tags")      or [],
        "ports":       sorted(set(j.get("ports") or [])),
        "org":         j.get("org"),
        "asn":         j.get("asn"),
        "country":     j.get("country_code"),
        "country_name": j.get("country_name"),
        "city":        j.get("city"),
        "isp":         j.get("isp"),
        "last_update": j.get("last_update"),
        "n_services":  len(services),
        "vulns":       sorted(j.get("vulns") or []),   # CVEs if any
        "service_products": sorted({s.get("product","") for s in services if s.get("product")}),
    }


_ADMIN_LOGIN_MARKERS = (
    # English / generic auth-panel markers
    "login", "log in", "sign in", "username", "password", "dashboard",
    "administration", "admin panel", "authentication",
    # ErrTraffic / GlitchFix kit markers
    "errtraffic", "glitchfix", "browserwarning",
    # Russian admin-UI markers (ErrTraffic v2 ships a Russian-only admin per Censys)
    "вход", "авторизац", "логин", "пароль", "панель",
    # Tooling often co-located on panel hosts
    "phpmyadmin", "adminer",
)
_ADMIN_INSTALL_MARKERS = ("install", "setup", "database", "db_host", "db_name",
                          "configuration", "step 1", "installation")
# A GENUINE login PAGE = a real password <input>. This is stricter than the
# keyword markers (which match any page merely mentioning "login"/"password") and
# lets us separate an exposed login *form* (gated by creds) from admin *content*
# served without auth. S47: two open-login classes confirmed live across the fleet —
#   v3-original flagship  /admin/   -> <input type=password>, title "Landing Analytics"
#                                       (client-side key gate; api.php?action=summary
#                                        returns 403 {"error":"unauthorized"} w/o key)
#   LenAI kit-author dev  /login.php -> username+password+CAPTCHA, title "Authorization"
#                                       (rpc-cloud.beer, composer name "id0/project")
# Hardened BW v2 production panels expose NO HTML login (only /api/* + /admin/partials/*).
_ADMIN_PW_INPUT_RE = re.compile(r"""<input[^>]+type\s*=\s*["']?password""", re.I)
def _admin_login_kind(title: str, body_lc: str) -> str:
    t = (title or "").lower()
    if "landing analytics" in t:
        return "v3_landing_analytics"          # flagship v3-original key-gated dashboard login
    if "authorization" in t and "captcha" in body_lc:
        return "authorization_captcha"         # LenAI kit-author dev instance (id0/project)
    if "wordpress" in t or "wp-login" in body_lc:
        return "wordpress"
    return "generic"


def probe_admin_panel(origin: str, *, timeout: int = 6, verify_tls: bool = True,
                      progress_fh=None) -> dict:
    """Passive probe for an EXPOSED operator admin / install panel on a ClickFix
    (ErrTraffic/GlitchFix) C2 host.

    CTI basis (Censys 'Inside a GlitchFix Attack Panel', 2026): ErrTraffic panels
    expose a PHP admin login (v2 = Russian-only UI) plus an install wizard; one
    misconfigured instance leaked full source. The operator admin lives on the
    SAME victim-facing panel host under /admin/* and /install.php (distinct from
    the separate Aeternum operator Next.js panel on :3000/:1337). We GET each
    documented admin path and report which EXIST (200 / 30x / 401 / 403 = not a
    404), with a title + marker excerpt and a severity call. Pure passive HTTP —
    no auth attempts, no writes, no exploitation.

    Returns: {origin, probed:[url...], found:[{path,url,url_defanged,status,
              content_type,bytes,title,markers,severity,note}], any_open:bool,
              any_unauth_200:bool}.
    Severity: 'exposed_unauth' (200 + admin/install markers — operator panel
    reachable without auth), 'install_wizard' (install.php live — can re-init DB
    / mint an admin), 'exists_protected' (30x/401/403 — surface present, gated),
    'exists' (200, no strong markers)."""
    origin = origin.rstrip("/")
    cache_key = origin.lower()
    with _ADMIN_PROBE_CACHE_LOCK:
        cached = _ADMIN_PROBE_CACHE.get(cache_key)
    if cached is not None:
        out = dict(cached); out["cache_hit"] = True
        return out
    out = {"origin": origin, "probed": [], "found": [],
           "any_open": False, "any_unauth_200": False}
    paths = list(ERRTRAFFIC_KIT.get("admin_paths") or [])
    # WP admin login is also worth a look on WP-hosted panels/lures.
    for extra in ("/wp-login.php", "/wp-admin/"):
        if extra not in paths:
            paths.append(extra)
    headers = {"User-Agent": _BROWSER_UA,
               "Accept": "text/html,application/xhtml+xml,*/*;q=0.8"}
    title_re = re.compile(r"<title[^>]*>(.*?)</title>", re.I | re.S)
    out["probed"] = [out["origin"] + p for p in paths]
    def _probe_one(path):
        # Returns (status_label, rec) so MISSES are observable too: a label of
        # "404" / "err:<reason>" / "interrupted" lets the caller build a status
        # histogram. Before S43 every miss collapsed to None, so "0 admin found"
        # could not be distinguished from "host timed out on every path" — the
        # peer-review observability gap. rec is the found-record or None.
        if _interrupted():
            return ("interrupted", None)
        url = out["origin"] + path
        try:
            att = _http_get_safe(url, headers, timeout, max_bytes=65_536,
                                 verify_tls=verify_tls)
        except TypeError:
            att = _http_get_safe(url, headers, timeout, max_bytes=65_536)
        except Exception as e:
            return (f"err:{type(e).__name__}", None)
        status = att.get("status")
        if status is None:
            return (f"err:{(att.get('error') or 'no_status')}"[:40], None)
        if status == 404:
            return ("404", None)  # path genuinely absent — not an admin surface
        # Use the FULL body (up to max_bytes) not the 400-byte head — login <form>s and
        # password inputs sit late in the document (flagship /admin/ is ~25 KB; the
        # <input type=password> is well past byte 400, so head-only missed every form).
        _bb = att.get("body_bytes")
        body = _bb.decode("utf-8", "replace") if _bb else (att.get("body_text_head") or "")
        body_lc = body.lower()
        m = title_re.search(body)
        title = (m.group(1).strip()[:160] if m else "")
        markers = sorted({kw for kw in _ADMIN_LOGIN_MARKERS if kw in body_lc})
        has_login_form = bool(_ADMIN_PW_INPUT_RE.search(body))
        login_kind = _admin_login_kind(title, body_lc) if has_login_form else None
        # composer.json build fingerprint (S47) — bare "{require:{maxmind-db/reader}}"
        # = hardened BW v2 production fleet; name "id0/project" + GeoLite2 desc = the
        # LenAI kit-author reference/dev build (rpc-cloud.beer). Pure backend attribution.
        backend_build = None; backend_lock_hash = None
        if path.endswith("composer.json") and status == 200 and ("maxmind" in body_lc or '"require"' in body):
            _nm = re.search(r'"name"\s*:\s*"([^"]+)"', body)
            backend_build = (_nm.group(1) if _nm else "maxmind-bare")
        # composer.lock content-hash = a CRYPTOGRAPHIC build-pipeline fingerprint. S47: the
        # ENTIRE production fleet shares one hash (0199ba7b… , single maxmind-db/reader pkg)
        # = one kit source across all operators; the LenAI dev instance rpc-cloud.beer has a
        # distinct hash (09146794…, full geoip2/geoip2 API) = dev-vs-prod build split.
        if path.endswith("composer.lock") and status == 200 and "content-hash" in body_lc:
            _ch = re.search(r'"content-hash"\s*:\s*"([0-9a-f]{8,})"', body)
            backend_lock_hash = (_ch.group(1)[:16] if _ch else None)
        # composer.lock/installed.json "time" fields date the build: max(time) = a build-date
        # FLOOR (composer install happened on/after the newest pinned package). S47: production
        # fleet build-floor 2025-11-21 (maxmind-db/reader v1.13.1) vs the LenAI dev box rpc-cloud.beer
        # 2026-01-13 (full geoip2 web-service stack) ⇒ the dev box runs a NEWER v-next build.
        backend_build_date = None
        if path.endswith(("composer.lock", "installed.json")) and status == 200 and '"time"' in body:
            _times = re.findall(r'"time"\s*:\s*"(\d{4}-\d{2}-\d{2})', body)
            if _times:
                backend_build_date = max(_times)
        # robots.txt that Disallows non-trivial paths can leak hidden admin dirs (op hiding them
        # from crawlers). "Disallow: /" alone is generic block-all (no intel).
        robots_disallow = None
        if path.endswith("robots.txt") and status == 200 and "disallow" in body_lc:
            _dis = [d.strip() for d in re.findall(r'(?im)^\s*Disallow:\s*(\S+)', body)]
            robots_disallow = [d for d in _dis if d not in ("/", "")] or None
        # Install wizard: path-driven first; body-driven requires STRONG evidence
        # (>=2 install markers AND an explicit install/setup word) so a single
        # incidental "database"/"configuration" word can't mislabel e.g. composer.json
        # (desc "GeoIP lookup via GeoLite2 database") as an install wizard.
        is_install = path.endswith(("install.php", "installer.php", "setup.php",
                                     "install/", "/install")) or (
            sum(kw in body_lc for kw in _ADMIN_INSTALL_MARKERS) >= 2
            and ("install" in body_lc or "setup" in body_lc))
        # S43 — PHP error discriminator. The expanded admin sweep frequently hits
        # admin PARTIALS (/admin/partials/*.php) that are meant to be include()d by
        # an authenticated parent; called directly they emit a PHP "Fatal error:
        # Call to undefined function errtraffic_csrf_token()" (200 body). That is
        # NOT a usable exposed admin panel — it is INFORMATION DISCLOSURE (leaks the
        # absolute server path + confirms the kit-internal file). Before S43 the
        # `errtraffic` token in the error text matched _ADMIN_LOGIN_MARKERS and the
        # path got mis-labeled `exposed_unauth`/"operator panel exposed (HIGH)" —
        # an over-claim on 74/163 reachable panels in the 6-01 sweep. Reclassify.
        is_php_error = any(k in body for k in ("Fatal error", "Parse error",
                           "Uncaught Error", "Stack trace</", "Stack trace\n")) or \
                       ("call to undefined function" in body_lc)
        leaked_path = None
        if is_php_error:
            _mp = re.search(r"(?:in|thrown in)\s+<b>([^<]+)</b>|in\s+(/[\w./\-]+\.php)", body)
            if _mp:
                leaked_path = (_mp.group(1) or _mp.group(2) or "").strip()
        # Severity call (php_error takes precedence over the marker→exposed branch)
        if status == 200 and is_php_error:
            severity = "info_disclosure"
            note = ("PHP error served unauth — leaks server path / confirms admin file "
                    "present, but no usable UI rendered (info disclosure, MEDIUM)"
                    + (f"; path={leaked_path}" if leaked_path else ""))
        elif status == 200 and is_install:
            severity, note = "install_wizard", ("install/setup wizard reachable — "
                "can re-initialize DB or create an operator account (HIGH)")
        elif status == 200 and has_login_form:
            severity, note = "open_login", ("operator login PAGE reachable (real password "
                f"form, kind={login_kind}) — access still gated by creds/key; confirms an "
                "admin exists + leaks its UI/structure (HIGH-but-gated)")
        elif status == 200 and markers:
            severity, note = "exposed_unauth", ("admin/login surface served WITHOUT "
                "auth (200) — operator panel exposed (HIGH)")
        elif status == 200 and robots_disallow:
            severity, note = "info_disclosure", ("robots.txt discloses non-trivial Disallow paths "
                "(possible hidden admin dirs): " + ", ".join(robots_disallow[:8]))
        elif status == 200 and (backend_build or backend_lock_hash or backend_build_date):
            severity, note = "info_disclosure", ("composer manifest world-readable — backend "
                f"build fingerprint: {backend_build or ''}"
                + (f" lock-hash={backend_lock_hash}" if backend_lock_hash else "")
                + (f" build-floor={backend_build_date}" if backend_build_date else ""))
        elif status in (301, 302, 303, 307, 308, 401, 403):
            severity, note = "exists_protected", (f"admin path present but gated "
                f"(HTTP {status}) — surface exists, auth/redirect in place")
        elif status == 200:
            severity, note = "exists", "path served 200 (no strong admin markers)"
        else:
            severity, note = "exists", f"path present (HTTP {status})"
        return (str(status), {"path": path, "url": url, "url_defanged": _defang(url),
                "status": status, "content_type": att.get("content_type"),
                "bytes": att.get("bytes"), "title": title, "leaked_path": leaked_path,
                "markers": markers, "severity": severity, "note": note,
                "login_form": has_login_form, "login_kind": login_kind,
                "backend_build": backend_build, "backend_lock_hash": backend_lock_hash,
                "backend_build_date": backend_build_date, "robots_disallow": robots_disallow})
    # PARALLEL — the expanded admin catalog (~39 paths) sequentially × timeout
    # would be the slowest panel-mode step; a small pool keeps it to a few sec.
    import concurrent.futures as _cf
    try:
        with _cf.ThreadPoolExecutor(max_workers=min(8, len(paths))) as _ex:
            results = list(_ex.map(_probe_one, paths))
    except Exception:
        results = [_probe_one(p) for p in paths]
    recs = [rec for (_lbl, rec) in results if rec]
    # Status histogram over ALL probed paths (incl. misses) — makes "0 found"
    # unambiguous: e.g. {"404": 37, "403": 2} = no surface vs {"err:timeout": 39}
    # = host unreachable. Pure observability; does not change any verdict.
    hist: dict[str, int] = {}
    for (lbl, _rec) in results:
        hist[lbl] = hist.get(lbl, 0) + 1
    out["status_histogram"] = dict(sorted(hist.items(), key=lambda kv: -kv[1]))
    out["probed_n"] = len(results)
    out["misses_404"] = hist.get("404", 0)
    out["unreachable_probes"] = sum(v for k, v in hist.items() if k.startswith("err:"))
    # Stable severity-ordered output (highest-value first).
    _sev_rank = {"exposed_unauth": 0, "open_login": 1, "install_wizard": 2,
                 "info_disclosure": 3, "exists_protected": 4, "exists": 5}
    recs.sort(key=lambda r: (_sev_rank.get(r["severity"], 9), r["path"]))
    out["found"] = recs
    out["any_open"] = bool(recs)
    # any_unauth_200 = a USABLE admin/install surface exposed without auth. PHP-error
    # info_disclosure is deliberately EXCLUDED (it leaks a path but renders no panel).
    out["any_unauth_200"] = any(r["severity"] in ("exposed_unauth", "install_wizard")
                                 for r in recs)
    out["any_info_disclosure"] = any(r["severity"] == "info_disclosure" for r in recs)
    # S47 — open login PAGE class (reachable login form, creds/key still required).
    # Distinct from any_unauth_200 (usable surface w/o auth). The flagship v3-original
    # fleet exposes /admin/ "Landing Analytics"; rpc-cloud.beer exposes the
    # "Authorization" username+password+captcha login (LenAI kit-author dev build).
    out["any_open_login"] = any(r["severity"] == "open_login" for r in recs)
    out["open_login_kinds"] = sorted({r.get("login_kind") for r in recs
                                      if r["severity"] == "open_login" and r.get("login_kind")})
    out["backend_build"] = next((r["backend_build"] for r in recs if r.get("backend_build")), None)
    out["backend_lock_hash"] = next((r["backend_lock_hash"] for r in recs if r.get("backend_lock_hash")), None)
    out["backend_build_date"] = next((r["backend_build_date"] for r in recs if r.get("backend_build_date")), None)
    out["robots_disallow"] = next((r["robots_disallow"] for r in recs if r.get("robots_disallow")), None)
    out["leaked_paths"] = sorted({r["leaked_path"] for r in recs if r.get("leaked_path")})
    # S43 — backend-instance fingerprint + CF-origin de-anonymization. The leaked
    # aaPanel site-dir (/www/wwwroot/idNN/) is a per-origin fingerprint; if it matches
    # a known origin's default vhost, we pin the true origin even through Cloudflare.
    out["backend_site_dir"] = _extract_backend_sitedir(out["leaked_paths"])
    out["origin_deanon"] = _origin_deanon_for_sitedir(out["backend_site_dir"])
    if progress_fh:
        for r in recs:
            print(f"[admin-probe] {r['severity']:16s} {r['status']} {r['url']}",
                  file=progress_fh)
    with _ADMIN_PROBE_CACHE_LOCK:
        _ADMIN_PROBE_CACHE.setdefault(cache_key, out)
    return out


def _build_kit_endpoint_catalog() -> list[dict]:
    """The COMPLETE set of known ErrTraffic/GlitchFix (BW v2) endpoints to probe
    on an identified panel — built from the ERRTRAFFIC_KIT catalog (itself
    sourced from Censys 'Inside a GlitchFix Attack Panel', LevelBlue 'Err-Hiding
    and Seek', Trinity Cyber, our own BW v2 RE, and observed-in-harvest paths).

    Each entry: {path, label, kind}. `kind` groups them for the report:
      runtime  — victim-flow API (init/cfg/settings/evt/dl/css.js)
      admin    — operator mint flow (/index.php?action=…) + admin/install UI
      legacy   — v2 (pre-Polygon) endpoints
      artifact — kit binaries/archives a victim's PS would fetch
      recon    — generic fingerprinting paths
    """
    k = ERRTRAFFIC_KIT
    cat: list[dict] = []
    seen: set[str] = set()
    def add(path, label, kind):
        if path and path not in seen:
            seen.add(path); cat.append({"path": path, "label": label, "kind": kind})
    for name, path in (k.get("panel_endpoints_v3_runtime") or {}).items():
        add(path, f"v3 runtime: {name}", "runtime")
    for name, path in (k.get("panel_endpoints_v3_admin") or {}).items():
        add(path, f"v3 admin: {name}", "admin")
    for name, path in (k.get("panel_endpoints_v2") or {}).items():
        add(path, f"v2 legacy: {name}", "legacy")
    # Only the CANONICAL admin entry points go in the surface map — the
    # exhaustive ~33-path admin sweep is owned by probe_admin_panel (which does
    # deeper marker/severity analysis). Including the full admin_paths here would
    # double-probe every admin path per panel (admin_probe + endpoint_probe) and
    # erode the v6.4 speedup, so we keep just the headline surfaces.
    for path in ("/admin/login.php", "/admin/", "/install.php"):
        add(path, "admin/install UI", "admin")
    # Kit artifacts a victim's clipboard PS pulls (BW v2 .7z dropper chain),
    # plus action aliases + recon paths observed across harvests.
    for path, label, kind in [
        ("/api/7z.exe",                "BW v2 7-Zip self-extractor", "artifact"),
        ("/api/index.php?a=7z",        "v3 runtime: 7z archive",     "artifact"),
        ("/api/index.php?a=log",       "v3 runtime: log beacon",     "runtime"),
        ("/api/index.php?a=ping",      "v3 runtime: ping",           "runtime"),
        ("/api/index.php?a=generateDownloadToken", "v3 runtime: gen-token alias", "runtime"),
        ("/api/index.php",             "v3 runtime: bare index",     "runtime"),
        ("/api/log.php",               "v2 legacy: log",             "legacy"),
        ("/robots.txt",                "recon: robots",              "recon"),
        ("/favicon.ico",               "recon: favicon",             "recon"),
        ("/.git/config",               "recon: exposed .git",        "recon"),
        ("/server-status",             "recon: apache status",       "recon"),
    ]:
        add(path, label, kind)
    return cat

_KIT_ENDPOINT_CATALOG = None  # lazy-built

def probe_known_endpoints(origin: str, *, timeout: int = 8, verify_tls: bool = False,
                          progress_fh=None) -> dict:
    """NEW (Task: find ALL known endpoints). Passively GET every known kit
    endpoint on an identified panel and report which EXIST/respond — a complete
    attack-surface map per panel. Pure passive HTTP (small byte caps; the dl/7z
    artifacts are NOT downloaded in full — only HEADed for existence). Per-origin
    cached so a sweep probes each panel's surface once.

    Returns: {origin, catalog_size, probed:[url...],
              found:[{path,label,kind,status,content_type,bytes,classification}],
              summary:{live,gated,absent,error, by_kind:{...}}}.
    classification: live (200) / gated (401/403/405/30x) / absent (404/None) / error."""
    global _KIT_ENDPOINT_CATALOG
    origin = origin.rstrip("/")
    ck = origin.lower()
    with _ENDPOINT_PROBE_CACHE_LOCK:
        c = _ENDPOINT_PROBE_CACHE.get(ck)
    if c is not None:
        out = dict(c); out["cache_hit"] = True; return out
    if _KIT_ENDPOINT_CATALOG is None:
        _KIT_ENDPOINT_CATALOG = _build_kit_endpoint_catalog()
    cat = _KIT_ENDPOINT_CATALOG
    out = {"origin": origin, "catalog_size": len(cat), "probed": [], "found": [],
           "summary": {"live": 0, "gated": 0, "absent": 0, "error": 0, "by_kind": {}}}
    hdrs = {"User-Agent": _BROWSER_UA, "Accept": "*/*", "Referer": origin + "/"}
    host = _urlsplit_host(origin)
    def _probe_one(ent):
        if _interrupted():
            return None
        path = ent["path"]
        # Some endpoints need the victim params to respond meaningfully; add a
        # benign set so init/cfg/dl don't 400 purely for missing params.
        url = origin + path
        if path.startswith("/api/index.php?a=") and path.split("a=")[-1] in (
                "init", "cfg", "settings", "dl", "evt", "7z", "generateDownloadToken"):
            url = f"{url}&os=windows&src={host}&mode=cloudflare"
        att = _http_get_safe(url, hdrs, timeout, max_bytes=8192, verify_tls=verify_tls)
        status = att.get("status")
        if status == 200:
            cls = "live"
        elif status in (301, 302, 303, 307, 308, 401, 403, 405):
            cls = "gated"
        elif status in (None, 404):
            cls = "absent"
        else:
            cls = "error" if att.get("error") and status is None else "gated"
        return (ent, url, status, cls, att.get("content_type"), att.get("bytes"))
    # Parallel — 31 independent GETs serially would be the slowest panel-mode
    # step (~15s); a small pool keeps it to ~3s. Per-host cached either way.
    import concurrent.futures as _cf
    results = []
    try:
        with _cf.ThreadPoolExecutor(max_workers=min(8, len(cat))) as _ex:
            results = [r for r in _ex.map(_probe_one, cat) if r is not None]
    except Exception:
        results = [r for r in (_probe_one(e) for e in cat) if r is not None]
    for ent, url, status, cls, ct, nbytes in results:
        out["probed"].append(url)
        out["summary"][cls] = out["summary"].get(cls, 0) + 1
        if cls in ("live", "gated"):
            out["found"].append({
                "path": ent["path"], "label": ent["label"], "kind": ent["kind"],
                "status": status, "content_type": ct,
                "bytes": nbytes, "classification": cls})
            out["summary"]["by_kind"][ent["kind"]] = \
                out["summary"]["by_kind"].get(ent["kind"], 0) + 1
            if progress_fh:
                print(f"[endpoints] {cls:6s} {status} {ent['path']}  ({ent['label']})",
                      file=progress_fh)
    # Stable, useful ordering: live first, then gated; within each by kind.
    out["found"].sort(key=lambda f: (f["classification"] != "live", f["kind"], f["path"]))
    with _ENDPOINT_PROBE_CACHE_LOCK:
        _ENDPOINT_PROBE_CACHE.setdefault(ck, out)
    return out


def _urlsplit_host(origin: str) -> str:
    try:
        from urllib.parse import urlsplit
        return (urlsplit(origin).hostname or "").lower()
    except Exception:
        return ""


def synthesize_colocated_hosts(fp: dict | None, queried_host: str | None) -> dict:
    """Answer 'what OTHER URLs/endpoints live on the same server?' from data we
    ALREADY collected — no extra requests. Two reliable sources + an honesty flag:
      - via_cert_san: other hostnames on the panel's TLS cert (a SHARED cert
        binds co-located panels to one backend — S40 found CN=anlytic-js-cloud.beer
        binding 3 hosts; most panels have a per-host cert so this is often empty).
      - via_shodan:   hostnames/domains Shodan has seen on the panel's IP.
      - is_cf_edge:   when the IP is Cloudflare (AS13335), the IP-based Shodan
        data + open ports reflect the CF EDGE, not the operator origin — so
        via_shodan/ports are NOT co-located operator infra. cert-SAN stays valid.
    Co-located KNOWN PANELS are flagged (cross-refs the baked KB)."""
    out = {"via_cert_san": [], "via_shodan": [], "is_cf_edge": False,
           "known_panels_colocated": [], "note": ""}
    fp = fp or {}
    qh = (queried_host or "").lower().rstrip(".")
    cert = fp.get("tls_cert") or {}
    for s in (cert.get("san") or []):
        sl = (s or "").lower().lstrip("*.").rstrip(".")
        if sl and sl != qh and sl not in out["via_cert_san"]:
            out["via_cert_san"].append(sl)
    sh = fp.get("shodan") or {}
    asn = str(sh.get("asn") or "")
    org = (sh.get("org") or "").lower()
    out["is_cf_edge"] = ("13335" in asn) or org.startswith("cloudflare")
    for h in (list(sh.get("hostnames") or []) + list(sh.get("domains") or [])):
        hl = (h or "").lower().rstrip(".")
        if hl and hl != qh and hl not in out["via_shodan"]:
            out["via_shodan"].append(hl)
    # Which co-located hostnames are themselves KNOWN panels (strong pivot)?
    for hh in set(out["via_cert_san"]) | set(out["via_shodan"]):
        if _is_known_panel(hh):
            out["known_panels_colocated"].append(hh)
    if out["is_cf_edge"]:
        out["note"] = ("Cloudflare-fronted (AS13335): Shodan/port data reflects the CF "
                       "edge, not the operator origin — only cert-SAN co-located hosts are "
                       "reliable here.")
    return out


# ── Cloudflare edge IP classification (S43 port-FP fix) ─────────────────────────
# A port-scan of a Cloudflare-fronted host resolves to a CF EDGE IP, where CF
# terminates the public web ports (80/443/8080/8443/8000/8888/2052..2096/8880).
# Those ports answering a TCP connect is therefore CF infrastructure, NOT an
# exposed origin service. Before S43, fingerprint_server reported e.g.
# "open: 80, 443, 8080, 8443" on amalgama.lat (104.21.x) with no caveat, which
# read as exposed origin ports — a false positive on 28/28 CF panels in the
# 6-01 sweep. We now flag the edge provider so callers never mis-read CF edge
# listeners as origin services. (The non-web service ports 22/3306/6379/… are
# never proxied by CF, so on a CF edge they are always closed — origin stays
# hidden, which is the correct, honest conclusion.)
_CF_EDGE_PREFIXES = (
    "104.16.", "104.17.", "104.18.", "104.19.", "104.20.", "104.21.", "104.22.",
    "104.23.", "104.24.", "104.25.", "104.26.", "104.27.", "104.28.",
    "172.64.", "172.65.", "172.66.", "172.67.", "172.68.", "172.69.", "172.70.", "172.71.",
    "162.158.", "162.159.", "131.0.72.", "188.114.", "190.93.", "197.234.", "198.41.")
_CF_EDGE_PORTS = frozenset({80, 443, 8080, 8443, 8000, 8888,
                            2052, 2053, 2082, 2083, 2086, 2087, 2095, 2096, 8880})
def _ip_is_cloudflare(ip: str | None) -> bool:
    return bool(ip) and any(ip.startswith(p) for p in _CF_EDGE_PREFIXES)


# ── Backend site-dir de-anonymization (S43) ─────────────────────────────────────
# ErrTraffic runs on aaPanel/BT-Panel (default web root /www/wwwroot/; panel :8888/:888;
# OSINT-confirmed). The kit names each deployment's site dir with an instance-ID
# convention `/www/wwwroot/idNN/` (NOT by domain). Hitting an admin PARTIAL directly
# (/admin/partials/*.php) throws an unhandled PHP "Call to undefined function
# errtraffic_csrf_token()" that LEAKS that absolute path. Crucially, each origin SERVER
# has a DISTINCT default-vhost site-dir (S43-verified by junk-Host probe: 178.16.52.101→
# id75, 158.94.209.253→id4), so the leaked site-dir is a per-ORIGIN fingerprint — and
# because Cloudflare forwards the request to the origin, the leak SURVIVES CF: a
# CF-fronted panel whose partials leak `id75` has its true origin on the id75 box
# (178.16.52.101), which cert-SAN/Shodan-on-the-edge cannot reveal. The generic value is
# the extracted site-dir (cluster panels sharing it = same backend instance); the KNOWN
# map adds origin-IP attribution for the defaults we have ground-truthed.
_SITEDIR_RE = re.compile(r"/www/wwwroot/([A-Za-z0-9_.\-]{1,40})/")
KNOWN_BACKEND_ORIGINS = {
    # leaked default-vhost site-dir -> the origin server it pins to (ground-truthed S43)
    "id75":      {"origin_ip": "178.16.52.101", "asn": "AS202412 OMEGATECH (BGP-RIS, S40)",
                  "note": "default/catch-all vhost of the OMEGATECH multi-tenant box; the CF-fronted "
                          ".shop/.site 'chances/opportunity' fleet + the anlytic .beer cluster share it"},
    "id4":       {"origin_ip": "158.94.209.253", "asn": "leased (Shodan org stale — verify via BGP)",
                  "note": "createbeer.beer origin (Shodan + cert-fingerprint confirmed)"},
    "errtraffic":{"origin_ip": None, "asn": None,
                  "note": "NAMED (not idNN) site-dir = the kit's canonical/reference instance (js-server.beer)"},
    "remoteshields.com": {"origin_ip": "107.189.22.239",
                  "asn": "AS14956 RouterHosting/Cloudzy (Shodan ssl.cn + live junk-Host default + S45)",
                  "note": "default/only site of customer-operator D's Cloudzy box; pierces CF for "
                          "mikelle.beer + remoteshields.com (cust-D brand = fake 'RemoteShields' theme)"},
}
def _extract_backend_sitedir(leaked_paths) -> str | None:
    """Return the aaPanel site-dir token (e.g. 'id75') from a leaked /www/wwwroot/<dir>/ path."""
    for p in (leaked_paths or []):
        m = _SITEDIR_RE.search(p or "")
        if m:
            return m.group(1)
    return None
def _origin_deanon_for_sitedir(site_dir: str | None) -> dict | None:
    """If a leaked default-vhost site-dir matches a known origin, return the de-anon record.
    Only fires for KNOWN defaults — a panel's own configured idNN does not de-anon others."""
    if site_dir and site_dir in KNOWN_BACKEND_ORIGINS:
        k = KNOWN_BACKEND_ORIGINS[site_dir]
        if k.get("origin_ip"):
            return {"site_dir": site_dir, "origin_ip": k["origin_ip"], "asn": k.get("asn"),
                    "basis": "leaked default-vhost site-dir matches a ground-truthed origin server "
                             "(survives Cloudflare — the leak comes from the origin, not the edge)",
                    "note": k.get("note")}
    return None


# ── Fleet-wide backend-origin clustering + CF de-anon (S44) ──────────────────────
# The single-host `_origin_deanon_for_sitedir` only fires for the handful of
# site-dirs we have hard-coded in KNOWN_BACKEND_ORIGINS. But a SWEEP carries the
# ground truth for free: a panel that resolves DIRECTLY to a bare IP (no
# Cloudflare) and leaks site-dir X *proves* X lives on that IP (S44-verified live:
# nsservclod.beer→178.16.52.101 leaks id30, sane-cdn-js.beer→178.16.52.101 leaks
# id63 — the box vhost-routes each real hostname to its OWN /www/wwwroot/idNN/,
# only falling back to its default site-dir for junk/bare-IP requests). So we can
# LEARN site-dir→origin-IP from any direct member of a sweep, then de-anonymize the
# CF-fronted members that leak the SAME site-dir — THROUGH Cloudflare, because the
# PHP error originates on the backend, not the CF edge. Self-updating, no hard-coding.
# RIGOR: idNN is a per-origin-server counter, so two different boxes can both have an
# "id75" — a `confirmed_origin` therefore requires a direct-resolving anchor observed
# in THIS sweep (or a ground-truthed KNOWN default); a site-dir shared only among
# CF-fronted hosts with no anchor is reported as `colocated_only` (same backend
# instance, IP unproven), and multiple distinct direct IPs on one site-dir as
# `ambiguous` (a per-box-counter collision, explicitly NOT a de-anon).
def _deanon_row_from_report(report: dict) -> dict:
    """Extract the (host, ip, is_cf, site_dir) tuple a sweep report contributes to
    backend-origin clustering. site_dir comes from the v6.7 backend_site_dir or, for
    older harvests, is re-extracted from the admin PHP-error leaked_paths."""
    fp = report.get("server_fingerprint") or {}
    ioc = report.get("ioc")
    host = (fp.get("host")
            or (ioc if isinstance(ioc, str) else (ioc or {}).get("host") if isinstance(ioc, dict) else None)
            or (report.get("input_role") or {}).get("host"))
    ip = fp.get("ip") or (fp.get("ips") or [None])[0]
    is_cf = bool(fp.get("edge_provider") == "cloudflare" or _ip_is_cloudflare(ip))
    adm = report.get("admin_probe") or {}
    site_dir = adm.get("backend_site_dir") or _extract_backend_sitedir(adm.get("leaked_paths"))
    return {"host": host, "ip": ip, "is_cf": is_cf, "site_dir": site_dir}


def cluster_backend_origins(rows: list) -> dict:
    """Fleet-wide aaPanel site-dir clustering + Cloudflare-piercing de-anonymization.

    rows: iterable of {host, ip, is_cf, site_dir}. Groups panels by leaked site-dir;
    within each group a single direct-resolving (non-CF) IP ANCHORS the origin and
    de-anonymizes the CF-fronted members. Returns {clusters, deanonymized_count, caveat}.
    Pure + deterministic (sorted) for testability; makes no network calls."""
    from collections import defaultdict
    groups = defaultdict(lambda: {"members": [], "direct_ips": defaultdict(list), "cf_members": []})
    for r in rows or []:
        sd = (r or {}).get("site_dir")
        if not sd:
            continue
        g = groups[sd]
        host = r.get("host") or r.get("ip")
        if host:
            g["members"].append(host)
        if r.get("is_cf"):
            if host: g["cf_members"].append(host)
        elif r.get("ip"):
            g["direct_ips"][r["ip"]].append(host or r["ip"])
    clusters, deanon_total = [], 0
    for sd, g in sorted(groups.items(), key=lambda x: (-len(set(x[1]["members"])), x[0])):
        direct_ips = {ip: sorted(set(h)) for ip, h in g["direct_ips"].items()}
        known = KNOWN_BACKEND_ORIGINS.get(sd) or {}
        anchor_ip = basis = None
        tier = "colocated_only"
        if len(direct_ips) == 1:
            anchor_ip = next(iter(direct_ips))
            basis = "direct-resolving (non-CF) member in this sweep anchors the origin IP"
            tier = "confirmed_origin"
        elif len(direct_ips) > 1:
            basis = (f"AMBIGUOUS: {len(direct_ips)} distinct direct IPs share site-dir '{sd}' "
                     f"(idNN is a per-box counter — collision, NOT a de-anon)")
            tier = "ambiguous"
        elif known.get("origin_ip"):
            anchor_ip = known["origin_ip"]
            basis = "ground-truthed KNOWN_BACKEND_ORIGINS default-vhost mapping"
            tier = "confirmed_origin"
        cf_deanon = sorted(set(g["cf_members"])) if anchor_ip else []
        deanon_total += len(cf_deanon)
        clusters.append({
            "site_dir": sd,
            "n_members": len(set(g["members"])),
            "origin_ip": anchor_ip,
            "asn": known.get("asn"),
            "tier": tier,
            "basis": basis,
            "direct_ips": direct_ips,
            "cf_members_deanonymized": cf_deanon,
            "members": sorted(set(g["members"])),
        })
    return {"clusters": clusters,
            "deanonymized_count": deanon_total,
            "caveat": ("idNN is a per-origin-server counter; 'confirmed_origin' requires a "
                       "direct-resolving anchor in-sweep or a ground-truthed default. CF-fronted "
                       "members sharing a site-dir with a direct anchor are de-anonymized THROUGH "
                       "Cloudflare (the PHP-error leak originates on the backend, not the CF edge).")}


def fingerprint_server(host: str, *, timeout: float = 4.0,
                       probe_ports: tuple = (
                           # web / origin
                           443, 80, 8443, 8080, 8000, 8888,
                           # operator-facing panel signatures (Aeternum Next.js
                           # admin on :3000, alt :1337 — S28/S37)
                           3000, 1337,
                           # origin services frequently left exposed on panel
                           # hosts (S37 OPSEC: SSH 742, MySQL 114, Redis 5,
                           # Elastic 2, RDP 14). MySQL matters: ErrTraffic stores
                           # ALL state (admin accts, tokens, config) in MySQL.
                           22, 21, 3306, 6379, 9200, 5432, 3389, 27017),
                       fetch_cert: bool = True,
                       shodan_key: str | None = None) -> dict:
    """Resolve DNS, probe a curated service-port set (parallel TCP connect),
    grab the TLS cert (peer cert only — passive, no full handshake content).
    Cached by hostname."""
    import socket
    host = host.lower().strip().rstrip(".")
    if not host: return {"error": "no host"}
    with _SERVER_FP_LOCK:
        cached = _SERVER_FP_CACHE.get(host)
    if cached: return {**cached, "from_cache": True}
    out: dict = {"host": host, "ip": None, "ips": [], "cname": None,
                 "open_ports": [], "tls_cert": None, "error": None,
                 "edge_provider": None, "origin_visible": None, "ports_note": None,
                 "from_cache": False}
    # DNS A
    try:
        infos = socket.getaddrinfo(host, None, type=socket.SOCK_STREAM)
        ips = sorted({ai[4][0] for ai in infos if ai[0] == socket.AF_INET})
        out["ips"] = ips
        out["ip"]  = ips[0] if ips else None
    except Exception as e:
        out["error"] = f"dns: {e}"
        with _SERVER_FP_LOCK: _SERVER_FP_CACHE[host] = out
        return out
    # CNAME (best-effort via socket; not all hosts have CNAME)
    try:
        canonical = socket.gethostbyname_ex(host)[0]
        if canonical.lower().rstrip(".") != host:
            out["cname"] = canonical
    except Exception: pass
    # Port probe — TCP connect scan, PARALLELIZED so the expanded service-port
    # set (16 ports) stays fast: sequential × 16 × timeout would be minutes per
    # host. Per-port connect timeout is capped at 3s; up to 8 ports concurrently.
    import concurrent.futures as _cf
    def _try_port(port):
        try:
            with socket.create_connection((out["ip"], port), timeout=min(timeout, 3.0)):
                return port
        except Exception:
            return None
    try:
        with _cf.ThreadPoolExecutor(max_workers=min(8, len(probe_ports))) as _ex:
            out["open_ports"] = sorted(p for p in _ex.map(_try_port, probe_ports)
                                       if p is not None)
    except Exception:
        # Fallback to sequential if the pool can't spin up (very constrained env)
        out["open_ports"] = sorted(p for p in (_try_port(pp) for pp in probe_ports)
                                   if p is not None)
    # S43 — classify edge vs origin so open ports are never mis-read. On a
    # Cloudflare edge IP the open web ports are CF listeners (origin hidden);
    # on a non-CF IP the ports DO belong to the host (origin visible) — which
    # is exactly the S42 "origin-visible cluster" signal.
    if _ip_is_cloudflare(out["ip"]):
        out["edge_provider"] = "cloudflare"
        out["origin_visible"] = False
        nonedge = [p for p in out["open_ports"] if p not in _CF_EDGE_PORTS]
        out["ports_note"] = ("resolved IP is a Cloudflare edge — open web ports are CF edge "
                             "listeners, NOT origin services; the true origin is hidden behind CF"
                             + (f"; NON-edge ports also seen: {nonedge}" if nonedge else ""))
    elif out["ip"]:
        out["edge_provider"] = None
        out["origin_visible"] = True
    # TLS cert from 443 if it's open
    if fetch_cert and 443 in out["open_ports"]:
        try:
            # D2 FIX (S37): CERT_NONE causes getpeercert() to return {} — the
            # Python ssl docs explicitly state that CERT_NONE suppresses the
            # decoded dict.  Use CERT_OPTIONAL instead: it downloads and
            # DECODES the peer certificate (populating notAfter etc.) but does
            # NOT verify the chain — so expired / self-signed certs (e.g.
            # megamegalodon.click) still return a full cert dict rather than {}.
            ctx = ssl.create_default_context()
            ctx.check_hostname = False
            ctx.verify_mode = ssl.CERT_OPTIONAL
            with socket.create_connection((out["ip"], 443), timeout=timeout) as raw:
                with ctx.wrap_socket(raw, server_hostname=host) as s:
                    der = s.getpeercert(binary_form=True)
                    cert = s.getpeercert()
            if cert:
                # Derive an `expired` boolean from notAfter so callers (and the
                # final report) can flag the OPSEC finding without re-parsing
                # the date. Format is the ssl-stdlib's strftime: "May 24 12:00:00 2026 GMT".
                expired = None
                days_remaining = None
                na = cert.get("notAfter")
                if na:
                    try:
                        # cert notAfter is GMT/UTC ("May 24 12:00:00 2026 GMT").
                        # strptime returns a NAIVE datetime even with %Z, so we
                        # attach UTC explicitly and compare against an aware
                        # now() — avoids the deprecated utcnow() and keeps the
                        # subtraction valid (aware - aware).
                        end = datetime.datetime.strptime(
                            na, "%b %d %H:%M:%S %Y %Z").replace(tzinfo=datetime.timezone.utc)
                        now = datetime.datetime.now(datetime.timezone.utc)
                        delta = (end - now).total_seconds()
                        expired = delta < 0
                        days_remaining = round(delta / 86400, 2)
                    except Exception:
                        pass
                out["tls_cert"] = {
                    "subject":    dict(x[0] for x in cert.get("subject", [])),
                    "issuer":     dict(x[0] for x in cert.get("issuer", [])),
                    "not_before": cert.get("notBefore"),
                    "not_after":  cert.get("notAfter"),
                    "expired":    expired,
                    "days_remaining": days_remaining,
                    "san":        [v for _,v in cert.get("subjectAltName", [])],
                    "fingerprint_sha256": hashlib.sha256(der).hexdigest() if der else None,
                }
        except Exception as e:
            out["tls_cert"] = {"error": str(e)[:120]}
    # OPTIONAL — free Shodan /host/{ip} enrichment when caller supplies a
    # Shodan key. Adds hostnames Shodan has historically seen for this IP,
    # CVE list, organization/ASN, and the open-port set Shodan crawled (a
    # superset of our local TCP probe, since Shodan's crawler hits more
    # ports more often). Costs ZERO query credits on Membership tier
    # (verified 2026-05-28). No-op if shodan_key is None/empty.
    if shodan_key and out.get("ip"):
        se = shodan_host_enrich(out["ip"], api_key=shodan_key)
        if se: out["shodan"] = se
    with _SERVER_FP_LOCK: _SERVER_FP_CACHE[host] = out
    return out


# ============================================================================
# AES-CBC for ErrTraffic clipboard recovery
#  - Prefers pycryptodome / cryptography if installed (fast, vetted)
#  - Falls back to a CORRECT pure-Python AES (table-driven; ~slow but tiny payload sizes)
#  - Reference: NIST FIPS-197 + standard MixColumns/InvMixColumns Galois-field multiply
# ============================================================================
_AES_SBOX = bytes.fromhex(
    "637c777bf26b6fc53001672bfed7ab76ca82c97dfa5947f0add4a2af9ca472c0"
    "b7fd9326363ff7cc34a5e5f171d8311504c723c31896059a071280e2eb27b275"
    "09832c1a1b6e5aa0523bd6b329e32f8453d100ed20fcb15b6acbbe394a4c58cf"
    "d0efaafb434d338545f9027f503c9fa851a3408f929d38f5bcb6da2110fff3d2"
    "cd0c13ec5f974417c4a77e3d645d197360814fdc222a908846eeb814de5e0bdb"
    "e0323a0a4906245cc2d3ac629195e479e7c8376d8dd54ea96c56f4ea657aae08"
    "ba78252e1ca6b4c6e8dd741f4bbd8b8a703eb5664803f60e613557b986c11d9e"
    "e1f8981169d98e949b1e87e9ce5528df8ca1890dbfe6426841992d0fb054bb16")
_AES_INV_SBOX = bytes(_AES_SBOX.index(i) for i in range(256))
_AES_RCON = (0,1,2,4,8,16,32,64,128,27,54,108,216,171,77,154)


def _gmul_build(n: int) -> bytes:
    """Build a GF(2^8) multiplication table for byte * n, mod 0x11b."""
    out = bytearray(256)
    for b in range(256):
        a, k, p = b, n, 0
        for _ in range(8):
            if k & 1: p ^= a
            hi = a & 0x80
            a = (a << 1) & 0xff
            if hi: a ^= 0x1b
            k >>= 1
        out[b] = p
    return bytes(out)

_GMUL2  = _gmul_build(2);  _GMUL3  = _gmul_build(3)
_GMUL9  = _gmul_build(9);  _GMUL11 = _gmul_build(11)
_GMUL13 = _gmul_build(13); _GMUL14 = _gmul_build(14)


def _aes_expand_key_flat(key: bytes) -> list[int]:
    """Expand AES key into a flat list of round-key bytes (16 per round)."""
    nk = len(key) // 4
    nr = {16: 10, 24: 12, 32: 14}[len(key)]
    w = bytearray(key)
    for i in range(nk, 4 * (nr + 1)):
        t = bytearray(w[(i-1)*4:i*4])
        if i % nk == 0:
            t = bytearray([_AES_SBOX[t[1]] ^ _AES_RCON[i//nk],
                           _AES_SBOX[t[2]], _AES_SBOX[t[3]], _AES_SBOX[t[0]]])
        elif nk > 6 and i % nk == 4:
            t = bytearray(_AES_SBOX[b] for b in t)
        for j in range(4):
            w.append(w[(i-nk)*4 + j] ^ t[j])
    return list(w)


def _aes_inv_round(state: list[int], rk: list[int]):
    """One inverse AES round (in-place). state and rk are 16-byte lists."""
    # AddRoundKey
    for i in range(16): state[i] ^= rk[i]
    # InvMixColumns
    for c in range(4):
        a = state[c*4]; b = state[c*4+1]; cc = state[c*4+2]; d = state[c*4+3]
        state[c*4]   = _GMUL14[a] ^ _GMUL11[b] ^ _GMUL13[cc] ^ _GMUL9[d]
        state[c*4+1] = _GMUL9[a]  ^ _GMUL14[b] ^ _GMUL11[cc] ^ _GMUL13[d]
        state[c*4+2] = _GMUL13[a] ^ _GMUL9[b]  ^ _GMUL14[cc] ^ _GMUL11[d]
        state[c*4+3] = _GMUL11[a] ^ _GMUL13[b] ^ _GMUL9[cc]  ^ _GMUL14[d]


def _aes_inv_shift_rows(s: list[int]):
    """Row i is shifted right by i (inverse of encryption's left shift)."""
    # row 1 (indexes 1,5,9,13): rotate right by 1
    s[1], s[5], s[9], s[13]   = s[13], s[1], s[5], s[9]
    # row 2: rotate right by 2 (= swap pairs)
    s[2], s[6], s[10], s[14]  = s[10], s[14], s[2], s[6]
    # row 3: rotate right by 3 (= rotate left by 1)
    s[3], s[7], s[11], s[15]  = s[7], s[11], s[15], s[3]


def _aes_decrypt_block(block: bytes, rks: list[int]) -> bytes:
    nr = (len(rks) // 16) - 1
    s = list(block)
    # initial AddRoundKey with last round key
    rk_off = nr * 16
    for i in range(16): s[i] ^= rks[rk_off + i]
    # nr-1 main inverse rounds
    for rnd in range(nr - 1, 0, -1):
        _aes_inv_shift_rows(s)
        for i in range(16): s[i] = _AES_INV_SBOX[s[i]]
        _aes_inv_round(s, rks[rnd*16:(rnd+1)*16])
    # final round (no InvMixColumns)
    _aes_inv_shift_rows(s)
    for i in range(16): s[i] = _AES_INV_SBOX[s[i]]
    for i in range(16): s[i] ^= rks[i]
    return bytes(s)


def aes_cbc_decrypt(key: bytes, iv: bytes, ct: bytes) -> bytes:
    """AES-128/192/256-CBC decrypt + PKCS7 unpad. Uses pycryptodome /
    cryptography if installed (fast); falls back to vendored pure-Python."""
    if len(key) not in (16, 24, 32):
        raise ValueError(f"AES key must be 16/24/32 bytes, got {len(key)}")
    if len(iv) != 16:
        raise ValueError(f"AES IV must be 16 bytes, got {len(iv)}")
    if len(ct) % 16 != 0 or not ct:
        raise ValueError(f"AES CT length must be a positive multiple of 16, got {len(ct)}")
    pt = None
    try:
        from Crypto.Cipher import AES as _PCAes        # pycryptodome
        pt = _PCAes.new(key, _PCAes.MODE_CBC, iv=iv).decrypt(ct)
    except ImportError: pass
    if pt is None:
        try:
            from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
            d = Cipher(algorithms.AES(key), modes.CBC(iv)).decryptor()
            pt = d.update(ct) + d.finalize()
        except ImportError: pass
    if pt is None:
        rks = _aes_expand_key_flat(key)
        pt = b""; prev = iv
        for i in range(0, len(ct), 16):
            blk = ct[i:i+16]
            dec = _aes_decrypt_block(blk, rks)
            pt += bytes(a ^ b for a, b in zip(dec, prev))
            prev = blk
    # PKCS7 unpad
    padlen = pt[-1] if pt else 0
    if 1 <= padlen <= 16 and pt[-padlen:] == bytes([padlen]) * padlen:
        pt = pt[:-padlen]
    return pt


# ============================================================================
# AES-256-GCM for ErrTraffic v3 (BW v2 generation) API envelope (`enc:"gcm1"`)
#   - Prefers pycryptodome / cryptography if installed
#   - Falls back to a CORRECT pure-Python AES-GCM
#   - Encryption block primitive (CTR keystream) built on top of the existing
#     AES key-schedule (_aes_expand_key_flat) + table-driven GF(2^8) ops above
# ============================================================================

def _aes_shift_rows(s: list[int]):
    """Forward ShiftRows — row i shifted left by i. Inverse of _aes_inv_shift_rows."""
    s[1], s[5], s[9], s[13]   = s[5], s[9], s[13], s[1]
    s[2], s[6], s[10], s[14]  = s[10], s[14], s[2], s[6]
    s[3], s[7], s[11], s[15]  = s[15], s[3], s[7], s[11]


def _aes_mix_columns(s: list[int]):
    """Forward MixColumns — multiply each column by the fixed matrix in GF(2^8)."""
    for c in range(4):
        a = s[c*4]; b = s[c*4+1]; cc = s[c*4+2]; d = s[c*4+3]
        s[c*4]   = _GMUL2[a] ^ _GMUL3[b] ^ cc ^ d
        s[c*4+1] = a ^ _GMUL2[b] ^ _GMUL3[cc] ^ d
        s[c*4+2] = a ^ b ^ _GMUL2[cc] ^ _GMUL3[d]
        s[c*4+3] = _GMUL3[a] ^ b ^ cc ^ _GMUL2[d]


def _aes_encrypt_block(block: bytes, rks: list[int]) -> bytes:
    """Forward AES block encryption — needed for GCM (CTR mode keystream + GHASH H)."""
    nr = (len(rks) // 16) - 1
    s = list(block)
    # Initial AddRoundKey
    for i in range(16): s[i] ^= rks[i]
    # nr-1 main rounds
    for rnd in range(1, nr):
        for i in range(16): s[i] = _AES_SBOX[s[i]]
        _aes_shift_rows(s)
        _aes_mix_columns(s)
        rk_off = rnd * 16
        for i in range(16): s[i] ^= rks[rk_off + i]
    # Final round (no MixColumns)
    for i in range(16): s[i] = _AES_SBOX[s[i]]
    _aes_shift_rows(s)
    rk_off = nr * 16
    for i in range(16): s[i] ^= rks[rk_off + i]
    return bytes(s)


def _gf128_mul(x: int, y: int) -> int:
    """Galois-field GF(2^128) multiplication, NIST SP 800-38D bit ordering
    (most-significant bit first). Reduction polynomial: x^128 + x^7 + x^2 + x + 1.

    Operands are 128-bit big-endian ints. Returns the 128-bit product as int.
    Pure-Python; only invoked when no AES-GCM library is available, so speed is
    not critical (envelope payloads are <1KB).
    """
    z = 0
    v = y
    # Iterate bits of x from MSB to LSB (NIST GCM convention).
    for i in range(127, -1, -1):
        if (x >> i) & 1:
            z ^= v
        # v = v >> 1 in GF, with reduction if LSB was set before shift
        if v & 1:
            v = (v >> 1) ^ 0xE1000000000000000000000000000000
        else:
            v >>= 1
    return z


def _ghash(h_int: int, data: bytes) -> int:
    """Compute GHASH(H, data). `data` must already be the
    GHASH input (AAD_padded || CT_padded || lenAAD_64 || lenCT_64)."""
    y = 0
    for i in range(0, len(data), 16):
        block = data[i:i+16].ljust(16, b"\x00")
        y ^= int.from_bytes(block, "big")
        y = _gf128_mul(y, h_int)
    return y


def _aes_gcm_decrypt_pyfallback(key: bytes, iv: bytes, ct_with_tag: bytes,
                                 aad: bytes = b"", tag_length: int = 16) -> bytes:
    """Pure-Python AES-GCM decrypt + auth-verify. Raises on tag mismatch.

    NIST SP 800-38D compliant. Used only when neither pycryptodome nor
    cryptography is installed. Envelope payloads are small (<2KB typical),
    so the O(n*128) pure-Python GHASH is acceptable.
    """
    if len(key) not in (16, 24, 32):
        raise ValueError(f"AES-GCM key must be 16/24/32 bytes, got {len(key)}")
    if tag_length not in (12, 13, 14, 15, 16):
        raise ValueError(f"GCM tag length must be 12..16, got {tag_length}")
    if len(ct_with_tag) < tag_length:
        raise ValueError(f"GCM ciphertext shorter than tag length")
    ct  = ct_with_tag[:-tag_length]
    tag = ct_with_tag[-tag_length:]
    rks = _aes_expand_key_flat(key)
    # Hash subkey H = AES_E(K, 0^128)
    h_block = _aes_encrypt_block(b"\x00" * 16, rks)
    h_int   = int.from_bytes(h_block, "big")
    # Initial counter J0
    if len(iv) == 12:
        j0 = iv + b"\x00\x00\x00\x01"
    else:
        # GHASH(H, IV || 0^s || 0^64 || lenIV_64)
        pad = (-len(iv)) % 16
        ghash_iv = iv + b"\x00" * pad + b"\x00" * 8 + (len(iv) * 8).to_bytes(8, "big")
        j0_int  = _ghash(h_int, ghash_iv)
        j0      = j0_int.to_bytes(16, "big")
    # CTR-mode decrypt — counter starts at J0+1
    pt = bytearray()
    ctr_int = int.from_bytes(j0, "big")
    for i in range(0, len(ct), 16):
        ctr_int = ((ctr_int & ~((1 << 32) - 1)) |
                   ((ctr_int + 1) & ((1 << 32) - 1)))
        keystream = _aes_encrypt_block(ctr_int.to_bytes(16, "big"), rks)
        block_ct  = ct[i:i+16]
        pt.extend(a ^ b for a, b in zip(keystream[:len(block_ct)], block_ct))
    # Auth: compute expected tag
    aad_pad = (-len(aad)) % 16
    ct_pad  = (-len(ct))  % 16
    ghash_in = (aad + b"\x00" * aad_pad +
                ct  + b"\x00" * ct_pad  +
                (len(aad) * 8).to_bytes(8, "big") +
                (len(ct)  * 8).to_bytes(8, "big"))
    s_int    = _ghash(h_int, ghash_in)
    e_j0     = _aes_encrypt_block(j0, rks)
    expected = (s_int ^ int.from_bytes(e_j0, "big")).to_bytes(16, "big")[:tag_length]
    # Constant-time compare
    diff = 0
    for x, y in zip(expected, tag): diff |= x ^ y
    if diff != 0 or len(expected) != len(tag):
        raise ValueError("AES-GCM authentication tag mismatch")
    return bytes(pt)


def aes_gcm_decrypt(key: bytes, iv: bytes, ct_with_tag: bytes,
                    aad: bytes = b"", tag_length: int = 16) -> bytes:
    """AES-128/192/256-GCM decrypt + auth-verify. Prefers pycryptodome /
    cryptography if installed (much faster); falls back to vendored pure-Python.
    Raises ValueError on tag mismatch (authenticated encryption guarantees)."""
    if len(key) not in (16, 24, 32):
        raise ValueError(f"AES-GCM key must be 16/24/32 bytes, got {len(key)}")
    if len(iv) < 1:
        raise ValueError("AES-GCM IV must be non-empty")
    try:
        from Crypto.Cipher import AES as _PCAes        # pycryptodome
        ct  = ct_with_tag[:-tag_length]
        tag = ct_with_tag[-tag_length:]
        cipher = _PCAes.new(key, _PCAes.MODE_GCM, nonce=iv, mac_len=tag_length)
        if aad: cipher.update(aad)
        return cipher.decrypt_and_verify(ct, tag)
    except ImportError: pass
    except ValueError as e:
        # tag mismatch from pycryptodome — re-raise with our message style
        raise ValueError(f"AES-GCM authentication tag mismatch ({e})") from None
    try:
        from cryptography.hazmat.primitives.ciphers.aead import AESGCM
        return AESGCM(key).decrypt(iv, ct_with_tag, aad if aad else None)
    except ImportError: pass
    except Exception as e:
        raise ValueError(f"AES-GCM authentication tag mismatch ({e.__class__.__name__})") from None
    return _aes_gcm_decrypt_pyfallback(key, iv, ct_with_tag, aad=aad, tag_length=tag_length)


# ============================================================================
# RC4 for ErrTraffic v3 legacy `q2` envelope mode
#   - Trivial cipher; vendored directly (no library preference needed).
# ============================================================================

def rc4(key: bytes, data: bytes) -> bytes:
    """RC4 stream cipher (encrypt == decrypt). 256-byte KSA + PRGA, no drop bytes
    — matches the kit's loader-side rc4() exactly."""
    if not key: raise ValueError("RC4 key must be non-empty")
    s = list(range(256))
    j = 0
    for i in range(256):
        j = (j + s[i] + key[i % len(key)]) & 0xff
        s[i], s[j] = s[j], s[i]
    out = bytearray(len(data))
    i = j = 0
    for k in range(len(data)):
        i = (i + 1) & 0xff
        j = (j + s[i]) & 0xff
        s[i], s[j] = s[j], s[i]
        out[k] = data[k] ^ s[(s[i] + s[j]) & 0xff]
    return bytes(out)


# ============================================================================
# decrypt_api_envelope — Python port of the kit's loader-side decryptApiEnvelope.
# ============================================================================
# Mirrors the JS exactly:
#   1. Reject non-objects / missing q field early.
#   2. If enc == "gcm1": derive AES-256 key as sha256(API_Q2_KEY || scope+"|gcm1"),
#      base64-url-decode q into [iv(12) || ct_with_tag(rest)], decrypt.
#      On GCM failure, fall back to obj.q2 RC4 path if present (the JS does this).
#   3. If enc == "q2": base64-url-decode q into [nonce(8) || ct], RC4 with
#      key = base_key || nonce.
#   4. JSON-parse the UTF-8 plaintext.
#
# `scope` is one of {"cfg","init","dl","evt"} and defaults to "cfg" per the JS.
# Returns the parsed JSON object or raises ValueError on a hard decrypt failure.

def _b64url_decode(s: str) -> bytes:
    """Base64-url-safe decode with auto-padding. Matches the kit's b64urlToBytes."""
    s = s.replace("-", "+").replace("_", "/")
    return base64.b64decode(s + "=" * (-len(s) % 4), validate=False)


def decrypt_api_envelope(obj: dict, *, scope: str = "cfg",
                          base_key_hex: str | None = None) -> dict:
    """Decrypt an ErrTraffic v3 (BW v2) API envelope.

    --- The envelope format (taught in plain English) ---
    The kit's `decryptApiEnvelope()` JS in /api/css.js handles two modes:

      MODE "gcm1"  =  "GCM, version 1"  =  AES-256-GCM with a one-byte version tag.
        AES-GCM is "AES in Galois/Counter Mode" — an authenticated encryption
        mode that produces both confidentiality (the bytes look random) AND
        integrity (a 128-bit authentication tag attached to the ciphertext;
        any tampering makes the decrypt fail). It's the modern web standard
        (TLS 1.3 default cipher) precisely because both properties matter.
        The "1" in "gcm1" is the kit-author's own version marker — they
        reserved the namespace so they can add gcm2/gcm3 later if they want
        to change the key derivation without breaking already-deployed
        loaders. We've only seen gcm1 in the wild.

        Key derivation: SHA256(API_Q2_KEY_HEX_bytes || utf8(scope || "|gcm1"))
          The `scope` ("cfg" / "init" / "dl" / "evt") is mixed in so that the
          cfg-decrypt key ≠ init-decrypt key ≠ dl-decrypt key even though the
          panel uses the same base key for everything. This is a defender-side
          win: capturing the cfg key doesn't let you forge an init response.

        Wire format: base64url(IV[12] || ciphertext[N] || authTag[16])

      MODE "q2"   =  "version 2 of the RC4 envelope" (the LEGACY path; the kit
        falls back to it when gcm1 fails or for older deployments).
        Wire format: base64url(nonce[8] || ciphertext[N]), key = baseKey || nonce.
        RC4 is broken cryptographically but the kit author isn't trying to
        protect against state-actor cryptanalysis — they're trying to defeat
        casual signature scanners and static IOC extraction.

    --- The /api/cfg + /api/settings endpoints (what "cfg" means) ---
    /api/cfg  (and the alias /api/settings) returns the panel's live config:
    `mode` (which fake-warning theme to show), `enabled` (kill-switch),
    `blockBots`, `rentalExpired` (the operator's subscription expiry date —
    a forensic gold-mine), `showDelay`, `panelBaseUrl` override, `os`,
    `browser`. ALL of it is gcm1-encrypted in the response body — decrypting
    it gives a defender plaintext visibility into the operator's current
    panel configuration without ever logging into the panel. "cfg" = config.

    Args:
        obj:  the raw JSON response from /api/index.php?a=cfg|settings|init|dl
        scope: the endpoint scope used in the key-derivation salt. Must match
               /^[a-z0-9_]{1,16}$/i; the kit defaults to "cfg" if invalid.
        base_key_hex: the API_Q2_KEY_HEX (64 hex chars = 32 bytes). When omitted,
               uses the documented current key from `ERRTRAFFIC_KIT['bw_v2_keys']`
               if populated, else raises ValueError. The S25 work added a
               registry so per-panel keys are auto-resolved by `resolve_bw_v2_key()`.

    Returns the parsed plaintext JSON, or raises ValueError on failure.

    Implementation matches the kit's loader-side `decryptApiEnvelope()` exactly
    (Polygon panel /api/css.js, BW v2 generation).
    """
    if not isinstance(obj, dict): raise ValueError("envelope must be a dict")
    q = obj.get("q")
    if not isinstance(q, str) or not q: raise ValueError("envelope missing 'q'")
    # Resolve base key: explicit > kit table > error
    if base_key_hex is None:
        base_key_hex = (ERRTRAFFIC_KIT.get("bw_v2_keys") or {}).get("API_Q2_KEY_HEX")
    if not base_key_hex:
        raise ValueError("no API_Q2_KEY_HEX provided (and none in ERRTRAFFIC_KIT['bw_v2_keys'])")
    if not re.fullmatch(r'[0-9a-fA-F]{64}', base_key_hex):
        raise ValueError(f"API_Q2_KEY_HEX must be 64 hex chars (got {len(base_key_hex)})")
    base_key = bytes.fromhex(base_key_hex)
    # Validate scope per the kit's regex; fall through to default on bad input
    if not re.fullmatch(r'[a-z0-9_]{1,16}', scope, re.I):
        scope = "cfg"
    enc = obj.get("enc")
    last_err = None
    if enc == "gcm1":
        try:
            packed = _b64url_decode(q)
            if len(packed) < 12 + 16 + 1: raise ValueError("gcm1: packed too short")
            iv  = packed[:12]
            ct  = packed[12:]                                         # cipher || 16B tag
            key = hashlib.sha256(base_key + (scope + "|gcm1").encode("utf-8")).digest()
            plain = aes_gcm_decrypt(key, iv, ct, tag_length=16)
            return json.loads(plain.decode("utf-8"))
        except Exception as e:
            last_err = e
            # The kit's JS falls back to obj.q2 (RC4) when gcm1 fails — mirror it.
            q2 = obj.get("q2")
            if isinstance(q2, str) and q2:
                try:
                    p2     = _b64url_decode(q2)
                    if len(p2) < 9: raise ValueError("q2 fallback: packed too short")
                    nonce  = p2[:8]
                    cipher = p2[8:]
                    key_mat = base_key + nonce
                    plain  = rc4(key_mat, cipher)
                    return json.loads(plain.decode("utf-8"))
                except Exception as e2:
                    last_err = e2
            # D3 FIX (S37): When decryption yields garbled bytes, Python's
            # json.loads / .decode("utf-8") raises a UnicodeDecodeError like
            # "'utf-8' codec can't decode byte 0x91…" — which logs as a codec
            # error and misleads analysts into thinking it's a text-encoding
            # bug.  The real cause is a key mismatch: we're decrypting with
            # the wrong base key (usually the global default when no per-host
            # key has been recovered for that panel).  Re-wrap with a clearer
            # message so the log is actionable.
            err_str = str(last_err)
            if "codec can't decode" in err_str or "invalid start byte" in err_str or "invalid continuation" in err_str:
                raise ValueError(f"gcm1 key mismatch — decryption produced garbage (wrong host-specific key; recover the panel's API_Q2_KEY_HEX from its loader JS). Underlying: {err_str}")
            raise ValueError(f"gcm1 decrypt failed: {last_err}")
    if enc == "q2":
        try:
            packed = _b64url_decode(q)
            if len(packed) < 9: raise ValueError("q2: packed too short")
            nonce  = packed[:8]
            cipher = packed[8:]
            key_mat = base_key + nonce
            plain  = rc4(key_mat, cipher)
            return json.loads(plain.decode("utf-8"))
        except Exception as e:
            # D3 FIX (S37): same key-mismatch re-wrap for q2/RC4 path.
            err_str = str(e)
            if "codec can't decode" in err_str or "invalid start byte" in err_str or "invalid continuation" in err_str:
                raise ValueError(f"q2 key mismatch — RC4 output is not valid UTF-8 JSON (wrong host-specific key; recover API_Q2_KEY_HEX from the panel loader). Underlying: {err_str}")
            raise ValueError(f"q2 decrypt failed: {e}")
    raise ValueError(f"unknown envelope enc={enc!r}")


def try_recover_clipboard_aes(text: str) -> dict | None:
    """If `text` contains the ErrTraffic AES kit pattern (3 FromBase64String
    blobs feeding RijndaelManaged in Key/IV/CT order), decrypt + return the
    recovered clipboard command. Returns None if not present or decode fails."""
    if not _AES_RE.search(text): return None
    blobs = _FB64_RE.findall(text)
    if len(blobs) < 3: return None
    # Filter out the very-small-but-not-AES-sized junk; we need: key=32B, IV=16B, CT=16B*n
    decoded = []
    for b in blobs:
        try:
            raw = base64.b64decode(b + "=" * (-len(b) % 4), validate=False)
            decoded.append((b, raw))
        except Exception: continue
    if len(decoded) < 3: return None
    # Identify by canonical AES-CBC shape:
    #   key  = 32 bytes (AES-256) — kit's documented choice
    #   IV   = 16 bytes (one AES block)
    #   CT   = largest 16-byte-aligned blob, longer than IV
    ct_cand  = max(decoded, key=lambda kv: len(kv[1]) if len(kv[1]) % 16 == 0 else 0)
    if len(ct_cand[1]) <= 16 or len(ct_cand[1]) % 16 != 0:
        return {"ok": False, "reason": f"no 16B-aligned ciphertext blob found "
                                       f"(sizes={[len(r) for _, r in decoded]})"}
    key_cand = next(((b, r) for b, r in decoded if len(r) == 32), None)
    iv_cand  = next(((b, r) for b, r in decoded
                     if len(r) == 16 and r != ct_cand[1]), None)
    if not key_cand or not iv_cand:
        return {"ok": False, "reason": (f"AES blob shape mismatch (need 32B key + 16B IV + "
                                        f"≥32B CT; got sizes "
                                        f"{[len(r) for _, r in decoded]})")}
    try:
        pt_bytes = aes_cbc_decrypt(key_cand[1], iv_cand[1], ct_cand[1])
    except Exception as e:
        return {"ok": False, "reason": f"AES decrypt failed: {e}"}
    pt = pt_bytes.decode("utf-8", errors="replace")
    # also pull the ErrTraffic URL from the recovered plaintext, if present
    urls_in_pt = sorted({u for u in _URL_RE.findall(pt)})
    parsed = None
    for u in urls_in_pt:
        info = parse_errtraffic_panel_url(u)
        if info and info["role"] == "payload_download":
            parsed = info; break
    return {
        "ok":               True,
        "key_b64":          key_cand[0],
        "iv_b64":           iv_cand[0],
        "ct_b64_head":      ct_cand[0][:48] + ("…" if len(ct_cand[0]) > 48 else ""),
        "ct_bytes":         len(ct_cand[1]),
        "plaintext_bytes":  len(pt_bytes),
        # FULL plaintext (not just an excerpt) — the dropper PS rarely exceeds
        # a few KB and is the primary defender artifact. Truncating it to 600
        # chars lost the very lines analysts need (the dl URL + token).
        "plaintext_excerpt": pt,
        "urls_in_plaintext":     urls_in_pt[:10],
        "urls_in_plaintext_defanged": [_defang(u) for u in urls_in_pt[:10]],
        "errtraffic_payload_url": parsed,
        "sha256":            hashlib.sha256(pt_bytes).hexdigest(),
    }


# ============================================================================
# Safe payload downloader   (--payload mode)
# ============================================================================
# Process-lifetime cache by (panel_origin, os_type) so 1000s of compromised
# pages pointing at the same panel only get fetched once per OS.
_PAYLOAD_CACHE: dict[tuple, dict] = {}
_PAYLOAD_CACHE_LOCK = threading.Lock()


def _safe_filename(s: str) -> str:
    """Slugify a string for use as a filename. Strips scheme, refangs `[.]`,
    replaces non-alnum with single underscores, collapses runs of underscores."""
    s = _refang(s).replace("://", "_").strip("/")
    s = re.sub(r'[^A-Za-z0-9._-]+', '_', s)   # one run of bad chars -> ONE underscore
    s = s.strip("._-")[:80]
    return s or "out"


def _ensure_parent_dir(path: str) -> None:
    """Create the parent directory of `path` if it doesn't exist. Idempotent
    and safe to call on relative or absolute paths. No-op when parent is the
    current working dir."""
    if not path:
        return
    parent = os.path.dirname(os.path.abspath(path))
    if parent and not os.path.isdir(parent):
        try: os.makedirs(parent, exist_ok=True)
        except Exception: pass


def _resolve_output_path(value: str | None, *, default_name: str,
                          ext: str, must_be_unique: bool = False,
                          base_dir: str | None = None) -> str | None:
    """Centralised, defensive resolution for every output-file CLI flag.

    Handles every shape of user input uniformly:
      • None / empty   -> returns None (caller should skip the output)
      • Bare name      -> uses CWD, appends ext if missing
      • Absolute path  -> normalised + parent dir auto-created
      • Path with no ext -> ext appended (e.g. `sweep` -> `sweep.jsonl`)
      • Path ending in `/` or `\\` -> treated as a directory, default_name
        + ext appended
      • Path matching an existing FILE + must_be_unique -> rename with
        suffix (`sweep.jsonl` -> `sweep-2.jsonl`, `sweep-3.jsonl`, ...)
      • `base_dir` -> when value is relative, resolve under base_dir
        (otherwise CWD)

    Always auto-creates the parent dir. Always returns an absolute path.

    Parameters
    ----------
    value : str | None
        Raw value from argparse — may be None, '', a name, or a full path.
    default_name : str
        Used when `value` is None/empty OR resolves to a directory. Should
        NOT include extension.
    ext : str
        Extension to append when missing. Must start with '.' (e.g. '.jsonl').
        Pass '' to skip extension handling (e.g. for log files).
    must_be_unique : bool
        When True, refuses to overwrite an existing file — appends '-2',
        '-3', ... until a free name is found. When False (default),
        overwrites freely (the standard caller-controls-clobber behaviour).
    base_dir : str | None
        Base directory for relative `value` resolution. Defaults to CWD.
    """
    if not value:
        return None
    v = str(value).strip()
    if not v:
        return None
    # Treat a trailing separator as "this is a directory; pick a default name"
    if v.endswith(("/", "\\")):
        v = os.path.join(v, default_name)
    base = base_dir or os.getcwd()
    if not os.path.isabs(v):
        v = os.path.join(base, v)
    v = os.path.abspath(v)
    # If the path is an existing directory, append the default basename
    if os.path.isdir(v):
        v = os.path.join(v, default_name)
    # Add extension when missing (case-insensitive check)
    if ext and not v.lower().endswith(ext.lower()):
        v = v + ext
    if must_be_unique and os.path.exists(v):
        stem, e = os.path.splitext(v)
        i = 2
        while os.path.exists(f"{stem}-{i}{e}"):
            i += 1
        v = f"{stem}-{i}{e}"
    _ensure_parent_dir(v)
    return v


def _open_output(path: str, mode: str = "w", *, newline: str | None = None) -> object:
    """Open an output file with utf-8 encoding + auto-created parent dir.
    Centralised so every output-open site behaves the same."""
    _ensure_parent_dir(path)
    return open(path, mode, encoding="utf-8", newline=newline)


# Magic labels that represent a real fetched BINARY/final-stage artifact (as
# opposed to a text clipboard/dropper script the kit served as an intermediate).
# Used by the served-script chase in fetch_panel_payload's _try_download.
_BINARY_MAGICS = {
    "pe_windows", "msi_or_office", "elf_linux", "macho_mac", "macho_fat_mac",
    "archive_7z", "archive_rar", "gzip", "apk_android", "jar_java",
    "dex_android", "zip",
}

def _detect_file_magic(data: bytes) -> str:
    """Return a coarse file-type label from magic bytes.

    Distinguishes the four payload classes ErrTraffic supports per-OS
    (windows = PE, mac = Mach-O, android = APK, linux = ELF or shell) plus
    common companion types. Covers fat-binary Mach-O headers, scripts beyond
    /bin/* (zsh, python, perl), and the ZIP-vs-APK ambiguity (APKs always
    contain AndroidManifest.xml — checked here cheaply via substring scan
    of the first 8 KB)."""
    if not data: return "empty"
    # Windows
    if data.startswith(b"MZ"):                          return "pe_windows"
    if data[:4] == b"\xd0\xcf\x11\xe0":                  return "msi_or_office"
    # Linux
    if data.startswith(b"\x7fELF"):                      return "elf_linux"
    # macOS — Mach-O (thin + fat)
    if data[:4] in (b"\xfe\xed\xfa\xce", b"\xfe\xed\xfa\xcf",
                     b"\xce\xfa\xed\xfe", b"\xcf\xfa\xed\xfe"): return "macho_mac"
    if data[:4] in (b"\xca\xfe\xba\xbe", b"\xbe\xba\xfe\xca"): return "macho_fat_mac"
    if data[:4] == b"#!/u" and b"osascript" in data[:200]:    return "osascript_mac"
    # Archives — the BW v2 generation drops a password-protected .7z that the
    # clipboard PS extracts with a per-campaign password ($p / $h8) before
    # running the inner .exe/.msi. So `archive_7z` in ANY OS slot is the
    # EXPECTED BW v2 dropper, not an anomaly (see _payload_os_mismatch_note).
    if data[:6] == b"7z\xbc\xaf\x27\x1c":                 return "archive_7z"
    if data[:4] == b"Rar!":                               return "archive_rar"
    if data[:2] == b"\x1f\x8b":                           return "gzip"
    # Android / Java / generic ZIP
    if data[:4] == b"PK\x03\x04":
        head = data[:8192]
        if b"AndroidManifest.xml" in head:               return "apk_android"
        if b"classes.dex" in head:                        return "apk_android"
        if b"META-INF/MANIFEST.MF" in head:              return "jar_java"
        return "zip"
    if data[:4] == b"\x03\x00\x08\x00":                   return "dex_android"
    # Shell scripts (Linux/mac/cross-platform)
    if data[:11] == b"#!/bin/bash":                       return "bash_script"
    if data[:9]  == b"#!/bin/sh":                         return "shell_script"
    if data[:11] == b"#!/bin/zsh" or data[:18] == b"#!/usr/bin/env zsh": return "zsh_script"
    if data[:18] == b"#!/usr/bin/env ba" or data[:17] == b"#!/usr/bin/env sh": return "shell_script"
    if data[:7]  == b"#!/usr/" and b"python" in data[:40]: return "python_script"
    if data[:7]  == b"#!/usr/" and b"perl" in data[:30]: return "perl_script"
    if data[:5]  in (b"#!/bi", b"#!/us"):                 return "shell_script"
    # PowerShell text (no magic — sniff for distinctive opening tokens)
    head = data[:200]
    if (b"FromBase64String" in head or b"[Convert]::" in head
            or b"$PSVersionTable" in head or b"Invoke-WebRequest" in head
            or b"powershell -" in head[:30].lower()):
        return "powershell_text"
    # Catch-all text vs binary
    if data[:5] == b"<?xml":                              return "xml"
    if data[:5] == b"<!DOC" or data[:5] == b"<html":      return "html"
    if data[:1] == b"{" and data[-1:] == b"}":            return "json_maybe"
    if all(0x20 <= b < 0x7f or b in (9, 10, 13) for b in data[:200]):
        return "text"
    return "binary_unknown"


def _payload_os_mismatch_note(os_slot: str, magic: str) -> str | None:
    """Return a short note when the file magic doesn't match the OS slot the
    operator advertised. Returns None when the pairing makes sense.
    Useful for surfacing 'operator served PE in the android slot' findings."""
    if not magic or magic == "empty": return None
    # Archives are OS-agnostic droppers in this kit (the BW v2 generation serves
    # one password-protected .7z to every OS slot; the inner PS extracts + runs
    # the real .exe/.msi). So an archive is EXPECTED, never a slot mismatch.
    if magic in {"archive_7z", "archive_rar", "zip", "gzip"}: return None
    expected = {
        "windows": {"pe_windows", "msi_or_office", "powershell_text"},
        "mac":     {"macho_mac", "macho_fat_mac", "osascript_mac", "shell_script", "bash_script", "zsh_script"},
        "android": {"apk_android", "dex_android"},
        "linux":   {"elf_linux", "shell_script", "bash_script", "zsh_script", "python_script", "perl_script"},
    }
    exp = expected.get(os_slot.lower())
    if exp and magic not in exp:
        return f"OS-slot/magic mismatch — {os_slot} slot served {magic}"
    return None


def _http_get_safe(url: str, headers: dict, timeout: int, *,
                   max_bytes: int = 50_000_000,
                   opener: urllib.request.OpenerDirector | None = None,
                   method: str = "GET", body: bytes | None = None,
                   verify_tls: bool = False) -> dict:
    """Minimal urllib GET/POST wrapper that always returns a dict — never raises.
    Captures status, content-type, body (capped), and any error string.

    When `opener` is supplied, the call is routed through it — typically a
    CookieJar-backed opener for session-aware victim-chain replay. When None
    (default), a fresh urlopen is used per call.

    SSL: v4.9 set tool-wide TLS verification OFF by default for both lure and
    payload fetches — attacker panels commonly self-sign or run expired certs
    (S29: megamegalodon.click flagship has been live for ~weeks with an expired
    cert, blocking every payload fetch in the May 2026 sweep). Verification can
    still be requested explicitly per-call via `verify_tls=True`.
    """
    out = {"url": url, "status": None, "content_type": None,
           "bytes": 0, "body_text_head": None, "body_bytes": None, "error": None,
           "final_url": None, "response_headers": {}}
    # Cooperative cancel: after Ctrl+C, in-flight workers stop issuing NEW
    # requests instead of stacking another full timeout each. This bounds the
    # gap between the interrupt and the workers going idle so the partial flush
    # + clean exit happen fast.
    if _interrupted():
        out["error"] = "interrupted"
        return out
    try:
        req = urllib.request.Request(url, headers=headers, data=body, method=method)
        ctx = ssl.create_default_context() if verify_tls else ssl._create_unverified_context()
        # Both paths now share the unverified-by-default TLS context so a panel
        # with an expired/self-signed cert (S29: megamegalodon.click) does not
        # break the recon chain.
        if opener is not None:
            r = opener.open(req, timeout=timeout)
        else:
            r = urllib.request.urlopen(req, timeout=timeout, context=ctx)
        try:
            data = r.read(max_bytes)
            out["status"]         = r.status
            out["content_type"]   = r.headers.get("Content-Type")
            out["bytes"]          = len(data)
            out["body_bytes"]     = data
            out["body_text_head"] = data[:400].decode("utf-8", "replace")
            out["final_url"]      = r.geturl()
            out["response_headers"] = {k.lower(): v for k, v in r.headers.items()}
        finally:
            try: r.close()
            except Exception: pass
    except urllib.error.HTTPError as e:
        out["status"] = e.code
        try:
            data = e.read(8192)
            out["body_text_head"] = data[:400].decode("utf-8", "replace")
            out["body_bytes"] = data
            out["content_type"] = e.headers.get("Content-Type") if e.headers else None
        except Exception:
            pass
        out["error"] = f"HTTP {e.code} {e.reason}"
    except Exception as e:
        out["error"] = str(e)[:200]
    return out


def _build_session_opener(verify_tls: bool = False) -> urllib.request.OpenerDirector:
    """Per-(panel,os) opener with a CookieJar for session continuity. Used by
    the kit-mimicking beacon warmup so any cookies the panel issues during
    /api/css.js or /api/cfg are carried into the subsequent /api/init and
    /api/dl calls.

    The opener is built with an HTTPSHandler whose SSL context defaults to
    UNVERIFIED — matching tool-wide v4.9 policy — so a panel running an
    expired/self-signed cert (S29: megamegalodon.click) doesn't sever the
    session warmup chain. `verify_tls=True` rebuilds with a strict context."""
    import http.cookiejar
    ctx = ssl.create_default_context() if verify_tls else ssl._create_unverified_context()
    handlers = [urllib.request.HTTPCookieProcessor(http.cookiejar.CookieJar()),
                urllib.request.HTTPSHandler(context=ctx)]
    return urllib.request.build_opener(*handlers)


def fetch_panel_payload(panel_url: str, os_type: str, *,
                        timeout: int = 15, out_dir: str | None = None,
                        known_token: str | None = None,
                        known_src: str | None = None,
                        known_mode: str | None = None,
                        known_token_param: str | None = None,
                        known_sevenz_password: str | None = None,
                        known_rlm: str | None = None,
                        cache_by_hash: bool = True,
                        strategy_budget_s: int = 60) -> dict:
    """Recover an ErrTraffic panel payload for one OS, SAFELY.

    Strategy chain (each attempt is recorded in `token_attempts` for transparency):

      0. If `known_token` is supplied (e.g. parsed out of an AES-recovered URL):
         skip token minting and GO STRAIGHT to the v3 RUNTIME download endpoint:
             /api/index.php?a=dl&token=<TOK>&src=<lure>&mode=<mode>
         This is the path the victim's PowerShell uses in the wild and the only
         one whose token policy we control end-to-end.

      1. v3 ADMIN-style mint (per Censys 2026, `errtraffic_payload_downloader.py`):
         GET   /index.php?action=generateDownloadToken&os=<os>      → {"token": "..."}
         GET   /index.php?action=download&token=<TOK>
         NOTE: NO /api/ prefix — this was the v3 bug in earlier versions of this script.

      2. v2 mint (Censys 2026):
         GET   /api/generate-download-token.php?os=<os>             → {"token": "..."}
         GET   /api/download.php?token=<TOK>

      3. v3 RUNTIME mint via GET /api/index.php?a=init&os=<os>&src=<lure>&mode=<mode>.
         The `token` field can be one of several shapes; we handle all:
           3  — AES-encrypted clipboard PS (v3-original) → try_recover_clipboard_aes
                → extract a=dl URL + token → download.
           3b — a CLIPBOARD COMMAND itself (newest generation, May 2026:
                megamegalodon.click / pusanik.shop / sandman.bond) wrapped in
                string-key rolling-XOR-hex or byte-array numeric-XOR. Decoded via
                decode_clipboard_command(): saves raw (#1) + decoded (#2) clipboard,
                then chases the next-stage (a=dl endpoint or direct binary) for #3.
      4. v3 BW v2 plain-hex token (64-char hex) → /a=dl?uj=<hex>&rlm=<...>.

    SERVED-SCRIPT CHASE: when a=dl returns a SCRIPT (text) instead of a binary
    (e.g. slndcdnclaud's byte-array-XOR loader_NN.ps1, bootstrup's install.bat),
    it is recognized as a served clipboard/dropper command (saved raw + decoded),
    and the REAL next-stage binary it points to is fetched one level deep.

    GOAL CONTRACT (Blake's S35 spec): (1) raw clipboard command, (2) decoded
    command, (3) defanged next-stage binary. The raw + decoded clipboard are
    persisted even when the binary fetch is kit-gated / the panel is down.

    SAFETY: every saved payload gets a ".bin" suffix (never .exe/.dmg/.apk/.msi),
    is never executed, never opened. SHA-256 is computed for VT lookup. Results
    are cached process-wide by (panel_origin, os_type) so a batch of 50 lures
    pointing to the same panel only fetches once per OS."""
    from urllib.parse import urlparse, urlunparse, urljoin, quote
    if not panel_url.startswith(("http://", "https://")):
        panel_url = "https://" + panel_url
    p = urlparse(panel_url)
    origin = f"{p.scheme}://{p.netloc}"
    cache_key = (origin, os_type.lower(), bool(known_token))
    with _PAYLOAD_CACHE_LOCK:
        cached = _PAYLOAD_CACHE.get(cache_key)
    if cached:
        return {**cached, "from_cache": True}

    out: dict = {
        "panel_origin":          origin,
        "panel_origin_defanged": _defang(origin),
        "os":                    os_type,
        "token":                 known_token,
        "token_source":          ("supplied_by_aes_recovery" if known_token else None),
        "version_used":          None,
        "endpoint_family":       None,    # "v3_runtime" | "v3_admin" | "v2_admin"
        "payload_bytes":         0,
        "sha256":                None,
        "sha1":                  None,
        "md5":                   None,
        "magic":                 None,
        "content_type":          None,
        # Full HTTP response metadata for the binary GET — lets you correlate
        # rotation / CDN / origin without keeping the bytes on disk.
        "payload_response_headers": None,
        "payload_filename":      None,   # parsed from Content-Disposition
        "payload_etag":          None,
        "payload_last_modified": None,
        "payload_server":        None,
        "payload_content_length": None,
        "download_url":          None,
        "download_url_defanged": None,
        "saved_path":            None,
        "saved_path_note":       None,
        "errors":                [],
        "token_attempts":        [],
        "from_cache":            False,
    }

    # Headers that mimic the wild victim chain. ErrTraffic v3 panels TDS-filter
    # on UA + Referer + Origin; sending these consistently produces a 200 where
    # a bare urllib request gets 404/403.
    src_param  = (known_src  or p.netloc).lstrip("/")
    mode_param = (known_mode or "cloudflare")
    sess_headers = {
        "User-Agent":       _BROWSER_UA,
        "Accept":           "application/json, text/html, */*",
        "Accept-Language":  "en-US,en;q=0.9",
        # Use the LURE host (src=) as referer when known — that's what the
        # in-the-wild PS one-liner sends and many panels gate on this.
        "Referer":          f"https://{src_param}/",
        "Origin":           f"https://{src_param}",
        "X-Requested-With": "XMLHttpRequest",
    }

    # Per-(panel,os) session opener with sticky cookies. The kit's real loader
    # makes ordered GETs (/api/css.js → /api/cfg → /api/evt → /api/init → /api/dl)
    # and any Set-Cookie or redirect-carried state established along the way is
    # auto-preserved here. Even on panels that don't set cookies, this gives us
    # a consistent connection profile.
    opener = _build_session_opener()

    # ── Beacon warmup ────────────────────────────────────────────────────────
    # Replay the legitimate loader-side order BEFORE attempting any mint/dl.
    # On panels with session-state gating (e.g. older v3 deployments), this is
    # the difference between 403 and 200. On IP-binding panels (e.g. May-2026
    # BW v2 generation observed on slndcdnclaud.beer) it doesn't help — those
    # bind the dl token to the original victim's IP, an anti-abuse limit no
    # tool can defeat from a non-victim source IP. Either way it's the
    # structurally correct request profile.
    warmup_records = []
    for step, suffix, http_method, post_body in [
        ("css_js",  "/api/css.js",
                    "GET",  None),
        ("cfg",     f"/api/index.php?a=cfg&os={quote(os_type, safe='')}"
                    f"&src={quote(src_param, safe='')}&mode={quote(mode_param, safe='')}",
                    "GET",  None),
        ("evt",     "/api/index.php?a=evt",
                    "POST", json.dumps({"eventType":"page_view","browser":"Chrome",
                                          "os": os_type, "mode": mode_param}).encode()),
    ]:
        att_w = _http_get_safe(origin + suffix, sess_headers, timeout,
                                max_bytes=200_000, opener=opener,
                                method=http_method, body=post_body)
        warmup_records.append({"step": step, "url": origin + suffix,
                                "status": att_w["status"],
                                "bytes":  att_w["bytes"],
                                "error":  att_w["error"]})
    out["beacon_warmup"] = warmup_records

    def _try_download(version_label: str, family: str, dl_url: str) -> bool:
        """Hit the download URL; on a real payload (binary content-type OR magic),
        commit it to `out` and return True. Otherwise record diagnostics."""
        att = _http_get_safe(dl_url, sess_headers, timeout, max_bytes=50_000_000,
                              opener=opener)
        rec = {"phase": "download", "version": version_label, "family": family,
               "url": dl_url, "status": att["status"], "content_type": att["content_type"],
               "bytes": att["bytes"], "error": att["error"],
               "body_excerpt": att["body_text_head"]}
        out["token_attempts"].append(rec)
        data = att["body_bytes"] or b""
        if att["status"] != 200 or not data:
            return False
        # Reject obvious HTML error pages even on HTTP 200
        head = data[:512].lstrip()
        ct = (att["content_type"] or "").lower()
        is_html_response = (b"<html" in head[:200].lower() or b"<!doctype" in head[:200].lower()
                            or "text/html" in ct)
        magic = _detect_file_magic(data)
        if is_html_response and not magic and att["bytes"] < 5000:
            rec["error"] = "got HTML body — likely an error page, not a payload"
            return False
        # ── Served-script detection ────────────────────────────────────────────
        # The kit sometimes serves a clipboard/dropper SCRIPT via a=dl (not the
        # final binary): e.g. slndcdnclaud's byte-array-XOR `loader_NN.ps1`
        # shellcode loader, or bootstrup's `install.bat`. If the response is a
        # TEXT class AND decodes to a known clipboard command WITH a fetchable
        # next stage, capture it (goal #1 raw + #2 decoded) and chase the REAL
        # next-stage binary (goal #3) one level deep. We only hijack the commit
        # when there's a chaseable URL — legit final text payloads pass through.
        if magic not in _BINARY_MAGICS and att["bytes"] <= 1_000_000:
            try:
                _txt = data.decode("utf-8", "replace")
                _clip = decode_clipboard_command(_txt)
            except Exception:
                _clip = {"ok": False}
            if _clip.get("ok"):
                # Served artifact IS a clipboard/dropper command — capture it as
                # the raw+decoded clipboard pair (goal #1 + #2) regardless of
                # whether it carries a fetchable next stage.
                _ns = _clip.get("next_stage") or {}
                _scheme = ("served_bat" if _txt.lstrip().lower().startswith(("@echo", "cmd /c"))
                           else _clip.get("scheme"))
                out["clipboard_ps_recovered"] = {
                    "source": "served_via_a_dl", "scheme": _scheme,
                    "raw": _txt, "decoded": _clip.get("decoded"),
                    "invocation": _clip.get("invocation"), "next_stage": _ns,
                }
                out["served_script_url"] = dl_url
                if _ns.get("url"):
                    # Chase the REAL next-stage binary (goal #3), one level deep.
                    chase = _http_get_safe(_ns["url"], sess_headers, timeout,
                                           max_bytes=50_000_000, opener=opener)
                    cdata = chase["body_bytes"] or b""
                    cmagic = _detect_file_magic(cdata) if cdata else None
                    out["token_attempts"].append({
                        "phase": "served_script_chase", "version": version_label,
                        "family": f"{family}->{_scheme}->{_ns.get('kind')}",
                        "url": _ns["url"], "status": chase["status"],
                        "content_type": chase["content_type"], "bytes": chase["bytes"],
                        "magic": cmagic, "error": chase["error"]})
                    if chase["status"] == 200 and cdata and cmagic in _BINARY_MAGICS:
                        # Got the real binary — commit IT instead of the script.
                        data = cdata; magic = cmagic; att = chase; dl_url = _ns["url"]
                    else:
                        # Chase failed/gated — keep the served command artifact
                        # (goals #1+#2 satisfied); report binary not recovered.
                        rec["error"] = (f"served {_scheme} clipboard command captured "
                                        f"(raw+decoded saved); next-stage {_ns.get('kind')} "
                                        f"fetch from {_ns['url'][:80]} returned "
                                        f"{chase['status']}/{cmagic or 'no-binary'} — "
                                        f"binary not recovered from this source IP.")
                        return False
                # No next-stage URL (self-contained served dropper): fall through
                # and commit the script itself as the recovered artifact (it is
                # both the clipboard command AND, lacking a binary URL, the
                # closest-to-payload object). The .clipboard.ps1/.decoded.ps1
                # are still written from clipboard_ps_recovered in finalize.
        out["payload_bytes"]  = len(data)
        out["sha256"]         = hashlib.sha256(data).hexdigest()
        out["sha1"]           = hashlib.sha1(data).hexdigest()
        out["md5"]            = hashlib.md5(data).hexdigest()
        out["magic"]          = magic
        out["content_type"]   = att["content_type"]
        out["version_used"]   = version_label
        out["endpoint_family"] = family
        out["download_url"]   = dl_url
        out["download_url_defanged"] = _defang(dl_url)
        # Capture the FULL response headers for the binary GET. These travel in
        # the JSON even in metadata-only mode (bytes discarded), so you can
        # cluster/rotate on Server / ETag / Last-Modified / filename without
        # ever storing the payload.
        hdrs = att.get("response_headers") or {}
        out["payload_response_headers"] = hdrs
        out["payload_etag"]          = hdrs.get("etag")
        out["payload_last_modified"] = hdrs.get("last-modified")
        out["payload_server"]        = hdrs.get("server")
        out["payload_content_length"] = hdrs.get("content-length")
        cd = hdrs.get("content-disposition") or ""
        mfn = re.search(r"filename\*?=(?:UTF-8'')?\"?([^\";]+)\"?", cd, re.I)
        out["payload_filename"] = (mfn.group(1).strip() if mfn else None)
        # Stash bytes for the (optional) disk-save step; popped before the dict
        # is serialized. In metadata-only mode the save step discards them.
        out["__bytes__"]      = data
        return True

    def _try_mint(version_label: str, family: str, mint_url: str, dl_tpl: str) -> bool:
        """Hit a token-mint endpoint, parse JSON for token/downloadToken, then
        invoke `_try_download`. Returns True on full success."""
        att = _http_get_safe(mint_url, sess_headers, timeout, max_bytes=64_000,
                              opener=opener)
        rec = {"phase": "mint", "version": version_label, "family": family,
               "url": mint_url, "status": att["status"], "content_type": att["content_type"],
               "bytes": att["bytes"], "error": att["error"],
               "body_excerpt": att["body_text_head"]}
        out["token_attempts"].append(rec)
        if att["status"] != 200 or not att["body_bytes"]:
            return False
        # Try strict JSON first, then loose regex over the body (some panels
        # wrap the JSON in JS).
        tok = None
        try:
            j = json.loads(att["body_bytes"])
            if isinstance(j, dict):
                tok = j.get("token") or j.get("downloadToken") or j.get("download_token")
        except Exception:
            pass
        if not tok:
            m = re.search(r'"(?:token|downloadToken|download_token)"\s*:\s*"([A-Fa-f0-9]{16,})"',
                          att["body_text_head"] or "")
            if m: tok = m.group(1)
        if not tok:
            rec["error"] = ("got HTTP 200 but no token field in body "
                            f"({att['bytes']}B / {att['content_type']})")
            return False
        out["token"]        = tok
        out["token_source"] = f"minted_via_{family}"
        return _try_download(version_label, family, dl_tpl % quote(tok, safe=""))

    # ─── Strategy 0: short-circuit on a known token (from AES recovery or
    #               --payload-token CLI). Try BOTH URL schemas in sequence
    #               since the user may have captured a token from either:
    #                 v3 original   →  ?a=dl&token=<HEX>&src=<host>&mode=<mode>
    #                 v3 BW v2 (May 2026+) →  ?a=dl&uj=<HEX>&rlm=<B64URL>
    #               When --payload-src is supplied it is used as BOTH the
    #               `src` (old) AND the `rlm` (BW v2) value — the user can
    #               override either independently by passing the exact value
    #               they captured.
    # ─────────────────────────────────────────────────────────────────────────
    # Resolve the panel's randomized download-token param name. Per-panel
    # observation > caller-supplied explicit > kit-default `uj`. This is the
    # difference between a 200 and a 403 on panels whose param the kit
    # author renamed for that fleet (uc / tj / vl / ujxm / token).
    panel_host_lc = p.netloc.lower()
    resolved_tp, tp_src = resolve_panel_token_param(panel_host_lc)
    effective_token_param = known_token_param or resolved_tp
    out["token_param"]        = effective_token_param
    out["token_param_source"] = ("supplied" if known_token_param else tp_src)
    # List of candidates to try (preferred first, then known aliases) — built
    # so a misregistered or recently-rotated panel still gets a chance.
    bw_v2_param_candidates: list[str] = []
    seen_p = set()
    for cand in [effective_token_param, "uj", "token", "uc", "tj", "vl", "ujxm", "t"]:
        cl = cand.lower()
        if cl not in seen_p:
            seen_p.add(cl); bw_v2_param_candidates.append(cand)

    if known_token:
        # The user passed --payload-token; we don't know which kit generation
        # issued it, so we try both URL schemas in order of recency.
        #
        # When --payload-src is set we treat it as BW v2's `rlm` value
        # (the modern naming — kit dropper PS embeds the LURE HOST as `rlm`,
        # per parse_bw_v2_dropper observations). Otherwise we use the panel
        # host as a fallback (rarely correct but worth one attempt).
        # rlm= candidates — try the LITERAL operator-set value first (most
        # reliable, came from parse_bw_v2_dropper), then the lure host
        # (Referer-derived), then panel host (last-resort). Deduped.
        bw_v2_rlm_cands: list[str] = []
        seen_rlm0 = set()
        for cand in [known_rlm, known_src, panel_host_lc]:
            if cand and cand.lower() not in seen_rlm0:
                seen_rlm0.add(cand.lower()); bw_v2_rlm_cands.append(cand)
        s0_deadline = time.time() + max(15, strategy_budget_s)
        for tp in bw_v2_param_candidates:
            if time.time() > s0_deadline:
                out["errors"].append(f"strategy 0 (known-token) budget exhausted after "
                                     f"{strategy_budget_s}s — skipping remaining candidates")
                break
            for rlm in bw_v2_rlm_cands:
                dl_url_bwv2 = (f"{origin}/api/index.php?a=dl"
                               f"&{tp}={quote(known_token, safe='')}"
                               f"&rlm={quote(rlm, safe='')}")
                if _try_download("v3_bwv2", f"v3_bwv2_runtime[{tp}+{rlm[:12]}]", dl_url_bwv2):
                    register_panel_token_param(panel_host_lc, tp)  # remember the winner
                    return _finalize_payload_save(out, p, os_type, out_dir,
                                                  sevenz_password=known_sevenz_password)
            dl_url_bwv2_norlm = (f"{origin}/api/index.php?a=dl"
                                  f"&{tp}={quote(known_token, safe='')}")
            if _try_download("v3_bwv2", f"v3_bwv2_runtime_norlm[{tp}]", dl_url_bwv2_norlm):
                register_panel_token_param(panel_host_lc, tp)  # remember the winner
                return _finalize_payload_save(out, p, os_type, out_dir,
                                              sevenz_password=known_sevenz_password)
        # Then: v3-original schema (lenders.digital-era / pre-May-2026 kits).
        dl_url_v3 = (f"{origin}/api/index.php?a=dl&token={quote(known_token, safe='')}"
                     f"&src={quote(src_param, safe='')}&mode={quote(mode_param, safe='')}")
        if _try_download("v3", "v3_runtime", dl_url_v3):
            return _finalize_payload_save(out, p, os_type, out_dir,
                                          sevenz_password=known_sevenz_password)
        out["errors"].append("known-token /a=dl fetch failed for BOTH BW v2 (uj/rlm) and v3-original "
                             "(token/src/mode) URL schemas. The kit IP-binds tokens to the original "
                             "victim chain — a captured token typically only works from the IP that "
                             "minted it. To recover the binary: replay the lure in a FlareVM browser "
                             "session, capture the clipboard PS, and run that PS in-VM (the PS itself "
                             "issues a single GET to the kit's dl endpoint from the right IP).")

    # ─── Strategy 1: v3 admin-style mint (per Censys) ──────────────────────────
    v3a = ERRTRAFFIC_KIT["panel_endpoints_v3_admin"]
    if _try_mint("v3", "v3_admin",
                 f"{origin}{v3a['gen_token']}&os={quote(os_type, safe='')}",
                 f"{origin}{v3a['download']}&token=%s"):
        return _finalize_payload_save(out, p, os_type, out_dir,
                                      sevenz_password=known_sevenz_password)

    # ─── Strategy 2: v2 mint ───────────────────────────────────────────────────
    v2 = ERRTRAFFIC_KIT["panel_endpoints_v2"]
    if _try_mint("v2", "v2_admin",
                 f"{origin}{v2['gen_token']}?os={quote(os_type, safe='')}",
                 f"{origin}{v2['download']}?token=%s"):
        return _finalize_payload_save(out, p, os_type, out_dir,
                                      sevenz_password=known_sevenz_password)

    # ─── Strategy 3: v3 runtime mint via /a=init  ──────────────────────────────
    # The v3 init endpoint returns:
    #     {"ok": true, "token": "<full AES-encrypted PowerShell command>"}
    # where the `token` field is NOT a download token but the entire AES PS that
    # the kit writes to the victim's clipboard. We:
    #   1. parse the JSON, extract the `token` field (the AES PS)
    #   2. AES-decrypt the PS locally (vendored AES, never executes)
    #   3. parse the decrypted plaintext for a /api/index.php?a=dl URL
    #   4. extract the REAL download token from that URL
    #   5. hit a=dl with the real token to get the binary
    # This is the kit's actual victim flow, replicated end-to-end with NO browser,
    # NO JS execution, NO clipboard-paste — fully passive static recovery.
    init_url = (f"{origin}/api/index.php?a=init&os={quote(os_type, safe='')}"
                f"&src={quote(src_param, safe='')}&mode={quote(mode_param, safe='')}")
    att = _http_get_safe(init_url, sess_headers, timeout, max_bytes=131_072,
                          opener=opener)
    rec = {"phase": "mint", "version": "v3", "family": "v3_runtime_init",
           "url": init_url, "status": att["status"], "content_type": att["content_type"],
           "bytes": att["bytes"], "error": att["error"],
           "body_excerpt": (att["body_text_head"] or "")[:300]}
    out["token_attempts"].append(rec)
    if att["status"] == 200 and att["body_bytes"]:
        # Parse the panel's init JSON
        try:
            j = json.loads(att["body_bytes"])
        except Exception:
            j = None
        if isinstance(j, dict) and j.get("token"):
            aes_ps = j["token"]
            out["init_response_aes_ps"]     = aes_ps          # raw AES PS as served
            out["init_response_aes_ps_sha256"] = hashlib.sha256(aes_ps.encode("utf-8")).hexdigest()
            # Decrypt the AES PS locally to extract the real dl URL+token.
            # try_recover_clipboard_aes returns None when no AES-kit pattern is
            # in the text — which is the BW v2 generation case where init's
            # `token` field is a plain sha256-sized hex string, NOT an AES PS.
            # Normalize None to a structured dict so downstream code never
            # AttributeErrors on .get(). Strategy 4 (below) picks up the BW v2
            # plain-hex shape and tries the /api/dl?uj=... path.
            try:
                aes_rec = try_recover_clipboard_aes(aes_ps)
            except Exception as e:
                aes_rec = {"ok": False, "reason": f"AES decrypt exception: {str(e)[:200]}"}
            if aes_rec is None:
                aes_rec = {"ok": False, "reason": ("no AES-kit pattern in init `token` field — "
                                                    "likely BW v2 generation (plain hex token); "
                                                    "Strategy 4 will handle this shape")}
            out["init_response_aes_decrypt"] = {
                "ok":             aes_rec.get("ok", False),
                "plaintext":      aes_rec.get("plaintext_excerpt"),
                "plaintext_sha256": aes_rec.get("sha256"),
                "plaintext_bytes": aes_rec.get("plaintext_bytes"),
                "dl_url":         (aes_rec.get("urls_in_plaintext") or [None])[0],
                "errtraffic_payload_url": aes_rec.get("errtraffic_payload_url"),
                "reason":         aes_rec.get("reason"),
            }
            ehp = aes_rec.get("errtraffic_payload_url") or {}
            real_token = ehp.get("token")
            if real_token:
                out["token"]        = real_token
                out["token_source"] = "minted_via_v3_runtime_init_AES_decrypt"
                # Build dl URL from the AES-decrypted fields (use exactly what the
                # kit said to use — not our guesses for src/mode)
                eh_src  = ehp.get("src")  or src_param
                eh_mode = ehp.get("mode") or mode_param
                dl_url = (f"{origin}/api/index.php?a=dl&token={quote(real_token, safe='')}"
                          f"&src={quote(eh_src, safe='')}&mode={quote(eh_mode, safe='')}")
                if _try_download("v3", "v3_runtime", dl_url):
                    return _finalize_payload_save(out, p, os_type, out_dir,
                                                  sevenz_password=known_sevenz_password)
            elif re.fullmatch(r'[0-9a-fA-F]{64}', (aes_ps or "").strip()):
                # BW v2 plain-hex token shape — the token IS the download token
                # directly (no wrapper to decode). Strategy 4 uses it as `uj=`.
                rec["error"] = ("init returned the BW v2 generation shape "
                                "({\"token\":\"<64-char hex>\"}) — the token IS the "
                                "download token directly (no AES wrap to decrypt). "
                                "Strategy 4 (BW v2 runtime) will use it as `uj=`.")
            else:
                # ── Strategy 3b: the init `token` is a CLIPBOARD COMMAND, not a
                #    download token. The newest ErrTraffic generation (observed
                #    on megamegalodon.click / pusanik.shop / sandman.bond, May
                #    2026) ships the victim's clipboard PowerShell directly in
                #    the init `token` field, wrapped in rolling-XOR-hex or
                #    byte-array-XOR. Run the unified decoder; on success this
                #    satisfies goal #1 (raw clipboard) + #2 (decoded) AND gives
                #    us the next-stage URL to fetch the binary (goal #3).
                try:
                    clip = decode_clipboard_command(aes_ps)
                except Exception as e:
                    clip = {"ok": False, "reason": f"clipboard decode exception: {str(e)[:160]}"}
                if clip.get("ok"):
                    out["clipboard_ps_recovered"] = {
                        "source":   "init_token_field",
                        "scheme":   clip.get("scheme"),
                        "raw":      aes_ps,
                        "decoded":  clip.get("decoded"),
                        "invocation": clip.get("invocation"),
                        "next_stage": clip.get("next_stage"),
                    }
                    ns = clip.get("next_stage") or {}
                    ns_url = ns.get("url")
                    if ns_url and ns.get("kind") == "dl_endpoint":
                        out["token"]        = ns.get("token")
                        out["token_source"] = f"init_token_clipboard[{clip.get('scheme')}]→dl_endpoint"
                        # Fetch via the exact dl URL the decoded dropper built.
                        if _try_download("v3", f"v3_init_clipboard[{clip.get('scheme')}]", ns_url):
                            return _finalize_payload_save(
                                out, p, os_type, out_dir,
                                sevenz_password=(ns.get("sevenz_password") or known_sevenz_password))
                    elif ns_url and ns.get("kind") == "direct_binary":
                        out["token_source"] = f"init_token_clipboard[{clip.get('scheme')}]→direct_binary"
                        if _try_download("v3", f"v3_init_clipboard_direct[{clip.get('scheme')}]", ns_url):
                            return _finalize_payload_save(
                                out, p, os_type, out_dir,
                                sevenz_password=(ns.get("sevenz_password") or known_sevenz_password))
                    rec["error"] = (f"init `token` decoded as {clip.get('scheme')} clipboard "
                                    f"command (raw+decoded saved); next-stage "
                                    f"{ns.get('kind')} fetch from {(ns_url or 'n/a')[:80]} "
                                    f"did not return a binary (kit gating / rotated URL).")
                else:
                    rec["error"] = ("init returned JSON with `token` field but no known "
                                    f"clipboard wrapper matched ({clip.get('reason')}). The kit "
                                    "may have rotated to a new generation; capture the kit's "
                                    "/api/css.js to update ClickChain's matchers.")
        else:
            rec["error"] = ("init returned 200 but no 'token' field in JSON response "
                            f"(content-type {att['content_type']})")

    # ─── Strategy 4: BW v2 generation /a=init→dl with uj=/rlm= param schema ────
    # The BW v2 generation returns a simpler init shape:
    #     {"token":"<64-char hex>"}           (no "ok" field, no AES wrap)
    # The hex token is the dl token directly. Download URL schema also rotated:
    #     /api/index.php?a=dl&uj=<hex>&rlm=<b64url-of-per-deploy-id>
    # The `rlm` value binds the token to a specific lure-source / theme; if we
    # don't have a captured one we try a small list of observed values + the
    # default mode-encoded fallback. (Identifying the right rlm typically
    # requires capturing it from the live victim chain via --payload-token
    # /--payload-src; this strategy is the best-effort speculative path.)
    bw_token = None
    # Re-use the init response we already fetched in Strategy 3 (avoid double-fetch).
    init_body = att if 'att' in locals() and isinstance(att, dict) else None
    if init_body and init_body.get("status") == 200 and init_body.get("body_bytes"):
        try:
            j2 = json.loads(init_body["body_bytes"])
        except Exception:
            j2 = None
        if isinstance(j2, dict):
            cand = j2.get("token")
            if isinstance(cand, str) and re.fullmatch(r'[0-9a-fA-F]{64}', cand or ""):
                bw_token = cand
    if bw_token:
        out["token"]        = bw_token
        out["token_source"] = "minted_via_v3_bwv2_init_plain_hex"
        # The `rlm` parameter binds the token to a specific lure-realm. We try
        # the explicit caller value first (most reliable — came from a real
        # victim chain), then the panel host as fallback. Wrong rlm values
        # burn against kit anti-abuse, so we cap the loop length deliberately.
        # Strategy 4 rlm= ordering — known_rlm (literal from dropper PS)
        # FIRST, then lure host (Referer-derived), then panel host fallback.
        rlm_candidates: list[str] = []
        seen_rlm = set()
        for cand in [known_rlm, known_src, panel_host_lc]:
            if cand and cand.lower() not in seen_rlm:
                seen_rlm.add(cand.lower()); rlm_candidates.append(cand)
        # Wall-clock budget — caps the combinatorial 7×3 token-param × rlm loop
        # below so we never spin > strategy_budget_s seconds on a single OS
        # against a stubborn panel. Each timed-out request still records its
        # diagnostics in `token_attempts`; we just stop trying new combos.
        s4_deadline = time.time() + max(15, strategy_budget_s)
        for tp in bw_v2_param_candidates:
            if time.time() > s4_deadline:
                out["errors"].append(f"strategy 4 (BW v2 runtime) budget exhausted after "
                                     f"{strategy_budget_s}s — skipping remaining candidates "
                                     f"(see token_attempts for what was tried)")
                break
            for rlm in rlm_candidates:
                dl_url_rlm = (f"{origin}/api/index.php?a=dl"
                              f"&{tp}={quote(bw_token, safe='')}"
                              f"&rlm={quote(rlm, safe='')}")
                if _try_download("v3_bwv2", f"v3_bwv2_runtime[{tp}+rlm]", dl_url_rlm):
                    register_panel_token_param(panel_host_lc, tp)  # remember the winner
                    return _finalize_payload_save(out, p, os_type, out_dir,
                                                  sevenz_password=known_sevenz_password)
            dl_url_norlm = (f"{origin}/api/index.php?a=dl"
                            f"&{tp}={quote(bw_token, safe='')}")
            if _try_download("v3_bwv2", f"v3_bwv2_runtime_no_rlm[{tp}]", dl_url_norlm):
                register_panel_token_param(panel_host_lc, tp)  # remember the winner
                return _finalize_payload_save(out, p, os_type, out_dir,
                                              sevenz_password=known_sevenz_password)
        # Token minted but dl gated — flag this so the renderer + summary can
        # surface "we got the token but the kit rejected the dl" instead of
        # making it look like nothing worked.
        out["kit_gating"] = {
            "init_minted":          True,
            "init_token":           bw_token,
            "dl_attempted":         True,
            "dl_outcome":           "kit_gated_403",
            "likely_cause":         ("Token IP-bound to original victim chain. Kit panel binds the "
                                      "minted token to the IP+rlm of the lure-side request that "
                                      "issued it. Our request is from a non-victim IP, so dl 403s."),
            "next_step":            ("Replay the lure in a FlareVM browser session and capture the "
                                      "clipboard PowerShell — the PS issues the dl GET from inside "
                                      "the VM (the victim IP) which is what the kit's anti-abuse "
                                      "expects. Then pass --payload-token <uj-hex> --payload-src "
                                      "<rlm-b64> to ClickChain to skip the mint step."),
        }

    # All strategies exhausted
    gated = out.get("kit_gating", {}).get("dl_attempted")
    if gated:
        msg = ("dl endpoint kit-gated (IP-bound token). Init endpoint DID issue a token but the "
                "panel rejected the dl request from this source IP — by design (kit anti-abuse). "
                "Re-run after replaying the lure in a FlareVM browser session, with the captured "
                "clipboard PS providing the right (uj, rlm) tuple from the victim IP.")
    else:
        msg = ("all five endpoint strategies failed: "
               "known-token /a=dl, v3-admin /index.php?action=, v2 /api/generate-download-token.php, "
               "v3-runtime /a=init→AES→dl, v3-bwv2 /a=init→dl?uj=. Panel may be down, gated on a "
               "cookie/UA we don't simulate, the kit has been updated, or `rlm` requires a value "
               "captured from a live victim chain (pass --payload-src <captured-rlm>). See "
               "token_attempts for per-endpoint diagnostics.")
    out["errors"].append(msg)
    # GOAL #1/#2 PRESERVATION: even when no binary was recovered (kit-gated dl,
    # rotated rlm, down panel), if we DID decode the clipboard command from the
    # init token we must still persist the raw + decoded clipboard artifacts —
    # the raw clipboard command is the paramount deliverable. Route through
    # finalize so the .clipboard.ps1/.decoded.ps1 get written.
    if out.get("clipboard_ps_recovered") or out.get("init_response_aes_ps"):
        return _finalize_payload_save(out, p, os_type, out_dir,
                                      sevenz_password=known_sevenz_password)
    with _PAYLOAD_CACHE_LOCK:
        _PAYLOAD_CACHE[cache_key] = out
    return out


def _try_extract_password_7z(data: bytes, password: str,
                              *, persist_dir: str | None = None,
                              max_entries: int = 5000) -> dict:
    """Extract a password-protected .7z archive and surface the inner file(s):
    per-entry sha256/md5/sha1 + file magic + size + name.

    Returns a structured result:
      {"ok": bool, "entries": [{name, size, sha256, sha1, md5, magic,
                                 is_executable}, ...],
       "primary_inner_sha256": str | None,    # the largest executable entry
       "primary_inner_magic":  str | None,
       "primary_inner_name":   str | None,
       "primary_inner_size":   int  | None,
       "executable_entries":   int,
       "total_entries":        int,
       "extractor": "py7zr" | None,
       "extract_dir": str | None,             # only when persist_dir set
       "error":    str | None}

    Uses py7zr (a project dependency, pure-Python AES-256-decrypt-aware
    reader). NEVER executes anything. By default extracts to a tempdir,
    hashes each file, then DELETES the tempdir — bytes do not survive the
    call. When `persist_dir` is set (typically when --payload-files OR --dump
    is in effect), extraction stays on disk under
    `<persist_dir>/<sha12>_extracted/` so the analyst can browse it."""
    out = {"ok": False, "entries": [], "primary_inner_sha256": None,
           "primary_inner_magic":  None, "primary_inner_name":  None,
           "primary_inner_size":   None, "executable_entries": 0,
           "total_entries":  0, "extractor": None,
           "extract_dir":    None, "error": None}
    if not data or data[:6] != b"7z\xbc\xaf\x27\x1c":
        out["error"] = "not a .7z archive"; return out
    if not password:
        out["error"] = "no password supplied"; return out
    # Feature-flag check — set at module import. When py7zr is missing we
    # surface the import error cleanly with the install hint, so the
    # surrounding pipeline never crashes and the analyst knows the fix.
    if not HAS_PY7ZR:
        out["error"] = (f"py7zr not installed ({_PY7ZR_IMPORT_ERROR or 'not found'}). "
                         "Outer .7z sha256 + magic + size were still surfaced; the inner "
                         "exe/msi will be skipped until you `pip install py7zr`.")
        return out
    try:
        import io as _io, tempfile, shutil
        import py7zr   # safe: HAS_PY7ZR guard above
    except Exception as e:
        out["error"] = f"py7zr unavailable: {e}"; return out

    # Pick an extract destination. Persisted (e.g. --payload-files) lands
    # under the user's chosen out_dir; otherwise a tempdir auto-cleaned
    # at the end of the call.
    auto_cleanup = persist_dir is None
    if persist_dir:
        os.makedirs(persist_dir, exist_ok=True)
        sha12 = hashlib.sha256(data).hexdigest()[:12]
        extract_dir = os.path.join(persist_dir, f"{sha12}_7z_extracted")
        os.makedirs(extract_dir, exist_ok=True)
    else:
        extract_dir = tempfile.mkdtemp(prefix="clickchain_7z_")
    out["extract_dir"] = extract_dir if not auto_cleanup else None

    try:
        try:
            with py7zr.SevenZipFile(_io.BytesIO(data), mode="r", password=password) as zf:
                # needs_password() is a guard against silently producing
                # gibberish; an empty/wrong-password attempt raises.
                if zf.needs_password() and not password:
                    out["error"] = "archive needs password but none supplied"
                    return out
                zf.extractall(path=extract_dir)
        except py7zr.exceptions.PasswordRequired as e:
            out["error"] = f"password required: {e}"; return out
        except py7zr.exceptions.Bad7zFile as e:
            out["error"] = f"corrupt 7z file: {e}"; return out
        except Exception as e:
            # py7zr raises plain Exception for wrong-password ('wrong password
            # for archive') — surface that cleanly.
            out["error"] = f"7z extract failed ({e.__class__.__name__}): {str(e)[:200]}"
            return out
        out["extractor"] = "py7zr"

        # Walk the extracted tree, hash each FILE entry (skip dirs).
        # Cap at max_entries because some packaged-app payloads (e.g. the
        # "Volume2" skins-as-decoy on lsikjsns.beer) contain thousands of
        # small files — we want hashes for the executables, not 4000 PNGs.
        entries: list[dict] = []
        for root, _dirs, files in os.walk(extract_dir):
            for fn in files:
                if len(entries) >= max_entries:
                    break
                fp = os.path.join(root, fn)
                try:
                    sz = os.path.getsize(fp)
                except OSError:
                    continue
                # Hash everything (cheap) but only file-magic the first 8 KB
                # to avoid loading huge files into memory.
                try:
                    with open(fp, "rb") as fh:
                        head = fh.read(8192)
                        h256 = hashlib.sha256(); h1 = hashlib.sha1(); hm = hashlib.md5()
                        h256.update(head); h1.update(head); hm.update(head)
                        while True:
                            chunk = fh.read(1024 * 1024)
                            if not chunk: break
                            h256.update(chunk); h1.update(chunk); hm.update(chunk)
                except Exception as e:
                    entries.append({"name": os.path.relpath(fp, extract_dir),
                                    "size": sz, "error": str(e)[:120]})
                    continue
                magic = _detect_file_magic(head) if head else "empty"
                is_exe = magic in {"pe_windows", "elf_linux", "macho_mac",
                                    "macho_fat_mac", "msi_or_office",
                                    "apk_android", "jar_java"}
                entries.append({
                    "name":          os.path.relpath(fp, extract_dir).replace("\\", "/"),
                    "size":          sz,
                    "sha256":        h256.hexdigest(),
                    "sha1":          h1.hexdigest(),
                    "md5":           hm.hexdigest(),
                    "magic":         magic,
                    "is_executable": is_exe,
                })
            if len(entries) >= max_entries: break
        out["entries"]         = entries
        out["total_entries"]   = len(entries)
        exes = [e for e in entries if e.get("is_executable")]
        out["executable_entries"] = len(exes)
        # Primary inner picker — biased toward the actual entry-point binary
        # rather than the largest payload, because BW v2 droppers frequently
        # bundle a legit Windows app for DLL sideloading (e.g. Volume2 +
        # protobuf.dll). Priority:
        #   1. The largest .exe (the runnable entry point)
        #   2. The largest MSI / Mach-O / ELF / APK (entry point on non-Win)
        #   3. The largest .dll (sideload target if no exe)
        #   4. The largest non-exec file (decoy-only archives)
        def _rank_pick(e):
            # Higher tuple = better pick (used with max()).
            # Priority 3 = explicit .exe (entry point)
            # Priority 2 = .msi / Mach-O / ELF / APK (entry point on non-Win)
            # Priority 1 = .dll / generic PE (sideload target)
            # Priority 0 = anything else
            name = (e.get("name") or "").lower()
            if name.endswith(".exe"):                                       return (3, e["size"])
            if name.endswith((".msi", ".bin")):                              return (2, e["size"])
            if e.get("magic") in {"macho_mac", "macho_fat_mac", "elf_linux",
                                   "apk_android"}:                          return (2, e["size"])
            if name.endswith(".dll") or e.get("magic") == "pe_windows":     return (1, e["size"])
            return (0, e.get("size", 0))
        pick = (max(exes, key=_rank_pick) if exes else
                (max(entries, key=lambda e: e.get("size", 0)) if entries else None))
        # Also expose the unambiguous .exe pick separately (when present)
        exes_only = [e for e in exes if (e.get("name") or "").lower().endswith(".exe")]
        if exes_only:
            ep = max(exes_only, key=lambda e: e["size"])
            out["entry_point_exe"] = {
                "name":   ep["name"], "size": ep["size"],
                "sha256": ep["sha256"], "magic": ep["magic"],
            }
        if pick:
            out["primary_inner_sha256"] = pick.get("sha256")
            out["primary_inner_magic"]  = pick.get("magic")
            out["primary_inner_name"]   = pick.get("name")
            out["primary_inner_size"]   = pick.get("size")
        out["ok"] = bool(entries) and out["error"] is None
    finally:
        if auto_cleanup:
            try: shutil.rmtree(extract_dir, ignore_errors=True)
            except Exception: pass
    return out


_BW_V2_TOKEN_SHAPE_RE = re.compile(r'^[0-9a-fA-F]{64}$')


def _is_bw_v2_token_shape(s: str | None) -> bool:
    """Return True iff `s` is the BW v2 init-response shape: a bare 64-char
    hex string. In v3-original the same `token` field carries a long
    AES-encrypted PowerShell blob; in BW v2 it's the per-victim download
    token directly. Telling them apart lets the save path emit the right
    artifact (real PS for v3-original, raw token file for BW v2)."""
    return bool(s and _BW_V2_TOKEN_SHAPE_RE.match(s.strip()))


def _finalize_payload_save(out: dict, parsed_url, os_type: str,
                           out_dir: str | None,
                           *, sevenz_password: str | None = None) -> dict:
    """Helper: write the recovered artifacts to disk (payload binary + raw AES
    clipboard PS + decrypted plaintext PS, all when present) and cache the result.

    Writes (when `out_dir` is set and the data is present):
      <out_dir>/<host>.<os>.<sha12>.bin             — the actual binary (.bin suffix, never .exe)
      <out_dir>/<host>.<os>.<sha12>.clipboard.ps1   — raw AES-encrypted PS the panel served
      <out_dir>/<host>.<os>.<sha12>.decoded.ps1     — AES-decrypted plaintext PS

    If the recovered payload is a .7z archive AND `sevenz_password` is
    supplied (typically the password parsed out of the BW v2 dropper PS by
    parse_bw_v2_dropper), the inner exe/msi is also extracted in-memory and
    its hashes/magic added to the report. This is the path that surfaces the
    REAL Stage-2 binary hash on BW v2 panels (the served .7z is a thin
    AES-encrypted wrapper)."""
    data = out.pop("__bytes__", b"") or b""
    # 7z auto-extract — runs BEFORE we discard bytes in metadata-only mode,
    # so even on the default capture mode we surface the inner exe/msi hash.
    # Triggered when (a) the payload is .7z by magic AND (b) a password is
    # known. Password sources: (1) caller passes `sevenz_password=` (typically
    # from parse_bw_v2_dropper); (2) future: cfg-envelope decrypt; (3) future:
    # a per-panel learned password registry.
    if data and out.get("magic") == "archive_7z" and sevenz_password:
        # When the user asked us to keep payloads on disk (--payload-files
        # /--dump), persist the extracted inner files alongside the .7z so
        # they can pivot. Otherwise extract to a tempdir we delete after
        # hashing — bytes never survive the call.
        persist_extract_under = out_dir if out_dir else None
        extract_result = _try_extract_password_7z(data, sevenz_password,
                                                   persist_dir=persist_extract_under)
        out["sevenz_extract"] = {
            **extract_result,
            "password_used":         sevenz_password,
            "password_used_redacted": (sevenz_password[:2] + "*" * max(0, len(sevenz_password)-2)
                                        if len(sevenz_password) > 2 else "**"),
            "outer_sha256":          out.get("sha256"),
            "outer_size":            out.get("payload_bytes"),
        }
        if extract_result["ok"]:
            # Promote the inner hash to top-level so reports show the REAL
            # Stage-2 binary (the .7z is just an AES-encrypted wrapper).
            out["inner_payload_sha256"] = extract_result["primary_inner_sha256"]
            out["inner_payload_magic"]  = extract_result["primary_inner_magic"]
            out["inner_payload_name"]   = extract_result["primary_inner_name"]
            out["inner_payload_size"]   = extract_result.get("primary_inner_size")
    elif data and out.get("magic") == "archive_7z" and not sevenz_password:
        out["sevenz_extract"] = {
            "ok": False, "extractor": None, "entries": [],
            "error": ("payload is a password-protected .7z but no password was "
                       "supplied. Capture the dropper PS via the lure to recover "
                       "the per-campaign password, then re-run with --payload-token "
                       "or pass the password via --sevenz-password."),
        }

    if not out_dir and out.get("sha256"):
        # Metadata-only mode (the default). We computed sha256/sha1/md5, file
        # magic, size, and full response headers above; now drop the bytes so
        # nothing malicious lands on disk.
        out["capture_mode"]    = "metadata_only"
        out["saved_path_note"] = ("metadata-only: payload bytes discarded after hashing "
                                   "(sha256/sha1/md5 + magic + size + HTTP headers retained). "
                                   "Re-run with --payload-files to persist the binary.")
    # Persist when we have a binary OR a recovered clipboard command (the raw
    # clipboard is the paramount artifact and must be written even when the
    # binary fetch was kit-gated / the panel was down).
    _has_clip = bool(out.get("clipboard_ps_recovered") or out.get("init_response_aes_ps"))
    if out_dir and (out.get("sha256") or _has_clip):
        out["capture_mode"] = "files"
        try:
            os.makedirs(out_dir, exist_ok=True)
            # Stem identity: binary sha12 when present, else a sha12 of the
            # recovered clipboard text so the filename is stable + collision-safe.
            if out.get("sha256"):
                _id = out["sha256"][:12]
            else:
                _clip_src = ((out.get("clipboard_ps_recovered") or {}).get("raw")
                             or out.get("init_response_aes_ps") or "")
                _id = hashlib.sha256(_clip_src.encode("utf-8", "replace")).hexdigest()[:12]
            stem = _safe_filename(parsed_url.netloc) + f".{os_type}.{_id}"
            # Binary payload
            if data:
                bin_path = os.path.join(out_dir, stem + ".bin")
                with open(bin_path, "wb") as fh: fh.write(data)
                out["saved_path"] = bin_path
                out["saved_path_note"] = ("Saved with .bin suffix (defanged). DO NOT rename to "
                                          ".exe/.dmg/.apk/.msi and double-click. Submit SHA-256 "
                                          "to VirusTotal for downstream attribution.")
            # Init-response artifact. BW v2 returns a plain 64-char hex token
            # (NOT a clipboard PS — the actual clipboard PS for BW v2 lives in
            # the lure-side loader JS, not the panel's /api/init response).
            # v3-original returns an AES-wrapped PS blob that IS the clipboard
            # PS the victim would paste.
            #
            # Writer contract (Blake's S34 spec — 3 artifacts in payload mode):
            #   1) RAW UNFILTERED CLIPBOARD PS — what the victim copies
            #   2) DECODED CLIPBOARD PS — the same after the kit's wrapper
            #      (AES-CBC for v3-original, rolling XOR for BW v2) is removed
            #   3) RAW BINARY — handled by the `.bin` write above
            #
            # PANEL-DIRECT MODE (this writer):
            #   • v3-original: the panel SERVES the clipboard PS via /api/init →
            #     save .clipboard.ps1 (raw AES PS) + .decoded.ps1 (decrypted)
            #   • BW v2: the panel does NOT serve the clipboard PS; only a
            #     token → save .init_token.txt for the artifact we DO have
            #     and let the comprehensive lure-mode post-step write the
            #     real clipboard PS from the loader (see
            #     `_save_lure_side_clipboard_artifacts` for the lure-mode path).
            #     No fake / synthesized .ps1 is emitted here — Blake's S34
            #     audit rejected that approach (regression vs the captured
            #     literal).
            # ── PRIORITY: a recovered clipboard COMMAND (new XOR-PS init-token
            #    generation, or a script SERVED via a=dl). When present this is
            #    the authoritative raw+decoded clipboard pair — write both and
            #    skip the init_token/AES branches below. Covers the newest
            #    ErrTraffic generation (megamegalodon et al.) + served-script
            #    panels (slndcdnclaud loader_NN.ps1, bootstrup install.bat).
            cpr = out.get("clipboard_ps_recovered")
            aes_ps_raw = out.get("init_response_aes_ps")
            ird        = out.get("init_response_aes_decrypt") or {}
            if cpr and cpr.get("raw"):
                scheme = cpr.get("scheme") or "unknown"
                # Pick an extension that matches the served artifact type so a
                # .bat dropper isn't mislabeled .ps1.
                raw_txt = cpr["raw"]
                ext = ".clipboard.ps1"
                if scheme == "served_bat" or raw_txt.lstrip().lower().startswith("@echo"):
                    ext = ".clipboard.bat"
                clip_path = os.path.join(out_dir, stem + ext)
                with open(clip_path, "w", encoding="utf-8") as fh:
                    fh.write(raw_txt if raw_txt.endswith("\n") else raw_txt + "\n")
                out["saved_clipboard_path"]    = clip_path
                out["clipboard_artifact_kind"] = f"clipboard_command_{scheme}_{cpr.get('source','')}"
                if cpr.get("decoded"):
                    dec_path = os.path.join(out_dir, stem + ".decoded.ps1")
                    with open(dec_path, "w", encoding="utf-8") as fh:
                        dtxt = cpr["decoded"]
                        fh.write(dtxt if dtxt.endswith("\n") else dtxt + "\n")
                    out["saved_decoded_path"] = dec_path
            elif aes_ps_raw and _is_bw_v2_token_shape(aes_ps_raw):
                # ── BW v2 panel-direct: the .ps1 isn't capturable here ──
                tok_path = os.path.join(out_dir, stem + ".init_token.txt")
                with open(tok_path, "w", encoding="utf-8") as fh:
                    fh.write(aes_ps_raw + "\n")
                out["saved_init_token_path"]   = tok_path
                out["clipboard_artifact_kind"] = "bw_v2_init_token_only"
                out["clipboard_artifact_note"] = (
                    "BW v2 /api/init returned a 64-hex download token, not a "
                    "clipboard PS. The raw clipboard PS lives in the lure-side "
                    "loader JS (it's the outer rolling-XOR-hex wrap that "
                    "constructs the URL with this token). To capture it, "
                    "run ClickChain on a known lure for this panel.")
            elif aes_ps_raw:
                # ── v3-original panel-direct: AES PS IS the clipboard ──
                clip_path = os.path.join(out_dir, stem + ".clipboard.ps1")
                with open(clip_path, "w", encoding="utf-8") as fh:
                    fh.write(aes_ps_raw)
                out["saved_clipboard_path"]    = clip_path
                out["clipboard_artifact_kind"] = "raw_aes_ps_v3_original"
                if ird.get("plaintext"):
                    dec_path = os.path.join(out_dir, stem + ".decoded.ps1")
                    with open(dec_path, "w", encoding="utf-8") as fh:
                        fh.write(ird["plaintext"])
                    out["saved_decoded_path"] = dec_path
        except Exception as e:
            out["errors"].append(f"disk save failed: {str(e)[:120]}")
    cache_key = (out["panel_origin"], os_type.lower(),
                 bool(out.get("token_source") == "supplied_by_aes_recovery"))
    with _PAYLOAD_CACHE_LOCK:
        _PAYLOAD_CACHE[cache_key] = out
    return out


def _save_lure_side_clipboard_artifacts(report: dict) -> None:
    """Comprehensive lure-mode post-step. After the panel binary has been
    fetched + saved to `<stem>.bin`, walk the lure-side captures and write
    the REAL raw clipboard PS + decoded plaintext PS next to it.

    Blake's S34 spec — payload mode produces 3 artifacts:
      1) RAW UNFILTERED CLIPBOARD PS — what the victim copies
      2) DECODED CLIPBOARD PS — same after the kit wrapper is removed
      3) RAW BINARY — already written

    For BW v2 the raw clipboard is the OUTER ROLLING-XOR-HEX wrap embedded
    in the loader JS (extracted via `classify_clipboard_payload` which
    captures the literal `navigator.clipboard.writeText(...)` argument).
    The decoded form is `decode_outer_xor_clipboard(...)["decoded"]` — the
    inner dropper PS that constructs the dl URL with the token + rlm.

    For v3-original the raw clipboard is the AES-CBC triple wrapper in the
    same `clipboard_arg`. The decoded form comes from
    `try_recover_clipboard_aes(...)["plaintext_excerpt"]`.

    This function only RUNS when the lure-side data is present (i.e.,
    `analyze_html` ran and surfaced classifications on the loader page).
    Panel-direct mode skips it. Writes silently if `saved_path` isn't set
    (metadata-only mode → no `--payload-files`)."""
    lp = report.get("lure_page") or {}
    groups = lp.get("groups") or []
    if not groups:
        return
    pp = report.get("panel_payloads") or {}
    per_os = pp.get("per_os") or {}
    if not per_os:
        return

    # 1) Discover the literal raw clipboard PS from any group's
    #    classify_clipboard_payload hit. The kit's loader writes the SAME
    #    clipboard string per OS (the OS branching happens INSIDE the
    #    decoded inner PS), so capturing one literal per page is enough.
    raw_clip: str | None = None
    for g in groups:
        for cls in g.get("classifications") or []:
            if cls.get("scheme") == "clipboard_payload":
                arg = cls.get("clipboard_arg") or cls.get("clipboard_arg_excerpt")
                if arg and (raw_clip is None or len(arg) > len(raw_clip)):
                    raw_clip = arg
    if not raw_clip:
        return

    # 2) Compute the decoded form via the UNIFIED clipboard decoder — covers
    #    every known kit scheme (BW v2 string-XOR-hex, byte-array numeric-XOR,
    #    v3-original AES-CBC, PowerShell -EncodedCommand, base64-embedded-URL,
    #    plaintext) in one call. If nothing matches we still save the raw
    #    clipboard but skip `.decoded.ps1`.
    decoded_text: str | None = None
    decode_kind: str = "unknown"
    try:
        clip = decode_clipboard_command(raw_clip)
    except Exception:
        clip = {"ok": False}
    if clip.get("ok") and clip.get("decoded"):
        decoded_text = clip["decoded"]
        decode_kind  = clip.get("scheme") or "unknown"
    # Last fallback: AES recovery may already exist at the report level
    # (older code path). Use it if we couldn't decode locally.
    if decoded_text is None:
        for r in (report.get("aes_clipboard_recovery") or []):
            if r.get("ok") and r.get("plaintext_excerpt"):
                decoded_text = r["plaintext_excerpt"]
                decode_kind  = "v3_original_aes_cbc"
                break

    # 3) For each per-OS slot that wrote a `.bin`, write `.clipboard.ps1`
    #    + `.decoded.ps1` next to it. Idempotent — overwrites any prior
    #    panel-side artifact (lure-side data is authoritative for the
    #    literal-clipboard question).
    for os_name, slot in per_os.items():
        if not isinstance(slot, dict):
            continue
        saved_bin = slot.get("saved_path") or ""
        if not saved_bin:
            continue
        # `<stem>.bin` -> `<stem>` so we write next to it
        if saved_bin.endswith(".bin"):
            stem_path = saved_bin[:-4]
        else:
            stem_path = saved_bin
        try:
            clip_path = stem_path + ".clipboard.ps1"
            with open(clip_path, "w", encoding="utf-8") as fh:
                fh.write(raw_clip)
            slot["saved_clipboard_path"]    = clip_path
            slot["clipboard_artifact_kind"] = ("lure_loader_clipboard_arg_"
                                                 + decode_kind)
            if decoded_text:
                dec_path = stem_path + ".decoded.ps1"
                with open(dec_path, "w", encoding="utf-8") as fh:
                    fh.write(decoded_text)
                slot["saved_decoded_path"] = dec_path
        except Exception as e:
            slot.setdefault("errors", []).append(
                f"lure-side clipboard save failed: {str(e)[:120]}")


def detect_rotation_for_panel(panel_url: str, *, runs: int, timeout: int = 15,
                                src: str | None = None, mode: str = "cloudflare",
                                progress_fh=None) -> dict:
    """Hit /api/index.php?a=init N times for each OS and record the AES PS sha256,
    decrypted plaintext sha256, AND embedded download token across runs.

    For each OS we return:
      - n_runs                 — total successful runs
      - distinct_aes_ps        — number of unique AES PS responses
      - distinct_decrypted     — number of unique AES-decrypted plaintexts
      - distinct_dl_tokens     — number of unique download tokens
      - aes_ps_hashes / decrypted_hashes / tokens — the per-run lists

    A 'rotating' panel produces distinct_aes_ps ≈ n_runs (true polymorphism) but
    might still produce 1 distinct_dl_token (one token wrapped in N encryptions)
    OR N distinct_dl_tokens (true per-victim tokens). The token count is the
    interesting signal — it tells you if defenders can track this kit by token.

    Pure observation. Burns N requests per OS against the live panel."""
    from urllib.parse import urlparse, quote
    results = {"panel_url": panel_url, "panel_url_defanged": _defang(panel_url),
               "runs_per_os": runs, "per_os": {}}
    p = urlparse(panel_url if panel_url.startswith(("http", "https"))
                 else "https://" + panel_url)
    origin   = f"{p.scheme or 'https'}://{p.netloc}"
    src_val  = src or p.hostname
    init_url = f"{origin}/api/index.php?a=init"
    headers  = {"User-Agent": _BROWSER_UA,
                "Accept": "application/json, text/html, */*",
                "Referer": f"https://{src_val}/", "Origin": f"https://{src_val}",
                "X-Requested-With": "XMLHttpRequest"}
    for os_type in ERRTRAFFIC_KIT["supported_os"]:
        aes_ps_hashes  = []
        decrypted_hashes = []
        tokens           = []
        errors           = []
        for i in range(runs):
            if progress_fh:
                print(f"  [rotation-probe] {panel_url} os={os_type} run={i+1}/{runs}",
                      file=progress_fh)
            url = (f"{init_url}&os={quote(os_type, safe='')}"
                   f"&src={quote(src_val, safe='')}&mode={quote(mode, safe='')}")
            att = _http_get_safe(url, headers, timeout, max_bytes=131_072)
            if att["status"] != 200 or not att["body_bytes"]:
                errors.append(f"run{i+1}: status={att['status']} err={att['error']}")
                continue
            try:    j = json.loads(att["body_bytes"])
            except Exception: j = None
            if not (isinstance(j, dict) and j.get("token")):
                errors.append(f"run{i+1}: no token field in response")
                continue
            aes_ps = j["token"]
            aes_ps_hashes.append(hashlib.sha256(aes_ps.encode("utf-8")).hexdigest())
            try:    rec = try_recover_clipboard_aes(aes_ps)
            except Exception as e: rec = {"ok": False, "reason": str(e)[:120]}
            if rec.get("ok") and rec.get("sha256"):
                decrypted_hashes.append(rec["sha256"])
                ehp = rec.get("errtraffic_payload_url") or {}
                if ehp.get("token"): tokens.append(ehp["token"])
        results["per_os"][os_type] = {
            "n_runs":                len(aes_ps_hashes),
            "distinct_aes_ps":       len(set(aes_ps_hashes)),
            "distinct_decrypted":    len(set(decrypted_hashes)),
            "distinct_dl_tokens":    len(set(tokens)),
            "aes_ps_hashes":         aes_ps_hashes,
            "decrypted_hashes":      decrypted_hashes,
            "dl_tokens":             tokens,
            "errors":                errors,
        }
    # Overall verdict
    meta = {
        "rotates_aes_ps":     False,
        "rotates_decrypted":  False,
        "rotates_token":      False,
        "interpretation":     None,
    }
    for os_type, r in results["per_os"].items():
        if r["distinct_aes_ps"]    > 1: meta["rotates_aes_ps"]    = True
        if r["distinct_decrypted"] > 1: meta["rotates_decrypted"] = True
        if r["distinct_dl_tokens"] > 1: meta["rotates_token"]     = True
    if meta["rotates_token"]:
        meta["interpretation"] = ("Per-request token rotation observed — token is NOT a "
                                   "stable IOC. Defenders cannot track this operator by token.")
    elif meta["rotates_aes_ps"] and not meta["rotates_token"]:
        meta["interpretation"] = ("AES wrapper rotates per request (different key/IV each time) "
                                   "but the embedded DOWNLOAD TOKEN is constant. "
                                   "Polymorphism defeats hash-based detection of the clipboard "
                                   "string but the token is a STABLE IOC defenders can track.")
    elif not meta["rotates_aes_ps"]:
        meta["interpretation"] = ("AES PS is byte-identical across all runs — "
                                   "panel served a fully-cached response. "
                                   "Hash-based detection works against this kit version.")
    results["meta"] = meta
    return results


# Cache: panel host → (key_hex|None, source) so a 12K-lure sweep that resolves
# to the same panel pulls its loader JS + extracts the key exactly ONCE.
_PANEL_KEY_PULL_CACHE: dict[str, tuple] = {}
_PANEL_KEY_PULL_LOCK = threading.Lock()

# The current BW v2 generation serves /api/css.js OBFUSCATED as an IIFE:
#   (function(){var k=12; var d='<base64>'; ... atob(d) ... ^k ...})()
# atob(d) then byte^k yields the real loader JS, which carries API_Q2_KEY_HEX.
# Older builds shipped the literal in cleartext. We try cleartext first, then
# this single-level deobfuscation. Confirmed live on best-opportunity.shop.
_RE_JS_INT_VAR = re.compile(r"(?:var|let|const)\s+\w+\s*=\s*(\d{1,3})\b")
_RE_JS_B64_VAR = re.compile(r"['\"]([A-Za-z0-9+/]{40,}={0,2})['\"]")


def _deobfuscate_loader_js(js: str) -> str | None:
    """Best-effort one-level deobfuscation of an IIFE-wrapped BW v2 loader.
    Returns the decoded JS (containing API_Q2_KEY_HEX on success) or None.
    Pure arithmetic over base64 — never executes JS.

    Key candidates: inline `var|let|const x=N` literals (the kit's own gadget),
    PLUS the kit's documented XOR keys (ERRTRAFFIC_KIT['v3_xor_keys_seen']) as a
    fallback so a renamed/obfuscated key var doesn't defeat extraction."""
    if not js:
        return None
    ks: list[int] = [int(m.group(1)) for m in _RE_JS_INT_VAR.finditer(js)][:8]
    # Fallback / supplement: the kit's known XOR keys (deduped, inline ones first).
    for kk in (ERRTRAFFIC_KIT.get("v3_xor_keys_seen") or []):
        if kk not in ks:
            ks.append(kk)
    blobs = sorted({m.group(1) for m in _RE_JS_B64_VAR.finditer(js)},
                   key=len, reverse=True)[:4]
    if not ks or not blobs:
        return None
    for blob in blobs:
        try:
            raw = base64.b64decode(blob)
        except Exception:
            continue
        for k in ks:
            for transform in (lambda b: bytes((x ^ k) & 255 for x in b),
                              lambda b: bytes((x - k) & 255 for x in b),
                              lambda b: bytes((x + k) & 255 for x in b)):
                try:
                    dec = transform(raw).decode("utf-8", "replace")
                except Exception:
                    continue
                # The key literal is the only thing _pull_panel_api_key needs;
                # return the first transform that surfaces it.
                if "API_Q2_KEY_HEX" in dec:
                    return dec
    return None


def _pull_panel_api_key(origin: str, host: str, *, timeout: int = 10,
                         verify_tls: bool = False, progress_fh=None) -> tuple:
    """Fetch the panel's own loader JS, recover its per-host API_Q2_KEY_HEX
    (cleartext literal OR one-level IIFE-deobfuscated), register it, and return
    (key_hex, source). The kit encrypts each panel's /api/cfg + /api/settings
    envelope with a PER-HOST key; without it we fall back to the kit-default key
    and decryption fails with "key mismatch" (142/155 of the 2230 sweep). This
    is the "pull encryption keys from JS AND use them" capability.

    Returns (None, reason) on miss. Cached per host."""
    hl = (host or "").lower()
    with _PANEL_KEY_PULL_LOCK:
        if hl in _PANEL_KEY_PULL_CACHE:
            return _PANEL_KEY_PULL_CACHE[hl]
    hdrs = {"User-Agent": _BROWSER_UA, "Accept": "*/*", "Referer": origin + "/"}
    # Candidate loader endpoints, most-likely first. css.js is the runtime
    # decryptor the victim browser includes; the WP-plugin assets path is the
    # older lure-side location.
    paths = ["/api/css.js", "/api/css.js.php", "/css.js",
             "/wp-content/plugins/", "/api/index.php?a=css"]
    result = (None, "no_key_in_loader")
    for path in paths:
        if _interrupted():
            break
        att = _http_get_safe(origin + path, hdrs, timeout, max_bytes=400_000,
                             verify_tls=verify_tls)
        body = att.get("body_bytes")
        if not body or att.get("status") != 200:
            continue
        try:
            text = body.decode("utf-8", "replace")
        except Exception:
            continue
        intel = None
        try:
            intel = extract_loader_intel(text)          # cleartext literal
        except Exception:
            intel = None
        if not (intel and intel.get("api_q2_key_hex")):
            deob = _deobfuscate_loader_js(text)          # obfuscated IIFE
            if deob:
                try:
                    intel = extract_loader_intel(deob)
                except Exception:
                    intel = None
        if intel and intel.get("api_q2_key_hex"):
            key = intel["api_q2_key_hex"].lower()
            register_bw_v2_key(panel_host=hl,
                               contract_address=intel.get("contract_address"),
                               api_q2_key_hex=key, source=f"loader_js:{path}")
            if progress_fh:
                print(f"[key-pull] {hl}: recovered API_Q2_KEY_HEX from {path} "
                      f"({key[:12]}…)", file=progress_fh)
            result = (key, f"loader_js:{path}")
            break
    with _PANEL_KEY_PULL_LOCK:
        _PANEL_KEY_PULL_CACHE[hl] = result
    return result


def probe_panel_envelopes(panel_url: str, *, host: str | None = None,
                           timeout: int = 15, verify_tls: bool = True,
                           progress_fh=None) -> dict:
    """Probe a BW v2 panel's /api/cfg and /api/settings endpoints, decrypt
    the AES-GCM envelope, return the plaintext config dict the operator is
    serving right now. Pure passive HTTP — no JS execution, no auth, no writes.

    Returns:
      {"probed": [str...],          # list of endpoint URLs hit
       "responses": [{
           "url": str, "status": int, "enc": "gcm1"|"q2"|None,
           "q_bytes": int, "key_source": "host_specific"|"default"|None,
           "decrypted": dict|None,   # plaintext JSON on success
           "error": str|None,
       }, ...],
       "summary": {...}}            # mode / enabled / rentalExpired / etc. (flat)
    """
    out = {"probed": [], "responses": [], "summary": {}, "host": host}
    from urllib.parse import urlparse
    origin = f"{urlparse(panel_url).scheme or 'https'}://{urlparse(panel_url).netloc or host or ''}"
    if not origin or origin == "https://":
        out["error"] = "no panel origin"; return out
    # Resolve the AES-256-GCM base key. Order: host-specific (recovered from
    # this panel's loader) > contract-specific (recovered from the panel's
    # router contract on chain) > kit-author default. If analyze_html ran
    # already for any lure pointing at this panel, the key was registered
    # in ERRTRAFFIC_KIT['bw_v2_keys'] and resolves automatically.
    host_lc   = (host or "").lower()
    base_key, key_src = resolve_bw_v2_key(panel_host=host_lc,
                                           contract_address=None)
    # KEY-FROM-JS: if we don't already have THIS panel's host-specific key,
    # fetch its loader JS and recover API_Q2_KEY_HEX (cleartext or one-level
    # deobfuscated). Each panel encrypts its envelope with a per-host key; the
    # kit-author default fails with "key mismatch" (142/155 of the 2230 sweep).
    # Cached per host, so a panel probed once isn't re-pulled.
    if key_src != "host_specific":
        pulled_key, pulled_src = _pull_panel_api_key(
            origin, host_lc, timeout=timeout, verify_tls=verify_tls,
            progress_fh=progress_fh)
        if pulled_key:
            base_key, key_src = pulled_key, pulled_src

    runtime = ERRTRAFFIC_KIT.get("panel_endpoints_v3_runtime", {})
    bw_v2   = ERRTRAFFIC_KIT.get("bw_v2", {})
    scopes  = bw_v2.get("scopes", {}) or {}
    # Endpoints to try (action_name, scope, url_suffix)
    endpoints = [
        ("cfg",      scopes.get("cfg",      "cfg"), runtime.get("cfg")),
        ("settings", scopes.get("settings", "cfg"), runtime.get("settings")),
    ]
    hdrs = {"User-Agent": _BROWSER_UA,
            "Accept":     "application/json, */*",
            "Referer":    origin + "/",
            "Origin":     origin}
    if progress_fh:
        print(f"[envelope-probe] base_key source: {key_src}", file=progress_fh)
    for action_name, scope, suffix in endpoints:
        if not suffix: continue
        url = (f"{origin}{suffix}"
               f"&os=windows&src={host_lc or ''}&mode=cloudflare"
               if "?" in suffix
               else f"{origin}{suffix}?os=windows&src={host_lc or ''}&mode=cloudflare")
        out["probed"].append(url)
        rec = {"url": url, "url_defanged": _defang(url), "action": action_name,
               "scope": scope, "key_source": key_src,
               "status": None, "enc": None, "q_bytes": 0,
               "decrypted": None, "error": None}
        try:
            att = _http_get_safe(url, hdrs, timeout, max_bytes=131_072)
            rec["status"]       = att["status"]
            rec["content_type"] = att["content_type"]
            rec["bytes"]        = att["bytes"]
            if att["status"] != 200 or not att["body_bytes"]:
                rec["error"] = f"non-200 / empty body ({att['status']}, {att['bytes']}B)"
                out["responses"].append(rec); continue
            try:
                env = json.loads(att["body_bytes"])
            except Exception as je:
                rec["error"] = f"json parse failed: {je}"
                out["responses"].append(rec); continue
            rec["enc"]     = env.get("enc") if isinstance(env, dict) else None
            rec["q_bytes"] = len(env.get("q","") or "") if isinstance(env, dict) else 0
            if not base_key:
                rec["error"] = ("no API_Q2_KEY_HEX available — cannot decrypt. "
                                "Add the per-host key to ERRTRAFFIC_KIT['bw_v2_keys']['by_host'].")
                out["responses"].append(rec); continue
            try:
                plain = decrypt_api_envelope(env, scope=scope, base_key_hex=base_key)
                rec["decrypted"] = plain
                if progress_fh:
                    print(f"[envelope-probe] {action_name}: decrypted "
                          f"({rec['enc']}, scope={scope})", file=progress_fh)
            except Exception as de:
                rec["error"] = f"decrypt failed: {de}"
        except Exception as e:
            rec["error"] = f"probe exception: {e.__class__.__name__}: {e}"
        out["responses"].append(rec)
    # Aggregate operator-visible config two ways:
    #   summary      — the hand-picked flat fields (back-compat: CSV cols + the
    #                  classifier + older renderers reference these by name).
    #   config_full  — the COMPLETE merged plaintext config across every
    #                  decrypted endpoint. No key dropped, nothing truncated, so
    #                  EVERY operator setting reaches JSON, CSV (serialized) and
    #                  stdout. (Methodology rule 2 — never truncate CTI.)
    summary = {}
    config_full: dict = {}
    for r in out["responses"]:
        d = r.get("decrypted") or {}
        if isinstance(d, dict):
            for k, v in d.items():
                # first non-empty value wins; later endpoints don't clobber it
                if k not in config_full or config_full[k] in (None, "", [], {}):
                    config_full[k] = v
            for k in ("mode","enabled","blockBots","rentalExpired","showDelay","os","browser",
                      "panelBaseUrl","apiBase","logUrl","tokenUrl","downloadUrl"):
                if k in d and k not in summary:
                    summary[k] = d[k]
    out["summary"]     = summary
    out["config_full"] = config_full
    return out


def _payload_result_is_conn_dead(res: dict) -> bool:
    """True when EVERY strategy diagnostic for a per-OS payload result failed
    with a connection-level error (timeout / refused / reset / DNS) rather than
    a kit-gating HTTP response (404/403/empty). Used to early-abort the
    remaining OSes: if the first OS can't even establish a connection, the host
    is down and the other 3 OSes will only stack identical timeouts."""
    if res.get("sha256"):
        return False  # got a payload — host is clearly up
    diags = res.get("token_attempts") or res.get("strategies") or []
    errs = []
    for d in diags:
        if isinstance(d, dict):
            e = (d.get("error") or "")
            if d.get("status") is not None:   # any HTTP status ⇒ host answered
                return False
            if e:
                errs.append(e.lower())
    if not errs:
        return False
    conn_markers = ("timed out", "timeout", "handshake", "refused",
                    "reset", "getaddrinfo", "name or service", "unreachable",
                    "no route", "interrupted")
    return all(any(m in e for m in conn_markers) for e in errs)


def _payload_result_is_kit_absent(res: dict) -> bool:
    """True when EVERY strategy for a per-OS result returned HTTP 404 (the kit
    runtime is gone — e.g. a host whose landing still serves 200 but whose
    /api/* all 404 because the operator rotated/decommissioned the API). Used to
    skip the remaining OSes: they will all 404 too. Distinct from conn-dead
    (the host answers; it just no longer hosts the kit endpoints)."""
    if res.get("sha256"):
        return False
    diags = res.get("token_attempts") or res.get("strategies") or []
    statuses = [d.get("status") for d in diags if isinstance(d, dict)]
    statuses = [s for s in statuses if s is not None]
    return bool(statuses) and all(s == 404 for s in statuses)


def download_all_os_payloads(panel_url: str, *, timeout: int = 15,
                              out_dir: str | None = None,
                              progress_fh=None,
                              known_token: str | None = None,
                              known_src:   str | None = None,
                              known_mode:  str | None = None,
                              known_token_param: str | None = None,
                              known_sevenz_password: str | None = None,
                              known_rlm: str | None = None,
                              deadline: float | None = None) -> dict:
    """Iterate every supported OS, fetch each payload safely, return per-OS
    results + a meta-analysis (same hash across OSes? size deltas? magic types?).

    If `known_token` is supplied (e.g. parsed out of an AES-recovered clipboard URL),
    the runtime /api/index.php?a=dl path is tried FIRST with that token. The mint
    fallbacks still fire if it doesn't yield a payload.

    `deadline` (time.monotonic instant) and a connection-dead check on the FIRST
    OS bound the worst case: a panel whose handshake hangs no longer stacks
    4 OS × 3 strategies × fetch_timeout (~minutes) — it aborts after the first."""
    results = {}
    aborted = None
    for idx, os_type in enumerate(ERRTRAFFIC_KIT["supported_os"]):
        if deadline is not None and time.monotonic() > deadline:
            aborted = f"per-target budget exceeded before os={os_type}"
            break
        if _interrupted():
            aborted = f"interrupted before os={os_type}"
            break
        if progress_fh:
            tok_tag = " (with AES-recovered token)" if known_token else ""
            print(f"  [payload] {panel_url} os={os_type}{tok_tag}", file=progress_fh)
        results[os_type] = fetch_panel_payload(panel_url, os_type,
                                                timeout=timeout, out_dir=out_dir,
                                                known_token=known_token,
                                                known_src=known_src,
                                                known_mode=known_mode,
                                                known_token_param=known_token_param,
                                                known_sevenz_password=known_sevenz_password,
                                                known_rlm=known_rlm)
        # Early-abort after the FIRST OS when it's clearly futile to try the
        # other 3: either the host can't connect at all (conn-dead) OR every
        # strategy 404'd (kit runtime gone — landing may still 200 but /api/*
        # is decommissioned, e.g. a rotated-away panel). Both mean OS 2-4 would
        # only repeat the same failure.
        if idx == 0 and _payload_result_is_conn_dead(results[os_type]):
            aborted = "first-OS connection dead — host down, skipped remaining OSes"
            if progress_fh:
                print(f"  [payload] {panel_url}: {aborted}", file=progress_fh)
            break
        if idx == 0 and _payload_result_is_kit_absent(results[os_type]):
            aborted = "first-OS kit endpoints all 404 — API rotated away, skipped remaining OSes"
            if progress_fh:
                print(f"  [payload] {panel_url}: {aborted}", file=progress_fh)
            break
    # Meta-analysis
    successful = {o: r for o, r in results.items() if r.get("sha256")}
    hashes = {r["sha256"] for r in successful.values()}
    magics = {r["magic"] for r in successful.values() if r.get("magic")}
    # Payload-outcome status + captured tokens. WHY a binary wasn't recovered is
    # itself intel (and stops "nos=0" from looking like a tool failure): a BW v2
    # panel that mints a token but 403s the dl is the kit's anti-analysis (the
    # binary is served only to a CAPTCHA-verified victim session / non-CIS geo);
    # the TOKEN is still a trackable IOC. Distinct from a rotated-away API (404)
    # or a dead host (conn errors).
    tokens_captured = sorted({(r.get("token") or r.get("init_token"))
                              for r in results.values()
                              if (r.get("token") or r.get("init_token"))})
    payload_status, payload_status_note = _classify_payload_status(results, successful)
    return {
        "panel_url":     panel_url,
        "panel_url_defanged": _defang(panel_url),
        "per_os":        results,
        "meta": {
            "successful_os":     sorted(successful.keys()),
            "failed_os":         sorted(set(ERRTRAFFIC_KIT["supported_os"]) - set(results.keys())),
            "os_probed":         sorted(results.keys()),
            "aborted":           aborted,
            "payload_status":    payload_status,
            "payload_status_note": payload_status_note,
            "tokens_captured":   tokens_captured,
            "distinct_hashes":   len(hashes),
            "all_same_payload":  len(hashes) == 1 and len(successful) > 1,
            "file_magics":       sorted(magics),
            "sha256_list":       sorted(hashes),
            "size_range":        ({"min": min(r["payload_bytes"] for r in successful.values()),
                                    "max": max(r["payload_bytes"] for r in successful.values())}
                                   if successful else None),
        },
    }


def _classify_payload_status(results: dict, successful: dict) -> tuple:
    """Explain the payload-recovery outcome across all OSes. Returns
    (status, human_note). One of:
      recovered          — at least one OS yielded a binary
      dl_gated_403       — token minted but every dl returned 403 (kit serves the
                           binary only to a verified victim session — anti-analysis
                           / CIS-geofence; the TOKEN remains a trackable IOC)
      kit_absent_404     — every strategy 404'd (panel API rotated/decommissioned)
      host_unreachable   — connection-level failures only (host down)
      no_binary          — none of the above cleanly (mixed / unknown gating)."""
    if successful:
        return "recovered", f"binary recovered for {sorted(successful.keys())}"
    all_statuses, dl_403, dl_any, conn_errs, minted = [], 0, 0, 0, 0
    for r in results.values():
        if r.get("token") or r.get("init_token"):
            minted += 1
        for a in (r.get("token_attempts") or r.get("strategies") or []):
            if not isinstance(a, dict):
                continue
            st = a.get("status"); url = a.get("url") or ""
            if st is not None:
                all_statuses.append(st)
                # A *download* attempt is `a=dl`, `/download.php`, or
                # `action=download` — NOT the `generateDownloadToken` /
                # `generate-download-token.php` MINT endpoints (which also
                # contain "download" but return 404 on most panels; counting
                # them as dl broke the "all dl are 403" check → dl_gated_403
                # panels mis-bucketed as no_binary).
                ul = url.lower()
                is_dl = (("a=dl" in ul)
                         or ("/download.php" in ul)
                         or ("action=download" in ul and "generatedownloadtoken" not in ul))
                if is_dl:
                    dl_any += 1
                    if st == 403:
                        dl_403 += 1
            elif a.get("error"):
                conn_errs += 1
    if all_statuses and all(s == 404 for s in all_statuses):
        return "kit_absent_404", "every kit endpoint 404'd — API rotated/decommissioned (host may still serve a landing page)"
    if dl_any and dl_403 == dl_any and minted:
        return ("dl_gated_403",
                "token minted but every download returned 403 — kit serves the binary "
                "only to a CAPTCHA-verified victim session (anti-analysis / CIS geofence); "
                "the captured token is still a trackable IOC")
    if not all_statuses and conn_errs:
        return "host_unreachable", "connection-level failures only — host down/unresponsive"
    return "no_binary", "no binary recovered (mixed/unknown gating — see per-OS strategy diagnostics)"


# ============================================================================
# Comprehensive single-IOC investigation (--comprehensive)
# ============================================================================
def classify_input_role(url: str, *, timeout: int = 8, verify_tls: bool = True,
                        known_panel_hosts: set | None = None,
                        retries: int = 1) -> dict:
    """Decide whether `url` is a LURE (compromised site running a loader) or a
    PANEL (the ErrTraffic C2 itself). Signals, weighted:

      1. host match against a known-panel set (caller-supplied — typically built
         from KNOWN_ACTORS + the on-chain resolved getURL of an active contract)
      2. probe GET /api/index.php?a=init&os=windows&src=<host>&mode=cloudflare
         → if response is {"ok": true, "token": "<AES PS...>"} the host IS a panel
      3. probe fallback: if init probe network-errors, retry once before giving up
      4. if everything fails, default to "lure" with low confidence (lures are
         the common case; lure-mode analysis still produces useful output even
         on a fully-down host)

    Returns: {"role": "panel" | "lure", "confidence": float,
              "signals": [str...], "probe": {<probe details + retries>}}"""
    from urllib.parse import urlparse, quote
    # Default to LURE (the common case) with very low confidence. NEVER returns
    # "unknown" — that confused users in the previous output ("ROLE: UNKNOWN
    # (confidence 0.00)" was alarming but actually meant "couldn't reach the
    # probe endpoint"). Better to say "lure (probe failed)" and let downstream
    # lure-mode produce whatever output it can.
    out = {"role": "lure", "confidence": 0.05, "signals": [], "probe": None}
    p = urlparse(url if url.startswith(("http://", "https://")) else "https://" + url)
    host = (p.hostname or "").lower()
    if not host:
        out["signals"].append("invalid_host")
        return out

    # Signal 1 — known-panel hostname (strongest, no network needed). Checks
    # the caller-supplied set AND the on-disk PANELS_COMPREHENSIVE HIGH-conf KB,
    # so a panel whose /api/init 404s today (rotated src-gating, temporary
    # block) is still routed to the panel-direct payload flow instead of being
    # mislabeled a lure and yielding nothing. This was the dominant cause of
    # reachable-but-empty known panels in the 5-29 panel sweep.
    in_caller_set = bool(known_panel_hosts and host in {h.lower() for h in known_panel_hosts})
    kb_entry = _is_known_panel(host)
    if in_caller_set or kb_entry:
        out["role"]       = "panel"
        out["confidence"] = 0.95
        out["signals"].append(f"host_in_known_panels:{host}")
        out["known_panel_kb"] = bool(kb_entry)

    # Signal 2 — live probe of /api/index.php?a=init (the ErrTraffic v3 victim
    # init endpoint). Returns the canonical {"ok": true, "token": "<AES PS>"}
    # shape on real panels and 404 / HTML on lures. Retry once on transient
    # network errors (timeout, DNS hiccup, connection reset).
    origin = f"{p.scheme or 'https'}://{p.netloc or host}"
    probe_url = (f"{origin}/api/index.php?a=init&os=windows"
                 f"&src={quote(host, safe='')}&mode=cloudflare")
    headers = {"User-Agent": _BROWSER_UA,
               "Accept": "application/json, text/html, */*",
               "Referer": f"https://{host}/",
               "Origin":  f"https://{host}",
               "X-Requested-With": "XMLHttpRequest"}
    attempts = []
    att = None
    for try_i in range(1 + max(0, retries)):
        att = _http_get_safe(probe_url, headers, timeout, max_bytes=8192)
        attempts.append({
            "try":          try_i + 1,
            "status":       att["status"],
            "content_type": att["content_type"],
            "error":        att["error"],
            "bytes":        att["bytes"],
        })
        # If we got ANY HTTP response (status set) we're done — don't retry
        if att["status"] is not None:
            break
        # Don't waste a retry on a hard TLS/connect TIMEOUT — it means the host
        # is slow/dead and a second attempt only stacks another full timeout
        # (this was ~8s × 2 per dead panel in the 2230 sweep). Transient resets
        # / refusals (e.g. a CF challenge dropping the first hit) DO retry.
        _e = (att.get("error") or "").lower()
        if any(m in _e for m in ("timed out", "timeout", "handshake")):
            break
    out["probe"] = {
        "url":          probe_url,
        "attempts":     attempts,
        "status":       att["status"],
        "content_type": att["content_type"],
        "body_excerpt": (att["body_text_head"] or "")[:300],
        "error":        att["error"],
    }
    if att["status"] == 200 and att["body_bytes"]:
        try:    j = json.loads(att["body_bytes"])
        except Exception: j = None
        if isinstance(j, dict) and (j.get("token") or j.get("ok")):
            out["role"]       = "panel"
            out["confidence"] = max(out["confidence"], 0.90)
            out["signals"].append("init_endpoint_returns_token")
        else:
            # 200 but not the panel shape → almost certainly a lure
            out["confidence"] = max(out["confidence"], 0.45)
            out["signals"].append("init_endpoint_returns_non_token_200")
    elif att["status"] in (404, 403, 400, 401, 500):
        # No /api/index.php?a=init endpoint exposed → not a panel. Strong lure signal.
        if out["role"] != "panel":
            out["confidence"] = max(out["confidence"], 0.65)
            out["signals"].append(f"init_endpoint_http_{att['status']}")
    else:
        # Probe network-errored even after retry — we have nothing to go on.
        # Stay defaulted to "lure" with low conf so downstream still runs.
        out["signals"].append(f"probe_unreachable:{(att['error'] or 'unknown')[:80]}")
    return out


# ── D1/D4 helpers (S37 fixes) ─────────────────────────────────────────────────

def _build_resolved_next_stage_urls(base_report: dict, panel_payloads: dict | None) -> list[str]:
    """Build the resolved_next_stage_urls list from all available data sources.

    D4 FIX: In comprehensive mode this field was always None/empty because
    analyze_html's on-chain resolution only fires when --resolve is active and
    the contract resolves live. The REAL next-stage download URLs live in
    panel_payloads.per_os[*].download_url (the /api/dl endpoints actually hit
    to recover binaries). We merge both sources so analysts get a flat list
    without digging into per_os records.
    """
    seen: list[str] = []
    added: set[str] = set()

    def _add(u: Any) -> None:
        if u and isinstance(u, str) and u not in added:
            seen.append(u)
            added.add(u)

    # Source 1: on-chain resolved URLs from analyze_html (EtherHiding path)
    for u in ((base_report.get("summary") or {}).get("resolved_next_stage_urls") or []):
        _add(u)

    # Source 2: per-OS download URLs from payload recovery (always present when
    # --payload ran and succeeded, regardless of --resolve being active)
    for _os, r in ((panel_payloads or {}).get("per_os") or {}).items():
        _add(r.get("download_url"))

    # Source 3: panel_origin (the /api/... base even if dl token failed)
    if panel_payloads:
        for _os, r in (panel_payloads.get("per_os") or {}).items():
            po = r.get("panel_origin")
            if po and not any(po in u for u in seen):
                _add(po)
    return seen


def _build_contract_resolution(contracts: list[str], selectors: list[str],
                                actors: list[dict], base_report: dict) -> dict | None:
    """Build a compact contract_resolution record for the comprehensive report.

    D1 FIX: This field was initialized as None and never populated.  We now
    carry the contract addresses recovered from the EtherHiding loader groups,
    the method selectors, and any actor attribution so analysts can see the
    on-chain context without needing --investigate-contract.  For lures where
    the live eth_call succeeded (--resolve), the resolved URL is already in
    resolved_next_stage_urls; we reference it here too for completeness.
    """
    if not contracts and not selectors and not actors:
        return None
    # Pull the on-chain resolved URL if present (set by analyze_html --resolve)
    resolved_urls = []
    for g in (base_report.get("groups") or []):
        for c in (g.get("classifications") or []):
            if c.get("scheme") == "etherhiding":
                for u in (c.get("resolved_urls") or []):
                    if u not in resolved_urls:
                        resolved_urls.append(u)
                # Also grab resolved_url (single-value variant)
                ru = c.get("resolved_url")
                if ru and ru not in resolved_urls:
                    resolved_urls.append(ru)
    return {
        "contract_addresses":  contracts,
        "method_selectors":    selectors,
        "resolved_urls":       resolved_urls,
        "actors_attributed":   [{"name": a.get("name"), "confidence": a.get("confidence"),
                                 "contract": a.get("contract")} for a in actors if isinstance(a, dict)],
        "note": ("Populated from EtherHiding loader static-decode. "
                 "Run --investigate-contract <addr> for full rotation history."),
    }


def investigate_ioc_comprehensive(url: str, args, progress_fh=None) -> dict:
    """Timing + budget wrapper around the per-IOC pipeline. Stamps a
    `timing` block (started_at / finished_at / duration_s) on EVERY exit path
    — including exceptions — so each target carries a historical performance
    record (Task: per-target scan duration counter). Also computes the hard
    per-target wall-clock deadline the pipeline honours so one dead-but-slow
    panel can't burn minutes."""
    _t0 = time.monotonic()
    budget = float(getattr(args, "target_budget", DEFAULT_TARGET_BUDGET_S) or DEFAULT_TARGET_BUDGET_S)
    deadline = _t0 + budget
    report: dict = {}
    try:
        report = _investigate_ioc_comprehensive_impl(url, args, progress_fh=progress_fh,
                                                       deadline=deadline)
    except Exception as e:
        # Catch here (don't re-raise) so EVERY target — even a crashing one —
        # returns a timed report. _one() in the batch is still a backstop.
        report = {"schema_version": SCHEMA_VERSION, "tool": TOOL_VERSION,
                  "mode": "comprehensive", "ioc": {"input": url},
                  "errors": [f"pipeline crash: {e.__class__.__name__}: {e}"],
                  "summary": {}, "lure_page": {}}
    finally:
        if not isinstance(report, dict):
            report = {"ioc": {"input": url}, "errors": ["pipeline returned no report"],
                      "summary": {}}
        dur = round(time.monotonic() - _t0, 2)
        fin = datetime.datetime.now(datetime.timezone.utc).isoformat(
            timespec="seconds").replace("+00:00", "Z")
        report["timing"] = {"started_at": report.get("started_at"),
                            "finished_at": fin, "duration_s": dur,
                            "budget_s": budget}
        if isinstance(report.get("summary"), dict):
            report["summary"]["scan_duration_s"] = dur
    return report


def _investigate_ioc_comprehensive_impl(url: str, args, progress_fh=None,
                                         deadline: float | None = None) -> dict:
    """Full pipeline for one IOC: fetch -> decode loader -> classify -> resolve
    contract -> server fingerprint -> WordPress detect -> CF detect -> AES
    decrypt -> optional payload download. Caches everything possible across
    invocations within the same process.

    `deadline` is a time.monotonic() instant after which the expensive probes
    (envelope / admin / payload) are skipped so a dead-but-TCP-open panel can't
    stack minutes of stacked socket timeouts. None = no budget (single-IOC)."""
    def _over_budget() -> bool:
        return deadline is not None and time.monotonic() > deadline
    started = datetime.datetime.now(datetime.timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z")
    report: dict = {
        "schema_version": SCHEMA_VERSION, "tool": TOOL_VERSION,
        "mode": "comprehensive", "started_at": started,
        "ioc": {"input": url, "normalized": normalize_target(url) if not url.startswith(("http://","https://")) else url},
        "lure_page": {}, "contract_resolution": None, "server_fingerprint": None,
        "wordpress": None, "cloudflare": None, "aes_clipboard_recovery": None,
        "panel_payloads": None, "admin_probe": None, "endpoint_probe": None,
        "colocated_hosts": None, "errors": [], "summary": {},
    }
    target = report["ioc"]["normalized"]

    # 0) Role classification — is this URL a LURE (compromised site running the
    # ErrTraffic loader) or a PANEL (the C2 itself)? Different downstream flow.
    if progress_fh: print(f"[comprehensive] classifying input role for {target}", file=progress_fh)
    role = classify_input_role(target, timeout=min(args.fetch_timeout, 8),
                                verify_tls=not args.no_tls_verify)
    report["input_role"] = role
    if progress_fh:
        print(f"[comprehensive]   role={role['role']} (conf {role['confidence']:.2f}) "
              f"signals={','.join(role['signals'])}", file=progress_fh)

    # ── PANEL-MODE PATH ───────────────────────────────────────────────────────
    # If the URL is a panel, skip lure-side decode and go straight to the panel
    # API. The user can still get the AES PowerShell from /api/index.php?a=init
    # per-OS and recover the binary directly.
    if role["role"] == "panel":
        if progress_fh: print(f"[comprehensive] PANEL detected — running panel-direct flow", file=progress_fh)
        report["mode"] = "comprehensive_panel"
        # Server fingerprint
        from urllib.parse import urlparse as _urlparse
        panel_host = _urlparse(target).hostname
        if panel_host:
            report["server_fingerprint"] = fingerprint_server(panel_host, shodan_key=getattr(args, "_shodan_key", None))
            # Co-located hosts ("other URLs/endpoints on the same server") —
            # pure synthesis from the cert SAN + Shodan we just collected, no
            # extra requests. CF-edge-flagged so it never misleads.
            report["colocated_hosts"] = synthesize_colocated_hosts(
                report["server_fingerprint"], panel_host)
        # ── REACHABILITY GATE ─────────────────────────────────────────────────
        # The dominant cost in a panel sweep is dead-but-listed panels: a parked
        # or rotated host still ran envelope×2 + admin×N + landing + payload
        # (4 OS × 3 strategies), each stacking a full --fetch-timeout. On a host
        # whose TLS handshake hangs that is ~8 minutes for ONE panel, and they
        # cluster at the alphabetical tail → the "170/179 crawl". The init-probe
        # in classify_input_role already attempted HTTP: if it got ANY status
        # (even 404/403/521) the host answers and we proceed; if it got None
        # (DNS / connection / TLS-handshake error) the host is down and we skip
        # the expensive probes — the single highest-impact perf fix.
        sf = report.get("server_fingerprint") or {}
        _probe_status = (role.get("probe") or {}).get("status")
        _dns_dead = isinstance(sf.get("error"), str) and sf["error"].startswith("dns:")
        _web_ports = [p for p in (sf.get("open_ports") or [])
                      if p in (443, 80, 8443, 8080, 8000, 8888)]
        _reachable = (_probe_status is not None) and not _dns_dead
        report["reachable"] = _reachable
        report["reachability"] = {
            "reachable": _reachable, "init_probe_status": _probe_status,
            "dns_dead": _dns_dead, "web_ports_open": _web_ports,
            "reason": ("init-probe returned HTTP status" if _reachable
                       else f"init-probe errored ({(role.get('probe') or {}).get('error') or 'no status'})"
                            + (" + DNS dead" if _dns_dead else "")),
        }
        if not _reachable:
            report["errors"].append(
                "panel unreachable at HTTP layer — skipped envelope/admin/landing/"
                f"payload probes to avoid timeout stacking (init_probe_status="
                f"{_probe_status}, dns_dead={_dns_dead}, web_ports={_web_ports})")
            if progress_fh:
                print(f"[comprehensive]   UNREACHABLE — skipping heavy probes "
                      f"(saved ~{4*3} payload + envelope/admin timeouts)", file=progress_fh)
        # Probe + decrypt BW v2 envelopes (/api/cfg, /api/settings). Yields the
        # operator's live config in plaintext — mode (lure theme), enabled flag,
        # blockBots, rentalExpired, etc. — without ever running JS or contacting
        # the loader. Gated on reachability + the per-target budget.
        # Use cached wrapper so a panel-role input later in the same batch
        # that points at an already-probed panel doesn't re-hit /api/cfg.
        if _reachable and not _over_budget():
            report["envelope_recovery"] = get_or_probe_envelope(
                target, host=panel_host, timeout=args.fetch_timeout,
                verify_tls=not args.no_tls_verify, progress_fh=progress_fh)
        # Probe for an EXPOSED operator admin / install panel (/admin/login.php,
        # /install.php, …). High-value OPSEC + takedown evidence per Censys.
        # Skip with --no-admin-probe; always-on for reachable panels otherwise.
        if _reachable and not _over_budget() and not getattr(args, "no_admin_probe", False):
            from urllib.parse import urlparse as _up_adm
            _adm_origin = f"{_up_adm(target).scheme or 'https'}://{_up_adm(target).netloc or panel_host}"
            report["admin_probe"] = probe_admin_panel(
                _adm_origin, timeout=min(args.fetch_timeout, 8),
                verify_tls=not args.no_tls_verify, progress_fh=progress_fh)
            # NEW: enumerate the FULL known-endpoint surface (every CTI/harvest-
            # documented kit endpoint) so we map what's live/gated on each panel.
            if not getattr(args, "no_endpoint_probe", False):
                report["endpoint_probe"] = probe_known_endpoints(
                    _adm_origin, timeout=min(args.fetch_timeout, 8),
                    verify_tls=not args.no_tls_verify, progress_fh=progress_fh)
        # Cloudflare detection on panel — we DO have headers now (we just probed)
        # so use them. But also check what we'd see for a normal GET.
        if _reachable and not _over_budget():
          try:
            html, meta = fetch_url_passively(target, timeout=args.fetch_timeout,
                                              verify_tls=not args.no_tls_verify)
            if getattr(args, "dump", None):
                report["_dump_raw_html"] = html or ""
            report["panel_landing_response"] = {
                "status": meta.get("status"), "bytes": meta.get("bytes_received"),
                "content_type": meta.get("content_type"),
                "headers_subset": {k: v for k, v in (meta.get("headers") or {}).items()
                                   if k.lower() in ("server","cf-ray","cf-cache-status",
                                                    "content-type","set-cookie")},
            }
            report["cloudflare"] = detect_cloudflare(html or "", headers=meta.get("headers"),
                                                      ip_meta={"ip": (report["server_fingerprint"] or {}).get("ip"),
                                                               "cname": (report["server_fingerprint"] or {}).get("cname"),
                                                               "asn":  None})
            report["wordpress"]  = detect_wordpress(html or "", headers=meta.get("headers"))
          except Exception as e:
            report["errors"].append(f"panel landing fetch failed: {e}")
        # If --payload, recover binaries directly for each OS via init→AES→dl
        if args.payload and _reachable and not _over_budget():
            if progress_fh: print(f"[comprehensive] panel-direct --payload fetch", file=progress_fh)
            known_token = getattr(args, "payload_token", None)
            known_src   = getattr(args, "payload_src", None) or panel_host
            known_mode  = getattr(args, "payload_mode", None) or "cloudflare"
            known_tp    = getattr(args, "payload_token_param", None)
            known_7zpw  = getattr(args, "sevenz_password", None)
            known_rlm   = getattr(args, "payload_rlm", None)
            _persist = bool(getattr(args, "payload_files", False) or getattr(args, "dump", None))
            report["panel_payloads"] = download_all_os_payloads(
                target, timeout=args.fetch_timeout,
                out_dir=(os.path.join(args.out or ".", "payloads") if (_persist and args.out) else None),
                progress_fh=progress_fh,
                known_token=known_token, known_src=known_src, known_mode=known_mode,
                known_token_param=known_tp, known_sevenz_password=known_7zpw,
                known_rlm=known_rlm, deadline=deadline)
        # --detect-rotation in panel-direct mode
        if getattr(args, "detect_rotation", 0) > 0:
            if progress_fh: print(f"[comprehensive] --detect-rotation: "
                                  f"{args.detect_rotation} runs per OS",
                                  file=progress_fh)
            try:
                report["rotation_probe"] = detect_rotation_for_panel(
                    target, runs=args.detect_rotation, timeout=args.fetch_timeout,
                    src=panel_host, mode="cloudflare", progress_fh=progress_fh)
            except Exception as e:
                report["errors"].append(f"rotation probe failed: {e}")
        # Minimal summary block. Carry actors_attributed when the IOC matches
        # a known-panel entry in our hand-curated KB — panel-mode never gets
        # to the EtherHiding loader-attribution path, so without this nothing
        # in the report would surface the operator association.
        from urllib.parse import urlparse as _up_kb
        _kb_host = _up_kb(target).hostname or panel_host
        _kb = _is_known_panel(_kb_host)
        # Attribution: name the KIT / VARIANT / OPERATOR / CONTRACT (the old,
        # useful style) instead of the redundant "Known-panel KB entry for
        # <host>" that just echoed the hostname. _panel_attribution joins the
        # panel KB to KNOWN_ACTORS' on-chain panel-router contracts.
        _attr = _panel_attribution(_kb_host)
        report["attribution"] = _attr   # structured, top-level for consumers
        kb_actors = []
        if _attr:
            kb_actors.append({
                "name":        _attr["label"],
                "kit":         _attr.get("kit"),
                "operator":    _attr.get("operator"),
                "confidence":  _attr.get("confidence") or "high",
                "sources":     _attr.get("sources") or (_kb or {}).get("sources") or ["panel KB"],
                "contract":    _attr.get("contract") or "",
                "admin_wallet": _attr.get("operator_wallet") or (_kb or {}).get("admin_wallet") or "",
            })
        elif _kb:
            kb_actors.append({
                "name": "ErrTraffic v3 (LenAI ecosystem) panel · operator not yet chain-mapped",
                "confidence": "high",
                "sources":   _kb.get("sources") or ["panel KB"],
                "contract":  _kb.get("contract") or "",
                "admin_wallet": _kb.get("admin_wallet") or "",
            })
        # D4 FIX: build resolved_next_stage_urls from panel_payloads download URLs
        _panel_next_stage = _build_resolved_next_stage_urls({}, report.get("panel_payloads"))
        report["summary"] = {
            "input_role":         "panel",
            "input_role_confidence": role["confidence"],
            "panel_url":          target,
            "panel_url_defanged": _defang(target),
            "panel_is_wordpress": (report.get("wordpress") or {}).get("is_wp", False),
            "panel_behind_cf":    (report.get("cloudflare") or {}).get("behind_cf", False),
            "panel_cf_signals":   len((report.get("cloudflare") or {}).get("signals") or []),
            "payload_oses_recovered": (sorted(report["panel_payloads"]["meta"]["successful_os"])
                                        if report.get("panel_payloads") else []),
            "payload_status": ((report.get("panel_payloads") or {}).get("meta") or {}).get("payload_status"),
            "payload_status_note": ((report.get("panel_payloads") or {}).get("meta") or {}).get("payload_status_note"),
            "payload_tokens_captured": ((report.get("panel_payloads") or {}).get("meta") or {}).get("tokens_captured") or [],
            "actors_attributed":  kb_actors,
            "actor_attribution_caveat":  ("Input classified as ErrTraffic panel; no lure-side "
                                          "EtherHiding decode performed (the panel IS the C2). "
                                          "Use --payload to recover the per-OS clipboard PS + binary."),
            "resolved_next_stage_urls": _panel_next_stage,
        }
        # D1 FIX: populate contract_resolution for panel-mode from KB entry
        _kb_contract = (_kb.get("contract") or "") if _kb else ""
        if _kb_contract or kb_actors:
            report["contract_resolution"] = {
                "contract_addresses":  [_kb_contract] if _kb_contract else [],
                "method_selectors":    [],
                "resolved_urls":       _panel_next_stage,
                "actors_attributed":   [{"name": a.get("name"), "confidence": a.get("confidence"),
                                          "contract": a.get("contract")} for a in kb_actors
                                         if isinstance(a, dict)],
                "note": "Populated from PANELS_COMPREHENSIVE KB entry (panel-direct mode).",
            }
        # S32 ClickFix classification (panel-mode early-return fix). Before
        # this addition, the panel-mode branch returned without calling the
        # scorer — so all 54 panel-routed records in the 5-29 panel sweep had
        # no `clickfix_classification` field. Now consistent with lure-mode.
        report["summary"]["clickfix_classification"] = classify_clickfix(report)
        return report

    # ── LURE-MODE PATH (default) ──────────────────────────────────────────────
    # 1) Fetch the lure
    if progress_fh: print(f"[comprehensive] fetching {target}", file=progress_fh)
    try:
        html, meta = fetch_url_passively(target, timeout=args.fetch_timeout,
                                          verify_tls=not args.no_tls_verify)
        if getattr(args, "dump", None):
            report["_dump_raw_html"] = html or ""
    except Exception as e:
        # Graceful degradation — preserve what we DO have (input URL, role probe,
        # any errors) instead of returning a near-empty report. Skip lure-side
        # analysis but still try the panel-side flow if --payload + role hints panel.
        report["errors"].append(f"lure fetch failed: {e}")
        # Try server fingerprint anyway — DNS + ports might still resolve
        from urllib.parse import urlparse as _urlparse
        _h = _urlparse(target).hostname
        if _h:
            try: report["server_fingerprint"] = fingerprint_server(_h, shodan_key=getattr(args, "_shodan_key", None))
            except Exception as fp_e: report["errors"].append(f"fingerprint failed: {fp_e}")
        # Minimum summary so the renderer doesn't print "None" headers.
        # Carry KB actor attribution when the target host matches a known
        # panel — gives the classifier a chain-grade signal even when the
        # main fetch failed (host is down / 403 / DNS-dead but we KNOW
        # historically it was kit infra).
        from urllib.parse import urlparse as _up_kb
        _kb_host = _up_kb(target).hostname
        _kb = _is_known_panel(_kb_host)
        # Attribution: name the KIT / VARIANT / OPERATOR / CONTRACT (the old,
        # useful style) instead of the redundant "Known-panel KB entry for
        # <host>" that just echoed the hostname. _panel_attribution joins the
        # panel KB to KNOWN_ACTORS' on-chain panel-router contracts.
        _attr = _panel_attribution(_kb_host)
        report["attribution"] = _attr   # structured, top-level for consumers
        kb_actors = []
        if _attr:
            kb_actors.append({
                "name":        _attr["label"],
                "kit":         _attr.get("kit"),
                "operator":    _attr.get("operator"),
                "confidence":  _attr.get("confidence") or "high",
                "sources":     _attr.get("sources") or (_kb or {}).get("sources") or ["panel KB"],
                "contract":    _attr.get("contract") or "",
                "admin_wallet": _attr.get("operator_wallet") or (_kb or {}).get("admin_wallet") or "",
            })
        elif _kb:
            kb_actors.append({
                "name": "ErrTraffic v3 (LenAI ecosystem) panel · operator not yet chain-mapped",
                "confidence": "high",
                "sources":   _kb.get("sources") or ["panel KB"],
                "contract":  _kb.get("contract") or "",
                "admin_wallet": _kb.get("admin_wallet") or "",
            })
        report["summary"] = {
            "lure_url":                  target,
            "lure_is_wordpress":         False,
            "lure_wordpress_confidence": 0.0,
            "lure_behind_cf":            False,
            "lure_cf_signals":           0,
            "panel_url":                 None,
            "panel_url_defanged":        None,
            "panel_behind_cf":           None,
            "panel_cf_signals":          0,
            "classifications":           [],
            "actors_attributed":         kb_actors,
            "actor_attribution_caveat":  "",
            "resolved_c2":               [],
            "clipboard_aes_recovered":   False,
            "clipboard_aes_caveat":      "",
            "payload_oses_recovered":    [],
            "fetch_status":              "FAILED",
            "fetch_failure_reason":      str(e)[:200],
            "site_likely_state":         ("Lure may be down, blocked, or has rotated to a new "
                                           "host. Site may have been taken down, the operator may "
                                           "have moved on, or the lure could be IP-gating us. "
                                           "Try a fresh IP, a different lure URL, or re-check later."),
        }
        # S32 ClickFix classification (lure-mode fetch-fail early-return fix).
        # Before this addition, the fetch-failed branch returned without
        # calling the scorer — so 44 records in the 5-29 panel sweep had no
        # `clickfix_classification` field. The KB lookup above ensures
        # known-panel hosts still get `clickfix_confirmed` even when reach
        # failed (we historically attributed them; today's reach result
        # doesn't change that).
        report["summary"]["clickfix_classification"] = classify_clickfix(report)
        return report
    meta["source_type"] = "url"
    # 2) Static decode + classify
    base_report = analyze_html(target, html, meta,
                                max_depth=args.max_depth, outdir=args.out,
                                resolve_chain=True, rpc_override=args.rpc_url,
                                rpc_timeout=args.rpc_timeout)
    report["lure_page"] = base_report
    # 3) Server fingerprint of the lure host
    from urllib.parse import urlparse
    lure_host = urlparse(target).hostname
    if lure_host:
        if progress_fh: print(f"[comprehensive] fingerprinting {lure_host}", file=progress_fh)
        report["server_fingerprint"] = fingerprint_server(lure_host, shodan_key=getattr(args, "_shodan_key", None))
    # 4) WordPress + Cloudflare detection on the lure (using real response headers)
    response_headers = meta.get("headers") or {}
    report["wordpress"]  = detect_wordpress(html, headers=response_headers)
    report["cloudflare"] = detect_cloudflare(html, headers=response_headers,
                                              ip_meta={"ip": report["server_fingerprint"].get("ip"),
                                                       "cname": report["server_fingerprint"].get("cname"),
                                                       "asn":  None})
    # 4b) WordPress backdoor probe — passive probe of /wp-content/mu-plugins/...
    # paths per LevelBlue 2026 + Sucuri 2025. Only runs when WP is detected
    # (skips wasted probes on non-WP sites).
    report["wp_backdoor_probe"] = None
    if report["wordpress"].get("is_wp"):
        from urllib.parse import urlparse as _urlparse
        _o = _urlparse(target)
        origin = f"{_o.scheme}://{_o.netloc}"
        if progress_fh: print(f"[comprehensive] probing mu-plugins backdoor paths on {lure_host}",
                              file=progress_fh)
        try:
            report["wp_backdoor_probe"] = probe_wordpress_backdoor(
                origin, timeout=min(args.fetch_timeout, 8),
                verify_tls=not args.no_tls_verify)
        except Exception as e:
            report["errors"].append(f"backdoor probe failed: {e}")
    # 4c) External <script src> body fetch + classify — DEFENSIBLE confirmation
    # of which (if any) injected external .js files actually carry the
    # obfuscated loader vs only the inline blocks. Static URL pattern alone
    # is suggestive but not authoritative; this fetches each candidate body
    # and classifies it. Surfaces ONLY high-confidence findings as
    # "MALICIOUS EXTERNAL JS" — ambiguous candidates listed separately.
    report["external_scripts_classified"] = None
    inj_srcs = ((base_report.get("page") or {}).get("injected_script_srcs") or [])
    if inj_srcs:
        if progress_fh: print(f"[comprehensive] passively fetching + classifying "
                              f"{len(inj_srcs)} external <script src> body(ies)",
                              file=progress_fh)
        try:
            report["external_scripts_classified"] = fetch_and_classify_external_scripts(
                target, inj_srcs,
                timeout=min(args.fetch_timeout, 8),
                verify_tls=not args.no_tls_verify,
                progress_fh=progress_fh)
        except Exception as e:
            report["errors"].append(f"external <script src> classify failed: {e}")
    # 5) AES clipboard recovery from each recovered loader.
    #
    # PRIOR BUG (S26+ sweep audit): this loop only ran when --out had written
    # recovered JS files to disk. Comprehensive batches without --out got
    # zero AES recoveries across 12,120 reports. Fixed: prefer the in-memory
    # `recovered_js` text that analyze_html now ships back on each group
    # object; fall through to disk only if the in-memory copy is empty.
    aes_recovery = []
    for group in base_report.get("groups", []):
        js_text = group.get("recovered_js") or ""
        if not js_text:
            js_path = group.get("recovered_js_path")
            if js_path and os.path.isfile(js_path):
                try:
                    js_text = open(js_path, encoding="utf-8", errors="replace").read()
                except Exception as e:
                    aes_recovery.append({"group_hash": group["group_hash"], "ok": False,
                                          "reason": f"file read: {e}"})
                    continue
        if not js_text:
            continue
        try:
            rec = try_recover_clipboard_aes(js_text)
            if rec: aes_recovery.append({"group_hash": group["group_hash"], **rec})
        except Exception as e:
            aes_recovery.append({"group_hash": group["group_hash"], "ok": False,
                                  "reason": f"recover error: {e}"})
    if aes_recovery: report["aes_clipboard_recovery"] = aes_recovery
    # 6) Identify panel URL — from the on-chain resolved URL OR from the AES plaintext
    panel_url = None
    for g in base_report.get("groups", []):
        for cls in g.get("classifications", []):
            r = cls.get("resolved") or {}
            cand = r.get("decoded_url")
            # Defense-in-depth host sanity: if a future contract uses an
            # unknown encoding (Strategy F & friends all return ok:False),
            # `cand` could still carry a degenerate string. Treat it as a
            # panel URL only if the host portion looks plausible (a dot, ≥2
            # labels, alphabetic TLD label OR IPv4).
            if cand and _is_plausible_panel_host(cand):
                panel_url = cand
                if not panel_url.startswith(("http://","https://")):
                    panel_url = "https://" + panel_url
                break
        if panel_url: break
    if not panel_url and aes_recovery:
        for rec in aes_recovery:
            if rec.get("errtraffic_payload_url"):
                panel_url = "https://" + rec["errtraffic_payload_url"]["host"]
                break
    # 6b) ENVELOPE PROBE — passively decrypt /api/cfg + /api/settings on the
    # resolved panel using the per-panel AES-256-GCM key we just harvested in
    # step 5/loader-intel sweep (extract_loader_intel + register_bw_v2_key).
    # PRIOR GAP (S26+ audit): comprehensive lure flow extracted the keys but
    # never USED them — only panel-role inputs called probe_panel_envelopes.
    # Result: 12K lures harvested ~24 keys, decrypted 0 envelopes. Fixed by
    # threading a per-run cache via get_or_probe_envelope so each panel is
    # probed exactly once even when 50 lures resolve to the same panel.
    report["envelope_recovery"] = None
    if panel_url:
        from urllib.parse import urlparse as _up
        _panel_host = _up(panel_url).hostname
        if _panel_host:
            try:
                if progress_fh:
                    print(f"[comprehensive] envelope probe (cached) for {_panel_host}",
                          file=progress_fh)
                report["envelope_recovery"] = get_or_probe_envelope(
                    panel_url, host=_panel_host, timeout=args.fetch_timeout,
                    verify_tls=not args.no_tls_verify, progress_fh=progress_fh)
            except Exception as _ee:
                report["errors"].append(f"envelope probe failed: {_ee}")
    # 7) If --payload, download safely. Prefer an AES-recovered (token, src, mode)
    # triple if we have one — that lets us hit /api/index.php?a=dl directly with
    # a real server-issued token, no mint chain required.
    if args.payload and panel_url:
        if progress_fh: print(f"[comprehensive] --payload fetch from {panel_url}", file=progress_fh)
        # Priority order for (token, src, mode):
        #   1) CLI overrides (--payload-token / --payload-src / --payload-mode /
        #      --payload-token-param / --sevenz-password)
        #   2) AES-recovered triple from this same investigation
        #   3) BW v2 launcher classification: token / token_param / src
        #      (from `ref=`) / 7z password — recovered statically from the
        #      lure-page loader's clipboard PS (no FlareVM needed when the
        #      kit ships the dropper as a literal in the loader script)
        #   4) None (mint chain will be tried)
        known_token = getattr(args, "payload_token", None)
        known_src   = getattr(args, "payload_src", None)
        known_mode  = getattr(args, "payload_mode", None) or "cloudflare"
        known_tp    = getattr(args, "payload_token_param", None)
        known_7zpw  = getattr(args, "sevenz_password", None)
        known_rlm   = getattr(args, "payload_rlm", None)
        if not known_token:
            for rec in (aes_recovery or []):
                ehp = (rec or {}).get("errtraffic_payload_url") or {}
                if ehp.get("token"):
                    known_token = ehp.get("token")
                    known_src   = known_src or ehp.get("src") or urlparse(target).hostname
                    known_mode  = ehp.get("mode") or known_mode
                    break
        # NEW: also harvest BW v2 launcher classifications from the loader-
        # side decode. These carry token / token_param / panel / 7z password
        # statically (no live FlareVM round-trip), and are how we recover
        # the per-panel randomized name when the kit author rotated `uj=`
        # to `uc`/`tj`/`vl`/`ujxm`/etc.
        bw_v2_hits: list[dict] = []
        for g in base_report.get("groups", []):
            for c in g.get("classifications", []):
                if c.get("scheme") == "bw_v2_launcher":
                    bw_v2_hits.append(c)
        if bw_v2_hits:
            # Prefer the BW v2 hit whose panel_host matches the resolved C2
            # (so cross-panel param-name confusion doesn't poison the dl).
            pref_host = urlparse(panel_url).hostname if panel_url else None
            pick = next((h for h in bw_v2_hits
                         if (h.get("panel_host") or "").lower() == (pref_host or "").lower()),
                        bw_v2_hits[0])
            if not known_token:        known_token = pick.get("token")
            if not known_tp:           known_tp    = pick.get("token_param")
            if not known_7zpw:         known_7zpw  = pick.get("sevenz_password")
            # NEW: pull the LITERAL rlm= value the kit's own dropper PS used.
            # When the kit ships rlm as base64url-of-bytes (not lure-host),
            # this is the only reliable way to pass panel validation.
            if not known_rlm:          known_rlm   = pick.get("rlm_value")
            # ref= value (real lure host) — sometimes carried in decoy_params
            # or matches the input target; falls back to the input apex.
            if not known_src:          known_src   = urlparse(target).hostname
        if not known_src:
            known_src = urlparse(target).hostname
        _persist = bool(getattr(args, "payload_files", False) or getattr(args, "dump", None))
        report["panel_payloads"] = download_all_os_payloads(
            panel_url, timeout=args.fetch_timeout,
            out_dir=(os.path.join(args.out or ".", "payloads") if (_persist and args.out) else None),
            progress_fh=progress_fh,
            known_token=known_token, known_src=known_src, known_mode=known_mode,
            known_token_param=known_tp, known_sevenz_password=known_7zpw,
            known_rlm=known_rlm)
        # S34: write the LURE-SIDE raw clipboard PS + decoded plaintext next
        # to each per-OS `.bin`. The panel-direct save inside
        # `_finalize_payload_save` only sees panel artifacts (which for BW v2
        # is just a 64-hex token, not a clipboard PS). The literal clipboard
        # string the victim copies is in the loader JS, captured by
        # `classify_clipboard_payload` during `analyze_html`. This post-step
        # surfaces both forms (raw + decoded) into `<stem>.clipboard.ps1` +
        # `<stem>.decoded.ps1` so Blake's S34 contract holds: payload mode
        # produces all 3 artifacts (raw clipboard, decoded clipboard, binary).
        if _persist:
            try:
                _save_lure_side_clipboard_artifacts(report)
            except Exception as _e:
                report["errors"].append(
                    f"lure-side clipboard post-save failed: {str(_e)[:200]}")
    # 7b) --detect-rotation: re-fetch init N times per OS to characterize
    # whether the kit serves polymorphic responses.
    if getattr(args, "detect_rotation", 0) > 0 and panel_url:
        if progress_fh: print(f"[comprehensive] --detect-rotation: "
                              f"{args.detect_rotation} runs per OS against {panel_url}",
                              file=progress_fh)
        try:
            report["rotation_probe"] = detect_rotation_for_panel(
                panel_url, runs=args.detect_rotation, timeout=args.fetch_timeout,
                src=known_src or urlparse(target).hostname, mode=known_mode or "cloudflare",
                progress_fh=progress_fh)
        except Exception as e:
            report["errors"].append(f"rotation probe failed: {e}")
    # 8) Server fingerprint of the panel (+ best-effort CF detection on the panel)
    report["panel_server_fingerprint"] = None
    report["panel_cloudflare"] = None
    if panel_url:
        panel_host = urlparse(panel_url).hostname
        if panel_host and panel_host != lure_host:
            if progress_fh: print(f"[comprehensive] fingerprinting panel {panel_host}",
                                  file=progress_fh)
            pfp = fingerprint_server(panel_host, shodan_key=getattr(args, "_shodan_key", None))
            report["panel_server_fingerprint"] = pfp
            # Admin/install-panel probe on the RESOLVED panel (lure → on-chain
            # panel discovery → check the panel's operator surface). Same passive
            # GET sweep used in panel-mode. Skipped with --no-admin-probe.
            if not getattr(args, "no_admin_probe", False) and report.get("admin_probe") is None:
                _padm_origin = f"{urlparse(panel_url).scheme or 'https'}://{urlparse(panel_url).netloc or panel_host}"
                report["admin_probe"] = probe_admin_panel(
                    _padm_origin, timeout=min(args.fetch_timeout, 8),
                    verify_tls=not args.no_tls_verify, progress_fh=progress_fh)
                # PARITY with direct panel-mode: enumerate the full known-endpoint
                # surface on the resolved panel too ("ALL panels that are up").
                if not getattr(args, "no_endpoint_probe", False) and report.get("endpoint_probe") is None:
                    report["endpoint_probe"] = probe_known_endpoints(
                        _padm_origin, timeout=min(args.fetch_timeout, 8),
                        verify_tls=not args.no_tls_verify, progress_fh=progress_fh)
            # CF detection on panel — when --payload ran we already hit the
            # panel and have its response headers. Use those for FULL CF
            # detection (5 signals). Otherwise fall back to IP/CNAME-only (1).
            panel_headers = None
            panel_body    = ""
            if report.get("panel_payloads"):
                for _, r in (report["panel_payloads"].get("per_os") or {}).items():
                    for att in (r.get("token_attempts") or []):
                        if att.get("phase") == "mint" and att.get("status") == 200:
                            # _http_get_safe stashes response headers — reach in via
                            # a second probe to the same endpoint (cheap; cached
                            # at the panel side) to harvest CF headers properly.
                            from urllib.parse import quote
                            probe = _http_get_safe(
                                att["url"],
                                {"User-Agent": _BROWSER_UA,
                                 "Accept": "application/json, text/html, */*",
                                 "Referer": f"https://{(known_src or panel_host)}/",
                                 "Origin":  f"https://{(known_src or panel_host)}",
                                 "X-Requested-With": "XMLHttpRequest"},
                                args.fetch_timeout, max_bytes=4096)
                            if probe.get("response_headers"):
                                panel_headers = probe["response_headers"]
                                panel_body    = probe.get("body_text_head") or ""
                                break
                    if panel_headers: break
            report["panel_cloudflare"] = detect_cloudflare(
                panel_body, headers=panel_headers,
                ip_meta={"ip": pfp.get("ip"), "cname": pfp.get("cname"), "asn": None})

    # 9) Summary — collect the critical IOCs from every layer into one block
    # so the analyst doesn't have to dig through 10 loader sections.
    schemes = base_report.get("summary", {}).get("schemes_seen", [])
    actors  = base_report.get("summary", {}).get("actors_attributed", [])
    resolved = base_report.get("summary", {}).get("resolved_next_stage_urls", [])
    # Extract contract + selector + dl-token + AES PS hashes
    contracts = []
    selectors = []
    for g in base_report.get("groups", []):
        for c in g.get("classifications", []):
            if c.get("scheme") == "etherhiding":
                for a in (c.get("contract_addresses") or []):
                    if a not in contracts: contracts.append(a)
                sel = c.get("method_selector")
                if sel and sel not in selectors: selectors.append(sel)
    dl_tokens         = []
    aes_ps_hashes     = []
    decrypted_hashes  = []
    payload_hashes    = []
    panel_origin      = None
    for o, r in ((report.get("panel_payloads") or {}).get("per_os") or {}).items():
        if r.get("token") and r["token"] not in dl_tokens: dl_tokens.append(r["token"])
        if r.get("init_response_aes_ps_sha256"):
            aes_ps_hashes.append(r["init_response_aes_ps_sha256"])
        ird = r.get("init_response_aes_decrypt") or {}
        if ird.get("plaintext_sha256"):
            decrypted_hashes.append(ird["plaintext_sha256"])
        if r.get("sha256") and r["sha256"] not in payload_hashes:
            payload_hashes.append(r["sha256"])
        if r.get("panel_origin"): panel_origin = r["panel_origin"]
    report["summary"] = {
        "lure_url":                  target,
        "lure_is_wordpress":         report["wordpress"]["is_wp"],
        "lure_wordpress_confidence": report["wordpress"]["confidence"],
        "lure_behind_cf":            report["cloudflare"]["behind_cf"],
        "lure_cf_signals":           len(report["cloudflare"].get("signals") or []),
        "panel_url":                 panel_url,
        "panel_url_defanged":        _defang(panel_url) if panel_url else None,
        "panel_behind_cf":           (report.get("panel_cloudflare") or {}).get("behind_cf"),
        "panel_cf_signals":          len((report.get("panel_cloudflare") or {}).get("signals") or []),
        # Critical IOCs surfaced at SUMMARY level
        "contract_addresses":        contracts,
        "method_selectors":          selectors,
        "controller_wallet":         None,  # filled by --investigate-contract when run
        "download_tokens":           dl_tokens,
        "distinct_aes_ps_hashes":    sorted(set(aes_ps_hashes)),
        "distinct_decrypted_hashes": sorted(set(decrypted_hashes)),
        "distinct_payload_hashes":   sorted(set(payload_hashes)),
        "classifications":           schemes,
        "actors_attributed":         actors,
        "actor_attribution_caveat":  ("Contract-address match against KNOWN_ACTORS table gives high "
                                      "confidence that the loader belongs to the named kit. Surrounding "
                                      "kit details (hosting / registrar / TTPs) are CTI from public reports — "
                                      "they describe the kit in general, NOT verified for THIS target."),
        "resolved_c2":               resolved,
        "clipboard_aes_recovered":   bool(aes_recovery and any(r.get("ok") for r in aes_recovery)),
        "clipboard_aes_caveat":      ("The AES blobs typically live in the SERVER response from the "
                                      "C2 panel (fetched at runtime), NOT in the on-page loader. "
                                      "'recovered: False' here means the loader-side static decode "
                                      "didn't see them — it does NOT mean the kit isn't AES-encrypting "
                                      "its clipboard payload. If you can complete the CAPTCHA in a "
                                      "FlareVM browser, capture the AES PowerShell from the clipboard, "
                                      "extract its token, and re-run with --payload-token <HEX> "
                                      "--payload-src <lure-domain> to download the binary."),
        "payload_oses_recovered": (sorted(report["panel_payloads"]["meta"]["successful_os"])
                                    if report.get("panel_payloads") else []),
        # Inherit the loader-stage verdict from analyze_html's summary.
        # PRIOR BUG (S26+ sweep audit): comprehensive flow built a fresh
        # summary dict and dropped this field on the floor, so all 12,120
        # reports in the 05-28 sweep had no `verdict`. Now propagated.
        "verdict":                  (base_report.get("summary") or {}).get("verdict"),
        # Surface the input role + confidence at summary level so analysts
        # can filter `summary.input_role` uniformly without falling back to
        # the nested `input_role` block.
        "input_role":               (report.get("input_role") or {}).get("role"),
        "input_role_confidence":    (report.get("input_role") or {}).get("confidence"),
        # Inherit fetch_error so the comprehensive path mirrors light batch.
        "fetch_error":              (base_report.get("summary") or {}).get("fetch_error"),
        # Loader-stage counts. Comprehensive previously dropped these too.
        "obfuscated_blocks":        (base_report.get("summary") or {}).get("obfuscated_blocks"),
        "distinct_groups":          (base_report.get("summary") or {}).get("distinct_groups"),
        # D4 FIX (S37): resolved_next_stage_urls was always empty in
        # comprehensive mode because analyze_html only returns the
        # on-chain-resolved URL (if --resolve hit the contract) and the
        # comprehensive path doesn't always call --resolve.  The REAL
        # next-stage data lives in panel_payloads.per_os[*].download_url.
        # Populate from both sources: lure-side EtherHiding resolution AND
        # panel_payloads download URLs — giving analysts one flat list.
        "resolved_next_stage_urls": _build_resolved_next_stage_urls(
            base_report, report.get("panel_payloads")),
    }
    # D1 FIX (S37): contract_resolution was initialized as None and never
    # populated in the comprehensive flow.  We already have the contract
    # addresses (extracted from EtherHiding loader groups above) and the
    # actors (from KNOWN_ACTORS attribution).  Serialize a compact record
    # so analysts can see which contract/selector each lure used WITHOUT
    # needing to run --investigate-contract separately.  The KB-routed
    # panel path still won't have on-chain resolution data (that was
    # intentional — KB routing bypasses the live eth_call), but we can at
    # least carry the contract address + actor name so the field is non-null.
    report["contract_resolution"] = _build_contract_resolution(
        contracts, selectors, actors, base_report)
    # --probe-admin FORCE: if the operator explicitly asked to check the scanned
    # endpoint's admin surface and nothing probed it yet (e.g. it classified as a
    # lure), run the passive admin/install sweep on the IOC host now.
    if getattr(args, "probe_admin", False) and report.get("admin_probe") is None:
        try:
            from urllib.parse import urlparse as _up_fa
            _fa_origin = f"{_up_fa(target).scheme or 'https'}://{_up_fa(target).netloc or _up_fa(target).hostname or ''}"
            if _up_fa(target).hostname:
                report["admin_probe"] = probe_admin_panel(
                    _fa_origin, timeout=min(args.fetch_timeout, 8),
                    verify_tls=not args.no_tls_verify, progress_fh=progress_fh)
        except Exception as e:
            report["errors"].append(f"forced admin probe failed: {e}")
    # S32: Replace the loader-stage shallow ClickFix classification with the
    # DEEP one — comprehensive mode has the full panel/envelope/wp_backdoor/
    # input_role context, so the scorer can produce a real verdict not just a
    # loader-only guess. Idempotent: re-runs on `report` give the same answer.
    report["summary"]["clickfix_classification"] = classify_clickfix(report)
    return report


# ============================================================================
# Input handling
# ============================================================================
def _strip_target_annotation(s: str) -> str:
    """Strip the inline `# kind=... source=... conf=... tags=...` annotation
    that cti_harvest.py appends to every line of its harvest_targets.txt.
    Without this, the leading URL ends up co-mingled with the annotation in
    every downstream consumer (regex match, URL fetch, dedup keys).

    Splits on first whitespace-then-#, takes the left side. Also trims any
    trailing whitespace. Idempotent on already-clean lines."""
    if not s: return s
    # Whitespace-bracketed `#` marker is the discriminator — `#fragment` in a
    # URL is fine (left alone), only `  #` style trailers get stripped.
    m = re.search(r'\s+#\s', s)
    if m: s = s[:m.start()]
    return s.rstrip()


def _looks_like_target(s: str) -> bool:
    # Strip leading bullets / annotation before matching, so harvest-format
    # lines like `host.com  # kind=url source=...` recognize correctly.
    s = _refang(_strip_target_annotation(s.strip().lstrip('-*•·').strip()))
    if not s: return False
    if s.startswith(("http://", "https://")): return True
    # Bare IPv4 — harvest lists thousands of these; without this branch they
    # all rate as non-targets and is_target_list_file fails the 80% threshold.
    if re.match(r'^(?:\d{1,3}\.){3}\d{1,3}(?::\d+)?$', s):
        # validate each octet 0-255
        host = s.split(':', 1)[0]
        try:
            if all(0 <= int(o) <= 255 for o in host.split('.')):
                return True
        except ValueError: pass
    # Bare IPv6 (bracketed or unbracketed with at least one `:` and hex chars)
    if s.startswith('[') and ']' in s: return True   # [::1]:8080 etc.
    # Bare domain or domain-with-path
    return bool(re.match(r'^(?:[a-zA-Z0-9][a-zA-Z0-9-]{0,62}\.)+[a-zA-Z]{2,24}(?:[:/].*)?$', s))


def normalize_target(s: str) -> str:
    """Refang + scheme-prepend a single target line. 'example[.]com' -> 'https://example.com/'.

    Strips the cti_harvest annotation (`  # kind=... source=...`) before
    normalizing, so downstream fetchers never see malformed URLs."""
    s = _refang(_strip_target_annotation(s.strip().lstrip('-*•·').strip()))
    if not s.startswith(("http://", "https://")):
        s = "https://" + s
    if "://" in s and s.rstrip().endswith(s.split("://", 1)[1].split("/", 1)[0]):
        s = s + "/"      # bare-domain: append /
    return s


def is_target_list_file(path: str) -> bool:
    """A target-list file: small text file containing newline-separated
    URLs/domains, no JSON/HTML markers in the first 64KB."""
    if not os.path.isfile(path): return False
    if path.lower().endswith((".json", ".html", ".htm")): return False
    try:
        with open(path, "rb") as fh:
            head = fh.read(64 * 1024)
    except OSError: return False
    if not head: return False
    lowered = head.lower()
    if b"<html" in lowered or b"<!doctype" in lowered or b"<script" in lowered: return False
    if head.lstrip().startswith((b"{", b"[")): return False
    sample = head.decode("utf-8", errors="replace").splitlines()[:20]
    non_blank = [l for l in sample if l.strip() and not l.strip().startswith("#")]
    if not non_blank: return False
    hits = sum(1 for l in non_blank if _looks_like_target(l))
    return hits / max(1, len(non_blank)) >= 0.8


def read_target_list(path: str) -> list[str]:
    """Parse a target-list file (skip blanks + # comments + de-dup)."""
    seen, out = set(), []
    with open(path, encoding="utf-8", errors="replace") as fh:
        for raw in fh:
            line = raw.strip()
            if not line or line.startswith("#"): continue
            norm = normalize_target(line)
            if norm in seen: continue
            seen.add(norm); out.append(norm)
    return out


def detect_input_kind(s: str) -> str:
    if s == "-": return "stdin"
    if s.startswith(("http://", "https://")): return "url"
    # bare domain like "example.com" or "example[.]com" → treat as URL target
    if _looks_like_target(s) and not os.path.exists(s): return "domain"
    if os.path.isdir(s): return "directory"
    if not os.path.isfile(s): return "html_file"
    if is_target_list_file(s): return "target_list"
    if s.lower().endswith((".html", ".htm")): return "html_file"
    if s.lower().endswith(".json"): return "clickgrab_json"
    with open(s, "rb") as fh:
        head = fh.read(512).lstrip().lower()
    if head.startswith(b"{") or head.startswith(b"["): return "clickgrab_json"
    if b"<html" in head or b"<!doctype" in head or b"<script" in head: return "html_file"
    return "html_file"


def iter_inputs(path: str, fetch_timeout: int, verify_tls: bool):
    """Yield (source_type, label, html_text, meta_dict). For batch sources
    (directory, target_list), yields one per discovered item but DOES NOT do
    URL fetching itself — that is the batch driver's job (so it can parallelize).
    URL/domain single inputs DO fetch here."""
    kind = detect_input_kind(path)
    if kind == "stdin":
        html = sys.stdin.read()
        yield ("stdin", "<stdin>", html, {"bytes": len(html)}); return
    if kind in ("url", "domain"):
        target = normalize_target(path) if kind == "domain" else path
        try:
            html, meta = fetch_url_passively(target, timeout=fetch_timeout, verify_tls=verify_tls)
            yield ("url", target, html, meta); return
        except (urllib.error.HTTPError, urllib.error.URLError, ConnectionError,
                TimeoutError, ssl.SSLError, OSError) as e:
            desc = _describe_fetch_exception(e, target, fetch_timeout=fetch_timeout,
                                             verify_tls=verify_tls)
            # Yield a sentinel telling the caller to emit a fetch_error report
            # instead of running analyze_html on empty HTML.
            yield ("fetch_error", target, "",
                   {"source_type": "url", "fetch_error_desc": desc}); return
    if kind == "directory":
        for root, _d, files in os.walk(path):
            for f in sorted(files):
                if f.lower().endswith((".html", ".htm", ".json")):
                    yield from iter_inputs(os.path.join(root, f), fetch_timeout, verify_tls)
        return
    if kind == "target_list":
        # NOTE: don't fetch here — emit deferred fetch jobs; the driver fetches.
        # S30 bug fix: the `; return` after the yield inside this loop killed
        # iteration after the first target. Removed; the bare `return` after
        # the loop handles end-of-generator correctly.
        for t in read_target_list(path):
            yield ("deferred_url", t, "", {"deferred": True})
        return
    if kind == "html_file":
        with open(path, encoding="utf-8", errors="replace") as fh:
            yield ("html_file", os.path.basename(path), fh.read(),
                   {"path": os.path.abspath(path)}); return
    if kind == "clickgrab_json":
        try:
            with open(path, encoding="utf-8", errors="replace") as fh:
                data = json.load(fh)
        except Exception as e:
            yield ("error", path, "", {"error": f"cannot parse: {e}"}); return
        sites = data.get("sites") if isinstance(data, dict) else (data if isinstance(data, list) else [])
        if not sites and isinstance(data, dict): sites = [data]
        for s in sites or []:
            url = s.get("URL") or s.get("url") or s.get("domain") or "?"
            html = s.get("RawHTML") or s.get("raw_html") or s.get("html") or ""
            if html:
                yield ("clickgrab_json", url, html, {"clickgrab_path": os.path.abspath(path)})
            else:
                blobs = []
                for b in (s.get("Base64Strings") or []):
                    v = b.get("Base64") if isinstance(b, dict) else b
                    if v: blobs.append(f'x=atob("{v}");')
                for b in (s.get("ObfuscatedJavaScript") or []):
                    v = b.get("code") if isinstance(b, dict) else b
                    if v: blobs.append(str(v))
                if blobs:
                    yield ("clickgrab_json_blobs",
                           url + " (no RawHTML; using saved blobs)",
                           "<script>" + "\n".join(blobs) + "</script>",
                           {"clickgrab_path": os.path.abspath(path)})
                else:
                    yield ("clickgrab_json_empty", url, "",
                           {"clickgrab_path": os.path.abspath(path),
                            "warning": "no RawHTML, no saved blobs"})


# ============================================================================
# Pure analyzer
# ============================================================================
def _short_hash(s: str) -> str:
    return hashlib.sha256(s.encode("utf-8", "replace")).hexdigest()[:12]


def _group_verdict(classifications: list[dict]) -> str:
    schemes = {c["scheme"] for c in classifications}
    if {"clipboard_payload", "aes_kit", "powershell_command", "bw_v2_launcher"} & schemes: return "payload"
    if {"etherhiding", "tds_beacon"} & schemes: return "next_stage_loader"
    return "decoded" if classifications else "no_decode"


def analyze_html(label: str, html: str, source_meta: dict, *, max_depth: int = 8,
                 outdir: str | None = None, resolve_chain: bool = False,
                 rpc_override: str | None = None, rpc_timeout: int = DEFAULT_RPC_TIMEOUT,
                 ) -> dict:
    report: dict[str, Any] = {
        "schema_version": SCHEMA_VERSION, "tool": TOOL_VERSION,
        "input": {"label": label, "source": source_meta},
        "page": {}, "groups": [], "summary": {}, "errors": [],
    }
    if not html:
        report["errors"].append("empty html")
        report["summary"] = {"verdict": "no_input", "obfuscated_blocks": 0,
                             "distinct_groups": 0, "schemes_seen": []}
        return report

    injected_srcs = [_defang(m.group(1)) for m in _RE_SCRIPTSRC.finditer(html)]
    scripts = _RE_SCRIPT.findall(html)
    obf = [s for s in scripts if is_obfuscated(s)]
    page_ns = scrape_namespace("\n".join(scripts))
    # Compute byte offsets + 1-indexed line numbers for each inline <script>
    # so analysts can find them in browser DevTools.
    script_positions = []
    for m in _RE_SCRIPT_POS.finditer(html):
        char_off = m.start()
        line     = html.count("\n", 0, char_off) + 1
        # tag if the script body it opens is obfuscated
        body_start = m.end()
        body_end   = html.find("</script>", body_start)
        body = html[body_start:body_end] if body_end > 0 else ""
        script_positions.append({
            "char_offset": char_off, "line": line,
            "is_obfuscated": is_obfuscated(body),
            "body_size": len(body),
            "body_head":  body.strip()[:80].replace("\n", " "),
        })
    report["page"] = {
        "injected_script_srcs":      injected_srcs,
        "inline_script_blocks":      len(scripts),
        "obfuscated_loader_blocks":  len(obf),
        "inline_script_positions":   script_positions,
    }
    decoded_groups: dict[str, dict] = {}
    for idx, code in enumerate(obf):
        final, methods = decode_chain(_html.unescape(code), page_ns, max_depth)
        key = _short_hash(final)
        if key not in decoded_groups:
            decoded_groups[key] = {
                "group_hash": key, "block_indexes": [], "decode_layers": methods,
                "classifications": classify(final), "iocs": extract_loose_iocs(final),
                "recovered_js": final, "recovered_js_path": None,
            }
        decoded_groups[key]["block_indexes"].append(idx)

    # Also run classifiers across ALL inline-script text (not just obfuscated
    # blocks). Catches plaintext clipboard launchers, plaintext PowerShell, and
    # TDS beacons that sit inside non-obfuscated <script> bodies — important
    # for ErrTraffic v3 (BW v2 generation) which dropped the clipboard-AES
    # wrap and ships a plaintext Invoke-WebRequest launcher.
    plain_text = "\n".join(scripts)
    if plain_text.strip():
        plain_cls = classify(_html.unescape(plain_text))
        # Only emit a synthetic "plaintext_scripts" group when classifiers
        # actually found something (so we don't litter the report on every page).
        if plain_cls:
            # De-dupe against schemes already produced from obfuscated decode
            existing_schemes = {c["scheme"] for g in decoded_groups.values()
                                            for c in g["classifications"]}
            novel = [c for c in plain_cls if c["scheme"] not in existing_schemes]
            if novel:
                key = _short_hash("plaintext::" + plain_text[:2000])
                decoded_groups[key] = {
                    "group_hash":      key,
                    "block_indexes":   [],          # synthetic group, no specific block
                    "decode_layers":   [{"scheme": "plaintext_scripts",
                                          "info": f"classified {len(scripts)} inline <script> body(ies) "
                                                  f"as plaintext (no obfuscation detected)"}],
                    "classifications": novel,
                    "iocs":            extract_loose_iocs(plain_text),
                    "recovered_js":    plain_text,
                    "recovered_js_path": None,
                }

    if outdir:
        os.makedirs(outdir, exist_ok=True)
        safe = re.sub(r'[^A-Za-z0-9._-]', '_', label)[:60]
        for key, g in decoded_groups.items():
            if g["decode_layers"] and g["decode_layers"][0]["scheme"] != "[stop]":
                fn = os.path.join(outdir, f"{safe}.group_{key}.recovered.js")
                with open(fn, "w", encoding="utf-8") as fh: fh.write(g["recovered_js"])
                g["recovered_js_path"] = fn

    if resolve_chain:
        for g in decoded_groups.values():
            for cls in g["classifications"]:
                if cls["scheme"] == "etherhiding":
                    cls["resolved"] = resolve_etherhiding(cls, override_rpc=rpc_override,
                                                         timeout=rpc_timeout)
                    # HEURISTIC ACTOR ATTRIBUTION
                    # If the contract wasn't in KNOWN_ACTORS at classify-time,
                    # the resolved URL may give us enough signal to attribute
                    # it now (BW v2 pattern = getDomain + burner-TLD result).
                    # Conservative: only fires when no attribution exists yet.
                    if not cls.get("actor_attribution"):
                        r = cls["resolved"]
                        if r.get("ok") and r.get("decoded_url"):
                            synth = synthesize_actor_attribution(
                                (cls.get("contract_addresses") or [None])[0],
                                cls.get("method_selector"),
                                r.get("decoded_url"))
                            if synth:
                                cls["actor_attribution"] = {
                                    "contract_matched": (cls.get("contract_addresses") or [None])[0],
                                    **synth,
                                }

    # Loader-intel sweep — recover per-panel API_Q2_KEY_HEX + on-chain
    # panel-router contract + function selector from each decoded JS group.
    # When a group is a BW v2 loader, register the (panel_host?, contract,
    # key) triple in the global registry so downstream payload + envelope
    # operations on the same panel/contract automatically use the right key.
    # We bind the key by contract (always available in the loader) AND by
    # panel_host (when an etherhiding classification resolved one).
    intel_collected: list[dict] = []
    for g in decoded_groups.values():
        js_text = g.get("recovered_js") or ""
        intel = extract_loader_intel(js_text)
        if not intel:
            continue
        # Try to pair the contract with a panel host: prefer an already-
        # resolved on-chain URL in the same group's classifications.
        panel_host = None
        for c in g["classifications"]:
            if c.get("scheme") == "etherhiding":
                r = c.get("resolved") or {}
                if r.get("ok") and r.get("decoded_url"):
                    from urllib.parse import urlparse
                    panel_host = urlparse(r["decoded_url"]).hostname
                    if panel_host: break
        register_bw_v2_key(panel_host=panel_host,
                            contract_address=intel.get("contract_address"),
                            api_q2_key_hex=intel["api_q2_key_hex"],
                            source="analyze_html_loader_extract")
        g["loader_intel"] = {**intel, "panel_host": panel_host,
                              "registered": True}
        intel_collected.append(g["loader_intel"])
    if intel_collected:
        report.setdefault("summary", {})["bw_v2_loader_intel"] = intel_collected
    for g in decoded_groups.values():
        g["verdict"] = _group_verdict(g["classifications"])
        # PRIOR: g.pop("recovered_js") removed the text from the report so
        # downstream AES recovery couldn't access it without re-reading from
        # disk (which only existed when --out was set). KEEP the text on the
        # group so AES recovery, classifiers, and any future in-memory
        # consumers can use it. Size still recorded for renderer/CSV.
        g["recovered_js_size"] = len(g.get("recovered_js") or "")
    report["groups"] = list(decoded_groups.values())

    schemes_seen = sorted({c["scheme"] for g in decoded_groups.values()
                                       for c in g["classifications"]})
    attrs, attr_seen, resolved_urls, resolved_seen = [], set(), [], set()
    for g in decoded_groups.values():
        for c in g["classifications"]:
            if c["scheme"] == "etherhiding" and c.get("actor_attribution"):
                a = c["actor_attribution"]
                key = (a["name"], a["confidence"])
                if key not in attr_seen:
                    attr_seen.add(key)
                    attrs.append({"name": a["name"], "confidence": a["confidence"],
                                  "sources": a["sources"]})
            r = c.get("resolved") or {}
            if r.get("ok") and r.get("decoded_url") and r["decoded_url"] not in resolved_seen:
                resolved_seen.add(r["decoded_url"]); resolved_urls.append(r["decoded_url"])

    if {"clipboard_payload", "aes_kit", "powershell_command", "bw_v2_launcher"} & set(schemes_seen):
        verdict = "clipboard_or_powershell_payload"
    elif "etherhiding" in schemes_seen: verdict = "etherhiding_loader"
    elif "tds_beacon" in schemes_seen:  verdict = "tds_beacon_only"
    elif schemes_seen:                  verdict = "scaffolding_only"
    else:                               verdict = "nothing_recovered"

    summary_block = {
        "obfuscated_blocks":         len(obf),
        "distinct_groups":           len(decoded_groups),
        "schemes_seen":              schemes_seen,
        "verdict":                   verdict,
        "actors_attributed":         attrs,
        "resolved_next_stage_urls":  [_defang(u) for u in resolved_urls],
    }
    # Loader-stage ClickFix classification (S32). Light-batch / loader-only
    # inputs get a SHALLOW classification here built from just the analyze_html
    # output. Comprehensive mode REPLACES this with a deep classification that
    # also sees envelope_recovery / panel_payloads / wp_backdoor_probe /
    # input_role / actor_attribution.  See `classify_clickfix()` below.
    summary_block["clickfix_classification"] = classify_clickfix({
        "summary":  summary_block,
        "lure_page": {"groups": list(decoded_groups.values())},
    })
    # Preserve BW v2 loader-intel surfaced by the intel sweep above. This
    # carries (api_q2_key_hex, contract_address, function_selector, panel_host)
    # per recovered loader and is the operator's per-panel envelope secret.
    if intel_collected:
        summary_block["bw_v2_loader_intel"] = intel_collected
    report["summary"] = summary_block
    return report


# ============================================================================
# ClickFix classification (S32) — score-driven verdict for every scan
# ============================================================================
# Why this exists: every prior verdict the script emitted was either a
# loader-stage label (`etherhiding_loader`, `scaffolding_only`) or a
# `classifications` list of schemes. Those are useful but they don't answer the
# question an analyst actually asks first: *is this IOC part of the ClickFix
# operation, and how confident are we?* — and *is it a panel or a lure?*
#
# S31 RCA showed why answering that question naïvely (e.g. "single classifier
# fired = positive") produces ~470 false positives on a 12k sweep. The fix is
# to score every signal we capture with calibrated weights and then map the
# score to a 5-class taxonomy + a 6-band semantic confidence label.
#
# The five output classes are intentionally narrow:
#   - `clickfix_confirmed`  — chain-grade evidence (≥1 STRONG signal)
#   - `clickfix_likely`     — kit-pattern signals but no chain-grade attribution
#   - `clickfix_suspicious` — only weak signals; human review needed
#   - `benign`              — reached the host, no ClickFix-related signals
#   - `unreachable`         — could not assess (fetch errors, no signals)
#
# Sub-attribute `role` (separate from class): `panel | lure | unknown_role`.
#
# Score bands: 0 → none, 1-9 → very_low, 10-34 → low, 35-59 → medium,
#              60-84 → high, 85-100 → certain.
#
# Signal weights are documented inline in `_CF_SIGNAL_WEIGHTS` below; their
# calibration came from inspecting the per-class signal-fingerprint distribution
# in the 05-28-26_21-33 sweep across hand-labelled TP/FP/noise records.

# Strong signals: ANY one of these alone is enough to push to `clickfix_confirmed`
_CF_STRONG_SIGNALS = {
    "actor_attribution":      60,  # KNOWN_ACTORS hit (hand-curated KB)
    "binary_recovered":       60,  # we actually downloaded a Stage-2 binary
    "envelope_decrypted":     50,  # gcm1/q2 kit-config plaintext recovered
    "aes_clipboard_recovered": 50,  # AES PowerShell decoded from loader
    "known_panel_inventory":  50,  # IOC host is in our manually-curated panel KB
                                    # (PANELS_COMPREHENSIVE.json HIGH-confidence set).
                                    # Catches the case where a known panel mis-routes
                                    # as "lure" because /api/init returned 404 today
                                    # and the lure-mode pipeline can't find loader JS
                                    # on the panel's HTML.
}


