_PANELS_KB_CACHE: dict | None = None
_PANELS_KB_OVERRIDE: str | None = None   # set by main() from --panels-kb
_PANELS_KB_LOADED_FROM: str | None = None  # provenance for the startup banner


def _coerce_panels_kb(path: str) -> dict[str, dict] | None:
    """Load a panel KB from EITHER a PANELS_COMPREHENSIVE.json (the canonical
    `{"panels": {host: {...}}}` shape) OR a plain text host list (panels.txt —
    one host per line, '#' comments allowed). Returns {host: entry} or None.

    The plain-text path exists so the file you already keep on the FlareVM
    (panels.txt) works as the KB with zero extra setup — every host in it is
    treated as a HIGH-confidence panel."""
    try:
        with open(path, encoding="utf-8") as f:
            blob = f.read()
    except Exception:
        return None
    stripped = blob.lstrip()
    if stripped[:1] in ("{", "["):
        try:
            data = json.loads(blob)
        except Exception:
            return None
        panels = data.get("panels") if isinstance(data, dict) else None
        return panels if isinstance(panels, dict) and panels else None
    # plain host list
    kb: dict[str, dict] = {}
    for line in blob.splitlines():
        h = line.strip()
        if not h or h.startswith("#"):
            continue
        h = h.split()[0].split("#")[0].strip().lower().rstrip(".")
        h = re.sub(r"^[a-z]+://", "", h).split("/")[0].split(":")[0]
        if h:
            kb[h] = {"sources": ["panels_txt"], "admin_wallet": None,
                     "contract": None, "tld": None, "confidence_tier": "HIGH"}
    return kb or None


def _load_panels_kb() -> dict[str, dict]:
    """Return {host: {sources, admin_wallet, contract, tld, confidence_tier}}.

    STANDALONE: the base is the baked-in KNOWN_PANELS set (always present, no
    external file needed). An OPTIONAL external KB is then merged ON TOP to add
    newer panels / richer per-panel metadata, found in this order (first hit):
      1. --panels-kb PATH override (canonical PANELS_COMPREHENSIVE.json OR plain panels.txt)
      2. analysis/PANELS_COMPREHENSIVE.json (next to script parent / script / cwd)
      3. PANELS_COMPREHENSIVE.json or panels.txt next to the script or in the run dir
    Cached after first call. Never empty (baked-in floor)."""
    global _PANELS_KB_CACHE, _PANELS_KB_LOADED_FROM
    if _PANELS_KB_CACHE is not None: return _PANELS_KB_CACHE
    # BASE — baked-in known panels (standalone floor)
    kb: dict[str, dict] = {h: {"sources": ["baked_in"], "admin_wallet": None,
                               "contract": None, "tld": None,
                               "confidence_tier": "HIGH"} for h in KNOWN_PANELS}
    here = os.path.dirname(os.path.abspath(__file__))
    candidates = []
    if _PANELS_KB_OVERRIDE:
        candidates.append(_PANELS_KB_OVERRIDE)
    candidates += [
        os.path.join(here, "..", "analysis", "PANELS_COMPREHENSIVE.json"),
        os.path.join(here, "analysis", "PANELS_COMPREHENSIVE.json"),
        os.path.join(os.getcwd(), "analysis", "PANELS_COMPREHENSIVE.json"),
        os.path.join(here, "PANELS_COMPREHENSIVE.json"),
        os.path.join(os.getcwd(), "PANELS_COMPREHENSIVE.json"),
        os.path.join(here, "panels.txt"),
        os.path.join(os.getcwd(), "panels.txt"),
    ]
    merged_from = None
    for p in candidates:
        if not os.path.exists(p): continue
        ext = _coerce_panels_kb(p)
        if not ext: continue
        for host, entry in ext.items():
            h = (host or "").lower().strip().rstrip(".")
            if not h: continue
            base = kb.get(h)
            if base is None:
                kb[h] = entry                      # net-new panel from external file
            else:
                # enrich baked-in entry with external (non-empty) metadata
                for k, v in entry.items():
                    if v not in (None, "", [], {}):
                        base[k] = v
                base["sources"] = sorted(set(base.get("sources") or [])
                                         | set(entry.get("sources") or []))
        merged_from = os.path.normpath(p)
        break
    _PANELS_KB_CACHE = kb
    _PANELS_KB_LOADED_FROM = (f"baked-in ({len(KNOWN_PANELS)}) + {merged_from}"
                             if merged_from else f"baked-in ({len(KNOWN_PANELS)} panels)")
    # Soft note ONLY if the user explicitly asked for an external KB we couldn't read.
    if _PANELS_KB_OVERRIDE and merged_from is None:
        try:
            sys.stderr.write(f"[clickchain] note: --panels-kb '{_PANELS_KB_OVERRIDE}' "
                             f"not found/empty; using baked-in panel set "
                             f"({len(KNOWN_PANELS)} panels).\n")
        except Exception:
            pass
    return _PANELS_KB_CACHE


def _is_known_panel(host: str | None) -> dict | None:
    """Return the inventory entry if `host` is in our HIGH-confidence panel KB,
    else None."""
    if not host: return None
    kb = _load_panels_kb()
    entry = kb.get(host.lower())
    if entry and (entry.get("confidence_tier") or "").upper() == "HIGH":
        return entry
    return None


# ── Panel attribution (kit / variant / operator) ──────────────────────────────
# The S39 panel-mode label was redundant ("Known-panel KB entry for <host>" just
# echoes the host). Defenders want the OLD style: WHICH kit/variant/operator/
# contract this panel belongs to. We derive it from KNOWN_ACTORS (the on-chain
# panel-router contracts carry `kit` + `admin_actor` + admin_wallet) joined to
# the panel KB. Built once, cached.
_PANEL_ATTR_INDEX: dict | None = None
_PANEL_ATTR_LOCK = threading.Lock()

def _build_panel_attr_index() -> dict:
    """{host: {kit, operator, operator_wallet, contract}} from KNOWN_ACTORS, plus
    {wallet: operator_name} so KB-only panels (which carry an admin_wallet but no
    contract name) still attribute to a named operator."""
    by_host: dict[str, dict] = {}
    by_wallet: dict[str, str] = {}
    wallet_votes: dict[str, dict] = {}
    for addr, v in KNOWN_ACTORS.items():
        if v.get("kind") != "c2_contract":
            # still let controller/deployer wallets seed the wallet→operator map
            if v.get("admin_actor") and addr.startswith("0x"):
                wallet_votes.setdefault(addr.lower(), {}).setdefault(v["admin_actor"], 0)
                wallet_votes[addr.lower()][v["admin_actor"]] += 1
            continue
        nm = v.get("name") or ""
        m = re.search(r"\bfor\s+([a-z0-9.\-]+\.[a-z]{2,})\b", nm)
        host = (m.group(1).lower() if m else None)
        aw = (v.get("admin_wallet") or "").lower() or None
        op = v.get("admin_actor")
        if aw and op:
            wallet_votes.setdefault(aw, {}).setdefault(op, 0)
            wallet_votes[aw][op] += 1
        if host:
            # first contract for a host wins; later ones don't clobber a richer one
            cur = by_host.get(host)
            cand = {"kit": v.get("kit"), "operator": op,
                    "operator_wallet": aw, "contract": addr.lower(),
                    "confidence": v.get("confidence") or "high"}
            if cur is None or (not cur.get("operator") and op):
                by_host[host] = cand
    for w, votes in wallet_votes.items():
        by_wallet[w] = max(votes, key=votes.get)
    return {"by_host": by_host, "by_wallet": by_wallet}


def _clean_operator_name(name: str | None) -> str | None:
    """Normalize an admin_actor label for clean fleet rollups. The KNOWN_ACTORS
    admin_actor strings carry editorial notes ("(12 panels — kit-as-a-service
    scaling)", "— runs this panel directly", "NEW S27 …") that fragment the
    [operators] count into one-off buckets. Strip the editorial tail/parens so
    "BW v2 customer-operator A (12 panels …)" and "BW v2 customer-operator A"
    roll up together."""
    if not name:
        return name
    # Order matters: strip noisy (balanced) parentheticals FIRST, then the
    # em/en-dash editorial tail — otherwise the dash-split would break an
    # unclosed "(12 panels — …)" before the paren-strip could match it.
    name = re.sub(r"\s*\((?:[^)]*\b(?:panels?|NEW|S\d+|variants?|scaling)\b[^)]*)\)",
                  "", name)                                  # drop noisy parentheticals
    name = re.split(r"\s+[—–-]{1,2}\s+", name)[0]          # drop em/en-dash editorial tail
    return name.strip()


def _panel_attribution(host: str | None) -> dict | None:
    """Return concise, evidence-backed attribution for a panel host:
      {label, kit, operator, operator_wallet, contract, confidence, sources}
    `label` is a single defensible line that names the kit/variant/operator/
    contract WITHOUT re-echoing the host. None if the host is unknown."""
    global _PANEL_ATTR_INDEX
    if not host:
        return None
    hl = host.lower()
    with _PANEL_ATTR_LOCK:
        if _PANEL_ATTR_INDEX is None:
            _PANEL_ATTR_INDEX = _build_panel_attr_index()
        idx = _PANEL_ATTR_INDEX
    kb = _is_known_panel(hl)
    chain = idx["by_host"].get(hl)
    if not kb and not chain:
        return None
    kit = (chain or {}).get("kit") or "ErrTraffic v3 (LenAI ecosystem)"
    contract = (chain or {}).get("contract") or (kb or {}).get("contract") or None
    operator = (chain or {}).get("operator")
    op_wallet = (chain or {}).get("operator_wallet") or (kb or {}).get("admin_wallet")
    if not operator and op_wallet:
        operator = idx["by_wallet"].get(op_wallet.lower())
    operator = _clean_operator_name(operator)
    sources = sorted(set((kb or {}).get("sources") or []) |
                     ({"KNOWN_ACTORS on-chain panel-router"} if chain else set()))
    # Build the label: kit · operator · contract — each part only if known.
    parts = [kit + " panel"]
    if operator:
        w = f" ({op_wallet[:10]}…)" if op_wallet else ""
        parts.append(f"operator: {operator}{w}")
    elif op_wallet:
        parts.append(f"admin wallet {op_wallet[:10]}…")
    else:
        parts.append("operator not yet chain-mapped")
    if contract:
        parts.append(f"contract {contract[:10]}…")
    label = " · ".join(parts)
    return {"label": label, "kit": kit, "operator": operator,
            "operator_wallet": op_wallet, "contract": contract,
            "confidence": (chain or {}).get("confidence") or "high",
            "sources": sources}

# Medium signals: ≥1 of these + reach context can lift to `clickfix_likely`
_CF_MEDIUM_SIGNALS = {
    "cls_bw_v2_launcher":     35,  # BW v2 marker patterns present
    "input_role_panel_high":  35,  # init-endpoint shape probe HIGH confidence
    "cls_aes_kit":            30,  # Rijndael + base64 blob pattern in JS
    "cls_etherhiding_noactor":25,  # etherhiding pattern but contract NOT in KB
    "cls_clipboard_payload":  20,  # navigator.clipboard.writeText present
    "wp_backdoor_hit":        20,  # mu-plugins backdoor present (any of 4 paths)
    "input_role_panel_med":   20,  # init-endpoint probe MED confidence
    "token_captured":         15,  # /api/init returned a token (no binary yet)
}

# Weak signals: corroborating only; alone they shouldn't classify
_CF_WEAK_SIGNALS = {
    "cls_powershell_command": 12,  # strict-discriminator PS command (v5.6)
    "external_obfuscated_script": 10,  # obfuscated 3rd-party JS detected
    "cls_tds_beacon":          8,  # suspect analytics/tracking endpoint
    "cls_antianalysis_gate":   5,  # debugger; / performance.now() check
}

_CF_ALL_SIGNALS = {**_CF_STRONG_SIGNALS, **_CF_MEDIUM_SIGNALS, **_CF_WEAK_SIGNALS}

# Score → semantic band
def _cf_band(score: int) -> str:
    if score >= 85: return "certain"
    if score >= 60: return "high"
    if score >= 35: return "medium"
    if score >= 10: return "low"
    if score >= 1:  return "very_low"
    return "none"

# (score, has_strong_signal, reached) → class
def _cf_class(score: int, has_strong: bool, reached: bool) -> str:
    if has_strong or score >= 60: return "clickfix_confirmed"
    if score >= 30:               return "clickfix_likely"
    if score >= 5:                return "clickfix_suspicious"
    if reached:                   return "benign"
    return "unreachable"


def _cf_role(report: dict, ioc_host: str | None) -> str:
    """Decide whether the SCANNED IOC is the panel or a lure (or unknown).

    Decision policy (first match wins):
    1) If `panel_payloads` captured a binary AND the panel_origin host == IOC host
       → IOC is the PANEL.
    2) If `envelope_recovery.host` == IOC host AND any response decrypted
       → IOC is the PANEL.
    3) If `input_role.role == "panel"` (init-endpoint shape probe) and confidence
       ≥ 0.65 → IOC is the PANEL.
    4) If `panel_payloads` captured a binary/token from a DIFFERENT panel_origin
       host AND the IOC has loader signals (etherhiding / clipboard_payload /
       wp_backdoor_hit) → IOC is a LURE.
    5) If loader-side classifications present AND IOC is a CMS (is_wp, behind_cf)
       → IOC is a LURE.
    6) Otherwise → unknown_role.
    """
    pp = report.get("panel_payloads") or {}
    per_os = pp.get("per_os") or {}
    er = report.get("envelope_recovery")

    # (1) panel_origin host == IOC host AND binary recovered
    for slot in per_os.values():
        if not isinstance(slot, dict): continue
        origin = slot.get("panel_origin", "")
        try:
            from urllib.parse import urlparse as _up
            origin_host = _up(origin).hostname or origin
        except Exception:
            origin_host = origin
        if origin_host and ioc_host and origin_host.lower() == ioc_host.lower():
            if slot.get("sha256") or slot.get("token"):
                return "panel"
    # (2) envelope_recovery host == IOC host
    if isinstance(er, dict) and er.get("host") and ioc_host:
        if er["host"].lower() == ioc_host.lower():
            if any((x or {}).get("decrypted") for x in (er.get("responses") or [])):
                return "panel"
    # (2b) IOC host is a chain-verified panel in our curated KB. A known panel
    # whose /api/init 404s today (rotated src-gating, temporarily down, or
    # behind a fresh CF challenge) would otherwise fall through to "lure" /
    # "unknown_role" — but its identity as a PANEL was established by prior
    # chain/admin attribution and does not depend on today's reachability.
    # This was the dominant cause of 58 of 111 known panels mis-roled as
    # unknown_role in the 5-29 sweep (compounded by the KB file not being on
    # the FlareVM). PANELS_COMPREHENSIVE HIGH-confidence is evidence-grade.
    if _is_known_panel(ioc_host):
        return "panel"
    # (3) input_role probe says panel
    ir = report.get("input_role") or {}
    if ir.get("role") == "panel" and (ir.get("confidence") or 0) >= 0.65:
        return "panel"
    # (4) lure: actor attribution OR loader-side signals + different panel_origin
    summ = report.get("summary") or {}
    schemes = set(summ.get("classifications") or summ.get("schemes_seen") or [])
    has_loader = bool(schemes & {"etherhiding", "clipboard_payload", "aes_kit", "bw_v2_launcher"})
    has_actor = bool(summ.get("actors_attributed"))
    if has_loader or has_actor:
        return "lure"
    # (5) WP + obfuscated script + backdoor → still a lure even without actor
    wp = report.get("wordpress") or {}
    wpb = (report.get("wp_backdoor_probe") or {}).get("hits")
    if wp.get("is_wp") and wpb:
        return "lure"
    return "unknown_role"


def _ioc_host(report: dict) -> str | None:
    """Best-effort extract of the scanned IOC's hostname."""
    summ = report.get("summary") or {}
    candidates = [summ.get("lure_url"), summ.get("panel_url"),
                  (report.get("input") or {}).get("label"),
                  (report.get("ioc") or {}).get("input")]
    for c in candidates:
        if not c: continue
        try:
            from urllib.parse import urlparse as _up
            host = _up(c).hostname or c
            if host: return host
        except Exception:
            pass
    return None


def classify_clickfix(report: dict) -> dict:
    """Score every signal in `report`, derive class + role + band + reasoning.

    `report` may be a partial dict (loader-stage only — `summary` + `lure_page`)
    or a full comprehensive report. Designed to be re-runnable: comprehensive
    mode calls it once at the end of `investigate_ioc_comprehensive` to REPLACE
    the loader-stage shallow result with a deep one that sees panel_payloads,
    envelope_recovery, panel_server_fingerprint, etc.

    Returns:
      {
        "class":     one of [clickfix_confirmed, clickfix_likely,
                              clickfix_suspicious, benign, unreachable],
        "role":      one of [panel, lure, unknown_role],
        "score":     int 0..100,
        "band":      one of [none, very_low, low, medium, high, certain],
        "signals":   [{name, weight, source}],  # ordered by descending weight
        "reasoning": one-line plain-English summary,
        "schema":    "v1",
      }
    """
    signals: list[dict] = []
    summ = report.get("summary") or {}

    # STRONG signals
    if summ.get("actors_attributed"):
        names = [a.get("name", "?") for a in (summ["actors_attributed"] or [])][:3]
        signals.append({"name": "actor_attribution",
                        "weight": _CF_STRONG_SIGNALS["actor_attribution"],
                        "source": f"KNOWN_ACTORS: {', '.join(names)}"})

    # known_panel_inventory — IOC host is in our hand-curated panel KB
    # (PANELS_COMPREHENSIVE.json HIGH-confidence set). Covers the case where
    # a known panel today returns 404 on /api/init (so the role probe says
    # "lure"), and lure-mode then finds no loader JS on the panel — without
    # this signal the scorer would mistakenly score the panel as benign.
    ioc_host_for_kb = _ioc_host(report)
    kb_entry = _is_known_panel(ioc_host_for_kb)
    if kb_entry:
        sources = ", ".join(kb_entry.get("sources") or [])[:60]
        signals.append({"name": "known_panel_inventory",
                        "weight": _CF_STRONG_SIGNALS["known_panel_inventory"],
                        "source": f"PANELS_COMPREHENSIVE: {sources}"})

    pp = report.get("panel_payloads") or {}
    per_os = pp.get("per_os") or {}
    recovered_hashes = [v.get("sha256") for v in per_os.values()
                        if isinstance(v, dict) and v.get("sha256")]
    if recovered_hashes:
        signals.append({"name": "binary_recovered",
                        "weight": _CF_STRONG_SIGNALS["binary_recovered"],
                        "source": f"{len(recovered_hashes)} sha256(s): "
                                  f"{', '.join(h[:12] for h in recovered_hashes[:3])}"})

    er = report.get("envelope_recovery")
    if isinstance(er, dict):
        decrypted = [r for r in (er.get("responses") or []) if r.get("decrypted")]
        if decrypted:
            signals.append({"name": "envelope_decrypted",
                            "weight": _CF_STRONG_SIGNALS["envelope_decrypted"],
                            "source": f"{len(decrypted)} env(s) on {er.get('host','?')}"})

    acr = report.get("aes_clipboard_recovery")
    aes_ok = False
    if isinstance(acr, list) and any(x.get("ok") for x in acr if isinstance(x, dict)):
        aes_ok = True
    elif isinstance(acr, dict) and acr.get("ok"):
        aes_ok = True
    if aes_ok:
        signals.append({"name": "aes_clipboard_recovered",
                        "weight": _CF_STRONG_SIGNALS["aes_clipboard_recovered"],
                        "source": "loader-side AES PowerShell decoded"})
    elif not aes_ok:
        # S35: panel-side clipboard COMMAND recovered + decoded from the init
        # token (new XOR-PS generation) or a served script. Same chain-grade
        # class as aes_clipboard_recovered — we statically decoded the literal
        # clipboard command and identified the kit scheme.
        clip_schemes = sorted({
            (slot.get("clipboard_ps_recovered") or {}).get("scheme")
            for slot in per_os.values()
            if isinstance(slot, dict) and slot.get("clipboard_ps_recovered")
        } - {None})
        if clip_schemes:
            signals.append({"name": "aes_clipboard_recovered",
                            "weight": _CF_STRONG_SIGNALS["aes_clipboard_recovered"],
                            "source": f"panel/served clipboard decoded ({', '.join(clip_schemes)})"})

    # MEDIUM signals — from loader classifications
    schemes_seen = set(summ.get("classifications") or summ.get("schemes_seen") or [])
    for g in (report.get("lure_page") or {}).get("groups", []) or []:
        for c in g.get("classifications", []) or []:
            sch = c.get("scheme")
            if sch: schemes_seen.add(sch)

    # cls_etherhiding gets either MED (with KNOWN_ACTORS) credit (already covered by
    # actor_attribution above) OR MED (without) credit. We don't double-count.
    if "etherhiding" in schemes_seen and not summ.get("actors_attributed"):
        signals.append({"name": "cls_etherhiding_noactor",
                        "weight": _CF_MEDIUM_SIGNALS["cls_etherhiding_noactor"],
                        "source": "EtherHiding loader pattern, unknown contract"})
    if "bw_v2_launcher" in schemes_seen:
        signals.append({"name": "cls_bw_v2_launcher",
                        "weight": _CF_MEDIUM_SIGNALS["cls_bw_v2_launcher"],
                        "source": "BW v2 marker patterns in loader"})
    if "aes_kit" in schemes_seen:
        signals.append({"name": "cls_aes_kit",
                        "weight": _CF_MEDIUM_SIGNALS["cls_aes_kit"],
                        "source": "Rijndael/AES-CBC kit pattern in inline JS"})
    if "clipboard_payload" in schemes_seen:
        signals.append({"name": "cls_clipboard_payload",
                        "weight": _CF_MEDIUM_SIGNALS["cls_clipboard_payload"],
                        "source": "navigator.clipboard.writeText present"})

    wpb_hits = (report.get("wp_backdoor_probe") or {}).get("hits") or []
    if wpb_hits:
        names = [h.get("path", "?") for h in wpb_hits[:3]]
        signals.append({"name": "wp_backdoor_hit",
                        "weight": _CF_MEDIUM_SIGNALS["wp_backdoor_hit"],
                        "source": f"mu-plugins backdoor: {', '.join(names)}"})

    ir = report.get("input_role") or {}
    if ir.get("role") == "panel":
        conf = ir.get("confidence") or 0
        if conf >= 0.90:
            signals.append({"name": "input_role_panel_high",
                            "weight": _CF_MEDIUM_SIGNALS["input_role_panel_high"],
                            "source": f"init-endpoint shape probe HIGH (conf={conf})"})
        elif conf >= 0.65:
            signals.append({"name": "input_role_panel_med",
                            "weight": _CF_MEDIUM_SIGNALS["input_role_panel_med"],
                            "source": f"init-endpoint shape probe MED (conf={conf})"})

    # token_captured: a token was minted from /api/init but no binary follow-up
    if any(isinstance(v, dict) and v.get("token") for v in per_os.values()) and not recovered_hashes:
        signals.append({"name": "token_captured",
                        "weight": _CF_MEDIUM_SIGNALS["token_captured"],
                        "source": "/api/init returned token; binary fetch blocked"})

    # WEAK signals
    if "powershell_command" in schemes_seen:
        signals.append({"name": "cls_powershell_command",
                        "weight": _CF_WEAK_SIGNALS["cls_powershell_command"],
                        "source": "strict-discriminator PS command in JS (v5.6)"})
    if (report.get("external_scripts_classified") or {}).get("obfuscated_confirmed"):
        signals.append({"name": "external_obfuscated_script",
                        "weight": _CF_WEAK_SIGNALS["external_obfuscated_script"],
                        "source": "obfuscated 3rd-party <script src> on page"})
    if "tds_beacon" in schemes_seen:
        signals.append({"name": "cls_tds_beacon",
                        "weight": _CF_WEAK_SIGNALS["cls_tds_beacon"],
                        "source": "suspect analytics/TDS beacon endpoint"})
    if "antianalysis_gate" in schemes_seen:
        signals.append({"name": "cls_antianalysis_gate",
                        "weight": _CF_WEAK_SIGNALS["cls_antianalysis_gate"],
                        "source": "debugger; / performance.now() anti-analysis"})

    # Compute score + flags
    score = sum(s["weight"] for s in signals)
    score = max(0, min(100, score))
    has_strong = any(s["name"] in _CF_STRONG_SIGNALS for s in signals)
    # Reach detection — "reached" means we successfully READ the main page
    # AND ran detectors against it. A bare HTTP status on an init-shape probe
    # (e.g. 404 on /api/index.php?a=init when the main fetch's SSL handshake
    # timed out) is NOT enough — we couldn't actually inspect the IOC, so we
    # don't have evidence either way. Such records should classify as
    # `unreachable`, not `benign`.
    lp = report.get("lure_page") or {}
    lp_summary = (lp or {}).get("summary") or {}
    src_status = ((report.get("input") or {}).get("source") or {}).get("status")
    # An lp_summary.verdict like "nothing_recovered" means analyze_html ran —
    # i.e., we got the page body. Any of those verdicts counts as reached.
    main_page_read = lp_summary.get("verdict") not in (None, "no_input")
    reached = bool(
        main_page_read
        or lp.get("groups")
        or schemes_seen
        # WP/CF detectors only run when we got the body, so non-None values
        # are positive reach evidence.
        or (report.get("wordpress") or {}).get("is_wp")
        or (report.get("cloudflare") or {}).get("behind_cf")
        # Panel-mode evidence: token/sha256 on at least one OS slot means we
        # actually completed a /api request chain on this IOC host.
        or any(isinstance(v, dict) and (v.get("token") or v.get("sha256"))
               for v in per_os.values())
        # Single-IOC mode: a 2xx/3xx fetch_status counts as reached.
        or (src_status and isinstance(src_status, int) and 200 <= src_status < 400)
    )

    cls = _cf_class(score, has_strong, reached)
    band = _cf_band(score)
    role = _cf_role(report, _ioc_host(report))

    # Reasoning — one-line plain English
    if signals:
        top3 = ", ".join(f'{s["name"]}(+{s["weight"]})' for s in
                         sorted(signals, key=lambda x: -x["weight"])[:3])
        reasoning = f"Top signals: {top3}."
    elif not reached:
        reasoning = "No signals captured; host unreachable or fetch failed."
    else:
        reasoning = "Reached host, no ClickFix-related signals detected."

    # Order signals descending by weight for stable rendering
    signals_sorted = sorted(signals, key=lambda s: (-s["weight"], s["name"]))

    return {
        "schema":    "v1",
        "class":     cls,
        "role":      role,
        "score":     score,
        "band":      band,
        "signals":   signals_sorted,
        "reasoning": reasoning,
    }


# ============================================================================
# Renderers
# ============================================================================
def render_text(report: dict, fh=sys.stdout, *, quiet: bool = False):
    p = fh.write
    label = report["input"]["label"]

    # ── Fast-path: fetch-error reports get their own concise panel ───────────
    # Instead of dumping an empty decode result, show the analyst:
    #   - what failed (HTTP code / error class)
    #   - what category (http / dns / tls / timeout / connect)
    #   - an actionable hint (e.g. "looks like a panel, try --comprehensive")
    summary = report.get("summary") or {}
    fe = summary.get("fetch_error")
    if summary.get("verdict") == "fetch_error" and fe:
        p("\n" + "=" * 80 + "\n")
        p(f" [fetch failed]  {label}\n")
        p("=" * 80 + "\n")
        msg = fe.get("message") or (report.get("errors") or ["?"])[0]
        cat = fe.get("category") or "other"
        st  = fe.get("status")
        cat_str = f"  [{cat.upper()}{(' '+str(st)) if st else ''}]"
        p(f"  error:    {msg}{cat_str}\n")
        pp = fe.get("panel_probe")
        if pp:
            p(f"  panel-probe:  role={pp.get('role')}  "
              f"confidence={pp.get('confidence')}  "
              f"signals={','.join(pp.get('signals') or [])}\n")
        if fe.get("hint"):
            p("\n  hint:\n")
            # Wrap the hint to 76 cols for readability
            import textwrap
            for line in textwrap.wrap(fe["hint"], width=76,
                                       initial_indent="    ", subsequent_indent="    "):
                p(line + "\n")
        p("\n")
        return

    p("\n" + "=" * 80 + "\n"); p(f" INPUT: {label}\n")
    src = report["input"]["source"]
    src_keys_to_show = ("status", "final_url", "content_type", "bytes_received", "fetched_at")
    src_bits = [f"{k}={v}" for k, v in src.items() if k in src_keys_to_show and v is not None]
    if src_bits: p(f"        ({', '.join(src_bits)})\n")
    p("=" * 80 + "\n")
    if report["errors"]:
        p("  [errors]\n")
        for e in report["errors"]: p(f"    - {e}\n")
    pg = report["page"]
    for s in pg.get("injected_script_srcs", []): p(f"  [injected <script src>] {s}\n")
    p(f"  inline <script> blocks: {pg.get('inline_script_blocks', 0)} | "
      f"obfuscated loader blocks: {pg.get('obfuscated_loader_blocks', 0)}\n")
    summ = report["summary"]
    if summ.get("actors_attributed"):
        p("\n  >>> ATTRIBUTION:\n")
        seen = set()
        for a in summ["actors_attributed"]:
            key = (a["name"], a["confidence"])
            if key in seen: continue
            seen.add(key)
            srcs = ", ".join(a["sources"])
            p(f"        {a['name']}  (confidence: {a['confidence']}; sources: {srcs})\n")
    if not quiet:
        for g in report["groups"]:
            idxs = g["block_indexes"]
            if not idxs:
                # Synthetic group (e.g. plaintext-scripts classifier pass).
                idxs_str = "[plaintext]"
            elif len(idxs) == 1:
                idxs_str = f"#{idxs[0]}"
            else:
                idxs_str = (f"#{idxs[0]} (+{len(idxs)-1} clones: " +
                            ", ".join(f"#{i}" for i in idxs[1:]) + ")")
            tag = {"payload":"[PAYLOAD]", "next_stage_loader":"[NEXT-STAGE LOADER]",
                   "decoded":"[decoded, inert]", "no_decode":"[no-decode]"}.get(
                       g["verdict"], f"[{g['verdict']}]")
            p(f"\n  --- block {idxs_str}  {tag}  hash:{g['group_hash']}  "
              f"layers: {len(g['decode_layers'])}\n")
            for layer in g["decode_layers"]:
                p(f"        {layer['scheme']}: {layer['info']}\n")
            for cls in g["classifications"]: _render_cls_text(cls, p)
            covered = set()
            for cls in g["classifications"]:
                for k in ("rpc_pool_defanged", "hosts_defanged", "commands", "contract_addresses"):
                    v = cls.get(k) or []
                    if isinstance(v, list): covered.update(v)
            for u in [u for u in g["iocs"]["urls"] if u not in covered][:8]:
                p(f"      * url:  {u}\n")
            for ip in g["iocs"]["ips"][:6]: p(f"      * ip:   {ip}\n")
            for cid in g["iocs"]["labeled_ids"]:
                if not any(cid in (cls.get("labeled_ids") or []) for cls in g["classifications"]):
                    p(f"      * labeled id: {cid}\n")
            if g.get("recovered_js_path"):
                p(f"      -> recovered JS: {g['recovered_js_path']}  "
                  f"({g.get('recovered_js_size', 0):,} bytes)\n")
    p("\n  " + "-" * 78 + "\n")
    p(f"  SUMMARY: {summ['obfuscated_blocks']} obfuscated blocks -> "
      f"{summ['distinct_groups']} distinct payload group(s); "
      f"classifications: {', '.join(summ['schemes_seen']) or 'none'}\n")
    _render_verdict_block(summ, p)
    p("\n")


def _render_cls_text(cls: dict, p):
    s = cls["scheme"]
    if s == "etherhiding":
        p(f"      * EtherHiding loader  (chain: {cls['chain']})\n")
        for a in cls["contract_addresses"]:
            tag = ""
            if cls.get("actor_attribution") and \
               cls["actor_attribution"].get("contract_matched", "").lower() == a.lower():
                tag = f"   <- {cls['actor_attribution']['name']}"
            p(f"      *   contract: {a}{tag}\n")
        if cls["method_selector"]:
            sel = cls["method_selector"]
            tag = ""
            meta = cls.get("selector_info") or {}
            if meta.get("signature"): tag = f"   ({meta['signature']})"
            p(f"      *   method selector: {sel}{tag}\n")
        p(f"      *   RPC pool ({len(cls['rpc_pool_defanged'])}):\n")
        for u in cls["rpc_pool_defanged"]: p(f"      *     - {u}\n")
        p(f"      *   WALL: {cls['wall_reason']}\n")
        if cls.get("actor_attribution"):
            a = cls["actor_attribution"]
            # Only print what we directly OBSERVED from this loader. The
            # advertised_as/infra/registrar/downstream/victims fields are CTI
            # background about the kit in general — NOT observations of THIS
            # target — and now live in a single dedicated section higher up
            # in the comprehensive report (see _render_kit_cti_background).
            # Per-block we only state the match + confidence + sources.
            p(f"      *   actor: {a['name']}  (kit-match confidence: {a['confidence']})\n")
            p(f"      *     sources: {', '.join(a['sources'])}\n")
        if cls.get("resolved"):
            r = cls["resolved"]
            if r["ok"]:
                p(f"      *   RESOLVED next-stage URL: {r.get('decoded_url_defanged')}\n")
                p(f"      *     via RPC: {_defang(r['rpc_used'])}  ({r['decoded_at']})\n")
            else: p(f"      *   RESOLVE FAILED: {r.get('error')}\n")
    elif s == "clipboard_payload":
        p(f"      * Clipboard sink: {cls['sink']}\n")
        # Print the full clipboard argument — this is the IOC, never truncate.
        arg = cls.get("clipboard_arg") or cls.get("clipboard_arg_excerpt")
        if arg:
            p(f"      *   arg ({cls.get('clipboard_arg_length')} chars):\n")
            for line in arg.splitlines() or [arg]:
                p(f"      *     {line}\n")
    elif s == "aes_kit":
        p(f"      * AES kit markers present  ({cls['note']})\n")
        for b in cls["fromBase64_blobs"]:
            p(f"      *   FromBase64String[{b['len']} chars]: {b['head']}...\n")
        for cid in cls["labeled_ids"]: p(f"      *   labeled id: {cid}\n")
    elif s == "bw_v2_launcher":
        p(f"      * BW v2 plaintext launcher  ({cls.get('kit','ErrTraffic v3 (BW v2)')})\n")
        p(f"      *   download URL: {cls.get('dl_url_defanged')}\n")
        if cls.get("token"):
            p(f"      *   token ({cls.get('token_alias','uj')}=): {cls['token']}\n")
        if cls.get("rlm"):
            p(f"      *   rlm: {cls['rlm']}\n")
        if cls.get("confidence") is not None:
            p(f"      *   confidence: {cls['confidence']:.2f}\n")
        chain_bits = []
        if cls.get("has_invoke_webrequest"): chain_bits.append("iwr")
        if cls.get("has_start_process"):     chain_bits.append("Start-Process")
        if cls.get("has_invoke_expression"): chain_bits.append("iex")
        if cls.get("has_file_arg"):          chain_bits.append("-File")
        if chain_bits:
            p(f"      *   chain primitives: {', '.join(chain_bits)}\n")
    elif s == "powershell_command":
        for c in cls["commands"]: p(f"      * command: {c[:240]}\n")
    elif s == "tds_beacon":
        p(f"      * TDS / fingerprint beacon hosts:\n")
        for h in cls["hosts_defanged"]: p(f"      *   - {h}\n")
    elif s == "antianalysis_gate":
        if cls.get("debugger_timing_gate"): p(f"      * anti-analysis: debugger+timing gate\n")
        if cls.get("os_device_gate"):
            excl = cls.get("os_device_excl") or []
            p(f"      * anti-analysis: OS/device gate"
              + (f" (excludes: {', '.join(excl)})" if excl else "") + "\n")
        if cls.get("cookie_dedup_names"):
            p(f"      * anti-analysis: per-victim cookies "
              f"({', '.join(cls['cookie_dedup_names'])})\n")


def _render_verdict_block(summ: dict, p):
    v = summ["verdict"]
    if v == "clipboard_or_powershell_payload":
        p("  VERDICT: CLIPBOARD / POWERSHELL PAYLOAD RECOVERED\n")
    elif v == "etherhiding_loader":
        if summ.get("resolved_next_stage_urls"):
            p("  VERDICT: EtherHiding loader recovered AND RESOLVED.\n")
            p("           Live next-stage URL(s) read from chain:\n")
            for u in summ["resolved_next_stage_urls"]: p(f"             {u}\n")
        else:
            attrs = summ.get("actors_attributed") or []
            if attrs: p(f"  VERDICT: EtherHiding loader recovered ({attrs[0]['name']}).\n")
            else:     p("  VERDICT: EtherHiding loader recovered (unknown actor).\n")
            p("           Next-stage URL is on-chain; re-run with --resolve to "
              "fetch it live\n           via a passive read-only eth_call.\n")
    elif v == "tds_beacon_only":
        p("  VERDICT: TDS/fingerprint beacon recovered, no payload — server-side gated.\n")
    elif v == "scaffolding_only":
        p("  VERDICT: loader scaffolding recovered, no payload "
          "(check recovered .js files; class may be unknown).\n")
    elif v == "no_input": p("  VERDICT: no input (empty html).\n")
    else: p("  VERDICT: nothing recovered.\n")
    # S32 ClickFix classification — always rendered when present
    _render_clickfix_classification(summ.get("clickfix_classification"), p)


def _render_clickfix_classification(cf: dict | None, p):
    """Render the ClickFix score + classification block. Always shown when
    `cf` is present; survives in both single-IOC and comprehensive reports."""
    if not cf: return
    cls   = cf.get("class", "unknown")
    role  = cf.get("role", "unknown_role")
    score = cf.get("score", 0)
    band  = cf.get("band", "none")
    reasoning = cf.get("reasoning", "")
    p("\n  ── ClickFix classification ──\n")
    p(f"     class: {cls}   role: {role}\n")
    p(f"     score: {score}/100   ({band})\n")
    if reasoning:
        p(f"     reasoning: {reasoning}\n")
    sigs = cf.get("signals") or []
    if sigs:
        p(f"     signals ({len(sigs)}):\n")
        for s in sigs[:10]:
            src = s.get("source") or ""
            p(f"       - {s['name']:28} +{s['weight']:>2}  {src[:70]}\n")
        if len(sigs) > 10:
            p(f"       ... ({len(sigs) - 10} more)\n")


def _slim_report_for_serialize(report: dict) -> dict:
    """ONLY strips `group["recovered_js"]` (the raw decoded loader source).

    Important — this is NOT general output trimming. Every other field in
    every report is preserved bit-for-bit:
      • summary (verdict, classifications, actors, IOCs, payload hashes…)
      • per-group classifications + IOCs + anti-analysis flags
      • server_fingerprint / panel_server_fingerprint (with --shodan-enrich)
      • wordpress / cloudflare / panel_cloudflare blocks
      • aes_clipboard_recovery (full plaintext kept)
      • panel_payloads (per-OS records, sha256, magic, all headers, etc.)
      • external_scripts_classified (per-script verdicts + confidence)
      • envelope_recovery (BW v2 gcm1 plaintexts)
      • input_role, errors[], enrichment_log, etc.

    Why strip recovered_js: the raw decoded loader JS sits in-memory on
    every group dict so AES recovery + classifiers can read it without
    disk I/O. Inline in JSONL it'd add ~50KB per report (12K = ~600 MB
    for no analyst benefit — the same text is on disk when --out is set,
    and `recovered_js_size` + `recovered_js_path` are preserved here).
    """
    # Drop the private raw-HTML stash (--dump only) before any serialization so
    # it never bloats JSON/JSONL output. Done first so it applies on both the
    # early-return and the full-slim paths, without mutating the original.
    if "_dump_raw_html" in report:
        report = {k: v for k, v in report.items() if k != "_dump_raw_html"}
    if not isinstance(report.get("groups"), list):
        return report
    # Shallow-copy report; shallow-copy each group so we don't mutate the
    # original (caller may still need recovered_js downstream).
    slim = dict(report)
    slim_groups = []
    for g in report["groups"]:
        if isinstance(g, dict) and "recovered_js" in g:
            gg = dict(g); gg.pop("recovered_js", None); slim_groups.append(gg)
        else:
            slim_groups.append(g)
    slim["groups"] = slim_groups
    # Also slim a `lure_page.groups` shape that comprehensive reports use.
    lp = report.get("lure_page")
    if isinstance(lp, dict) and isinstance(lp.get("groups"), list):
        lp_slim = dict(lp)
        lp_slim["groups"] = []
        for g in lp["groups"]:
            if isinstance(g, dict) and "recovered_js" in g:
                gg = dict(g); gg.pop("recovered_js", None); lp_slim["groups"].append(gg)
            else:
                lp_slim["groups"].append(g)
        slim["lure_page"] = lp_slim
    return slim


def render_json(report: dict, fh=sys.stdout, *, jsonl: bool = False):
    out = _slim_report_for_serialize(report)
    if jsonl:
        json.dump(out, fh, ensure_ascii=False, sort_keys=False); fh.write("\n")
    else:
        json.dump(out, fh, ensure_ascii=False, sort_keys=False, indent=2); fh.write("\n")


